insert into private.study_guides (guide, chunks, sha256) values ('study_guide_gst111', 76, '750bf80e80f1556893a28386da30617f272b22e6376af591ed3330427c94cb5b');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 1, $study_guide${"guide":"study_guide_gst111","code":"GST111","courseId":"40000000-0000-4000-8000-000000000008","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"684b4900-fe11-57fe-9c14-d7270a801804","before":{"title":"Communication in English","body":"Communication skills course covering listening, the sounds of English, stress and intonation, reading and comprehension, writing, grammar, vocabulary, and using the library and information sources."},"after":{"title":"Communication in English","body":"Communication skills course covering listening, the sounds of English, stress and intonation, reading and comprehension, writing, grammar, vocabulary, and using the library and information sources.","outcomes":["Listen effectively in lectures and take notes that capture the essence of what is said.","Describe the organs of speech and identify the consonants, vowels and diphthongs of English with their symbols.","Divide words into syllables, place stress correctly and use the intonation tunes of English.","Read efficiently, using skimming, scanning and study reading, and avoid the common reading faults.","Answer comprehension questions and write a summary or synopsis.","Use study-reading methods such as SQ3R and explain how memory works.","Write a well-formed paragraph with a clear topic sentence, unity and coherence.","Write the main types of essay and punctuate correctly.","Build vocabulary and explain how English words are formed.","Identify word classes, phrases, clauses and sentence types, and avoid common sentence errors.","Use the library, its resources and its retrieval tools, and search electronic sources well.","Avoid plagiarism and cite sources in APA, Harvard and MLA style."],"assessment":["The exam is objective (CBT). Questions test definitions, lists and counts, examples, symbols and the exact wording used in this course.","Every topic is examinable."]}},"retire":[],"notes":[{"kind":"note","itemId":"e3464900-6162-5329-821c-edc367e2f880","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Listening Skills","body":"What listening is and why it matters in lectures; the three conditions that cause ineffective listening; the seven strategies for better listening; formal versus informal listening; how listening links to note-taking (requirements, strategies, before/during/after a lecture, symbols and abbreviations).","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What listening is and why it matters in lectures; the three conditions that cause ineffective listening; the seven strategies for better listening; formal versus informal listening; how listening links to note-taking (requirements, strategies, before/during/after a lecture, symbols and abbreviations)."}],"lessons":[{"number":"1.1","title":"Listening and the lecture method","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Listening:","bold":true},{"text":" the ability of a person to "},{"text":"receive, perceive and decode","bold":true},{"text":" the meaning of spoken words. In class, it is the ability to receive, perceive and decode the meaning of what the lecturer is disseminating as knowledge. In short: the ability to identify and understand what a speaker is saying."}]},{"text":[{"text":"Listening is a "},{"text":"receptive skill","bold":true},{"text":" in language and communication. You must acquire it "},{"text":"consciously","bold":true},{"text":" to reach "},{"text":"communicative competence","bold":true},{"text":", which leads to excellence in your studies."}]},{"text":[{"text":"Why it is important:","bold":true},{"text":" without listening, communication is impossible."}]},{"text":[{"text":"Knowledge in a university is communicated through "},{"text":"lectures","bold":true},{"text":". The main goal of a lecture is to "},{"text":"impart knowledge","bold":true},{"text":" to students. Your duty is to capture the "},{"text":"essence","bold":true},{"text":" of what the lecturer says in your notes, which is impossible without effective listening."}]},{"text":[{"text":"A lecture has three parts:","bold":true},{"text":" introduction, main lecture (body) and conclusion."}]},{"text":[{"text":"Course outline:","bold":true},{"text":" a listing of the relevant "},{"text":"topics to be treated in a particular course","bold":true},{"text":", provided by the "},{"text":"lecturer","bold":true},{"text":"."}]},{"text":[{"text":"This course (GST 111, formerly GST 105 Use of English) covers listening, speaking (the sounds of English, i.e. phonology), reading, writing, grammar, vocabulary and use of the library. Epistemology is not part of it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The four language skills divide into two groups. "},{"text":"Receptive:","bold":true},{"text":" listening and reading (you take language in). "},{"text":"Productive:","bold":true},{"text":" speaking and writing (you produce language). When a question in this topic asks for the receptive skill, the answer is "},{"text":"listening","bold":true},{"text":"."}]},{"text":[{"text":"Trap: listening is "},{"text":"not","bold":true},{"text":" predicting what the speaker will say, guiding the speaker's speech, or simply keeping quiet. Keeping quiet is good manners; listening is understanding."}]},{"text":[{"text":"Trap: listening is the ability to receive, perceive and decode meaning. \"Denounce\" (to condemn publicly) is not part of the definition."}]},{"text":[{"text":"The skills involved in listening include understanding the speaker's "},{"text":"accent, vocabulary and presentation","bold":true},{"text":" of the topic. Reading the topic beforehand and preparing for the lecture are pre-lecture activities, not listening skills themselves."}]},{"text":[{"text":"A lecture is mostly one-way delivery, not an equal trade of information. Giving a course outline or introducing the lecturer is not its goal."}]},{"text":[{"text":"The course outline is prepared before teaching begins, so it lists t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 2, $study_guide$opics, not the specific or main points raised in a lecture. Those belong in your notes."}]}]}]},{"number":"1.2","title":"Factors responsible for ineffective and unproductive listening","mustKnow":[{"type":"paragraph","text":[{"text":"Three conditions make listening ineffective:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical condition of the environment","bold":true},{"text":" where you receive the lecture. A "},{"text":"noisy","bold":true},{"text":" or "},{"text":"ill-ventilated","bold":true},{"text":" room inhibits listening."}]},{"text":[{"text":"Physiological condition of the lecturer:","bold":true},{"text":" his "},{"text":"speech defects, pronunciation problems and intonation","bold":true},{"text":". These are parts of communication skills, but when the speaker is deficient in them they become "},{"text":"barriers to listening","bold":true},{"text":"."}]},{"text":[{"text":"Psychological condition of the listener:","bold":true},{"text":" mostly the "},{"text":"emotional state","bold":true},{"text":" of the listener. It has a great impact on the result of listening."}]}]},{"type":"paragraph","text":[{"text":"Situations that make listening unproductive: noise, speech defects, pronunciation problems, intonation, the mind of the listener."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match the condition to the person or thing: "},{"text":"physical = environment","bold":true},{"text":", "},{"text":"physiological = lecturer (speaker)","bold":true},{"text":", "},{"text":"psychological = listener","bold":true},{"text":". A speech defect is a "},{"text":"physiological","bold":true},{"text":" condition. Noise is "},{"text":"physical","bold":true},{"text":". Grief or excitement in the listener is "},{"text":"psychological","bold":true},{"text":"."}]},{"text":[{"text":"Trap: a \"spiritual\" condition is not one of the three."}]},{"text":[{"text":"Other barriers: an unfamiliar accent or speech affectation, and difficult vocabulary. "},{"text":"Organised and cohesive speech","bold":true},{"text":" helps the listener, so it does not harm listening."}]}]}]},{"number":"1.3","title":"Strategies for enhancing listening skills","mustKnow":[{"type":"paragraph","text":[{"text":"Seven strategies, in this order:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Eye contact:","bold":true},{"text":" maintaining eye contact with your lecturer is the "},{"text":"beginning","bold":true},{"text":" of any attempt at effective listening. It links your mind with the speaker's and establishes your physical readiness to process the message."}]},{"text":[{"text":"Identify and concentrate on the content of the lecture:","bold":true},{"text":" first identify what the lecture is about, then focus your mind on the content."}]},{"text":[{"text":"Repress all forms of emotional attachment:","bold":true},{"text":" suppress your emotion so that your interest is a product of genuine interest to know."}]},{"text":[{"text":"Avoid distractions:","bold":true},{"text":" noises inside and outside the lecture room."}]},{"text":[{"text":"Listening as a mental challenge:","bold":true},{"text":" see listening as a challenge you can overcome; prepare psychologically by stimulating your interest in the lecture."}]},{"text":[{"text":"Ask mental questions","bold":true},{"text":" as the lecture progresses."}]},{"text":[{"text":"Avoid hasty generalisations and conclusions:","bold":true},{"text":" be patient enough to let the speaker finish the point before you react."}]}]},{"type":"paragraph","text":[{"text":"Effective listening requires that you pay "},{"text":"total attention","bold":true},{"text":" to what the speaker is saying."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Eye contact","bold":true},{"text":" also lets you focus on the lecturer's actions in laboratory demonstrations or step-by-step explanations. Exam wording: maintain "},{"text":"eye","bold":true},{"text":" contact (not \"close\", \"full\" or \"virtual\")."}]},{"text":[{"text":"Emotional attachment","bold":true},{"text":" to the subject leads to "},{"text":"prejudices","bold":true},{"text":", which may come from religious, cultural, economic, tribal or financial bias against the topic or the lecturer. Personal emotions such as grief, happiness or love also hinder listening."}]},{"text":[{"text":"Distractions","bold":true},{"text":" include music, friends and classmates talking, spectacles created by people's manner of dressing, and humorous remarks by the lecturer. Admiring the lecturer's outfit is a distraction, not listening."}]},{"text":[{"text":"Mental questions","bold":true},{"text":" to ask: What is the main thrust of the lecture? How does it relate to my past knowledge of previous topics? What other course in my field has said something about this topic?"}]},{"text":[{"text":"Hasty generalisation:","bold":true},{"text":" drawing your conclusion on the content before the lecture ends. However attractive, agitating or irritating the delivery, there may still be something in it you will benefit from. Listen to the end, or until the lecturer pauses for your reaction."}]},{"text":[{"text":"Trap: effective listening does "},{"text":"not","bold":true},{"text":" mean dictating the speaker's pace, or judging his attitude and comportment. Critical thinking is useful, but it comes after you have fully taken in what was said."}]}]}]},{"number":"1.4","title":"Formal and informal listening","mustKnow":[{"type":"paragraph","text":[{"text":"There are "},{"text":"two types","bold":true},{"text":" of listening: "},{"text":"formal","bold":true},{"text":" and "},{"text":"informal","bold":true},{"text":"."}]},{"type":"table","header":[[],[{"text":"Formal listening"}],[{"text":"Informal listening"}]],"rows":[[[{"text":"Where"}],[{"text":"Specific formal environments, e.g. a university lecture, and all formal contexts"}],[{"text":"Normal, regular conversations with anyone we$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 3, $study_guide$ talk to or who talks to us"}]],[[{"text":"Purpose"}],[{"text":"Specific formal purposes, e.g. to pass exams"}],[{"text":"Not to pass exams; to improve our relationships with people"}]],[[{"text":"Strategies"}],[{"text":"Deploy the seven strategies above for maximum results"}],[{"text":"Still essential to improve our capacity to listen to others"}]]]},{"type":"paragraph","text":[{"text":"In the classroom we engage in formal listening for any of "},{"text":"six purposes","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"comprehend","bold":true},{"text":" or gain a general understanding of the lecture."}]},{"text":[{"text":"To "},{"text":"remember","bold":true},{"text":" a specific equation, formula or concept so you can define it when the time arises."}]},{"text":[{"text":"To "},{"text":"evaluate or criticise","bold":true},{"text":" a theory, a point of logic, the weakness or strength of an argument."}]},{"text":[{"text":"To "},{"text":"analyse","bold":true},{"text":" a step or method of arriving at an answer or the result of an experiment."}]},{"text":[{"text":"To "},{"text":"learn","bold":true},{"text":" so as to outline, account for and discuss the historical development of an event, theory or concept."}]},{"text":[{"text":"To learn the "},{"text":"critical tools","bold":true},{"text":" used in practical analysis of literary texts and how to deploy them to evaluate the texts' categories and functions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"These purposes are "},{"text":"not mutually exclusive","bold":true},{"text":": one lecture may need you to comprehend, criticise and evaluate a concept at the same time."}]},{"text":[{"text":"Lecturers try to focus on a specific topic, but not in every lecture. What you need most is "},{"text":"awareness of the situation","bold":true},{"text":", so you can relate it to former knowledge."}]},{"text":[{"text":"Exam wording: during lectures we engage in "},{"text":"formal","bold":true},{"text":" listening; regular conversations attract "},{"text":"informal","bold":true},{"text":" listening. \"Total\" and \"partial\" are not types of listening."}]},{"text":[{"text":"Informal listening still matters: listening skills shape your relationships in the larger society, not only your academic performance."}]}]}]},{"number":"1.5","title":"Listening and note-taking","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why take notes:","bold":true},{"text":" you cannot remember everything you listen to, however ingenious you are. Even verbatim recall is "},{"text":"tentative","bold":true},{"text":"; after a period you forget part or even the entire main gist. Hence the necessity of taking notes while listening."}]},{"text":[{"text":"Note-taking:","bold":true},{"text":" the aspect of communication skills that involves your ability to "},{"text":"keep a record of a speaker's message","bold":true},{"text":" and to "},{"text":"record the essential points from textbooks or written materials","bold":true},{"text":". Through it you engage actively in learning and produce your own written record of main ideas and important details for revision and examinations."}]}]},{"type":"paragraph","text":[{"text":"Six requirements of effective note-taking.","bold":true},{"text":" You must be able to:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Recognise the main ideas","bold":true},{"text":" in a speaker's message, lecture or reading material."}]},{"text":[{"text":"Identify only relevant information","bold":true},{"text":" from the lecture or reading."}]},{"text":[{"text":"Devise a personal system","bold":true},{"text":" of recording information that works for you (e.g. a format with columns: Heading, Source, Reference, Content, Details)."}]},{"text":[{"text":"Reduce the content","bold":true},{"text":" of the lecture to note form, possibly with a diagram format."}]},{"text":[{"text":"Possess the skills of "},{"text":"sentence reduction, summary, paraphrasing","bold":true},{"text":", etc."}]},{"text":[{"text":"Correctly cite and reference","bold":true},{"text":" sources when making notes from a textbook."}]}]},{"type":"paragraph","text":[{"text":"Five strategies for effective note-taking:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Define the purpose","bold":true},{"text":" for listening or reading; have a firm grasp of the message or topic before you begin. For written material, skim and highlight the relevant parts."}]},{"text":[{"text":"Identify the function and purpose","bold":true},{"text":" of the text or lecture: make out the potentially important information; overview the outline as you listen or read. For a book, read the title, preface, foreword, abstract, table of contents and introduction, and skim the material."}]},{"text":[{"text":"Know the "},{"text":"organising principles","bold":true},{"text":" by which the lecturer or textbook presents the information."}]},{"text":[{"text":"Include your own thoughts","bold":true},{"text":" in the note, in a separate column or on the margin."}]},{"text":[{"text":"Do not write verbatim.","bold":true},{"text":" Use "},{"text":"shorthand","bold":true},{"text":": symbols, abbreviations, concept maps or diagrams."}]}]},{"type":"paragraph","text":[{"text":"Before, during and after a live lecture:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Before:","bold":true},{"text":" revise previous related lectures; read about the topic (a "},{"text":"pre-lecture survey","bold":true},{"text":"); check the meaning of new words that are vital terms in the course; prepare the format for note-taking; arrive in time to sit close to the lecturer."}]},{"text":[{"text":"During:","bold":true},{"text":" distinguish the lecture's "},{"text":"main points","bold":true},{"text":" from elaborations, examples, repetitions and re-statements; listen for "},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 4, $study_guide$text":"transition cues","bold":true},{"text":" (in addition, however, moreover, consequently) that mark movement from introduction to body to conclusion or summary; look out for "},{"text":"non-verbal cues","bold":true},{"text":" (facial expressions, gesticulations, body movement); observe "},{"text":"illustrations and demonstrations","bold":true},{"text":" with visual materials (diagrams, tables, drawings and their labels); listen for "},{"text":"phonological cues","bold":true},{"text":" (voice changes, accent, word stress, speed, emotional nuances)."}]},{"text":[{"text":"After:","bold":true},{"text":" "},{"text":"revise or review","bold":true},{"text":" the notes as soon as possible and compare notes with course-mates; "},{"text":"tidy up","bold":true},{"text":" handwriting and fill in missing bits; try out a "},{"text":"summary","bold":true},{"text":" of the lecture in your own words."}]}]},{"type":"paragraph","text":[{"text":"Common symbols and abbreviations:","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Meaning"}],[{"text":"Abbreviation"}],[{"text":"Meaning"}]],"rows":[[[{"text":"→"}],[{"text":"gives, causes, leads to, results in"}],[{"text":"c.f."}],[{"text":"confer, compare"}]],[[{"text":"≠"}],[{"text":"not equal to, not the same as"}],[{"text":"i.e."}],[{"text":"that is"}]],[[{"text":"≡"}],[{"text":"equivalent to"}],[{"text":"NB"}],[{"text":"note well"}]],[[{"text":"¶"}],[{"text":"paragraph"}],[{"text":"diff."}],[{"text":"different"}]],[[{"text":"@"}],[{"text":"at"}],[{"text":"gov"}],[{"text":"government"}]],[[{"text":"&"}],[{"text":"and"}],[{"text":"NEC"}],[{"text":"necessary"}]],[[{"text":"+"}],[{"text":"more, plus, and"}],[{"text":"no."}],[{"text":"number"}]],[[],[],[{"text":"ed."}],[{"text":"editor"}]],[[],[],[{"text":"edn."}],[{"text":"edition"}]],[[],[],[{"text":"dev."}],[{"text":"development"}]],[[],[],[{"text":"L1"}],[{"text":"first language"}]],[[],[],[{"text":"cd."}],[{"text":"could"}]],[[],[],[{"text":"exc."}],[{"text":"except"}]],[[],[],[{"text":"incl."}],[{"text":"including"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organising principles","bold":true},{"text":" a lecture or text may follow: steps or stages of a process or event; general to specific ideas; simple to complex ideas; problems and solutions; causes and results; largest parts to smallest parts; well-known ideas to least known; most important point to least important; past ideas to present ones."}]},{"text":[{"text":"Note-taking from a text differs from note-taking in a live lecture because you cannot stop the lecturer to ask for a review (unless it is a recording). Hence the before, during and after activities."}]},{"text":[{"text":"Good notes are:","bold":true},{"text":" brief and concise, legible, systematic and orderly. They are "},{"text":"not","bold":true},{"text":" all that is said in class."}]},{"text":[{"text":"Good habits:","bold":true},{"text":" record the main points with a "},{"text":"selection","bold":true},{"text":" of illustrations and examples; summarise main points; think logically about ideas; disregard digressions; use personal abbreviations "},{"text":"consistently","bold":true},{"text":"."}]},{"text":[{"text":"Bad habits:","bold":true},{"text":" verbatim recording; recording all the lecturer says; recording main points with "},{"text":"all","bold":true},{"text":" the illustrations; using "},{"text":"inconsistent","bold":true},{"text":" personal abbreviations."}]},{"text":[{"text":"Pre-lecture preparation:","bold":true},{"text":" surveying the course outline and topic beforehand, reading introductory surveys of an unfamiliar topic, and arriving before the lecturer are all good. Speculating about the lecturer's sources is "},{"text":"not","bold":true},{"text":" preparation. A "},{"text":"pre-lecture survey","bold":true},{"text":" means reading up on a topic before the lecture."}]},{"text":[{"text":"Post-lecture activities are review, revision and summary. \"Disposal\" (throwing notes away) is not one."}]},{"text":[{"text":"Note-taking skills are sentence reduction, summary and paraphrasing. "},{"text":"Sound articulation","bold":true},{"text":" is a speaking skill, not a note-taking skill."}]},{"text":[{"text":"Abbreviation trap: "},{"text":"NEC","bold":true},{"text":" means \"necessary\", not National Executive Council or National Electoral Commission."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Listening = ability to receive, perceive and decode the meaning of spoken words; a receptive skill; without it communication is impossible."}]},{"text":[{"text":"A lecture imparts knowledge: introduction, main lecture, conclusion. A course outline lists a course's topics; the lecturer provides it."}]},{"text":[{"text":"Three conditions hinder listening: physical (environment), physiological (lecturer), psychological (listener)."}]},{"text":[{"text":"Seven strategies: eye contact; concentrate on content; repress emotional attachment; avoid distractions; mental challenge; mental questions; no hasty generalisations."}]},{"text":[{"text":"Formal listening (lectures; six purposes) versus informal (normal conversations)."}]},{"text":[{"text":"Six requirements and five strategies of note-taking; never verbatim, use shorthand consistently."}]},{"text":[{"text":"Before: revise, read up, check new words, prepare format, arrive early. During: main points, transition, non-verbal, visual and phonological cues. After: review, tidy up, summarise."}]},{"text":[{"text":"Good notes: brief, legible, systematic, orderly. NEC = necessary, c.f. = compare, NB = note well."}]}]}],"theory":{"itemId":"ec7fe978-c8e8-53e4-be5f-cc7dd10fcb82","question":[{"type":"paragraph","text":[{"text":"Define listening and discuss four strategies for enhancing listening skills."}]}]},"practice":[{"topic":"Listening Skills and Note-taking","named":false}]}},{"kind":"note","itemId":"3c5daf1d-ee3e-5f1e-84ea-4a8893bc45ec","sourceKey":"guide-topic:$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 5, $study_guide$2","position":2,"payload":{"title":"Speaking Skills I, the Sounds of English","body":"The organs of speech and what each does; the 44 phonemes of English (24 consonants, 20 vowels); how consonants are described by place, manner and voicing; how vowels are described by tongue height, tongue position, lip shape and length; the 12 pure vowels and 8 diphthongs; IPA symbols and how to transcribe short words.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The organs of speech and what each does; the 44 phonemes of English (24 consonants, 20 vowels); how consonants are described by place, manner and voicing; how vowels are described by tongue height, tongue position, lip shape and length; the 12 pure vowels and 8 diphthongs; IPA symbols and how to transcribe short words."}],"lessons":[{"number":"2.1","title":"The organs of speech","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organs of speech:","bold":true},{"text":" all the parts of the body involved in producing speech sounds, from the "},{"text":"lungs","bold":true},{"text":" to the "},{"text":"lips and nose","bold":true},{"text":". About half the body, from the head to the abdomen, is needed for speech. The organs modify the airstream from the lungs to produce different sounds."}]},{"text":[{"text":"Lungs:","bold":true},{"text":" sponge-like tissues housed within the "},{"text":"rib cage","bold":true},{"text":". They provide the airstream for speech. Air pushed out from the lungs is the "},{"text":"pulmonic egressive airstream","bold":true},{"text":", the airstream used for English sounds."}]},{"text":[{"text":"Trachea:","bold":true},{"text":" the windpipe; air passes up through it from the lungs."}]},{"text":[{"text":"Larynx:","bold":true},{"text":" the voice box; it contains the "},{"text":"vocal folds","bold":true},{"text":", two elastic tissues."}]},{"text":[{"text":"Glottis:","bold":true},{"text":" the aperture (opening) between the vocal folds. It decides voicing:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Glottis held "},{"text":"open","bold":true},{"text":", air passes without obstruction = "},{"text":"voiceless","bold":true},{"text":" sound."}]},{"text":[{"text":"Glottis relatively "},{"text":"closed","bold":true},{"text":" so the vocal folds "},{"text":"vibrate","bold":true},{"text":" under air pressure = "},{"text":"voiced","bold":true},{"text":" sound. Voicing is caused by the "},{"text":"vibration","bold":true},{"text":" of the vocal folds."}]}]}]},{"text":[{"text":"Vocal tract:","bold":true},{"text":" the air passages above the larynx. Two parts: the "},{"text":"oral cavity","bold":true},{"text":" (mouth and pharynx) and the "},{"text":"nasal cavity","bold":true},{"text":" (nose)."}]},{"text":[{"text":"Articulators:","bold":true},{"text":" parts of the vocal tract used to form sounds (tongue, lips and so on). "},{"text":"Articulation","bold":true},{"text":" is the contact of two or more speech organs."}]},{"text":[{"text":"Active articulators","bold":true},{"text":" move (lips, tongue, soft palate). "},{"text":"Passive articulators","bold":true},{"text":" are fixed (teeth, hard palate). The "},{"text":"tongue","bold":true},{"text":" is the most flexible of all the organs of speech."}]}]},{"type":"paragraph","text":[{"text":"Other articulators and their functions:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Soft palate (velum):","bold":true},{"text":" a muscular flap at the back of the roof of the mouth. Raised, it presses against the back wall of the pharynx and shuts off the nasal tract so no air leaves through the nose. Lowered, air escapes through the nose (nasal sounds)."}]},{"text":[{"text":"Hard palate:","bold":true},{"text":" a bony structure at the front part of the roof of the mouth."}]},{"text":[{"text":"Alveolar ridge:","bold":true},{"text":" the rough surface just behind the upper teeth; you can feel it with the tip of the tongue."}]},{"text":[{"text":"Upper and lower teeth.","bold":true}]},{"text":[{"text":"Lips:","bold":true},{"text":" brought together, rounded or spread; for some consonants the lower lip touches the upper teeth."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Parts of the tongue used in articulation: "},{"text":"tip (apex), blade, front, centre (middle), back, root and body","bold":true},{"text":"."}]},{"text":[{"text":"Locations: lungs in the chest (rib cage); larynx and vocal folds in the neck; pharynx above the larynx; velum, hard palate, alveolar ridge and teeth in the mouth; nasal cavity in the nose. The "},{"text":"uvula","bold":true},{"text":" hangs at the end of the soft palate."}]},{"text":[{"text":"Trap: the lungs are housed in the "},{"text":"rib cage","bold":true},{"text":", not the larynx. The larynx houses the vocal folds."}]},{"text":[{"text":"Trap: \"separation\" of the vocal folds gives voicelessness; "},{"text":"vibration","bold":true},{"text":" gives voicing."}]},{"text":[{"text":"Trap: pulmonic (lungs) is the English airstream; glottalic and velaric airstreams belong to some other languages, and \"laryngeal\" names a place, not an airstream."}]}]}]},{"number":"2.2","title":"Consonants","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Phoneme:","bold":true},{"text":" a sound a language selects as significant, one that can keep meanings apart (distinguish words). The speech organs can make unlimited sounds; each language uses only a few."}]},{"text":[{"text":"English has "},{"text":"44 phonemes: 20 vowels and 24 consonants","bold":true},{"text":". (26 is the number of letters, not sounds.)"}]},{"text":[{"text":"Consonant:","bold":true},{"text":" a speech sound produced when at least "},{"text":"two articulators come in contact","bold":true},{"text":", obstructing the flow of air from the larynx to the lips or nostrils."}]},{"text":[{"text":"Consonants are described by "},{"text":"three parameters","bold":true},{"text":":"}],"blo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 6, $study_guide$cks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Place of articulation:","bold":true},{"text":" where the contact takes place."}]},{"text":[{"text":"Manner of articulation:","bold":true},{"text":" the nature of the obstruction."}]},{"text":[{"text":"State of the glottis (voicing):","bold":true},{"text":" whether or not the vocal folds vibrate."}]}]}]}]},{"type":"paragraph","text":[{"text":"Places of articulation","bold":true},{"text":" (9):"}]},{"type":"table","header":[[{"text":"Place"}],[{"text":"Organs involved"}],[{"text":"Sounds"}]],"rows":[[[{"text":"Bilabial"}],[{"text":"the two lips"}],[{"text":"/p/ /b/ /m/ /w/"}]],[[{"text":"Labio-dental"}],[{"text":"lower lip and upper front teeth"}],[{"text":"/f/ /v/"}]],[[{"text":"Dental"}],[{"text":"tongue tip or blade and upper front teeth"}],[{"text":"/θ/ /ð/"}]],[[{"text":"Alveolar"}],[{"text":"tongue blade or tip and alveolar ridge"}],[{"text":"/t/ /d/ /s/ /z/ /n/ /l/"}]],[[{"text":"Post-alveolar"}],[{"text":"tongue raised towards the ridge but no contact"}],[{"text":"/r/"}]],[[{"text":"Palato-alveolar"}],[{"text":"blade on alveolar ridge plus front of tongue raised to the palate"}],[{"text":"/ʃ/ /ʒ/ /ʧ/ /ʤ/"}]],[[{"text":"Palatal"}],[{"text":"front of tongue and hard palate"}],[{"text":"/j/"}]],[[{"text":"Velar"}],[{"text":"back of tongue and soft palate"}],[{"text":"/k/ /g/ /ŋ/"}]],[[{"text":"Glottal"}],[{"text":"vocal folds, friction but no vibration"}],[{"text":"/h/"}]]]},{"type":"paragraph","text":[{"text":"Manners of articulation","bold":true},{"text":" (7 groups):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Stops (plosives)","bold":true},{"text":" /p t k b d g/: total closure of the airflow in the mouth, then sudden release."}]},{"text":[{"text":"Fricatives","bold":true},{"text":" /f v θ ð s z ʃ ʒ h/: two articulators come close; air escapes through a small passage with friction or a hissing sound."}]},{"text":[{"text":"Affricates","bold":true},{"text":" /ʧ ʤ/: begin as plosives, end as fricatives (total closure, then gradual release). They combine the manner of stops and fricatives, which their two-part symbols show."}]},{"text":[{"text":"Nasals","bold":true},{"text":" /m n ŋ/: complete closure in the mouth, the soft palate is lowered, so air escapes through the nose."}]},{"text":[{"text":"Approximants","bold":true},{"text":" /r w j/: a narrowing, but the articulators are not close enough to produce audible friction. /w/ and /j/ are a sub-group called "},{"text":"glides","bold":true},{"text":"."}]},{"text":[{"text":"Lateral","bold":true},{"text":" /l/: the centre of the tongue touches the alveolar ridge and air passes along the sides of the mouth."}]},{"text":[{"text":"Liquids:","bold":true},{"text":" /l/ and /r/ together form the group called liquids."}]}]},{"type":"paragraph","text":[{"text":"Voicing:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Voiceless (9):","bold":true},{"text":" /p t k s f ʃ θ h ʧ/."}]},{"text":[{"text":"Voiced (15):","bold":true},{"text":" /b d g z v ʒ ð ʤ m n ŋ l r w j/."}]}]},{"type":"paragraph","text":[{"text":"The 24 English consonants","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Voicing"}],[{"text":"Place"}],[{"text":"Manner"}],[{"text":"Examples"}]],"rows":[[[{"text":"/p/"}],[{"text":"voiceless"}],[{"text":"bilabial"}],[{"text":"stop"}],[{"text":"pot, spot, happy, hiccough"}]],[[{"text":"/b/"}],[{"text":"voiced"}],[{"text":"bilabial"}],[{"text":"stop"}],[{"text":"bad, robust, rubber, number"}]],[[{"text":"/t/"}],[{"text":"voiceless"}],[{"text":"alveolar"}],[{"text":"stop"}],[{"text":"top, cot, Thomas, kitten"}]],[[{"text":"/d/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"stop"}],[{"text":"den, dead, golden, friend"}]],[[{"text":"/k/"}],[{"text":"voiceless"}],[{"text":"velar"}],[{"text":"stop"}],[{"text":"cough, kitchen, character, queue"}]],[[{"text":"/g/"}],[{"text":"voiced"}],[{"text":"velar"}],[{"text":"stop"}],[{"text":"goat, ghost, haggard, rag"}]],[[{"text":"/f/"}],[{"text":"voiceless"}],[{"text":"labio-dental"}],[{"text":"fricative"}],[{"text":"off, fan, cough, chauffeur"}]],[[{"text":"/v/"}],[{"text":"voiced"}],[{"text":"labio-dental"}],[{"text":"fricative"}],[{"text":"van, of, cave, love"}]],[[{"text":"/θ/"}],[{"text":"voiceless"}],[{"text":"dental"}],[{"text":"fricative"}],[{"text":"thing, mouth, healthy, thigh"}]],[[{"text":"/ð/"}],[{"text":"voiced"}],[{"text":"dental"}],[{"text":"fricative"}],[{"text":"this, mother, clothe, worthy"}]],[[{"text":"/s/"}],[{"text":"voiceless"}],[{"text":"alveolar"}],[{"text":"fricative"}],[{"text":"see, cease, silence, centre"}]],[[{"text":"/z/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"fricative"}],[{"text":"zoo, rise, rays, maize"}]],[[{"text":"/ʃ/"}],[{"text":"voiceless"}],[{"text":"palato-alveolar"}],[{"text":"fricative"}],[{"text":"shoe, chauffeur, social, issue"}]],[[{"text":"/ʒ/"}],[{"text":"voiced"}],[{"text":"palato-alveolar"}],[{"text":"fricative"}],[{"text":"genre, seizure, garage, casual"}]],[[{"text":"/h/"}],[{"text":"voiceless"}],[{"text":"glottal"}],[{"text":"fricative"}],[{"text":"he, behave, heaven, offhand"}]],[[{"text":"/ʧ/"}],[{"text":"voiceless"}],[{"text":"palato-alveolar"}],[{"text":"affricate"}],[{"text":"church, touch, chew, catch"}]],[[{"text":"/ʤ/"}],[{"text":"voiced"}],[{"text":"palato-alveolar"}],[{"text":"affricate"}],[{"text":"edge, judge, George, joy"}]],[[{"text":"/m/"}],[{"text":"voiced"}],[{"text":"bilabial"}],[{"text":"nasal"}],[{"text":"man, hammer, mansion"}]],[[{"text":"/n/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"nasal"}],[{"text":"new, manner, sun, sunny"}]],[[{"text":"/ŋ/"}],[{"text":"voiced"}],[{"text":"velar"}],[{"text":"nasal"}],[{"text":"song, singing, nothingness"}]],[[{"text":"/l/"}],[{"text":"voiced"}],[{"text":"alveolar"}],[{"text":"lateral"}],[{"text":"letter, swallow, little, lofty"}]],[[{"text":"/r/"}],[{"text":"voiced"}],[{"text":"post-alveolar"}],[{"text":"approx$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 7, $study_guide$imant"}],[{"text":"right, marry, rarity, reaction"}]],[[{"text":"/w/"}],[{"text":"voiced"}],[{"text":"bilabial"}],[{"text":"glide (approximant)"}],[{"text":"twist, sweater, dwindle, war"}]],[[{"text":"/j/"}],[{"text":"voiced"}],[{"text":"palatal"}],[{"text":"glide (approximant)"}],[{"text":"youth, stew, few, yam, suitor"}]]]},{"type":"paragraph","text":[{"text":"The consonant chart arranges the same facts by place (columns) and manner (rows):"}]},{"type":"table","header":[[{"text":"Manner"}],[{"text":"Bilabial"}],[{"text":"Labio-dental"}],[{"text":"Dental"}],[{"text":"Alveolar"}],[{"text":"Post-alveolar"}],[{"text":"Palato-alveolar"}],[{"text":"Palatal"}],[{"text":"Velar"}],[{"text":"Glottal"}]],"rows":[[[{"text":"Plosives (stops)"}],[{"text":"p b"}],[],[],[{"text":"t d"}],[],[],[],[{"text":"k g"}],[]],[[{"text":"Fricatives"}],[],[{"text":"f v"}],[{"text":"θ ð"}],[{"text":"s z"}],[],[{"text":"ʃ ʒ"}],[],[],[{"text":"h"}]],[[{"text":"Affricates"}],[],[],[],[],[],[{"text":"ʧ ʤ"}],[],[],[]],[[{"text":"Nasals"}],[{"text":"m"}],[],[],[{"text":"n"}],[],[],[],[{"text":"ŋ"}],[]],[[{"text":"Lateral"}],[],[],[],[{"text":"l"}],[],[],[],[],[]],[[{"text":"Approximants"}],[{"text":"w"}],[],[],[],[{"text":"r"}],[],[{"text":"j"}],[],[]]]},{"type":"paragraph","text":[{"text":"In each pair the voiceless sound is on the left and the voiced on the right."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The slants / / around a symbol mark it as a phoneme, not a letter of the alphabet."}]},{"text":[{"text":"The voiceless th symbol is sometimes printed as /ɵ/; the correct IPA symbol is /θ/ (thing, youth, mouth). In typed questions it may come out as an odd character; any voiceless th option still means /θ/. The voiced one is /ð/ (this, mother)."}]},{"text":[{"text":"Sounds that share a "},{"text":"place","bold":true},{"text":" but differ in manner: /s/, /t/ and /n/ are all "},{"text":"alveolar","bold":true},{"text":" (/s/ fricative, /t/ stop, /n/ nasal). Sounds that share a "},{"text":"manner","bold":true},{"text":" but differ in place: /p/, /t/ and /k/ are all voiceless stops."}]},{"text":[{"text":"Trap: /f/ is "},{"text":"not","bold":true},{"text":" bilabial; it is labio-dental. Bilabials are /p b m w/."}]},{"text":[{"text":"Trap: the "},{"text":"lateral","bold":true},{"text":" is /l/ only. /r/ is the post-alveolar approximant (it is sometimes classed as a trill); /w/ and /j/ are glides."}]},{"text":[{"text":"Trap: the only "},{"text":"glottal","bold":true},{"text":" sound is /h/. /k/ and /g/ are velar."}]},{"text":[{"text":"Feel voicing: fingertips on your larynx while saying a long \"zzzz\" (vibration) then \"ssss\" (none). Or block your ears and contrast [s z f v ʃ ʒ]; you hear buzzing in /z v ʒ/."}]},{"text":[{"text":"Nasals and stops both start with complete closure; in nasals the velum drops and air leaves through the nose."}]}]}]},{"number":"2.3","title":"Vowels: the 12 pure vowels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vowel:","bold":true},{"text":" a sound produced "},{"text":"without any obstruction","bold":true},{"text":" to the airflow from the larynx to the lips. The articulators do not come close; there is "},{"text":"no contact","bold":true},{"text":". The vocal folds vibrate, so "},{"text":"all vowels are voiced","bold":true},{"text":"."}]},{"text":[{"text":"20 vowels: 12 pure vowels (monophthongs) and 8 diphthongs.","bold":true}]},{"text":[{"text":"Because the articulators never meet, vowels are "},{"text":"not","bold":true},{"text":" described by place or manner. Four parameters are used instead:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Tongue height","bold":true},{"text":" (vertical distance from the tongue to the palate): "},{"text":"high (close)","bold":true},{"text":" vowels /i: ɪ u: ʊ/; "},{"text":"low (open)","bold":true},{"text":" vowels /æ ɒ ʌ ɑ:/; "},{"text":"mid","bold":true},{"text":" vowels /ɛ ɜ: ə ɔ:/ in between."}]},{"text":[{"text":"Tongue horizontality","bold":true},{"text":" (which part of the tongue is raised highest): "},{"text":"front","bold":true},{"text":" /i: ɪ ɛ æ/; "},{"text":"back","bold":true},{"text":" /u: ʊ ɒ ɔ: ɑ:/; "},{"text":"central","bold":true},{"text":" /ɜ: ə ʌ/."}]},{"text":[{"text":"Lip rounding","bold":true},{"text":" (the easiest to observe): "},{"text":"spread","bold":true},{"text":" /i: ɪ ɛ æ/; "},{"text":"neutral","bold":true},{"text":" /ʌ ɜ: ɑ: ə/; "},{"text":"rounded","bold":true},{"text":" /ɒ ʊ ɔ: u:/."}]},{"text":[{"text":"Duration:","bold":true},{"text":" long or short. Because context can lengthen or shorten a vowel, the terms "},{"text":"tense","bold":true},{"text":" (= long: /i: ɜ: ɔ: u: ɑ:/) and "},{"text":"lax","bold":true},{"text":" (= short: /ɪ ɛ æ ʌ ə ɒ ʊ/) are preferred, stressing quality over quantity."}]}]}]}]},{"type":"paragraph","text":[{"text":"The 12 pure vowels","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Description"}],[{"text":"Examples"}]],"rows":[[[{"text":"/i:/"}],[{"text":"high, front, tense"}],[{"text":"seat, seed, receive, be, machine, key"}]],[[{"text":"/ɪ/"}],[{"text":"mid-high, front, lax"}],[{"text":"rich, basket, symbol, village, ladies"}]],[[{"text":"/ɛ/"}],[{"text":"mid, front, lax"}],[{"text":"bed, breath, many"}]],[[{"text":"/æ/"}],[{"text":"low, front, lax"}],[{"text":"man, back, hat, badge, land"}]],[[{"text":"/ɑ:/"}],[{"text":"low, back, tense"}],[{"text":"card, heart, clerk, pass, half, laugh"}]],[[{"text":"/ɒ/"}],[{"text":"low, back, lax"}],[{"text":"cot, was, cough, knowledge, because"}]],[[{"text":"/ɔ:/"}],[{"text":"mid-low, back, tense"}],[{"text":"war, four, door, board, cause, water, jaw, ought, broad"}]],[[{"text":"/ʊ/"}],[{"text":"mid-high, back, lax"}],[{"text":"full, book, woman, could"}]],[[{"text":"/u:/"}],[{"text":"high, back, tense"}],[{"text":"rule, food, who, soup, chew, blue, juice"}]],[[{"text":"/ʌ/"}],[{"text":"mid-low, central, lax"}],[{"text":"cup, son, young, bl$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 8, $study_guide$ood, does"}]],[[{"text":"/ɜ:/"}],[{"text":"mid-high, central, tense"}],[{"text":"serve, nurse, bird, myrrh, work, search, journey"}]],[[{"text":"/ə/"}],[{"text":"mid, central, lax"}],[{"text":"woman, oblige, figure, mother, possible, suppose, colour"}]]]},{"type":"paragraph","text":[{"text":"The vowel chart","bold":true},{"text":" (tongue height down the side, tongue position across):"}]},{"type":"table","header":[[],[{"text":"Front"}],[{"text":"Central"}],[{"text":"Back"}]],"rows":[[[{"text":"High (close)"}],[{"text":"i: ɪ"}],[],[{"text":"u: ʊ"}]],[[{"text":"Mid"}],[{"text":"ɛ"}],[{"text":"ɜ: ə"}],[{"text":"ɔ:"}]],[[{"text":"Low (open)"}],[{"text":"æ"}],[{"text":"ʌ"}],[{"text":"ɒ ɑ:"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"high\" vowels are also called "},{"text":"close","bold":true},{"text":" vowels (tongue close to the roof of the mouth); \"low\" vowels are "},{"text":"open","bold":true},{"text":". \"High\" does not mean long or rounded."}]},{"text":[{"text":"Real vowel distinctions: high/low, close/open, front/back, long/short (tense/lax), spread/neutral/rounded. \"Rounded/around\" is not a distinction, and \"pursed\" is not a lip position."}]},{"text":[{"text":"Trap: what is "},{"text":"not","bold":true},{"text":" involved in vowel articulation is "},{"text":"contact","bold":true},{"text":" between articulators. Tongue movement, lip shaping and length all are."}]},{"text":[{"text":"/u:/ is the high, back, tense vowel; /i:/ is high and tense but "},{"text":"front","bold":true},{"text":"; /ɜ:/ is central; /ɑ:/ is low and back. In typed questions /ɜ:/ sometimes appears as /3:/ and /ɑ:/ as /a:/."}]},{"text":[{"text":"Schwa /ə/ is the mid central lax vowel of unstressed syllables (the \"a\" in woman, the \"er\" in mother)."}]},{"text":[{"text":"The vowel of bed is written /ɛ/ here; some dictionaries write it /e/. Same sound."}]},{"text":[{"text":"Length pairs differ in quality too: /i:/ high front vs /ɪ/ mid-high front; /u:/ high back vs /ʊ/ mid-high back; /æ/ low front vs /ɑ:/ low back; /ɒ/ low back vs /ɔ:/ mid-low back."}]}]}]},{"number":"2.4","title":"Diphthongs and the spelling problem","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Diphthong:","bold":true},{"text":" a vowel sound that consists of a "},{"text":"movement or glide from one vowel position to another","bold":true},{"text":". A pure vowel is static in phonetic space. Diphthongs contain two elements but are "},{"text":"equal in length to the long pure vowels","bold":true},{"text":". Their symbols show both elements."}]},{"text":[{"text":"The 8 diphthongs are grouped by the "},{"text":"direction of the glide","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Closing (rising) diphthongs (5):","bold":true},{"text":" first element a mid or low vowel, second element a "},{"text":"high","bold":true},{"text":" vowel."}]},{"text":[{"text":"Centring diphthongs (3):","bold":true},{"text":" first element a front or back vowel, ending in the central vowel "},{"text":"schwa /ə/","bold":true},{"text":"."}]}]}]}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Symbol"}],[{"text":"Examples"}]],"rows":[[[{"text":"Closing"}],[{"text":"/eɪ/"}],[{"text":"gate, waist, play, eight, they, great"}]],[[{"text":"Closing"}],[{"text":"/aɪ/"}],[{"text":"time, pie, fly, type, light, dye, eye"}]],[[{"text":"Closing"}],[{"text":"/ɔɪ/"}],[{"text":"boil, boy, joint, joy, oyster, void, voyage"}]],[[{"text":"Closing"}],[{"text":"/əʊ/"}],[{"text":"so, hoe, own, toast, soul, go, pillow"}]],[[{"text":"Closing"}],[{"text":"/aʊ/"}],[{"text":"house, how, loud, crowd, shout, owl"}]],[[{"text":"Centring"}],[{"text":"/ɪə/"}],[{"text":"here, cheer, media, idea, museum"}]],[[{"text":"Centring"}],[{"text":"/ɛə/"}],[{"text":"care, chair, bear, parent, aerial"}]],[[{"text":"Centring"}],[{"text":"/ʊə/"}],[{"text":"poor, gourd, endure, during"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"No sound-letter correspondence:","bold":true},{"text":" the same letters can be pronounced in many ways. The letter \"a\" is /eɪ/ in gate, /ə/ in woman, /ɛ/ in many, /ɪ/ in village, /æ/ in man, /ɑ:/ in pass and /ɒ/ in was. Never use spelling as a guide to pronunciation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Closing diphthongs end in /ɪ/ (eɪ, aɪ, ɔɪ) or /ʊ/ (əʊ, aʊ). Centring diphthongs all end in /ə/."}]},{"text":[{"text":"The vowel classes you may meet are "},{"text":"monophthongs","bold":true},{"text":" (12), "},{"text":"diphthongs","bold":true},{"text":" (8) and "},{"text":"triphthongs","bold":true},{"text":" (a glide through three positions, e.g. fire /faɪə/, formed by a closing diphthong plus schwa). There is no such thing as a "},{"text":"quadriphthong","bold":true},{"text":"."}]},{"text":[{"text":"Trap: diphthongs are single vowel phonemes, not two vowels. \"Care\" /kɛə/ has two sounds in total, not three."}]},{"text":[{"text":"Trap: \"pure vowel\" = monophthong = one steady position; \"diphthong\" = glide. Tense does not mean diphthong: /i:/ is a long pure vowel."}]}]}]},{"number":"2.5","title":"Symbols and transcription","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The symbols for English sounds are adapted from the "},{"text":"International Phonetic Association's alphabet (IPA)","bold":true},{"text":", not from the 26 letters. They represent the "},{"text":"phonemes","bold":true},{"text":", the sounds that differentiate words."}]},{"text":[{"text":"Transcription:","bold":true},{"text":" capturing an utterance or word as a linear sequence of sound symbols. It mirrors pronunciation. "},{"text":"Orthography","bold":true},{"text":" is the conventional spelling system. Phonetics is to pronunciation what orthography is to spelling."}]},{"text":[{"text":"Minimal pairs","bold":true},{"text":" show phonemes at work: /kʌt/ cut, /kɒt/ cot, /kɑ:t/ cart, /kæt/ cat, /kɔ:t/ caught, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 9, $study_guide$/kɪt/ kit. Change one vowel phoneme and the word changes."}]},{"text":[{"text":"The "},{"text":"length mark (diacritic) ':'","bold":true},{"text":" after a vowel symbol shows the vowel is "},{"text":"long","bold":true},{"text":": /i:/ seat vs /ɪ/ sit; /u:/ fool vs /ʊ/ full; /ɔ:/ caught vs /ɒ/ cot; /ɑ:/ cart vs /æ/ cat. It does not change the perceptual quality of the long vowel; it marks length only."}]},{"text":[{"text":"Number of letters is not number of sounds:"}]}]},{"type":"table","header":[[{"text":"Word"}],[{"text":"Transcription"}],[{"text":"Sounds"}],[{"text":"Letters"}]],"rows":[[[{"text":"source"}],[{"text":"/sɔ:s/"}],[{"text":"3"}],[{"text":"6"}]],[[{"text":"fall"}],[{"text":"/fɔ:l/"}],[{"text":"3"}],[{"text":"4"}]],[[{"text":"shirt"}],[{"text":"/ʃɜ:t/"}],[{"text":"3"}],[{"text":"5"}]],[[{"text":"tough"}],[{"text":"/tʌf/"}],[{"text":"3"}],[{"text":"5"}]],[[{"text":"care"}],[{"text":"/kɛə/"}],[{"text":"2"}],[{"text":"4"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"How to transcribe a monosyllabic word: say it aloud, ignore the spelling, write one symbol per sound. Worked examples: youth /ju:θ/ (glide /j/ + long /u:/ + voiceless /θ/; never written with the letter \"y\", never with /ð/); mouth /maʊθ/; state /steɪt/; love /lʌv/; teach /ti:ʧ/; care /kɛə/; proud /praʊd/; street /stri:t/."}]},{"text":[{"text":"Counting sounds: cheap /ʧi:p/ has "},{"text":"3","bold":true},{"text":" sounds (ch is one affricate). Trust /trʌst/ has 5; frog /frɒg/ has 4; thoughts /θɔ:ts/ has 4 (th is one sound, \"ough\" is one vowel)."}]},{"text":[{"text":"Trap: silent letters (knowledge, half, queue) and double letters (hammer, rubber) get one symbol or none. /ŋ/ in \"song\" is one sound spelt with two letters."}]},{"text":[{"text":"Pronounce correctly to transcribe correctly, and use the transcription your dictionary gives for every entry."}]},{"text":[{"text":"Trap: APA and MLA are referencing styles; the symbol source is the "},{"text":"IPA","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organs of speech run from the lungs (in the rib cage) to the lips and nose; the pulmonic egressive airstream powers English speech."}]},{"text":[{"text":"Glottis open = voiceless; vocal folds vibrating = voiced. The tongue is the most flexible articulator."}]},{"text":[{"text":"Active articulators move (lips, tongue, velum); passive ones are fixed (teeth, hard palate)."}]},{"text":[{"text":"44 phonemes: 24 consonants, 20 vowels (12 pure vowels + 8 diphthongs)."}]},{"text":[{"text":"Consonants: place (9), manner (stops, fricatives, affricates, nasals, approximants/glides, lateral, liquids), voicing (9 voiceless, 15 voiced)."}]},{"text":[{"text":"Bilabial /p b m w/; labio-dental /f v/; dental /θ ð/; alveolar /t d s z n l/; glottal /h/; lateral /l/."}]},{"text":[{"text":"Vowels: no contact, all voiced; described by tongue height, tongue horizontality, lip rounding, length (tense/lax). High = close, low = open."}]},{"text":[{"text":"Diphthongs glide: 5 closing (eɪ aɪ ɔɪ əʊ aʊ), 3 centring (ɪə ɛə ʊə)."}]},{"text":[{"text":"Symbols come from the IPA; ':' marks length; spelling is not a guide to sound (source = 3 sounds, 6 letters)."}]}]}],"theory":{"itemId":"012bd206-3418-51b1-b543-d68a623244a6","question":[{"type":"paragraph","text":[{"text":"What is the basic difference between consonant and vowel articulation, and how is each type of sound described?"}]}]},"practice":[{"topic":"Speaking Skills I: Sounds of English","named":false}]}},{"kind":"note","itemId":"b78678e1-46de-5434-893b-dd9b4075cfab","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Speaking Skills II: The Syllable, Stress and Intonation","body":"What a syllable is and its structure (onset, peak, coda; C0-3VC0-4); acceptable and unacceptable consonant clusters; stress, the four factors of prominence and the three levels of stress; predicting stress phonologically, syntactically and morphologically; intonation, its three functions and the uses of the four tunes.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What a syllable is and its structure (onset, peak, coda; C0-3VC0-4); acceptable and unacceptable consonant clusters; stress, the four factors of prominence and the three levels of stress; predicting stress phonologically, syntactically and morphologically; intonation, its three functions and the uses of the four tunes."}],"lessons":[{"number":"3.1","title":"The English syllable","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentals:","bold":true},{"text":" the individual consonant and vowel sounds."}]},{"text":[{"text":"Suprasegmentals:","bold":true},{"text":" features that apply to units higher than the segments (the syllable and beyond), such as "},{"text":"stress","bold":true},{"text":" and "},{"text":"intonation","bold":true},{"text":". They are \"above the segments\" but still need them to function."}]},{"text":[{"text":"Syllable:","bold":true},{"text":" a distinct group of sounds that can be pronounced in one moment of uninterrupted breath. It usually consists of a vowel which may be preceded or followed by one or more consonants. Easy to identify, hard to define: "},{"text":"education","italic":true},{"text":" has four syllables."}]},{"text":[{"text":"Two phonetic theories of the syllable:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Chest Pulse Theory:","bold":true},{"text":" the syllable equals a single puff of air by the intercostal muscles of the chest cavity."}]},{"text":[{"text":"Prominence Theory:","bold":true},{"text":" the syllable is the most prominent, relatively loudest or most sonorous sound in a phonetic environment."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Phonological definition:","bold":true},{"text":" looks at how English phonemes combine. A syllable has three parts:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 10, $study_guide$":"Onset:","bold":true},{"text":" all the consonants before the vowel (optional)."}]},{"text":[{"text":"Peak:","bold":true},{"text":" the vowel itself (compulsory; the only obligatory element)."}]},{"text":[{"text":"Coda:","bold":true},{"text":" all the consonants after the vowel (optional)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Formula:","bold":true},{"text":" "},{"text":"C0-3VC0-4","bold":true},{"text":". Onset: 0 to "},{"text":"3","bold":true},{"text":" consonants (maximum 3 at the beginning). Peak: an obligatory vowel. Coda: 0 to "},{"text":"4","bold":true},{"text":" consonants (maximum 4 at the end)."}]},{"text":[{"text":"Consonant cluster:","bold":true},{"text":" two or more consonants at the beginning or end of a syllable with no vowel between them, e.g. "},{"text":"spray","italic":true},{"text":" /spreɪ/, "},{"text":"street","italic":true},{"text":" /striːt/, "},{"text":"tasks","italic":true},{"text":" /tɑːsks/, "},{"text":"bagged","italic":true},{"text":" /bægd/."}]},{"text":[{"text":"Open syllable:","bold":true},{"text":" no coda (ends in the vowel), e.g. "},{"text":"slow","italic":true},{"text":" /sləʊ/, "},{"text":"tea","italic":true},{"text":" /tiː/. A CV syllable is open."}]},{"text":[{"text":"Closed syllable:","bold":true},{"text":" has a coda (ends in a consonant), e.g. "},{"text":"slap","italic":true},{"text":" /slæp/, "},{"text":"tag","italic":true},{"text":" /tæg/."}]},{"text":[{"text":"Minimal syllable:","bold":true},{"text":" a single sound preceded and followed by silence, e.g. "},{"text":"are","italic":true},{"text":" /ɑː/, "},{"text":"or","italic":true},{"text":" /ɔː/, "},{"text":"err","italic":true},{"text":" /ɜː/; also /m/ (agreement) and /ʃ/ (asking for silence). The dominant single-sound syllable is the "},{"text":"schwa /ə/","bold":true},{"text":", an unstressed vowel, as in "},{"text":"about","italic":true},{"text":" /əbaʊt/, "},{"text":"amiss","italic":true},{"text":" /əmɪs/."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Phonetically, a syllable has a "},{"text":"centre","bold":true},{"text":" with little or no obstruction to airflow and relative loudness (the vowel), surrounded by greater obstruction and less loudness (the consonants)."}]},{"text":[{"text":"Syllable structures (C = consonant, V = vowel):"}]}]},{"type":"table","header":[[{"text":"Structure"}],[{"text":"Examples"}]],"rows":[[[{"text":"V"}],[{"text":"I","italic":true},{"text":" /aɪ/, "},{"text":"eye","italic":true},{"text":", "},{"text":"oh","italic":true},{"text":" /əʊ/"}]],[[{"text":"CV"}],[{"text":"boy","italic":true},{"text":" /bɔɪ/, "},{"text":"no","italic":true}]],[[{"text":"VC"}],[{"text":"in","italic":true},{"text":" /ɪn/, "},{"text":"up","italic":true}]],[[{"text":"CVC"}],[{"text":"pick","italic":true},{"text":" /pɪk/, "},{"text":"sock","italic":true}]],[[{"text":"CCV"}],[{"text":"slow","italic":true},{"text":" /sləʊ/, "},{"text":"glue","italic":true}]],[[{"text":"CCVC"}],[{"text":"prayed","italic":true},{"text":" /preɪd/, "},{"text":"glued","italic":true}]],[[{"text":"CCVCC"}],[{"text":"prank","italic":true},{"text":" /præŋk/, "},{"text":"cracked","italic":true},{"text":" /krækt/"}]],[[{"text":"CCCV"}],[{"text":"spree","italic":true},{"text":" /spriː/, "},{"text":"straw","italic":true}]],[[{"text":"CCCVC"}],[{"text":"stretch","italic":true},{"text":" /stretʃ/"}]],[[{"text":"CCCVCC"}],[{"text":"sprint","italic":true},{"text":" /sprɪnt/"}]],[[{"text":"CVCCCC"}],[{"text":"waltzed","italic":true},{"text":" /wɒltst/"}]],[[{"text":"CCCVCCCC"}],[{"text":"strengths","italic":true},{"text":" /streŋkθs/"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Count sounds, not letters: "},{"text":"eye","italic":true},{"text":" is one vowel sound (V); "},{"text":"cracked","italic":true},{"text":" ends in /kt/; "},{"text":"axe","italic":true},{"text":" is VCC; "},{"text":"through","italic":true},{"text":" is CCV."}]},{"text":[{"text":"Restrictions on onset and coda:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"/ŋ/ and /ʒ/ do "},{"text":"not","bold":true},{"text":" occur in the onset (so /ŋɔɪz/ is unacceptable)."}]},{"text":[{"text":"/h/, /r/, /w/ and /j/ do "},{"text":"not","bold":true},{"text":" occur in the coda (so /lɔːw/ and /hɑːsh/ are unacceptable)."}]},{"text":[{"text":"A "},{"text":"three-consonant onset","bold":true},{"text":" always has "},{"text":"/s/","bold":true},{"text":" as the first consonant, "},{"text":"/p/, /t/ or /k/","bold":true},{"text":" as the second, and "},{"text":"/l/, /r/, /w/ or /j/","bold":true},{"text":" as the third: "},{"text":"strike","italic":true},{"text":" /straɪk/, "},{"text":"square","italic":true},{"text":" /skweə/, "},{"text":"stew","italic":true},{"text":" /stjuː/, "},{"text":"sprite","italic":true},{"text":" /spraɪt/. Any other three-consonant onset is deviant and unacceptable in English."}]}]}]},{"text":[{"text":"Trap: the compulsory constituent of a syllable is the "},{"text":"vowel","bold":true},{"text":", not the consonant, the schwa or a pause. The maximum onset is "},{"text":"3","bold":true},{"text":", not 4; four consonants are possible only in the coda ("},{"text":"strengths","italic":true},{"text":")."}]}]}]},{"number":"3.2","title":"Stress, prominence and levels of stress","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stress:","bold":true},{"text":" the relative force of articulation or degree of auditory prominence of one syllable over others in a polysyllabic word. The prominence of one syllable over the others in a word is a function of "},{"text":"stress","bold":true},{"text":"."}]},{"text":[{"text":"Stress can fall on any syllable. First (initial): "},{"text":"REAson, MESsage, JAnitor","italic":true},{"text":". Second: "},{"text":"anNOUNcer, inTENtion, creAtion","italic":true},{"text":". Final: "},{"text":"reCORD","italic":true},{"text":" (verb), "},{"text":"agGRIEVED, reLENT","italic":true},{"text":"."}]},{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 11, $study_guide$xt":[{"text":"Two perspectives on stress:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production:","bold":true},{"text":" the speaker uses more muscular energy for stressed syllables."}]},{"text":[{"text":"Perception:","bold":true},{"text":" all stressed syllables share one thing, "},{"text":"prominence","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Four factors of prominence:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Loudness:","bold":true},{"text":" stressed syllables are louder."}]},{"text":[{"text":"Length:","bold":true},{"text":" a longer syllable is heard as stressed."}]},{"text":[{"text":"Pitch:","bold":true},{"text":" the rise and fall of the tone of the voice, from the speed of vocal cord vibration. A syllable said on a noticeably higher pitch than its neighbours is heard as prominent."}]},{"text":[{"text":"(Vowel) quality:","bold":true},{"text":" a syllable with a "},{"text":"strong","bold":true},{"text":" vowel quality attracts stress."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Pitch","bold":true},{"text":" produces the "},{"text":"strongest effect","bold":true},{"text":" on stress placement of all four factors."}]},{"text":[{"text":"Strong vowels","bold":true},{"text":" (usually stressed): long vowels /iː, ɜː, ɑː, uː, ɔː/, diphthongs and triphthongs. "},{"text":"Weak vowels","bold":true},{"text":" (usually unstressed): /ə/, /ɪ/, /ʊ/. Examples: "},{"text":"aBOUT, rePORT, reUnion, FURther, anNOYance, TEAcher","italic":true},{"text":"."}]},{"text":[{"text":"Marking stress:","bold":true},{"text":" a mark (ˈ) at the beginning of the stressed syllable, or capital letters: "},{"text":"ˈrebel","italic":true},{"text":" REbel, "},{"text":"acˈcount","italic":true},{"text":" acCOUNT, "},{"text":"ocˈcasion","italic":true},{"text":" ocCAsion, "},{"text":"biˈnoculars","italic":true},{"text":" biNOculars."}]},{"text":[{"text":"Three levels of stress:","bold":true}]}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Mark"}],[{"text":"Description"}],[{"text":"Examples"}]],"rows":[[[{"text":"Primary"}],[{"text":"raised stroke (ˈ)"}],[{"text":"the strongest stress; results from pitch movement within a word"}],[{"text":"withDRAWal, condemNAtion, POSTman, toGEther, inviTAtion"}]],[[{"text":"Secondary"}],[{"text":"subscript (ˌ)"}],[{"text":"weaker than primary, stronger than unstressed"}],[{"text":"first syllable of "},{"text":"millionaire","italic":true},{"text":" /ˌmɪljəˈneə/, "},{"text":"cigarette","italic":true},{"text":" /ˌsɪgəˈret/; second syllable of "},{"text":"congratulation","italic":true},{"text":", "},{"text":"responsibility","italic":true}]],[[{"text":"Zero (unstressed)"}],[{"text":"none"}],[{"text":"no recognisable prominence; weak vowels"}],[{"text":"first syllable of "},{"text":"retain, opinion","italic":true},{"text":"; middle of "},{"text":"intimate, custody","italic":true},{"text":"; last of "},{"text":"flavour, mother","italic":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A word usually has "},{"text":"one","bold":true},{"text":" primary-stressed syllable; longer words may add one secondary-stressed syllable and several unstressed ones."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Syllable and stress:","bold":true},{"text":" (a) stressed/accented = said with greater energy or breath force; unstressed/unaccented = not; (b) a stressed syllable is more prominent than the sounds around it; (c) word stress operates only on words of "},{"text":"more than one syllable","bold":true},{"text":". The schwa /ə/ and the "},{"text":"syllabic consonants /l, m, n/","bold":true},{"text":" usually occur in unstressed syllables ("},{"text":"about, bottle, cotton","italic":true},{"text":")."}]},{"text":[{"text":"Diphthongs","bold":true},{"text":" do "},{"text":"not","bold":true},{"text":" usually occur in unstressed syllables; the schwa, short vowels and syllabic consonants do."}]},{"text":[{"text":"The four factors usually work together, but prominence can come from only one or two."}]},{"text":[{"text":"Trap: "},{"text":"voice","bold":true},{"text":" (vocal cord vibration that separates /b/ from /p/) is "},{"text":"not","bold":true},{"text":" a factor of prominence; the four are loudness, length, pitch, quality."}]},{"text":[{"text":"Trap: zero stress means "},{"text":"unstressed","bold":true},{"text":" syllables. There is no \"tertiary\" stress."}]},{"text":[{"text":"Secondary stress often sits on the syllable that carried primary stress "},{"text":"before","bold":true},{"text":" a stress-moving affix was added: "},{"text":"reˈsponsible","italic":true},{"text":" becomes /rɪˌspɒnsɪˈbɪlɪti/, correctly marked "},{"text":"responsiˈbility","bold":true},{"text":", not reˈsponsibility."}]},{"text":[{"text":"Sentence stress:","bold":true},{"text":" content words (nouns, main verbs, adjectives) are usually stressed; "},{"text":"function words","bold":true},{"text":" ("},{"text":"the, of, and, a","italic":true},{"text":") are usually "},{"text":"unstressed","bold":true},{"text":" in connected speech, never \"always stressed\"."}]}]}]},{"number":"3.3","title":"Predicting stress: phonological and syntactic criteria","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"English stress is "},{"text":"free","bold":true},{"text":" (not fixed): it can fall on the first, second, third or last syllable, so many learners learn each word individually. Still, "},{"text":"three criteria","bold":true},{"text":" help predict it:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Phonological:","bold":true},{"text":" the number of syllables and their internal constitution (syllable structure, strong or weak vowels)."}]},{"text":[{"text":"Syntactic:","bold":true},{"text":" the word class (part of speech)."}]},{"text":[{"text":"Morphological:","bold":true},{"text":" the interna$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 12, $study_guide$l structure of the word (simple, compound or complex; affixes)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Stress is "},{"text":"not","bold":true},{"text":" predicted historically or semantically."}]},{"text":[{"text":"Phonological criterion:","bold":true},{"text":" weak syllables (/ə, ɪ, ʊ/) are unstressed; strong syllables (long vowels, diphthongs, triphthongs, consonant clusters) are stressed. With two strong vowels, the stronger gets primary stress, the other secondary. Six rules:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Disyllabic nouns:","bold":true},{"text":" short vowel in the final syllable → stress the "},{"text":"first","bold":true},{"text":" syllable: "},{"text":"TIcket, ASset, PREmise, FOcus, MOney, PIDgin, TODdler","italic":true},{"text":"."}]},{"text":[{"text":"Disyllabic nouns:","bold":true},{"text":" long vowel or diphthong in the final syllable → stress the "},{"text":"final","bold":true},{"text":" syllable: "},{"text":"esTATE, balLOON, canTEEN, maCHINE, rouTINE","italic":true},{"text":"."}]},{"text":[{"text":"Trisyllabic nouns:","bold":true},{"text":" a final syllable with a short vowel or the diphthong /əʊ/ does "},{"text":"not","bold":true},{"text":" attract stress: "},{"text":"toMORrow, anNOUNCEment, reJOINder, acCEPTance","italic":true},{"text":"."}]},{"text":[{"text":"Trisyllabic nouns:","bold":true},{"text":" a penultimate (second) syllable with a long vowel, a diphthong other than /əʊ/, or a consonant-cluster coda "},{"text":"is","bold":true},{"text":" stressed: "},{"text":"poTAto, syNOPsis, diSASter, torNAdo, arRIval, conJUNCtion","italic":true},{"text":"."}]},{"text":[{"text":"Disyllabic adjectives:","bold":true},{"text":" open final syllable or consonant-cluster coda on the final syllable → stress the "},{"text":"final","bold":true},{"text":" syllable: "},{"text":"seVERE, corRECT, diRECT, adHERE, aGHAST","italic":true},{"text":"."}]},{"text":[{"text":"Trisyllabic verbs:","bold":true},{"text":" final syllable with a short vowel or a one-consonant coda → stress the "},{"text":"second (penultimate)","bold":true},{"text":" syllable: "},{"text":"enCOUNter, imPREGnate, maRAUder, conSIder, soLIcit","italic":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Syntactic criterion:","bold":true},{"text":" in noun-verb (and noun-adjective) pairs, the "},{"text":"noun","bold":true},{"text":" takes stress on the "},{"text":"first","bold":true},{"text":" syllable and the "},{"text":"verb","bold":true},{"text":" on the "},{"text":"second","bold":true},{"text":":"}]}]},{"type":"table","header":[[{"text":"Noun (first syllable)"}],[{"text":"Verb/Adjective (second syllable)"}]],"rows":[[[{"text":"EXport"}],[{"text":"exPORT (V)"}]],[[{"text":"REcord"}],[{"text":"reCORD (V)"}]],[[{"text":"ABstract"}],[{"text":"absTRACT (V)"}]],[[{"text":"AUgust (N)"}],[{"text":"auGUST (Adj)"}]],[[{"text":"PREsent (Adj)"}],[{"text":"preSENT (V)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Exceptions","bold":true},{"text":" (same stress in more than one class): "},{"text":"PREsent","italic":true},{"text":" (N/Adj), "},{"text":"INterest","italic":true},{"text":" (N/V), "},{"text":"CHALlenge","italic":true},{"text":" (N/V), "},{"text":"miSTAKE","italic":true},{"text":" (N/V), "},{"text":"COMfort","italic":true},{"text":" (N/V), "},{"text":"reSPECT","italic":true},{"text":" (N/V), "},{"text":"HARvest","italic":true},{"text":" (N/V); "},{"text":"adVICE","italic":true},{"text":" (N), "},{"text":"adVISE","italic":true},{"text":" (V). So "},{"text":"challenge","italic":true},{"text":" is "},{"text":"CHALlenge/CHALlenge","bold":true},{"text":" as noun and verb."}]},{"text":[{"text":"Compound noun vs noun phrase:","bold":true},{"text":" a "},{"text":"compound noun","bold":true},{"text":" is stressed on the "},{"text":"first","bold":true},{"text":" element; a "},{"text":"noun phrase","bold":true},{"text":" is stressed on the "},{"text":"second (rightmost)","bold":true},{"text":" element."}]}]},{"type":"table","header":[[{"text":"Compound noun (first element)"}],[{"text":"Noun phrase (second element)"}]],"rows":[[[{"text":"GREENhouse (glass building for plants)"}],[{"text":"a green HOUSE (a house that is green)"}]],[[{"text":"BLACKbird"}],[{"text":"a black BIRD"}]],[[{"text":"ENGLISH-teacher"}],[{"text":"an English TEACHER"}]],[[{"text":"WHITE house"}],[{"text":"a white HOUSE"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A compound noun is a "},{"text":"single entity","bold":true},{"text":" whose meaning may or may not relate to its parts ("},{"text":"Facebook","italic":true},{"text":"). A noun phrase is "},{"text":"two separate syntactic elements","bold":true},{"text":", preceded by an article ("},{"text":"a/an","italic":true},{"text":"), in which the first element modifies the second."}]},{"text":[{"text":"Trap: \"based on syllable structure\" = "},{"text":"phonological","bold":true},{"text":"; \"based on word class\" = "},{"text":"syntactic","bold":true},{"text":"; \"based on internal structure/affixes\" = "},{"text":"morphological","bold":true},{"text":"."}]},{"text":[{"text":"Matching stress patterns","bold":true},{"text":" (a common exam task: pick the word with the same stress as the given one):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First syllable (like "},{"text":"ˈhumble","italic":true},{"text":"): "},{"text":"STANdard, SADdle, PUnish, MARvel, PREtext, COMpact","italic":true},{"text":" (noun), "},{"text":"ACtivist, COMpany","italic":true},{"text":"."}]},{"text":[{"text":"Second syllable (like "},{"text":"comˈplaint","italic":true},{"text":", "},{"text":"conˈcern","italic":true},{"text":"): "},{"text":"sucCESS, rePORT, reGRET, reTURN, comBINE","italic":true},{"text":" (verb), "},{"text":"ocCURrence, inSURance, amBItion, reACtion","italic":true},{"text":"; like "},{"text":"proˈfessor","italic":true},{"text":": "},{"text":"creAtor","itali$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 13, $study_guide$c":true},{"text":"."}]},{"text":[{"text":"Third syllable (like "},{"text":"indiˈcation","italic":true},{"text":"): "},{"text":"eduCAtion","italic":true},{"text":". Words ending in "},{"text":"-tion","bold":true},{"text":" stress the syllable "},{"text":"just before","bold":true},{"text":" the ending."}]},{"text":[{"text":"Like "},{"text":"ˈcapitalism","italic":true},{"text":": "},{"text":"REgionalism","italic":true},{"text":". The suffix "},{"text":"-ism","bold":true},{"text":" does not move stress, so the word keeps the stress of its base ("},{"text":"CApital, REgion","italic":true},{"text":")."}]}]}]}]}]},{"number":"3.4","title":"Predicting stress: the morphological criterion","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Words are morphologically "},{"text":"simple","bold":true},{"text":", "},{"text":"compound","bold":true},{"text":" or "},{"text":"complex","bold":true},{"text":"; each structure guides stress."}]},{"text":[{"text":"Simple words","bold":true},{"text":" (single-base morphemes): one meaningful unit, e.g. "},{"text":"table, glass, window, boy","italic":true},{"text":". Their stress is found phonologically or syntactically."}]},{"text":[{"text":"Compound words:","bold":true},{"text":" two words that can each exist independently. Written three ways:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"One word: "},{"text":"suitcase, blackboard, windscreen","italic":true},{"text":"."}]},{"text":[{"text":"Hyphenated: "},{"text":"fruit-cake, baby-sitter, mother-tongue","italic":true},{"text":"."}]},{"text":[{"text":"Two words with a space: "},{"text":"child care, credit card, income tax, heart attack","italic":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Compound stress rules","bold":true},{"text":" (determined by word class):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Compound nouns","bold":true},{"text":" (especially noun + noun): stress on the "},{"text":"first","bold":true},{"text":" element: "},{"text":"ˈhandbag, ˈguest house, ˈtea-party, ˈbookshelf, ˈcity mall","italic":true},{"text":"."}]},{"text":[{"text":"Compound adjectives","bold":true},{"text":" with an adjectival first element and "},{"text":"-ed","bold":true},{"text":" at the end: stress on the "},{"text":"second","bold":true},{"text":" element: "},{"text":"ill-ˈmannered, well-ˈbred, heavy-ˈhanded","italic":true},{"text":"."}]},{"text":[{"text":"Compounds whose first element is a "},{"text":"number","bold":true},{"text":" (ordinal or cardinal): stress on the "},{"text":"second","bold":true},{"text":" element: "},{"text":"two-ˈseater, five-ˈstar, second-ˈhand","italic":true},{"text":"."}]},{"text":[{"text":"Compound adverbs","bold":true},{"text":" (adverbial element + noun): stress on the "},{"text":"second","bold":true},{"text":" element: "},{"text":"up-ˈcountry, down-ˈstream, inside-ˈout","italic":true},{"text":"."}]},{"text":[{"text":"Compound verbs","bold":true},{"text":" with an adverbial first element: stress on the "},{"text":"final","bold":true},{"text":" element: "},{"text":"down-ˈsize, back-ˈpedal, ill-ˈtreat","italic":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Complex words:","bold":true},{"text":" two or more elements, formed by "},{"text":"affixation","bold":true},{"text":", e.g. "},{"text":"boys, unrepentant, disloyal, international, endearment","italic":true},{"text":". "},{"text":"Prefixes","bold":true},{"text":" go before the base ("},{"text":"un-","italic":true},{"text":" in "},{"text":"unpleasant","italic":true},{"text":"); "},{"text":"suffixes","bold":true},{"text":" go after ("},{"text":"-ness","italic":true},{"text":" in "},{"text":"fairness","italic":true},{"text":")."}]},{"text":[{"text":"Three types of affix by effect on stress:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Stress-bearing affixes:","bold":true},{"text":" the affix itself carries primary stress: "},{"text":"semi-","italic":true},{"text":" ("},{"text":"ˈsemicircle","italic":true},{"text":"), "},{"text":"-eer","italic":true},{"text":" ("},{"text":"engiˈneer","italic":true},{"text":"), "},{"text":"-aire","italic":true},{"text":" ("},{"text":"millioˈnaire","italic":true},{"text":"), "},{"text":"-ette","italic":true},{"text":" ("},{"text":"cigaˈrette","italic":true},{"text":")."}]},{"text":[{"text":"Stress-neutral affixes:","bold":true},{"text":" the word keeps its original stress: "},{"text":"un-","italic":true},{"text":" and "},{"text":"-ing","italic":true},{"text":" ("},{"text":"ˈpleasant","italic":true},{"text":" / "},{"text":"unˈpleasant","italic":true},{"text":"; "},{"text":"ˈmarket","italic":true},{"text":" / "},{"text":"ˈmarketing","italic":true},{"text":")."}]},{"text":[{"text":"Stress-moving affixes:","bold":true},{"text":" stress stays on the stem but shifts to a different syllable: "},{"text":"-ic","italic":true},{"text":" and "},{"text":"-ity","italic":true},{"text":" ("},{"text":"ˈmagnet","italic":true},{"text":" / "},{"text":"magˈnetic","italic":true},{"text":"; "},{"text":"ˈinfidel","italic":true},{"text":" / "},{"text":"infiˈdelity","italic":true},{"text":")."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"stress-conserving\" is "},{"text":"not","bold":true},{"text":" a type of affix. The three types are bearing, neutral and moving."}]},{"text":[{"text":"-ism","italic":true},{"text":" behaves as stress-neutral ("},{"text":"CApitalism, REgionalism","italic":true},{"text":"); "},{"text":"-ity","italic":true},{"text":" and "},{"text":"-tion","italic":true},{"text":" move stress to the syllable before them ("},{"text":"responsiˈbility","italic":true},{"text":", "},{"text":"indiˈcation","italic":true},{"text":")."}]},{"text":[{"text":"Compound nouns are the only compound type stressed on the first element; adjective, number, adverb and verb compounds all stress the "},{"text":"second","bold":tr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 14, $study_guide$ue},{"text":" element."}]}]}]},{"number":"3.5","title":"Intonation and the four tunes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Intonation:","bold":true},{"text":" the use of the "},{"text":"pitch of the voice","bold":true},{"text":" to convey meaning or syntactic information; the distinctive use of patterns of pitch or melody in an utterance; the rise and fall of the tone of the voice. Intonation in English is a matter of "},{"text":"sentence stress","bold":true},{"text":". It is the melody of speech."}]},{"text":[{"text":"No language is spoken in a monotone. "},{"text":"Tone:","bold":true},{"text":" the overall behaviour of pitch in speech."}]},{"text":[{"text":"Pitch changes are linguistic only when they affect meaning (the pitch changes of someone speaking while running are not): "},{"text":"You are travelling today","italic":true},{"text":" on a "},{"text":"falling","bold":true},{"text":" tone = statement; on a "},{"text":"rising","bold":true},{"text":" tone = question or doubt/surprise. Intonation in speech equals "},{"text":"punctuation","bold":true},{"text":" in writing."}]},{"text":[{"text":"Three functions of intonation:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Grammatical:","bold":true},{"text":" shows the communicative function of a sentence (statement, question, exclamation)."}]},{"text":[{"text":"Attitudinal:","bold":true},{"text":" betrays the speaker's emotion or attitude (disinterest, sarcasm, boredom; anger, excitement, impatience)."}]},{"text":[{"text":"Discourse:","bold":true},{"text":" guides turn-taking in conversation (end-of-utterance patterns differ from mid-utterance ones), and points to the focus and implied meanings. "},{"text":"Yes/no","italic":true},{"text":" on a falling tone = definiteness or finality; on a rising tone = interest or continuity."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Four intonation tunes:","bold":true},{"text":" falling, rising, falling-rising, rising-falling."}]},{"text":[{"text":"Falling tune","bold":true},{"text":", five uses:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Declarative statements:","bold":true},{"text":" "},{"text":"We shall travel tomorrow.","italic":true}]},{"text":[{"text":"Imperatives","bold":true},{"text":" (commands, instructions, advice): "},{"text":"Look at the blackboard.","italic":true}]},{"text":[{"text":"Wh-questions:","bold":true},{"text":" "},{"text":"What did you see? Where is your sister?","italic":true}]},{"text":[{"text":"Tag questions seeking confirmation:","bold":true},{"text":" "},{"text":"It is true, isn't it?","italic":true}]},{"text":[{"text":"Exclamations:","bold":true},{"text":" "},{"text":"How brilliant he is! What a horrible accident!","italic":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Rising tune","bold":true},{"text":", four uses:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Polar (yes/no) questions:","bold":true},{"text":" "},{"text":"Do you know his house? Can we go now?","italic":true}]},{"text":[{"text":"Polite requests","bold":true},{"text":" (interrogative or imperative form): "},{"text":"Kindly shut the door. Could you lend me some cash?","italic":true}]},{"text":[{"text":"Requests for repetition","bold":true},{"text":" (wh-question or echo question): "},{"text":"What did she say? Bisi has travelled?","italic":true}]},{"text":[{"text":"Tag questions seeking information:","bold":true},{"text":" "},{"text":"He has left, hasn't he?","italic":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Falling-rising tune","bold":true},{"text":", two uses:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Counting or listing:","bold":true},{"text":" each item takes a fall-rise until the last, which falls: "},{"text":"We can invite students, lawyers, soldiers, politicians and workers too.","italic":true}]},{"text":[{"text":"Sentence modifiers (adverbials):","bold":true},{"text":" "},{"text":"Fortunately, it did not rain. Clearly, she cannot drive well.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: wh-questions take a "},{"text":"falling","bold":true},{"text":" tune; yes/no questions take a "},{"text":"rising","bold":true},{"text":" tune. A wh-question rises only when asking for repetition."}]},{"text":[{"text":"Trap: tag questions take "},{"text":"both","bold":true},{"text":" tunes. Falling = seeking confirmation (you already believe it). Rising = seeking information (you really do not know)."}]},{"text":[{"text":"Trap: \"statement, question or exclamation\" = "},{"text":"grammatical","bold":true},{"text":" function; \"emotion or attitude\" = "},{"text":"attitudinal","bold":true},{"text":"; \"turn-taking\" = "},{"text":"discourse","bold":true},{"text":". \"Accentual\" refers to stress placement, not sentence type."}]},{"text":[{"text":"Trap: stress is prominence of a syllable within a "},{"text":"word","bold":true},{"text":"; intonation (not \"rhythm\") is pitch movement over an "},{"text":"utterance","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"rising-falling","bold":true},{"text":" tune is the fourth tune; it is typically used to show strong feeling, such as approval, disapproval or surprise. Declaratives take the falling tune, not rise-fall."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Suprasegmentals = stress and intonation, above the segments (consonants and vowels)."}]},{"text":[{"text":"Syllable = onset (optional) + peak (compulsory vowel) + coda (optional): "},{"text":"C0-3VC0-4","bold":true},{"text":"."}]},{"text":[{"text":"Three-consonant onset = /s/ + /p, t, k/ + /l, r, w, j/. /ŋ, ʒ/ never start; /h, r, w, j/ never end a syllable."}]},{"text":[{"text":"Open syllable = no coda (CV); closed = has coda. Minimal syllable = one sound."}]},{"text":[{"text":"Stress = prominence of $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 15, $study_guide$one syllable; four factors: loudness, length, pitch (strongest), quality. Not voice."}]},{"text":[{"text":"Three levels: primary (ˈ), secondary (ˌ, subscript), zero (unstressed). One primary stress per word."}]},{"text":[{"text":"English stress is free; predict it phonologically, syntactically, morphologically."}]},{"text":[{"text":"Noun = first syllable, verb = second (EXport/exPORT); exception: CHALlenge (N/V). Compound noun = first element; noun phrase = second."}]},{"text":[{"text":"Affixes: stress-bearing (-eer, -aire, -ette), stress-neutral (un-, -ing, -ism), stress-moving (-ic, -ity)."}]},{"text":[{"text":"Intonation = pitch for meaning; functions: grammatical, attitudinal, discourse. Falling: statements, commands, wh-questions, confirming tags, exclamations. Rising: yes/no questions, polite requests, repetition, information tags. Fall-rise: lists, adverbials."}]}]}],"theory":{"itemId":"ef210d0b-f9ba-5347-8a99-74e606af4cb3","question":[{"type":"paragraph","text":[{"text":"Stress is perceptually marked by four main features. List them and explain how each indicates stress."}]}]},"practice":[{"topic":"Speaking Skills II: Syllable, Stress, Intonation","named":false}]}},{"kind":"note","itemId":"7bcafa95-dda2-5e3e-8185-f144c7a52c88","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Reading Skills I: Strategies for Effective Reading","body":"What reading is and the 4 misconceptions; the 3 types of reading (skimming, scanning, study reading) and LEARNER; the 8 bad reading habits; the 3 strategies for efficient reading (preview, read with intent, review) and the steps under each.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What reading is and the 4 misconceptions; the 3 types of reading (skimming, scanning, study reading) and LEARNER; the 8 bad reading habits; the 3 strategies for efficient reading (preview, read with intent, review) and the steps under each."}],"lessons":[{"number":"4.1","title":"What reading is; reading efficiency and misconceptions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading:","bold":true},{"text":" the process of translating written or printed symbols and letters into words and sentences which convey meaning to the individual. The main purpose of reading is to "},{"text":"comprehend","bold":true},{"text":" a written material."}]},{"text":[{"text":"Reading involves "},{"text":"both the eyes and the brain","bold":true},{"text":". The "},{"text":"eyes","bold":true},{"text":" do the physical task of linking the letters and symbols to know what the author "},{"text":"says","bold":true},{"text":"; the "},{"text":"brain","bold":true},{"text":" interprets what the author "},{"text":"means","bold":true},{"text":". Essential to reading: written or printed signs, the eyes, the brain. "},{"text":"Not","bold":true},{"text":" essential: the articulatory (vocal) system."}]},{"text":[{"text":"Reading is a "},{"text":"developmental process","bold":true},{"text":" which can never be completely mastered. Many students get no instruction in reading and so develop unhealthy habits."}]},{"text":[{"text":"Reading efficiency:","bold":true},{"text":" the acquisition of proper reading skills which facilitate the efficient physical and mental processing of written materials; the relationship between the physical aspects of reading and reading speed, which influences comprehension."}]},{"text":[{"text":"Target speed: about "},{"text":"600 words per minute","bold":true},{"text":" by the end of your programme. Efficiency improves only through "},{"text":"constant reading practice","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 misconceptions about reading","bold":true},{"text":" (and the truth):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"You need to read everything.","bold":true},{"text":" No: read selectively, depending on your purpose, the nature of the material and your familiarity with it."}]},{"text":[{"text":"Everything on a page is equally important.","bold":true},{"text":" No: each text mixes important and not-so-important information; sort and evaluate what you need."}]},{"text":[{"text":"Everything can be read the same way.","bold":true},{"text":" No: purpose determines what you read, how fast or carefully, what you attend to and what you skip. Vary your technique to suit purpose and material."}]},{"text":[{"text":"Everything we read is \"true\".","bold":true},{"text":" No: read with a critical, questioning eye and some scepticism. Consider the "},{"text":"authority of the author","bold":true},{"text":" and the "},{"text":"author's purpose","bold":true},{"text":"; distinguish "},{"text":"facts","bold":true},{"text":" from "},{"text":"opinions, value judgements and generalisations","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"What determines how (and how fast) you read:","bold":true},{"text":" the "},{"text":"nature","bold":true},{"text":" of the material, your "},{"text":"purpose","bold":true},{"text":", and your "},{"text":"familiarity","bold":true},{"text":" with the topic. A newspaper is read once; a study text is studied repeatedly. The "},{"text":"author","bold":true},{"text":" and the "},{"text":"publisher","bold":true},{"text":" do not prescribe how you read. Trap: \"the author's prescription\" is the odd one out among factors deciding reading speed (the reader, who varies speed to suit the material, does count as a factor). Trap: asked what determines "},{"text":"how a material is read","bold":true},{"text":", choose "},{"text":"its nature","bold":true},{"text":" (newspaper once, study text repeatedly), not the reader, author or publisher."}]},{"text":[{"text":"A passage in "},{"text":"technical or difficult language","bold":true},{"text":" is best read at a "},{"text":"slow pace","bold":true},{"text":"."}]},{"text":[{"text":"Benefits of reading:","bold":true},{"text":" it enlarges your vocabulary and improves you$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 16, $study_guide$r listening, speaking and writing skills. It does "},{"text":"not","bold":true},{"text":" diminish your speech ability."}]},{"text":[{"text":"Critical reading (misconception 4) also helps in examinations that ask you to "},{"text":"apply, connect and evaluate","bold":true},{"text":" ideas."}]}]}]},{"number":"4.2","title":"Types of reading: skimming, scanning, study reading","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stages of reading development:","bold":true},{"text":" early primary school stresses word recognition and meaning: "},{"text":"\"learning to read\"","bold":true},{"text":". From mid-primary and junior secondary school the emphasis shifts to silent reading for comprehension: "},{"text":"\"reading to learn\"","bold":true},{"text":". In secondary school and higher institutions reading is used to learn facts and concepts and acquire new vocabulary and information."}]},{"text":[{"text":"Different "},{"text":"purposes","bold":true},{"text":" give different types of reading. Three types:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Skimming:","bold":true},{"text":" looking at the content quickly to get the "},{"text":"overall (general) idea","bold":true},{"text":". You look at the title and author, the blurb at the back (or the abstract of an article), the table of contents, preface and foreword, then the subtitles, tables, charts and the topic sentences of each paragraph, without bothering with details. You are "},{"text":"not","bold":true},{"text":" looking for specific information."}]},{"text":[{"text":"Scanning:","bold":true},{"text":" running the eyes quickly through the material in search of a "},{"text":"particular piece of specific information","bold":true},{"text":", or to see whether the material is relevant to your purpose. You ignore irrelevant details. You locate the section in the "},{"text":"table of contents or index","bold":true},{"text":", then read the indicated pages. In scanning, the "},{"text":"index","bold":true},{"text":" can be very important."}]},{"text":[{"text":"Study reading:","bold":true},{"text":" an "},{"text":"intensive","bold":true},{"text":" kind of reading: a thorough examination of the material and a critical analysis of the issues raised; reading to gather information that will translate to "},{"text":"knowledge","bold":true},{"text":". Guided by the acronym "},{"text":"LEARNER","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"LEARNER","bold":true},{"text":" (for productive study reading):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"L","bold":true},{"text":"ay out the purpose for reading."}]},{"text":[{"text":"E","bold":true},{"text":"xamine all parts of the material."}]},{"text":[{"text":"A","bold":true},{"text":"sk questions about each subheading during the study."}]},{"text":[{"text":"R","bold":true},{"text":"ead all materials on the topic to find answers to the set-out questions."}]},{"text":[{"text":"N","bold":true},{"text":"ote names, places, dates, events, directions and labels while reading."}]},{"text":[{"text":"E","bold":true},{"text":"ase away from studying one subject before starting another."}]},{"text":[{"text":"R","bold":true},{"text":"eview notes and materials before a test or a discussion."}]}]}],"explainMore":[{"type":"table","header":[[],[{"text":"Skimming"}],[{"text":"Scanning"}]],"rows":[[[{"text":"Goal"}],[{"text":"General idea of the whole"}],[{"text":"One specific piece of information"}]],[[{"text":"Tool"}],[{"text":"Title, blurb, contents, headings, topic sentences"}],[{"text":"Index or contents, then the pages"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"have a general idea of the topic\" = skimming; \"get specific information\" = scanning. \"Looking for specific details\" is the one thing skimming does "},{"text":"not","bold":true},{"text":" involve."}]},{"text":[{"text":"Trap: \"spinning\" and \"exploring\" are "},{"text":"not","bold":true},{"text":" types of reading."}]},{"text":[{"text":"LEARNER is a "},{"text":"mnemonic","bold":true},{"text":"; REARER, REALER and NEARER are distractors."}]}]}]},{"number":"4.3","title":"Reading deficiencies (bad reading habits)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading "},{"text":"speed","bold":true},{"text":" is directly related to "},{"text":"comprehension","bold":true},{"text":". Bad habits lead to slow reading with poor comprehension. Reading should involve no other muscles except those of the eyes."}]}]},{"type":"paragraph","text":[{"text":"8 bad reading habits:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Word-by-word reading:","bold":true},{"text":" emphasises word recognition and sounding out every word; slow and laborious."}]},{"text":[{"text":"Vocalisation:","bold":true},{"text":" moving the lips or any other vocal apparatus (tongue, throat, vocal cords) while reading; whispering to yourself, with or without audible sound. Comes from an emphasis on word recognition; reduces rate and comprehension."}]},{"text":[{"text":"Sub-vocalisation:","bold":true},{"text":" pronouncing the words in your mind with "},{"text":"no part of the vocal apparatus moving","bold":true},{"text":". Hinders comprehension. Written words represent both a sound system and an idea system; you need not go through the sounds to reach the ideas."}]},{"text":[{"text":"Moving the head from side to side:","bold":true},{"text":" stops the eyes focusing fully; divides attention; unnecessary and wasteful."}]},{"text":[{"text":"Finger-pointing:","bold":true},{"text":" pointing with a finger or any object to the words. The eyes naturally take in whole phrases and sentences; pointing forces them word by word."}]},{"text":[{"text":"Regression:","bold":true},{"text":" glancing "},{"text":"back","bold":true},{"text":" to re-read words, phrases and sentences. Usually caused by "},{"text":"lack of concentration","bold":tr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 17, $study_guide$ue},{"text":"; corrected by concentrating. Some regression is sometimes necessary, but "},{"text":"excessive","bold":true},{"text":" regression hinders comprehension."}]},{"text":[{"text":"Short span of recognition:","bold":true},{"text":" "},{"text":"span of recognition","bold":true},{"text":" = the number of words you can recognise while your eyes are fixed at one point. A poor reader recognises one or two words per glance; a good reader has a "},{"text":"wide","bold":true},{"text":" span and takes in several words."}]},{"text":[{"text":"Erratic eye movement:","bold":true},{"text":" eyes moving across the line haphazardly instead of rhythmically. Good eyes move from the "},{"text":"middle of one phrase to the middle of the next","bold":true},{"text":", in tune with the syntactic arrangement of the line."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Habits 7 and 8 (narrow span and erratic movement) need "},{"text":"continual practice over time","bold":true},{"text":" to correct."}]},{"text":[{"text":"Eye movement terms:","bold":true},{"text":" the eyes do not glide along a line; they move in little jumps and stops. The forward jumps are "},{"text":"saccadic","bold":true},{"text":" movements; the backward glances are "},{"text":"regressive","bold":true},{"text":" movements. Both are "},{"text":"natural","bold":true},{"text":" reading movements; regression is a deficiency only when excessive. Trap: velaric, glottalic and pulmonic are airstream mechanisms in speech, not eye movements."}]},{"text":[{"text":"Trap: "},{"text":"a wide span of recognition","bold":true},{"text":" marks a "},{"text":"good","bold":true},{"text":" reader; it is not a bad habit."}]},{"text":[{"text":"Trap: the backward movement of the eyes is "},{"text":"regression","bold":true},{"text":", not \"backwarding\"."}]}]}]},{"number":"4.4","title":"Strategy 1: Preview before reading","mustKnow":[{"type":"paragraph","text":[{"text":"The strategies for efficient reading fall into "},{"text":"3 major parts","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Preview before reading:","bold":true},{"text":" connect to your experience; decide what you need to know."}]},{"text":[{"text":"Read with intent:","bold":true},{"text":" search for key elements; highlight key points; annotate your impressions."}]},{"text":[{"text":"Review after reading:","bold":true},{"text":" review and evaluate what has been read."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Previewing is the first step","bold":true},{"text":" in reading a passage. Never start reading without first "},{"text":"skimming","bold":true},{"text":"; skimming belongs to the "},{"text":"preview","bold":true},{"text":" stage. Previewing familiarises you with the content and organisation, connects the material to your experience, helps you decide what you need to know, builds interest and concentration, and gives a mental outline before you read."}]}]},{"type":"paragraph","text":[{"text":"7 steps in previewing:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Check the "},{"text":"title, subtitles and author","bold":true},{"text":"."}]},{"text":[{"text":"Read the "},{"text":"introduction and the first paragraph","bold":true},{"text":" (where the author gives the general idea)."}]},{"text":[{"text":"Read "},{"text":"each heading and the first sentence","bold":true},{"text":" after it (headings together form a mini-outline)."}]},{"text":[{"text":"Read the "},{"text":"first sentence in a few paragraphs","bold":true},{"text":" on each page (when there are no headings)."}]},{"text":[{"text":"Examine all "},{"text":"photographs, charts, tables and diagrams","bold":true},{"text":"."}]},{"text":[{"text":"Read the "},{"text":"conclusion or summary","bold":true},{"text":" (a conclusion signals the end; a summary condenses the whole)."}]},{"text":[{"text":"Read any "},{"text":"end-of-assignment questions","bold":true},{"text":" (they show what is important and what you will be expected to know)."}]}]},{"type":"paragraph","text":[{"text":"Connect the material to your own experience (3 suggestions):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Think of "},{"text":"familiar situations","bold":true},{"text":" similar to the one in the material; note them in a journal or jotter."}]},{"text":[{"text":"Ask questions and answer them","bold":true},{"text":"; this recalls similar events that illuminate the content."}]},{"text":[{"text":"Allow your mind to jump","bold":true},{"text":" from one idea to another; write in your jotter or work with a friend."}]}]},{"type":"paragraph","text":[{"text":"Decide what you need to know and remember:","bold":true},{"text":" reading only because \"I've been told to read it\" leaves little behind, just as you cannot describe a twenty-naira note despite handling many. Decide first what you need to know, then turn the preview (title, headings, first paragraph, first sentences, subtitles) into "},{"text":"questions","bold":true},{"text":" you answer as you read. This strengthens comprehension and recall."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the first step in reading a passage is to "},{"text":"preview","bold":true},{"text":" it, not to summarise, edit or appreciate it. Summarising comes after reading."}]},{"text":[{"text":"Trap: skimming is classified under "},{"text":"preview before reading","bold":true},{"text":", not under reading with intent or review after reading."}]}]}]},{"number":"4.5","title":"Strategies 2 and 3: Read with intent; review after reading","mustKnow":[{"type":"paragraph","text":[{"text":"Read with intent.","bold":true},{"text":" Comprehension is usually gradual; active reading is actively searching for ideas and separating important from unimportant ones. You may need to read a material more than once. Three activities:"}]},{"type":"pa$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 18, $study_guide$ragraph","text":[{"text":"(a) Search for 5 key elements:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The meaning of the "},{"text":"title and subtitles","bold":true},{"text":" (the title announces the topic and often the author's point of view; sometimes its meaning is clear only after reading everything)."}]},{"text":[{"text":"The "},{"text":"introduction","bold":true},{"text":": the opening paragraph; gives background, announces the focus, captures attention."}]},{"text":[{"text":"The "},{"text":"author's main point","bold":true},{"text":": in the "},{"text":"thesis statement","bold":true},{"text":", the one big idea the whole piece explores, usually in the "},{"text":"first or second paragraph","bold":true},{"text":"; sometimes elsewhere or merely implied."}]},{"text":[{"text":"The "},{"text":"support and explanation","bold":true},{"text":": the body; each paragraph has a "},{"text":"topic sentence","bold":true},{"text":" that explains an aspect of the thesis."}]},{"text":[{"text":"The "},{"text":"conclusion","bold":true},{"text":": closes the piece; may restate the main point, offer ideas for further thought or suggest future directions."}]}]},{"type":"paragraph","text":[{"text":"Spelling errors are not a key element.","bold":true}]},{"type":"paragraph","text":[{"text":"(b) Highlight key points","bold":true},{"text":" (read with a highlighter or pen in hand), 4 rules:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Decide what kinds of information to highlight (the task after reading decides this)."}]},{"text":[{"text":"Read first, then highlight","bold":true},{"text":" (prevents too much highlighting)."}]},{"text":[{"text":"Be selective","bold":true},{"text":" (makes important points stand out)."}]},{"text":[{"text":"Highlight key elements, words and phrases: the "},{"text":"thesis statement, topic sentences","bold":true},{"text":" and everything related to the thesis."}]}]},{"type":"paragraph","text":[{"text":"(c) Annotate your impressions.","bold":true},{"text":" "},{"text":"Annotation","bold":true},{"text":" = jotting down personal ideas about the material; your response to the author's ideas, written in the "},{"text":"margin","bold":true},{"text":": questions, agreement, disagreement, surprise, phrases summarising important points. 5 things to annotate:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Important points (e.g. the thesis statement) that prompt personal responses."}]},{"text":[{"text":"Sections you need further information on."}]},{"text":[{"text":"Sections where the author reveals his or her reasons for writing."}]},{"text":[{"text":"Ideas you agree with, disagree with or question."}]},{"text":[{"text":"Any "},{"text":"inconsistency","bold":true},{"text":" on the author's part."}]}]},{"type":"paragraph","text":[{"text":"Review after reading.","bold":true},{"text":" Do not simply close the book. Spend a few minutes reviewing and evaluating, "},{"text":"immediately","bold":true},{"text":" after reading, to increase what you remember. The "},{"text":"same steps used to preview are used to review","bold":true},{"text":". Goal: touch on each main point once more. Write a "},{"text":"summary","bold":true},{"text":" from the highlighted items and annotations (a start if you must later write an essay). Pay attention to "},{"text":"3 things","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"heading","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"highlighted or underlined items","bold":true},{"text":" that point to the main ideas."}]},{"text":[{"text":"The "},{"text":"annotated items","bold":true},{"text":" on the margin."}]}]},{"type":"paragraph","text":[{"text":"References are not part of the review.","bold":true}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why reading can be difficult:","bold":true},{"text":" the topic is uninteresting, you cannot \"connect\" with the author, or the style is confusing. You will not experience much difficulty if you "},{"text":"follow the appropriate steps","bold":true},{"text":" (preview, read with intent, review)."}]},{"text":[{"text":"Graphic organiser:","bold":true},{"text":" a diagram of the structure of the main points in a material; an active way to connect and review major ideas. It must include all the key elements. Helps when a material is hard."}]},{"text":[{"text":"With persistence and practice you gain speed, read more actively, and improve comprehension and the rate and depth of recollection. Reading is a conscious activity requiring total concentration."}]},{"text":[{"text":"Trap: annotation is "},{"text":"personal response","bold":true},{"text":" in the margin; highlighting is "},{"text":"marking the text","bold":true},{"text":". Both feed the review summary."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading = translating written/printed symbols into meaning; eyes (what the author says) + brain (what the author means); purpose: comprehension."}]},{"text":[{"text":"Target about 600 words per minute; efficiency grows only through constant practice."}]},{"text":[{"text":"4 misconceptions: read everything; everything equally important; everything read the same way; everything in print is true."}]},{"text":[{"text":"How you read depends on nature of material, purpose and familiarity, never the author or publisher."}]},{"text":[{"text":"Skimming = general idea; scanning = specific information (index); study reading = intensive, guided by LEARNER."}]},{"text":[{"text":"8 bad habits: word-by-word, vocalisation, sub-vocalisation, head movement, finger-pointing, regression, short span of recognition, erratic eye movement. Saccadic and regressive movements are natural."}]},{"text":[{"text":"3 strategies: preview (first step; 7 steps; skimming belongs here), read with intent (5 key elements, 4 highlighting rules,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 19, $study_guide$ 5 things to annotate), review (heading, highlights, annotations)."}]},{"text":[{"text":"Difficulty: uninteresting topic, no connection with the author, confusing style; a graphic organiser helps."}]}]}],"theory":{"itemId":"89869c2e-9fb3-5179-b521-a6966386ef84","question":[{"type":"paragraph","text":[{"text":"Differentiate between skimming and scanning, and list four bad reading habits, stating why each is not recommended."}]}]},"practice":[{"topic":"Reading Skills I: Effective Reading Strategies","named":false}]}},{"kind":"note","itemId":"dc41bf63-45f6-5e55-9dfe-8b299a625cba","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Reading Skills II: Comprehension and Summary","body":"How to study a comprehension passage in stages (preview, first reading, second reading); the two major question types (MCQ and Traditional) and how to answer each; the four categories of comprehension questions; what a summary, synopsis and abstract are; the rules and the four steps for writing a summary.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"How to study a comprehension passage in stages (preview, first reading, second reading); the two major question types (MCQ and Traditional) and how to answer each; the four categories of comprehension questions; what a summary, synopsis and abstract are; the rules and the four steps for writing a summary."}],"lessons":[{"number":"5.1","title":"Studying a comprehension passage","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading","bold":true},{"text":" involves the eyes and the brain and is fundamental to acquiring knowledge. To understand a comprehension passage fully, study its components carefully and methodically."}]},{"text":[{"text":"Preview first:","bold":true},{"text":" previewing prepares you to study the passage in a \"questioning\" manner, as if searching for something. Turn the title into a question: \"The Causes of Election Violence\" becomes \"What are the causes of election violence?\""}]},{"text":[{"text":"Read the passage more than once.","bold":true},{"text":" This is the key habit for studying a comprehension passage effectively. A passage is best understood when it is read "},{"text":"more than once","bold":true},{"text":" (not simply \"once\", \"twice\" or \"thrice\")."}]},{"text":[{"text":"Match your speed to the passage:","bold":true},{"text":" your reading speed should correspond to how easy or difficult the language is."}]}]},{"type":"table","header":[[{"text":"Passage language"}],[{"text":"Speed"}],[{"text":"Reason"}]],"rows":[[[{"text":"Technical or difficult"}],[{"text":"Slow"}],[{"text":"To assimilate the peculiar vocabulary"}]],[[{"text":"Fairly familiar"}],[{"text":"Faster"}],[{"text":"Easier to follow"}]]]},{"type":"paragraph","text":[{"text":"The two stages of reading:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"First reading:","bold":true},{"text":" done "},{"text":"rapidly","bold":true},{"text":", whatever the nature of the passage, to get a "},{"text":"general impression of the central ideas","bold":true},{"text":". You gain insight into:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"What the writer's "},{"text":"tone","bold":true},{"text":" suggests about his or her "},{"text":"attitude","bold":true},{"text":" to the topic."}]},{"text":[{"text":"What the writer is trying to "},{"text":"achieve","bold":true},{"text":": to persuade, inform, educate, frighten or annoy the reader (the purpose)."}]},{"text":[{"text":"The "},{"text":"theme","bold":true},{"text":" or central idea of the passage."}]}]}]},{"text":[{"text":"Second reading:","bold":true},{"text":" done at a "},{"text":"much slower pace","bold":true},{"text":". Here you isolate the "},{"text":"main ideas from the minor ones","bold":true},{"text":", the "},{"text":"subjective from the objective","bold":true},{"text":", and the "},{"text":"direct from the indirect","bold":true},{"text":". It demands careful attention to details of the general ideas found in the first reading. Focus on:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sentences which "},{"text":"summarise","bold":true},{"text":" an idea or ideas."}]},{"text":[{"text":"Examples or illustrations","bold":true},{"text":"."}]},{"text":[{"text":"Statements which give a clue to the writer's "},{"text":"viewpoint","bold":true},{"text":"."}]},{"text":[{"text":"Statements which tend to "},{"text":"suggest ideas","bold":true},{"text":" to you."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First reading = fast, big picture (tone, purpose, theme). Second reading = slow, details (main vs minor, salient points). Exams swap these: if an option says the first reading is \"slow and detailed\", it is wrong."}]},{"text":[{"text":"A passage on \"The Michael Jackson Saga\" can be raced through; \"Globalist Action and the African Psyche\" must be read slowly. The difference is the difficulty of the language, not the length."}]},{"text":[{"text":"The four focus points of the second reading help you recognise the "},{"text":"salient points","bold":true},{"text":" (the most important ideas) of the passage."}]},{"text":[{"text":"Order: preview, first (rapid) reading, second (slow) reading, then answer the questions."}]}]}]},{"number":"5.2","title":"Answering the questions: MCQ and Traditional Type","mustKnow":[{"type":"paragraph","text":[{"text":"Three things comprehension passages do:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"They require you to "},{"text":"analyse","bold":true},{"text":" the contents of the passage."}]},{"text":[{"text":"They test your understanding by demanding a "},{"text":"summary of the salient points","bold":true},{"text":" or ideas."}]},{"text":[{"text":"They demand an "},{"text":"in-depth study","bold":true},{"text":" so that you can "},{"text":"infer","bold":true},{"text":" information that is not presented d$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 20, $study_guide$irectly (implied, suggested or subtly indicated)."}]}]},{"type":"paragraph","text":[{"text":"Two major types of comprehension question:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Multiple Choice Questions (MCQ):","bold":true},{"text":" a "},{"text":"fast mode","bold":true},{"text":" of testing understanding. The alternatives are carefully designed to "},{"text":"disguise","bold":true},{"text":" the answer, which you obtain through a "},{"text":"process of elimination","bold":true},{"text":"."}]},{"text":[{"text":"Traditional Type Questions:","bold":true},{"text":" questions which require you to give answers "},{"text":"in your own words","bold":true},{"text":", e.g. \"What do you suppose is the writer's attitude towards the subject matter?\", \"What is your impression of the writer's viewpoint?\", \"In one sentence, summarise the central idea of the passage.\""}]}]},{"type":"paragraph","text":[{"text":"4 clues to answering MCQ:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Never mark more than one answer.","bold":true}]},{"text":[{"text":"Ensure that "},{"text":"all other options are incorrect","bold":true},{"text":" before marking your answer."}]},{"text":[{"text":"Attempt the question through a "},{"text":"process of elimination","bold":true},{"text":", discarding the incorrect answers."}]},{"text":[{"text":"There is "},{"text":"usually a correct answer","bold":true},{"text":" unless otherwise stated."}]}]},{"type":"paragraph","text":[{"text":"4 features of MCQ options:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Some answers are "},{"text":"suggested by the writer but not confirmed","bold":true},{"text":" in the text."}]},{"text":[{"text":"Some answers are "},{"text":"only partly correct","bold":true},{"text":"."}]},{"text":[{"text":"Some answers are "},{"text":"logically true but not specifically mentioned","bold":true},{"text":" in the text."}]},{"text":[{"text":"Some contain "},{"text":"zero answers","bold":true},{"text":", e.g. \"none of the above\", \"don't know\"."}]}]},{"type":"paragraph","text":[{"text":"4 features of Traditional Type questions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Some demand answers "},{"text":"obtainable only in the passage","bold":true},{"text":", e.g. \"According to the passage, what does globalisation mean?\""}]},{"text":[{"text":"Some require you to explain the "},{"text":"meaning of specific words in context","bold":true},{"text":", e.g. \"cat\" could be an animal or a metaphor (a cat with nine lives)."}]},{"text":[{"text":"Some demand your "},{"text":"personal opinion","bold":true},{"text":" about the contents, as long as your inferences are relevant to the text. These test your "},{"text":"imagination","bold":true},{"text":"."}]},{"text":[{"text":"Some demand your "},{"text":"personal deductions","bold":true},{"text":" based on what is implied, suggested or clearly stated."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MCQ","bold":true},{"text":" = Multiple Choice Questions. If an exam lists \"OPQ\", \"PVQ\", \"TDQ\" and \"MCQ\" as question types asked in comprehension passages, only "},{"text":"MCQ","bold":true},{"text":" is real."}]},{"text":[{"text":"\"Zero answer\" is the name for an option such as \"none of the above\" or \"don't know\". It carries no content of its own."}]},{"text":[{"text":"An MCQ needs only a choice; a Traditional question needs a written response in "},{"text":"your own words","bold":true},{"text":", so it demands in-depth understanding of the passage."}]},{"text":[{"text":"Word-in-context questions (feature 2) test whether you can tell the literal meaning from the figurative one. Answer with the meaning the "},{"text":"passage","bold":true},{"text":" uses, not the dictionary's first meaning."}]}]}]},{"number":"5.3","title":"The four categories of comprehension questions","mustKnow":[{"type":"paragraph","text":[{"text":"MCQ and Traditional Type describe the "},{"text":"format","bold":true},{"text":" of questions. When you consider the "},{"text":"tools examiners use to test understanding","bold":true},{"text":", there are "},{"text":"four categories","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Direct reference questions:","bold":true},{"text":" require you to "},{"text":"refer directly to the text","bold":true},{"text":", e.g. \"With reference to the passage, what are the major types of masquerades in Africa?\""}]},{"text":[{"text":"Inference questions:","bold":true},{"text":" require you to "},{"text":"infer","bold":true},{"text":" from the text, i.e. find out or establish the "},{"text":"relationship between two or more sentences or parts","bold":true},{"text":" of the passage, e.g. \"What do you consider the difference between the view expressed in sentence 1 and sentence 3 of paragraph four?\""}]},{"text":[{"text":"Supposition questions:","bold":true},{"text":" require you to "},{"text":"think about ideas which extend beyond the passage","bold":true},{"text":", relating aspects of the passage to the "},{"text":"outside world","bold":true},{"text":", e.g. \"What do you suppose is responsible for the negative attitude of labour leaders to most undemocratic governments in the world today?\""}]},{"text":[{"text":"Evaluation questions:","bold":true},{"text":" require an "},{"text":"evaluation of the passage","bold":true},{"text":" in terms of the "},{"text":"information provided","bold":true},{"text":" and the "},{"text":"effectiveness of the writer's language","bold":true},{"text":" in presenting the main idea, e.g. \"In your opinion, what is the motivation of the writer in this passage?\""}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"There is "},{"text":"no","bold":true},{"text":" \"affirmation question\" among the four. If an exam asks which is NOT$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 21, $study_guide$ one of the categories, the odd one out is whichever name is not direct reference, inference, supposition or evaluation."}]},{"text":[{"text":"Trap: \"two types\" and \"four categories\" are different lists. Two "},{"text":"types","bold":true},{"text":" (format): MCQ, Traditional. Four "},{"text":"categories","bold":true},{"text":" (examiner's tools): direct reference, inference, supposition, evaluation."}]},{"text":[{"text":"Signals in the stem: \"with reference to the passage\" = direct reference; \"difference between sentence 1 and sentence 3\" = inference; \"what do you suppose\" = supposition; \"in your opinion ... the writer's language\" = evaluation."}]},{"text":[{"text":"Supposition takes you "},{"text":"outside","bold":true},{"text":" the text to the world; evaluation keeps you "},{"text":"on","bold":true},{"text":" the text but asks you to judge it."}]}]}]},{"number":"5.4","title":"Summary, synopsis and abstract","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Summary (also synopsis or recap):","bold":true},{"text":" a "},{"text":"condensed version of an original work","bold":true},{"text":", usually about "},{"text":"one-third of the length","bold":true},{"text":" of the original. It highlights the "},{"text":"major points","bold":true},{"text":", with the sole purpose of helping the reader get the message in a more concise manner."}]},{"text":[{"text":"A "},{"text":"paragraph","bold":true},{"text":" can often be summarised in a "},{"text":"single sentence","bold":true},{"text":"; a "},{"text":"three or four paragraph passage","bold":true},{"text":" can usually be summarised in a "},{"text":"single paragraph","bold":true},{"text":"."}]},{"text":[{"text":"Synopsis:","bold":true},{"text":" a "},{"text":"summary of a plot","bold":true},{"text":". When you return from a movie and say what it was about, naming the main characters and what happened to them, that is a synopsis. Its use is "},{"text":"limited to novels, plays and stories","bold":true},{"text":". For all other reading materials, the "},{"text":"summary","bold":true},{"text":" is used."}]},{"text":[{"text":"Abstract:","bold":true},{"text":" a "},{"text":"shorter, more concise non-fiction summary","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Written summary of a comprehension passage:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Begin with a "},{"text":"lead","bold":true},{"text":" which states the "},{"text":"title, author, text type and main idea","bold":true},{"text":" of the text."}]},{"text":[{"text":"Arrange the ideas "},{"text":"clearly","bold":true},{"text":"."}]},{"text":[{"text":"Paraphrase","bold":true},{"text":" expressions with new words; "},{"text":"no quotations","bold":true},{"text":" from the text."}]},{"text":[{"text":"No dramatic structure is needed, because a summary does not retell a story."}]},{"text":[{"text":"Use the "},{"text":"present tense","bold":true},{"text":" or the "},{"text":"historic present","bold":true},{"text":"."}]},{"text":[{"text":"If the material is a "},{"text":"book or dissertation","bold":true},{"text":", present the "},{"text":"major facts","bold":true},{"text":" in common scientific language."}]}]},{"type":"paragraph","text":[{"text":"Summary in non-fiction:","bold":true},{"text":" non-fiction portrays "},{"text":"actual events","bold":true},{"text":". You highlight the "},{"text":"author's point of view","bold":true},{"text":" on the subject matter "},{"text":"without offering analysis or assessment","bold":true},{"text":". In addition to the guidelines above, you provide "},{"text":"numerical ratings and evaluations","bold":true},{"text":" of the titles covered."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap question: \"Which is NOT true about writing a summary?\" The false statement is \"quotations from the text are included\". True statements: expressions are paraphrased with new words; the major facts are included; the present tense is used."}]},{"text":[{"text":"\"A ____ is a condensed version of an original work\" = "},{"text":"summary","bold":true},{"text":". Not \"abstract\" (a specific short non-fiction summary), \"preface\" (an introduction before a book's main text) or \"blurb\" (the promotional text on a book's cover)."}]},{"text":[{"text":"\"A ____ is a summary of a plot\" = "},{"text":"synopsis","bold":true},{"text":". Not \"storyline\" (the plot itself), \"prologue\" (an introductory section) or \"episode\" (one part of a work)."}]},{"text":[{"text":"Why present tense? A summary describes what the text says now, so \"the writer argues\", not \"the writer argued\". "},{"text":"Historic present","bold":true},{"text":" = present tense used for past events (\"In 1349 the king issues an ordinance\"); it is accepted in summaries."}]}]}]},{"number":"5.5","title":"Strategies and steps for writing a summary","mustKnow":[{"type":"paragraph","text":[{"text":"Summary writing requires you to distinguish "},{"text":"important, less important and trivial","bold":true},{"text":" information, and to judge "},{"text":"main ideas","bold":true},{"text":" against "},{"text":"supporting details","bold":true},{"text":". The strategy depends on the type and length of the text."}]},{"type":"paragraph","text":[{"text":"3 recommended strategies:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Paragraph summarisation:","bold":true},{"text":" focus on "},{"text":"one paragraph at a time","bold":true},{"text":"."}]},{"text":[{"text":"Section summarisation:","bold":true},{"text":" focus on the "},{"text":"multi-paragraph section","bold":true},{"text":" that covers the topic and "},{"text":"integrate the multiple ideas","bold":true},{"text":"."}]},{"text":[{"text":"Multi-section summarisation","bold":true},{"text":" (e.g. report writing): read each section or chapter and make "},{"text":"at least three summarising statements","bold":true},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 22, $study_guide$text":" out of each. This creates a paragraph with a "},{"text":"topic sentence, at least three supporting sentences and a closing sentence","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Summarising a paragraph:","bold":true},{"text":" condense the whole paragraph into a few sentences. "},{"text":"Two results:","bold":true},{"text":" (1) you prove you understand it by translating it into your own words; (2) you reduce it to a more convenient form for review."}]},{"type":"paragraph","text":[{"text":"The 4 steps of summarising, in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Read","bold":true},{"text":" the paragraph to determine its "},{"text":"basic idea","bold":true},{"text":"."}]},{"text":[{"text":"Read it again","bold":true},{"text":" to pick out the "},{"text":"essentials","bold":true},{"text":", summarising mentally as you read; make notes if necessary."}]},{"text":[{"text":"Without consulting the paragraph","bold":true},{"text":", express its content "},{"text":"in your own words","bold":true},{"text":". If you get stuck, stop and repeat step 2."}]},{"text":[{"text":"Compare","bold":true},{"text":" your summary with the original and make any necessary "},{"text":"revisions","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Tense in summaries of literature:","bold":true}]},{"type":"table","header":[[{"text":"Text"}],[{"text":"Tense"}]],"rows":[[[{"text":"Drama"}],[{"text":"Present tense is most appropriate"}]],[[{"text":"Poems, stories, novels"}],[{"text":"Present preferred; past allowed if it seems more natural"}]]]},{"type":"paragraph","text":[{"text":"Whichever tense you choose, "},{"text":"use it throughout","bold":true},{"text":". Shifting tense gives the appearance of "},{"text":"uncertainty","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Most paragraphs develop "},{"text":"one simple idea","bold":true},{"text":" by "},{"text":"repetition, explanation or illustration","bold":true},{"text":". If the idea is not stated openly, "},{"text":"distil","bold":true},{"text":" it from the sentences that come closest to stating it."}]},{"text":[{"text":"The same four steps in other words: (i) find the basic idea; (ii) eliminate whatever is not essential; (iii) write the summary, safest done with the original put aside; (iv) compare the digested form with the original for accuracy and revise."}]},{"text":[{"text":"Ordering trap: exams jumble the steps. The correct order is always "},{"text":"read for basic idea, read for essentials, express in own words, compare with original","bold":true},{"text":". Writing can never come before reading, and comparing can only come last."}]},{"text":[{"text":"Keep to the point:","bold":true},{"text":" no new opinions, no needless examples, no quotations."}]},{"text":[{"text":"Worked example. Original: \"Many students fail examinations not because they are unintelligent but because they prepare badly. They start reading a few days before the paper, read everything at the same speed, and never test themselves. Those who plan their reading, vary their speed and check their understanding usually do far better.\" One-sentence summary: \"Examination failure usually comes from poor preparation, so students who plan, vary their reading speed and test themselves do better.\" Check: basic idea kept, examples condensed, own words, present tense, under half the length."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Preview (turn the title into a question); read "},{"text":"more than once","bold":true},{"text":", at a speed matching the difficulty of the language."}]},{"text":[{"text":"First reading: "},{"text":"rapid","bold":true},{"text":", for tone, purpose, theme. Second reading: "},{"text":"much slower","bold":true},{"text":", for main vs minor ideas, summarising sentences, examples, viewpoint clues."}]},{"text":[{"text":"Two question "},{"text":"types","bold":true},{"text":": "},{"text":"MCQ","bold":true},{"text":" (fast; elimination; never mark more than one) and "},{"text":"Traditional Type","bold":true},{"text":" (your own words)."}]},{"text":[{"text":"MCQ options may be partly correct, logically true but not in the text, suggested but not confirmed, or "},{"text":"zero answers","bold":true},{"text":"."}]},{"text":[{"text":"Four "},{"text":"categories","bold":true},{"text":": "},{"text":"direct reference, inference, supposition, evaluation","bold":true},{"text":". No \"affirmation question\"."}]},{"text":[{"text":"Summary","bold":true},{"text":" = condensed version, about "},{"text":"one-third","bold":true},{"text":" the length. "},{"text":"Synopsis","bold":true},{"text":" = summary of a "},{"text":"plot","bold":true},{"text":" (novels, plays, stories). "},{"text":"Abstract","bold":true},{"text":" = short, concise non-fiction summary."}]},{"text":[{"text":"Written summary: lead (title, author, text type, main idea); paraphrase; "},{"text":"no quotations","bold":true},{"text":"; "},{"text":"present tense","bold":true},{"text":"."}]},{"text":[{"text":"Four steps: read for basic idea, read for essentials, write in own words, compare and revise. Three strategies: paragraph, section, multi-section."}]},{"text":[{"text":"Keep one tense throughout; shifting tense looks like uncertainty."}]}]}],"theory":{"itemId":"4e3c6792-c883-5505-b754-5200e0943a0e","question":[{"type":"paragraph","text":[{"text":"Explain the four categories of comprehension questions, giving one example of each."}]}]},"practice":[{"topic":"Reading Skills II: Comprehension and Summary","named":false}]}},{"kind":"note","itemId":"8d114f3f-b3af-5372-a0bf-0cd6fc6974aa","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Reading Skills III: Study Reading","body":"What reading is and why it is communication; what to read and when to read, including the conditions a serious student sets up; the four methods of study reading (SQ3R, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 23, $study_guide$PQRST, 3S3R, OK4R) plus flash cards, summarisation and mnemonics; the three types of memory and the three stages of storing information.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What reading is and why it is communication; what to read and when to read, including the conditions a serious student sets up; the four methods of study reading (SQ3R, PQRST, 3S3R, OK4R) plus flash cards, summarisation and mnemonics; the three types of memory and the three stages of storing information."}],"lessons":[{"number":"6.1","title":"What reading is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading:","bold":true},{"text":" an activity which involves looking at words and understanding their meanings, either for pleasure or for serious purposes like an examination. Put another way, reading is the process of translating written or printed symbols and letters into words and sentences which convey meaning."}]},{"text":[{"text":"Reading uses two things: the "},{"text":"eyes","bold":true},{"text":" and the "},{"text":"mental faculty","bold":true},{"text":" (the mind). It is understanding and interpreting written or printed words and signs."}]},{"text":[{"text":"Reading is a "},{"text":"process of communication","bold":true},{"text":". Most formal activities of learning take place through it."}]},{"text":[{"text":"Reading is an important part of the "},{"text":"learning process","bold":true},{"text":": it lets you garner (gather) the information you need for growth."}]},{"text":[{"text":"Through reading you "},{"text":"enlarge your vocabulary","bold":true},{"text":" and so improve your listening and writing."}]},{"text":[{"text":"Saccadic movement:","bold":true},{"text":" when you read, your eyes move by little jumps forward, then stop, then jump forward again, alternately along the line. The eyes can also jump "},{"text":"backward","bold":true},{"text":" to words already read."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Purposes of reading:","bold":true},{"text":" we read for pleasure, for examinations, for knowledge, for information. Reading is not for one purpose only. Trap: any option that says we read \"only\" for pleasure, \"only\" for exams or \"only\" for knowledge is false. If all the options carry \"only\", the correct answer is \"none of the above\"."}]},{"text":[{"text":"Reading is a "},{"text":"receptive","bold":true},{"text":" skill (you take in meaning), like listening. Speaking and writing are "},{"text":"productive","bold":true},{"text":" skills. Reading interprets written or printed symbols; listening interprets spoken words."}]},{"text":[{"text":"Reading is basic to learning in a literate society."}]}]}]},{"number":"6.2","title":"The nature of reading: what and when to read","mustKnow":[{"type":"paragraph","text":[{"text":"What to read","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading materials include "},{"text":"newspapers, magazines, phone directories and textbooks","bold":true},{"text":" on any subject."}]},{"text":[{"text":"Different materials are read in "},{"text":"different ways","bold":true},{"text":". Reading can involve "},{"text":"scanning","bold":true},{"text":", "},{"text":"skimming","bold":true},{"text":" or normal "},{"text":"study reading","bold":true},{"text":"."}]},{"text":[{"text":"Skimming is a mere "},{"text":"survey","bold":true},{"text":". A textbook is read with "},{"text":"concentration and effort","bold":true},{"text":"."}]},{"text":[{"text":"A newspaper is usually read through "},{"text":"once","bold":true},{"text":" and discarded. A textbook is read "},{"text":"over and over again","bold":true},{"text":"; ideas are questioned and recalled, possibly for examinations."}]},{"text":[{"text":"Rule: "},{"text":"the nature of the reading material dictates how it is read","bold":true},{"text":" and the rigour attached to its reading. What you read determines how you read."}]}]},{"type":"paragraph","text":[{"text":"When to read","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"You can read at "},{"text":"any time of the day","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"place","bold":true},{"text":" you choose for reading usually determines the nature of what is read. A newspaper or magazine can be read "},{"text":"anywhere and at any time","bold":true},{"text":". A mathematics textbook requires a "},{"text":"private, noise-free and distraction-free","bold":true},{"text":" area for adequate comprehension."}]},{"text":[{"text":"Marks of a "},{"text":"serious student","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sets aside a "},{"text":"particular time","bold":true},{"text":" of the day for study."}]},{"text":[{"text":"Studies at a "},{"text":"regular place","bold":true},{"text":" designated for it."}]},{"text":[{"text":"Draws up a "},{"text":"reading timetable","bold":true},{"text":"."}]},{"text":[{"text":"Prioritises","bold":true},{"text":" the reading schedule and excludes himself or herself from parties."}]},{"text":[{"text":"Eliminates distractions","bold":true},{"text":" as much as possible."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"reading study materials anywhere\" is "},{"text":"not","bold":true},{"text":" a mark of a serious student. Newspapers can be read anywhere; study materials need a fixed time and place."}]},{"text":[{"text":"Conditions that affect reading and listening.","bold":true},{"text":" Distractions fall into three groups. Know which is which:"}]}]},{"type":"table","header":[[{"text":"Condition"}],[{"text":"What it covers"}],[{"text":"Examples"}]],"rows":[[[{"text":"Physical","bold":true}],[{"text":"the environment around you"}],[{"text":"noise","bold":true},{"text":", a noisy or ill-ventilated room, music from radio, television, laptop or phone"}]],[[{"text":"Physiological","bold":true}],[{"text":"the bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 24, $study_guide$dy of the speaker or reader"}],[{"text":"speech defects, tiredness, illness, hunger"}]],[[{"text":"Psychological","bold":true}],[{"text":"the mind of the listener or reader"}],[{"text":"worries about love affairs, money or health; emotional state; prejudice"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Noise is a physical condition","bold":true},{"text":", not psychological or physiological. There is no \"spiritual\" category."}]},{"text":[{"text":"Texts you read for a course:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Prescribed text:","bold":true},{"text":" the recommended main book for a course. It usually contains "},{"text":"most of the topics to be treated, or the basis for discussion in the lectures","bold":true},{"text":". Trap: it does not contain "},{"text":"all","italic":true},{"text":" the topics, and it is not the lecturer's sole source."}]},{"text":[{"text":"Supplementary texts:","bold":true},{"text":" given so that students can "},{"text":"acquire additional information","bold":true},{"text":" for their courses. \"Supplement\" means to add to."}]}]}]},{"text":[{"text":"Selective reading","bold":true},{"text":" is important because it may be "},{"text":"impossible, or a waste of time, to read everything in a text","bold":true},{"text":". Depending on your purpose and how familiar the material is, you read selectively. Believing you must read every word is a misconception."}]},{"text":[{"text":"Good study practice: generate guide questions as you read, adopt a "},{"text":"flexible reading speed","bold":true},{"text":", and use "},{"text":"memory-enhancing devices","bold":true},{"text":" (mnemonics). "},{"text":"Not","bold":true},{"text":" recommended: reading with "},{"text":"pre-conceived ideas","bold":true},{"text":". Prejudice and emotional attachment to a subject block understanding; keep an open, questioning mind."}]}]}]},{"number":"6.3","title":"Study reading and the SQ3R technique","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Study reading:","bold":true},{"text":" the type of reading we engage in to gather information that will translate to knowledge on a specific area of study. It targets "},{"text":"detailed, sometimes critical, exploration and evaluation","bold":true},{"text":" of the content. To succeed you must read vigorously and widely and become an avid reader who can recall what has been read."}]},{"text":[{"text":"There are many methods of study reading. "},{"text":"Four","bold":true},{"text":" are treated here: "},{"text":"SQ3R, PQRST, 3S3R and OK4R","bold":true},{"text":"."}]},{"text":[{"text":"SQ3R","bold":true},{"text":" = "},{"text":"S","bold":true},{"text":"urvey, "},{"text":"Q","bold":true},{"text":"uestion, and 3R = "},{"text":"R","bold":true},{"text":"ead, "},{"text":"R","bold":true},{"text":"ecall/Recite, "},{"text":"R","bold":true},{"text":"eview."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"S, Survey:","bold":true},{"text":" examine the "},{"text":"preliminary matters","bold":true},{"text":" of the book: the "},{"text":"title, preface, foreword and table of contents","bold":true},{"text":". Read the "},{"text":"blurb","bold":true},{"text":" (it summarises what the book is about). Check the "},{"text":"publication date","bold":true},{"text":" to see whether the material is current. Ask whether the title is relevant to what you are searching for. To survey an "},{"text":"article or chapter","bold":true},{"text":", check the "},{"text":"title","bold":true},{"text":", the "},{"text":"first and concluding paragraphs","bold":true},{"text":", and the "},{"text":"topic sentences","bold":true},{"text":" of each paragraph."}]},{"text":[{"text":"Q, Question:","bold":true},{"text":" ask questions about what is being read. They direct and guide your reading and lead you to careful, serious study. Examples:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"How correct is the idea or information in the book?"}]},{"text":[{"text":"Does the book actually contain what it said it would in the introduction?"}]},{"text":[{"text":"Does the book contradict your opinions on the subject?"}]},{"text":[{"text":"What is the writer's aim in writing the book?"}]},{"text":[{"text":"Does the writer present his or her views objectively or otherwise?"}]}]}]},{"text":[{"text":"R1, Read:","bold":true},{"text":" a "},{"text":"careful reading","bold":true},{"text":" of the text, examining its main ideas, illustrations and examples, and getting answers to the questions you asked. You may read the text "},{"text":"two or three times","bold":true},{"text":". Read with a "},{"text":"critical mind","bold":true},{"text":", clarify issues, accommodate new vocabulary and take notes."}]},{"text":[{"text":"R2, Recall/Recite:","bold":true},{"text":" make an effort to remember from memory what you have read: definitions, keywords, new words, illustrations. Do this by "},{"text":"paraphrasing","bold":true},{"text":" or by using the "},{"text":"exact words","bold":true},{"text":" of the text; write the expressions down or have a "},{"text":"friend listen","bold":true},{"text":" while you recall them verbally. Go back to the text if you need to refresh your memory. Purpose: learn new ideas and add them to your knowledge base."}]},{"text":[{"text":"R3, Review:","bold":true},{"text":" to review is to "},{"text":"assess","bold":true},{"text":"; it is synonymous with "},{"text":"revision","bold":true},{"text":". You look again at everything you have done on the SQ3R scale, read the text again and make corrections, making sure "},{"text":"nothing has been forgotten","bold":true},{"text":". It is more or less a "},{"text":"repetition of all the steps","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap on the 3Rs: "},{"text":"Read, Recall, Review","bold":true},{"text":". \"Recite\" is another name for Recall, but \"Rep$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 25, $study_guide$eat\", \"Roll\", \"Replay\" and \"Rehash\" are not part of the method."}]},{"text":[{"text":"Trap on survey: the "},{"text":"blurb","bold":true},{"text":" belongs to the survey of a whole "},{"text":"book","bold":true},{"text":" (only books carry one). When surveying an "},{"text":"article or chapter","bold":true},{"text":", you consider the title, the introduction and conclusion, and the topic sentences, not a blurb."}]},{"text":[{"text":"\"Survey\" here has nothing to do with land surveyors or measuring the size of a book, and it is not an in-depth investigation of the content."}]},{"text":[{"text":"Seven reading strategies","bold":true},{"text":" that help you understand what you read at the Read stage:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Reading with purpose and flexibility:","bold":true},{"text":" the nature of the material and your purpose dictate the thoroughness and speed of reading. Flexibility is your ability to "},{"text":"vary your reading speed","bold":true},{"text":" to suit the material. Skim, scan or study-read with your purpose and the difficulty of the material in mind."}]},{"text":[{"text":"Pre-reading:","bold":true},{"text":" read the preliminary details such as the introductory paragraph, and the conclusion, before the actual reading. It helps you organise what is to be read."}]},{"text":[{"text":"Identifying verbal and sense links:","bold":true},{"text":" words are strung into phrases, clauses and sentences. Look for cues and linkages; "},{"text":"keywords and topic sentences","bold":true},{"text":" help understanding."}]},{"text":[{"text":"Adopting a proper mental posture:","bold":true},{"text":" be mentally alert and stable. To aid this: (a) have a "},{"text":"regular place of study","bold":true},{"text":" so you adapt to the environment; (b) "},{"text":"avoid distractions","bold":true},{"text":", both physical (music from the radio, television, laptop or phone) and other forms (worries about love affairs, money or health)."}]},{"text":[{"text":"Dividing up the study material:","bold":true},{"text":" break the material into manageable smaller units and take one step at a time to aid assimilation."}]},{"text":[{"text":"Adhering to the writer's leads:","bold":true},{"text":" follow the text's division into "},{"text":"introduction, main body and conclusion","bold":true},{"text":" as the writer intends."}]},{"text":[{"text":"Being a participant reader:","bold":true},{"text":" take part in the process of communication by asking yourself important questions and finding the answers in the text; be critical of what you read."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: your mental posture is affected by music from gadgets, noise and worries about money or affairs. It is "},{"text":"not","bold":true},{"text":" affected by the "},{"text":"arrangement of keywords and topic sentences","bold":true},{"text":"; that is a reading strategy that helps you, not a distraction."}]}]}]},{"number":"6.4","title":"PQRST, 3S3R, OK4R and other study aids","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PQRST","bold":true},{"text":" = "},{"text":"P","bold":true},{"text":"review, "},{"text":"Q","bold":true},{"text":"uestion, "},{"text":"R","bold":true},{"text":"ead, "},{"text":"S","bold":true},{"text":"ummary, "},{"text":"T","bold":true},{"text":"est. It gives priority to the information to be examined, especially in an examination."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Preview:","bold":true},{"text":" examine the topic and the various headings and ideas in the course outline."}]},{"text":[{"text":"Question:","bold":true},{"text":" ask the usual questions about what you are reading to aid understanding."}]},{"text":[{"text":"Read:","bold":true},{"text":" carefully read all materials related to the topic and select ideas that answer the questions."}]},{"text":[{"text":"Summary:","bold":true},{"text":" put all you have studied in summary form, taking account of illustrations and diagrams."}]},{"text":[{"text":"Test:","bold":true},{"text":" test yourself by answering the questions you formulated earlier, focusing only on the topic."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3S3R:","bold":true},{"text":" 3S = "},{"text":"Survey, Study-read, Speech-read","bold":true},{"text":"; 3R = "},{"text":"Recite, Reflect, Recollect","bold":true},{"text":"."}]},{"text":[{"text":"OK4R:","bold":true},{"text":" "},{"text":"O","bold":true},{"text":"verview, "},{"text":"K","bold":true},{"text":"ey points; 4R = "},{"text":"Read, Recall, Reflect, Review","bold":true},{"text":"."}]},{"text":[{"text":"3S3R and OK4R are strategies for studying better; they teach effective "},{"text":"note-taking","bold":true},{"text":" and "},{"text":"mnemonic devices","bold":true},{"text":"."}]},{"text":[{"text":"Other methods of study reading:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Flash cards:","bold":true},{"text":" cards of "},{"text":"A5 size","bold":true},{"text":" carrying short notes for revision. They are usually "},{"text":"visual clues","bold":true},{"text":"."}]},{"text":[{"text":"Summarisation:","bold":true},{"text":" read and recall what you have read in a short form using "},{"text":"keywords","bold":true},{"text":"; the keywords bring the ideas back in the examination hall."}]},{"text":[{"text":"Mnemonic devices:","bold":true},{"text":" acronyms or simple phrases that help you memorise ideas for an examination. Example: "},{"text":"ROYGBIV","bold":true},{"text":" for the colours of the rainbow: red, orange, yellow, green, blue, indigo, violet."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages of study reading","bold":true},{"text":" (3): it increases better study habits; it boosts your effort at studying and passing examinations; it helps you to study smartly and pass well."}]}]}],"explainMore":[{"type":"list","ordered":fa$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 26, $study_guide$lse,"items":[{"text":[{"text":"Trap: only "},{"text":"PQRST","bold":true},{"text":" is a real technique. STPQR, QRSTP and RSTPQ are scrambled letters, not methods."}]},{"text":[{"text":"Compare the acronyms: SQ3R and OK4R both contain Read, Recall and Review (OK4R adds Reflect); PQRST is the only one that ends with a "},{"text":"Test","bold":true},{"text":"; 3S3R is the only one with Speech-read and Recollect."}]}]}]},{"number":"6.5","title":"Reading, retaining and remembering","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory","bold":true},{"text":" controls the retention of what has been studied. The ability to remember and recollect what you have read is important to a student."}]},{"text":[{"text":"Three types of memory","bold":true},{"text":", classified by "},{"text":"how long","bold":true},{"text":" information is kept:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sensory memory (SM):","bold":true},{"text":" linked to the "},{"text":"senses","bold":true},{"text":": the ears, eyes, hands, tongue and nose. Information here is very "},{"text":"ephemeral","bold":true},{"text":" (short-lived). It is the first area of memory."}]},{"text":[{"text":"Short-term memory (STM):","bold":true},{"text":" the second compartment. Ideas stay for a "},{"text":"short time","bold":true},{"text":". Information is "},{"text":"organised","bold":true},{"text":" here; vital and relevant points are selected and irrelevant ones filtered out."}]},{"text":[{"text":"Long-term memory (LTM):","bold":true},{"text":" a "},{"text":"permanent","bold":true},{"text":" room for storing information. It is "},{"text":"large and limitless","bold":true},{"text":", and new ideas are allowed in."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Best way to remember","bold":true},{"text":" what you read: recall it "},{"text":"without using the exact words","bold":true},{"text":" of the textbook, that is, "},{"text":"paraphrase","bold":true},{"text":" in your own words. Another way is to "},{"text":"recite verbatim","bold":true},{"text":"; this suits lines in a play, words in a foreign language, or the sciences."}]},{"text":[{"text":"Three stages of storing information:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Encoding:","bold":true},{"text":" the ability to read, organise and internalise information."}]},{"text":[{"text":"Storage:","bold":true},{"text":" the ability to retain the information."}]},{"text":[{"text":"Retrieval:","bold":true},{"text":" remembering or recalling stored information. Aided by "},{"text":"attention","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Recall is aided by "},{"text":"attention, concentration and focus","bold":true},{"text":", and by "},{"text":"repetition, recitation and review","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the "},{"text":"brain","bold":true},{"text":" is not a sense organ, so it is "},{"text":"not","bold":true},{"text":" associated with sensory memory. The ears, eyes, hands, tongue and nose are."}]},{"text":[{"text":"Trap: the classification based on "},{"text":"length of storage","bold":true},{"text":" is "},{"text":"long-term and short-term","bold":true},{"text":" (with sensory memory as the very brief first stage). \"Transient and permanent\", \"visible and invisible\" and \"variable and invariable\" are not the terms used."}]},{"text":[{"text":"Trap: "},{"text":"reproduction","bold":true},{"text":" (simply producing information, as in an exam) does "},{"text":"not","bold":true},{"text":" enhance recall. Repetition, recitation and review do."}]},{"text":[{"text":"Practical test of good study reading: read a passage at least twice, then answer questions on it without looking back."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading = looking at words and understanding their meanings; eyes plus mind; a process of communication; saccadic eye movement."}]},{"text":[{"text":"We read for pleasure, exams and knowledge; never \"only\" one."}]},{"text":[{"text":"The nature of the material dictates how it is read: newspaper once, textbook over and over."}]},{"text":[{"text":"Serious student: fixed time, regular place, timetable, no parties, no distractions. Noise is a "},{"text":"physical","bold":true},{"text":" condition; worries are psychological."}]},{"text":[{"text":"Prescribed text covers most topics; supplementary texts add information; selective reading saves time."}]},{"text":[{"text":"Four methods: "},{"text":"SQ3R","bold":true},{"text":" (Survey, Question, Read, Recall, Review), "},{"text":"PQRST","bold":true},{"text":" (Preview, Question, Read, Summary, Test), "},{"text":"3S3R","bold":true},{"text":", "},{"text":"OK4R","bold":true},{"text":"."}]},{"text":[{"text":"Survey a book: title, preface, foreword, contents, blurb, date. Survey a chapter: title, first and last paragraphs, topic sentences."}]},{"text":[{"text":"Other aids: A5 flash cards, summarisation with keywords, mnemonics (ROYGBIV)."}]},{"text":[{"text":"Memory: sensory (senses, ephemeral), short-term, long-term (permanent, limitless). Stages: encoding, storage, retrieval."}]},{"text":[{"text":"Recall is aided by attention, repetition, recitation and review; paraphrasing beats memorising exact words."}]}]}],"theory":{"itemId":"d8a9e146-234e-515d-9111-7148c5c6a8b8","question":[{"type":"paragraph","text":[{"text":"Explain the SQ3R technique of study reading."}]}]},"practice":[{"topic":"Reading Skills III: Study Reading","named":false}]}},{"kind":"note","itemId":"ecbcb325-80a7-51c8-9ceb-f341de345514","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Writing Skills I: The Paragraph","body":"What a paragraph is; the 8 types and their helper words; the topic sentence and the 5 qualities of a good one; the 3-stage structure; the 5-step process; the 3 troubleshoot$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 27, $study_guide$ing problems; the 4 elements; when to start a new paragraph; transitions and signposts.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What a paragraph is; the 8 types and their helper words; the topic sentence and the 5 qualities of a good one; the 3-stage structure; the 5-step process; the 3 troubleshooting problems; the 4 elements; when to start a new paragraph; transitions and signposts."}],"lessons":[{"number":"7.1","title":"What a paragraph is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paragraph:","bold":true},{"text":" a unit of any composition comprising a collection of related sentences dealing with a single topic. Simply: a sentence or group of sentences that support one main idea."}]},{"text":[{"text":"It usually contains a "},{"text":"main idea","bold":true},{"text":" and may contain a "},{"text":"sub-idea","bold":true},{"text":"."}]},{"text":[{"text":"Essay:","bold":true},{"text":" a combination of ideas from one paragraph to another that creates a united whole; all paragraphs support each other, leading from the first idea to the final resolution."}]},{"text":[{"text":"Length is not a determinant","bold":true},{"text":" in defining a paragraph. Single-sentence paragraphs are rare, so write a "},{"text":"minimum of three sentences","bold":true},{"text":"."}]},{"text":[{"text":"A good paragraph shows "},{"text":"unity and coherence","bold":true},{"text":", just as a good composition shows them among its paragraphs. These are the features shared by paragraphs and essays."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The unit described is the paragraph: not the sentence (too small), the essay (made of paragraphs) or \"text\" (too general)."}]},{"text":[{"text":"Trap: the shared pair is "},{"text":"unity and coherence","bold":true},{"text":", not \"unity and self-sufficiency\", \"cohesion and transparency\" or \"transition and cohesion\". Transition is only a device for achieving coherence."}]},{"text":[{"text":"True of paragraphs: they vary in length, each addresses only an aspect of the topic, and a paragraph is hardly ever longer than the entire essay. "},{"text":"Not","bold":true},{"text":" true: every paragraph begins with a topic sentence (Lesson 7.3)."}]}]}]},{"number":"7.2","title":"The 8 types of paragraph","mustKnow":[{"type":"paragraph","text":[{"text":"Learn each type by what it does, then its "},{"text":"helper words","bold":true},{"text":"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Definition:","bold":true},{"text":" explains the key words or main topic of a composition. Helpers: \"is defined as\", \"a kind of\". "},{"text":"Suicide is defined as the act of taking one's own life.","italic":true}]},{"text":[{"text":"Classification:","bold":true},{"text":" groups things or ideas into specific categories. Helpers: \"is a kind of\", \"can be divided into\", \"is a type of\", \"falls under\", \"belongs to\", \"is a part of\", \"fits into\", \"is grouped with\", \"is related to\", \"is associated with\". "},{"text":"Coal is a kind of non-renewable resource.","italic":true}]},{"text":[{"text":"Descriptive:","bold":true},{"text":" describes a person, place or thing. Helpers: \"measurement\", \"location\", \"size\", \"length\", \"is like\", \"colour\", \"width\", \"resembles\", \"above\", \"shape\", \"mass/weight\", \"below\", \"purpose\", \"speed\", \"beside\", \"near\", \"north/east/west\". "},{"text":"Ogbomosho is west of Ibadan.","italic":true}]},{"text":[{"text":"Comparison and contrast:","bold":true},{"text":" similarities and differences between two or more people, places, things or ideas. Helpers: \"is similar to\", \"on the other hand\", \"both\", \"however\", \"also\", \"but\", \"too\", \"in contrast to\", \"differs from\", \"while\". "},{"text":"Both Jos and Lagos have rain in August. However, rain in Lagos is heavier.","italic":true}]},{"text":[{"text":"Sequence:","bold":true},{"text":" describes a series of events or a process in some sort of order, usually based on "},{"text":"time","bold":true},{"text":". Helpers of order: \"first\", \"second\", \"third\", \"in the beginning\"; of time: \"recently\", \"previously\". "},{"text":"First, join a political party. Second, win your party's nomination. Third, win the election.","italic":true}]},{"text":[{"text":"Choice:","bold":true},{"text":" you choose which object, idea or action you prefer and give your opinion. Helpers of point of view: \"in my opinion\", \"belief\", \"feel\"; of personal opinion: \"like/dislike\", \"hope\", \"idea\". "},{"text":"In my opinion, football is more fun than lawn tennis.","italic":true}]},{"text":[{"text":"Explanation:","bold":true},{"text":" explains "},{"text":"how or why","bold":true},{"text":" something happens; explores "},{"text":"causes and effects","bold":true},{"text":". Helpers: \"because\", \"therefore\", \"thus\", \"since\". "},{"text":"Living conditions were terrible. Thus, many people moved to Europe.","italic":true}]},{"text":[{"text":"Evaluation:","bold":true},{"text":" makes "},{"text":"judgements","bold":true},{"text":" about people, ideas and possible actions, based on "},{"text":"criteria","bold":true},{"text":" you develop; you state your evaluation or recommendation and support it. Helpers of criteria: \"good/bad\", \"correct/incorrect\", \"moral/immoral\"; of recommendation: \"suggest\", \"recommend\", \"advise\". "},{"text":"I recommend that pesticides should not be used because they are harmful.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"a series of events or a process in some sort of order\" = "},{"text":"sequence","bold":true},{"text":", not descriptive (a person, place or thing) and not explanation."}]},{"text":[{"text":"Trap: \"explains how or why something happens\" = "},{"text":"explanation","bold":true},{"text":", not definition (key words) or sequence (time order)."}]},{"text":[{"text":"Choice$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 28, $study_guide$ vs evaluation: choice is what "},{"text":"I prefer","italic":true},{"text":"; evaluation is a judgement by criteria (good/bad, moral/immoral) plus a recommendation."}]}]}]},{"number":"7.3","title":"The topic sentence","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Topic sentence:","bold":true},{"text":" the sentence that "},{"text":"states the main idea","bold":true},{"text":" of the paragraph and "},{"text":"works as a summary","bold":true},{"text":" of it."}]},{"text":[{"text":"It is "},{"text":"the most important sentence","bold":true},{"text":" (and the most important part) of a paragraph."}]},{"text":[{"text":"It is "},{"text":"often but not always","bold":true},{"text":" the first sentence: usually first or second, occasionally last, sometimes in the middle."}]},{"text":[{"text":"A thesis statement is to an "},{"text":"essay","bold":true},{"text":" what a topic sentence is to "},{"text":"the paragraph","bold":true},{"text":": it is the "},{"text":"thesis of the paragraph","bold":true},{"text":"."}]},{"text":[{"text":"Read in sequence, an essay's topic sentences give a "},{"text":"sketch of the argument","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5 qualities of a good topic sentence:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Concise and emphatic:","bold":true},{"text":" no longer than the idea requires; stresses the important word. "},{"text":"The Nigerian banking system has collapsed","italic":true},{"text":": brief, clear, strong, with the key word \"collapsed\" stressed at the end."}]},{"text":[{"text":"Lets readers "},{"text":"see your point immediately","bold":true},{"text":"; especially useful in an application or an argumentative essay."}]},{"text":[{"text":"Placed "},{"text":"at the end","bold":true},{"text":" of the paragraph when specific details "},{"text":"lead up to a generalisation","bold":true},{"text":"."}]},{"text":[{"text":"Occasionally "},{"text":"avoided","bold":true},{"text":", when the main idea is so obvious it need not be stated."}]},{"text":[{"text":"Carefully worded and restricted","bold":true},{"text":" (focused), which helps you generate and control your information."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"the most important sentence in a paragraph\" is the "},{"text":"topic","bold":true},{"text":" sentence, not \"first\", \"last\" or \"concluding\". First and last are positions; the concluding sentence is optional."}]},{"text":[{"text":"Trap: \"states the main idea and works as its summary\" is the topic sentence, not the conclusion (which only closes the paragraph)."}]},{"text":[{"text":"Since it can be first, middle, last or omitted, \"every paragraph begins with a topic sentence\" is "},{"text":"false","bold":true},{"text":"."}]}]}]},{"number":"7.4","title":"Structure of a paragraph and the 5-step process","mustKnow":[{"type":"paragraph","text":[{"text":"3 stages of a typical academic paragraph:","bold":true}]},{"type":"table","header":[[{"text":"Stage"}],[{"text":"Name"}],[{"text":"Status"}]],"rows":[[[{"text":"1"}],[{"text":"Topic sentence or main idea"}],[{"text":"Essential"}]],[[{"text":"2"}],[{"text":"Body: support or detail sentences"}],[{"text":"Essential"}]],[[{"text":"3"}],[{"text":"Conclusion or concluding sentence"}],[{"text":"Optional"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A paragraph is "},{"text":"complete","bold":true},{"text":" when it has "},{"text":"a topic sentence and supporting details","bold":true},{"text":"."}]},{"text":[{"text":"Paragraph structure "},{"text":"parallels essay structure","bold":true},{"text":" in order and content: a coherent argument, supporting evidence/analysis, and a conclusion."}]}]},{"type":"paragraph","text":[{"text":"3 contents of a paragraph:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Topic sentence:","bold":true},{"text":" "},{"text":"two purposes","bold":true},{"text":": (1) the "},{"text":"thesis of your paragraph","bold":true},{"text":"; (2) pushes the essay's thesis forward and presents an arguable point. Usually first or second sentence; at the end occasionally, but not as a habit."}]},{"text":[{"text":"Support or detail sentences:","bold":true},{"text":" the "},{"text":"evidence/analysis","bold":true},{"text":" that makes your claim digestible. Balance "},{"text":"evidence","bold":true},{"text":" (facts, quotations, summary of events) with "},{"text":"analysis","bold":true},{"text":" (interpretation). Evidence-heavy = no argument; analysis-heavy = claim not supported."}]},{"text":[{"text":"Concluding observation:","bold":true},{"text":" closes with an observation that is "},{"text":"more than a summary","bold":true},{"text":"; a final idea that leads to the next step. Usually the last or second-to-last sentence."}]}]},{"type":"paragraph","text":[{"text":"Length:","bold":true},{"text":" paragraphs are hardly ever longer than one page, double spaced. "},{"text":"Lengthy","bold":true},{"text":" paragraphs signal a "},{"text":"lack of structure","bold":true},{"text":" (split them); "},{"text":"short","bold":true},{"text":" paragraphs signal a "},{"text":"lack of substance","bold":true},{"text":" (develop or merge)."}]},{"type":"paragraph","text":[{"text":"The 5-Step Process to Paragraph Development","bold":true},{"text":" (model paragraph: African oral narratives, proved by "},{"text":"illustration","bold":true},{"text":"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Decide on a controlling idea and create a topic sentence.","bold":true},{"text":" The controlling idea directs the paragraph's development and often appears as the topic sentence. "},{"text":"African oral narratives often had hidden double meanings.","italic":true}]},{"text":[{"text":"Explain the controlling idea:","bold":true},{"text":" tell the reader how to interpret the topic sentence. "},{"text":"On one leve$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 29, $study_guide$l the narratives entertained; on another they spoke truths and imparted moral virtues.","italic":true}]},{"text":[{"text":"Give an example (or multiple examples):","bold":true},{"text":" support or evidence for the idea. The story \"The tortoise goes to a feast in the sky\": tortoise, disguised as a bird, attended a feast meant for birds; his greed made the birds take back their feathers."}]},{"text":[{"text":"Explain the example(s):","bold":true},{"text":" show each example's relevance to the topic sentence, usually in a separate sentence. Abandoned in the sky, tortoise sent a message home; the birds delivered the wrong message, his wife brought out furniture instead of mattresses, and he broke his back."}]},{"text":[{"text":"Complete the paragraph's idea or transition into the next paragraph:","bold":true},{"text":" tie up loose ends and recall the main idea, or move the reader on. "},{"text":"The moral is that greed could lead a person to becoming pretentious and would ultimately lead to his destruction.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Steps 3 and 4 "},{"text":"can be repeated","bold":true},{"text":" until the main idea is fully developed."}]},{"text":[{"text":"Trap: the process has "},{"text":"5","bold":true},{"text":" steps, not 1, 3 or 7. \"Choosing a controlling idea\", \"giving examples\" and \"explaining the controlling idea\" are all real steps; asked which is not a step, pick \"none of the above\"."}]},{"text":[{"text":"Trap: \"complete\" does not mean a capital letter and a full stop, and \"an argument\" on its own is not what completes a paragraph; the answer is a topic sentence and supporting details."}]}]}]},{"number":"7.5","title":"Troubleshooting and the 4 elements","mustKnow":[{"type":"paragraph","text":[{"text":"Troubleshoot a paragraph in 3 cases:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Topic sentence problem.","bold":true},{"text":" The topic sentence may be at the beginning, middle or end; it must be "},{"text":"in there somewhere","bold":true},{"text":". A paragraph may open with a "},{"text":"transition sentence","bold":true},{"text":" ("},{"text":"Like sharks, snakes and scorpions, dogs are widely feared","italic":true},{"text":"); the topic sentence should follow ("},{"text":"Although most people consider dogs quite dangerous, they are, for the most part, entirely harmless","italic":true},{"text":"). If it never comes, you have a problem."}]},{"text":[{"text":"Multiple controlling ideas.","bold":true},{"text":" "},{"text":"Eliminate","bold":true},{"text":" sentences on the second idea, or "},{"text":"split","bold":true},{"text":" into two or more paragraphs with one idea each. In the dogs paragraph, the sentences about groups that fry and eat dogs branch off; the revision removes them and ends by returning to the main idea."}]},{"text":[{"text":"Transitions within the paragraph","bold":true},{"text":" (intra-paragraph linkages): single words or short phrases that relate ideas and create logical progression, especially across multiple examples ("},{"text":"however","italic":true},{"text":", "},{"text":"The first is...","italic":true},{"text":", "},{"text":"The second is...","italic":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"Length (too long or too short) is "},{"text":"not","bold":true},{"text":" one of the three cases."}]},{"type":"paragraph","text":[{"text":"4 elements of an effective paragraph","bold":true},{"text":" (they overlap):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unity:","bold":true},{"text":" a "},{"text":"single focus","bold":true},{"text":" throughout; it must not begin with one point and end with another, or wander. Unity = "},{"text":"singularity of focus","bold":true},{"text":"."}]},{"text":[{"text":"Coherence:","bold":true},{"text":" the trait that makes the paragraph "},{"text":"easily understandable to a reader","bold":true},{"text":", created by "},{"text":"logical bridges","bold":true},{"text":" and "},{"text":"verbal bridges","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Logical bridges (2):","bold":true},{"text":" the same idea carried from sentence to sentence; successive sentences in "},{"text":"parallel form","bold":true},{"text":"."}]},{"text":[{"text":"Verbal bridges (4):","bold":true},{"text":" repeated "},{"text":"key words","bold":true},{"text":"; repeated "},{"text":"synonyms","bold":true},{"text":"; "},{"text":"pronouns","bold":true},{"text":" referring to nouns in earlier sentences; "},{"text":"transition words","bold":true},{"text":" linking sentences."}]}]}]},{"text":[{"text":"A topic sentence:","bold":true},{"text":" indicates in a general way the idea or thesis of the paragraph. Not every paragraph has a clear-cut one, and it can be anywhere, but the easy way is "},{"text":"near the beginning","bold":true},{"text":". Either way you should be able to summarise the paragraph."}]},{"text":[{"text":"Adequate development:","bold":true},{"text":" the topic is discussed "},{"text":"fully and adequately","bold":true},{"text":". A paragraph of only two or three sentences is probably not fully developed."}]}]},{"type":"paragraph","text":[{"text":"11 methods of adequate development:","bold":true},{"text":" (1) use examples and illustrations; (2) cite data (facts, statistics, evidence, details); (3) examine testimony (quotes and paraphrases); (4) use an anecdote or story; (5) define terms; (6) compare and contrast; (7) evaluate causes and reasons; (8) examine effects and consequences; (9) analyse the topic; (10) describe the topic; (11) offer a chronology of an event (time segments)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"easily understandable to the reader\" = "},{"text":"coherence","bold":true},{"text":", not unity or development. \"Completeness\" is not an element."}]},{"text":[{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 30, $study_guide$"Trap: unity is not \"connection with other paragraphs\", brevity or elocution."}]},{"text":[{"text":"Trap: ways of enhancing coherence are transition words, synonyms, repeated key words "},{"text":"and pronouns","bold":true},{"text":". \"Avoiding pronouns\" is "},{"text":"not","bold":true},{"text":" one."}]}]}]},{"number":"7.6","title":"New paragraphs, transitions and signposts","mustKnow":[{"type":"paragraph","text":[{"text":"Start a new paragraph in 4 cases:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"When you begin a new idea or point.","bold":true},{"text":" Each new point within an extended idea gets its own paragraph."}]},{"text":[{"text":"To contrast information or ideas:","bold":true},{"text":" sides in a debate, points in an argument, any other difference."}]},{"text":[{"text":"When your readers need a pause:","bold":true},{"text":" a short break for readability, when the paragraph grows too long or the material is complex."}]},{"text":[{"text":"When you are ending your introduction or starting your conclusion.","bold":true},{"text":" These always sit in new paragraphs; many introductions and conclusions have several."}]}]},{"type":"paragraph","text":[{"text":"It is "},{"text":"not","bold":true},{"text":" ideal to start a new paragraph "},{"text":"when you have just introduced the topic","bold":true},{"text":"; stay and support it."}]},{"type":"paragraph","text":[{"text":"Transitions and signposts","bold":true},{"text":" are two very important elements of paragraphing:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Signposts:","bold":true},{"text":" internal aids to readers; usually several sentences or a paragraph outlining "},{"text":"what the article has covered and where it is going","bold":true},{"text":"."}]},{"text":[{"text":"Transitions:","bold":true},{"text":" usually one or several sentences that move from one idea to the next, used at the "},{"text":"end of most paragraphs","bold":true},{"text":" so they flow into the next. Transitions are also needed within paragraphs (Lesson 7.5)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Linking devices","bold":true},{"text":" (transition words) show how an idea follows from the last: "},{"text":"furthermore","italic":true},{"text":" (adding), "},{"text":"however","italic":true},{"text":" (contrasting), "},{"text":"finally","italic":true},{"text":" (ordering), "},{"text":"therefore","italic":true},{"text":", "},{"text":"thus","italic":true},{"text":", "},{"text":"on the other hand","italic":true},{"text":"."}]},{"text":[{"text":"Trap: "},{"text":"because","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" a linking device in this sense; it is a subordinating conjunction joining a dependent clause to a main clause inside one sentence. Among "},{"text":"furthermore","italic":true},{"text":", "},{"text":"however","italic":true},{"text":", "},{"text":"finally","italic":true},{"text":" and "},{"text":"because","italic":true},{"text":", the odd one out is "},{"text":"because","italic":true},{"text":"."}]},{"text":[{"text":"Trap: a new paragraph is "},{"text":"not","bold":true},{"text":" ideal \"when you have introduced the topic\"; concluding, contrasting and introducing a new idea are all proper moments."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Paragraph = unit of composition: related sentences on a single topic; at least 3 sentences; length does not define it."}]},{"text":[{"text":"Paragraphs and essays share "},{"text":"unity and coherence","bold":true},{"text":"."}]},{"text":[{"text":"8 types: definition, classification, descriptive, comparison and contrast, sequence (time order), choice, explanation (how or why), evaluation (criteria plus recommendation)."}]},{"text":[{"text":"Topic sentence = states the main idea and works as its summary; the most important sentence; the thesis of the paragraph; often but not always first."}]},{"text":[{"text":"Good topic sentence: concise and emphatic; shows the point at once; at the end when details build to a generalisation; sometimes avoided; carefully worded and restricted."}]},{"text":[{"text":"Structure: topic sentence (essential), support sentences (essential), concluding sentence (optional)."}]},{"text":[{"text":"5 steps: controlling idea and topic sentence; explain it; example(s); explain example(s); complete or transition."}]},{"text":[{"text":"Troubleshoot 3 problems: topic sentence, multiple controlling ideas, transitions within the paragraph. Not length."}]},{"text":[{"text":"4 elements: unity, coherence (logical and verbal bridges), topic sentence, adequate development (11 methods)."}]},{"text":[{"text":"New paragraph: new idea, contrast, pause, ending introduction or starting conclusion. Signposts say where the piece has been and is going; transitions carry one idea into the next."}]}]}],"theory":{"itemId":"4bd81e1d-548e-510e-949b-183e435120aa","question":[{"type":"paragraph","text":[{"text":"Outline and explain the five-step process for paragraph development."}]}]},"practice":[{"topic":"Writing Skills I: The Paragraph","named":false}]}},{"kind":"note","itemId":"77671218-e56e-59ef-a2ef-64c688d32f17","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Writing Skills II: Essay Writing","body":"Why writing matters to scholarship; what an essay is and its thesis; the four essay types (narrative, analytical, descriptive, argumentative/persuasive) and what each demands; the COEM factor (Content, Organisation, Expression, Mechanics); introduction, body and conclusion; linking paragraphs; the punctuation marks and their functions; capitalisation, spelling, reports and the parts of a formal letter.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"Why writing matters to scholarship; what an essay is and its thesis; the four essay types (narrative, analytical, descriptive, argumentative/persuasive) and what each demands; the COEM facto$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 31, $study_guide$r (Content, Organisation, Expression, Mechanics); introduction, body and conclusion; linking paragraphs; the punctuation marks and their functions; capitalisation, spelling, reports and the parts of a formal letter."}],"lessons":[{"number":"8.1","title":"Writing, the essay and its parts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Writing","bold":true},{"text":" is an indispensable part of scholarship: about the most "},{"text":"permanent record","bold":true},{"text":" of your view on an issue. It requires "},{"text":"training, tact, imagination and rigour","bold":true},{"text":"."}]},{"text":[{"text":"Academic activity consists of observing phenomena and reporting on them, listening to lectures, group projects and, most important, "},{"text":"reading and reviewing","bold":true},{"text":". Through writing (term papers, research reports) you are tested on how much you have learned."}]},{"text":[{"text":"Essay:","bold":true},{"text":" a written paper of "},{"text":"several paragraphs","bold":true},{"text":" addressing a "},{"text":"central subject","bold":true},{"text":" clearly specified in the "},{"text":"thesis statement","bold":true},{"text":". An essay is a combination of ideas from one paragraph to another that creates a "},{"text":"united whole","bold":true},{"text":"."}]},{"text":[{"text":"Thesis:","bold":true},{"text":" the "},{"text":"major point an essay seeks to prove","bold":true},{"text":"; the central idea and organising principle. In a scholarly (expository) essay it is stated in the "},{"text":"first (introductory) paragraph","bold":true},{"text":". In imaginative writing (a short story) it is implied in the "},{"text":"conflict","bold":true},{"text":" and need not be in the first paragraph."}]},{"text":[{"text":"The thesis statement is to an essay what the topic sentence is to a paragraph.","bold":true}]},{"text":[{"text":"4 types of essay","bold":true},{"text":" (by content, goal or strategy): "},{"text":"narrative, analytical, persuasive (argumentative), descriptive","bold":true},{"text":". Keep them distinct; do not confuse the method of one with another."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Introduction:","bold":true},{"text":" states the "},{"text":"thesis","bold":true},{"text":", sets the "},{"text":"tone","bold":true},{"text":", gives the "},{"text":"plan","bold":true},{"text":" of the essay; arouses interest."}]},{"text":[{"text":"Middle (main body):","bold":true},{"text":" develops the thesis, one idea per paragraph."}]},{"text":[{"text":"Conclusion:","bold":true},{"text":" signals the "},{"text":"idea of concluding","bold":true},{"text":", looks back over the argument (a "},{"text":"flashback","bold":true},{"text":" or recap) and gives a "},{"text":"resolution of the thesis","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 main features of a full essay:","bold":true},{"text":" (1) appropriate choice of words and acceptable sentences; (2) good paragraphing and grammatical sentences; (3) coherence and use of standard writing conventions."}]},{"text":[{"text":"3 stages of the writing process:","bold":true},{"text":" "},{"text":"pre-writing","bold":true},{"text":" (planning, "},{"text":"brainstorming","bold":true},{"text":": jotting down every idea on the topic before organising them), "},{"text":"writing","bold":true},{"text":" (drafting), "},{"text":"proof-reading","bold":true},{"text":" (checking and correcting). "},{"text":"Publishing is not a stage.","bold":true},{"text":" Brainstorming is a fundamental of writing a good essay."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learning takes place when you can compare issues, define, classify, analyse and illustrate phenomena; your writing shows your competence and comprehension."}]},{"text":[{"text":"Trap: the three parts of good writing are "},{"text":"introduction, middle, conclusion","bold":true},{"text":", not \"introduction, summary, conclusion\" (the summary belongs in the conclusion)."}]},{"text":[{"text":"Trap: a "},{"text":"proposal","bold":true},{"text":" and an "},{"text":"experimental","bold":true},{"text":" essay are "},{"text":"not","bold":true},{"text":" essay types. \"Expository\" is another name for the factual, analytical essay; \"argumentative\" is another name for persuasive."}]},{"text":[{"text":"A "},{"text":"synopsis","bold":true},{"text":" is a summary; a "},{"text":"theme","bold":true},{"text":" is the general subject area; the "},{"text":"thesis","bold":true},{"text":" is the point you prove."}]}]}]},{"number":"8.2","title":"The four types of essay","mustKnow":[{"type":"paragraph","text":[{"text":"1. Narrative essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"sequential or chronological account","bold":true},{"text":" of an experience, procedure or incident; largely "},{"text":"reportorial","bold":true},{"text":". Ranges from a field-trip account to biography, autobiography and fiction. A "},{"text":"police statement","bold":true},{"text":" (what happened, in order) is narrative writing."}]},{"text":[{"text":"Chief aim:","bold":true},{"text":" to "},{"text":"arouse and sustain interest","bold":true},{"text":"; to make the reader feel a good story has been told."}]},{"text":[{"text":"Features: "},{"text":"story line, plot, suspense","bold":true},{"text":" and other rhetorical devices. It does "},{"text":"not","bold":true},{"text":" need a strong argument."}]},{"text":[{"text":"It "},{"text":"emphasises character and setting","bold":true},{"text":" so the reader identifies with the subject. It should be "},{"text":"racy","bold":true},{"text":" (lively), "},{"text":"captivating","bold":true},{"text":" and "},{"text":"plausibly handled","bold":true},{"text":". It lacks the complexity of other types."}]}]},{"type":"paragraph","text":[{"text":"2. Analytical essay","bold":true}]},{"type":"list","ordered":false,"items"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 32, $study_guide$:[{"text":[{"text":"The type a university student writes most. The writer identifies an issue, "},{"text":"examines","bold":true},{"text":" it in detail and "},{"text":"assesses its implications for human existence","bold":true},{"text":". It does "},{"text":"not","bold":true},{"text":" give a chronological account."}]},{"text":[{"text":"2 forms (by strategy of rendition):","bold":true},{"text":" "},{"text":"rationalisations","bold":true},{"text":" (explain the state of things by interpreting facts or data so the reader can form a judgement) and "},{"text":"critiques","bold":true},{"text":" (review an issue, experiment or creative work by making "},{"text":"statements on its quality","bold":true},{"text":"; must rest on reliable and verifiable authority, fact, logic, clear thinking and valid opinion). "},{"text":"Criticism = the informed evaluation of imaginative writing.","bold":true},{"text":" Critique suits the humanities and social sciences."}]},{"text":[{"text":"Empirical method:","bold":true},{"text":" self-evident or verifiable facts; results come instantly without controversy (an object thrown up falls). Suits the "},{"text":"natural sciences","bold":true},{"text":"."}]},{"text":[{"text":"Interpreting the results of experiments may need "},{"text":"rationalisation, critique and empirical methods","bold":true},{"text":" combined (all three)."}]},{"text":[{"text":"A good analytical essay rests on "},{"text":"clear thinking, accurate or verified data, reliable authority and a clear conclusion","bold":true},{"text":" from the evidence, and separates the writer's opinion from facts."}]}]},{"type":"paragraph","text":[{"text":"3. Descriptive essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"detailed and often dispassionate account of people, incidents, scenes and situations","bold":true},{"text":" so the reader can imagine and visualise them as a participant/observer; it "},{"text":"creates a mental picture","bold":true},{"text":"."}]},{"text":[{"text":"Often part of fiction, biography or a "},{"text":"travelogue","bold":true},{"text":" (account of a travel). Objective: an overall impression that aligns the reader with the writer's view, by appealing to "},{"text":"visual and sensory perceptions","bold":true},{"text":"."}]},{"text":[{"text":"2 requirements:","bold":true},{"text":" (1) "},{"text":"appropriate wording","bold":true},{"text":": a large stock of visual and sensory vocabulary; the essay is "},{"text":"shorn of personal feelings","bold":true},{"text":" so the writer stays invisible; (2) "},{"text":"keen observation","bold":true},{"text":": authentic details; noticing what is uncommon to the general eye."}]}]},{"type":"paragraph","text":[{"text":"4. Argumentative (persuasive) essay","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The writer tries to get readers to "},{"text":"accept a point of view","bold":true},{"text":". Goal: to "},{"text":"sell an idea","bold":true},{"text":", "},{"text":"convince readers","bold":true},{"text":" to make up or change their minds, "},{"text":"persuade the audience","bold":true},{"text":" (all three). The writer "},{"text":"takes a stand","bold":true},{"text":". Argument is at the core of most university writing."}]},{"text":[{"text":"2 strategies:","bold":true},{"text":" (1) "},{"text":"the use of details","bold":true},{"text":": reasoning that is "},{"text":"inductive","bold":true},{"text":" (particular to general) or "},{"text":"deductive","bold":true},{"text":" (general to specific), using statistics, illustrations, justifications, cause/effect relations, analogies and appeals to authorities; (2) "},{"text":"appeal to the emotion","bold":true},{"text":": logic alone cannot win a reader; build a friendly disposition, show authority, arrange ideas for emotional impact."}]},{"text":[{"text":"Not","bold":true},{"text":" necessary in an argument: creating a mental picture (that is description)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Narrative: a narration fails when the subject is commonplace or has a trite moral; the reader says \"and so what?\" Fantasy works (science and detective fiction) if plausibly handled. Sample: \"A Face in the Night\" by Ruskin Bond (Mr Oliver and the faceless boy at Simla); its force lies in character, word choice and brevity."}]},{"text":[{"text":"Analytical example: an essay on a major decision (postgraduate study versus paid employment): state the decision in the first paragraph; give each reason its own paragraph. The sample on a mother giving up her baby for adoption (reasons: her age, her parents' problems, her own future) illustrates "},{"text":"rationalisation","bold":true},{"text":"."}]},{"text":[{"text":"Descriptive samples: \"In the Jungle\" (Gerald Durrell) emphasises "},{"text":"size","bold":true},{"text":" with visual words (\"tremendous\", \"choked\", \"ran riot\"); \"jungle\" appears only in the title. \"The Open Boat\" (Stephen Crane) uses colour, shape, sound and smell to evoke doom; the mood is "},{"text":"dejection and despair","bold":true},{"text":"."}]},{"text":[{"text":"Descriptive trap: words like \"dirty\", \"clean\", \"untidy\" (describing a slum) and superlatives like \"wonderful\", \"excellent\", \"best\" rob the essay of "},{"text":"detachment","bold":true},{"text":"; use them only where justified."}]},{"text":[{"text":"Persuasive sample: \"The Crime of Imprisonment\" uses "},{"text":"reasoning by analogy","bold":true},{"text":" (prisoner compared with a pneumonia patient punished and cured at once). Prisons aim to be "},{"text":"retributory, deterrent and reformative","bold":true},{"text":", yet men are not improved by injuries. The analogy works as an extended metaphor, appealing to emotion and logic."}]},{"text":[{"text":"Trap: a "},{"text":"police statement","bold":true},{"text":" is narrative in method (events in order), but a police report, an annual general meeting report a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 33, $study_guide$nd a sports report count as "},{"text":"expository","bold":true},{"text":" (they set out facts). A "},{"text":"newspaper article","bold":true},{"text":" is not classed as expository because it may narrate, describe, argue or entertain."}]}]}]},{"number":"8.3","title":"The COEM factor and connecting paragraphs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"COEM = Content, Organisation, Expression, Mechanics:","bold":true},{"text":" the four quality-control components that separate a well-executed essay from a poor one."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Content:","bold":true},{"text":" the "},{"text":"depth of treatment","bold":true},{"text":" of the subject; the authority or knowledge brought to it. Called the "},{"text":"\"meat of the essay\"","bold":true},{"text":". Two rules: (a) "},{"text":"limit or narrow the subject","bold":true},{"text":" to achieve depth, since content is a function of size: \"population growth\" is too large; \"Africa's Demographic Multiplications: Implications for the Continent's Economic Development\" is manageable; (b) "},{"text":"maintain a central idea","bold":true},{"text":" (the thesis), which guides selection of material and keeps you focused."}]},{"text":[{"text":"Organisation:","bold":true},{"text":" arranging materials in a "},{"text":"logical order","bold":true},{"text":" to create the desired effect. Develop (a) a suitable "},{"text":"introduction","bold":true},{"text":": perhaps the "},{"text":"most important part","bold":true},{"text":"; arouses and sustains interest; may range from a definition to general ideas; rests on a strong thesis; (b) the "},{"text":"main body","bold":true},{"text":": at the writer's discretion, but move from "},{"text":"familiar to unfamiliar","bold":true},{"text":", simple to complex; (c) a fitting "},{"text":"conclusion","bold":true},{"text":": inferences drawn from linking the facts presented; "},{"text":"striking, memorable and definitive","bold":true},{"text":"."}]},{"text":[{"text":"Expression:","bold":true},{"text":" discriminating choice of "},{"text":"suitable words","bold":true},{"text":" in simple, clear, unambiguous language. Writers lack the speaker's feedback (questions, gestures, tone of voice), so the key is to be "},{"text":"precise, concise and economical","bold":true},{"text":". Two steps: (a) "},{"text":"avoid jargon, deodorant language and highfalutin expressions","bold":true},{"text":"; (b) "},{"text":"be concrete","bold":true},{"text":" (\"Mrs Babatunde mailed the agreement to me\" names the performer; \"The agreement was mailed to me\" is non-concrete). Use clear, concise, forceful sentences and a friendly, natural, courteous tone."}]},{"text":[{"text":"Mechanics:","bold":true},{"text":" meaningful items in a sentence expressed in "},{"text":"symbols rather than words","bold":true},{"text":"; the technical term is "},{"text":"punctuation","bold":true},{"text":". Mechanics of writing also covers "},{"text":"capitalisation","bold":true},{"text":" and "},{"text":"spelling and letter shapes","bold":true},{"text":" (all of these)."}]}]},{"type":"paragraph","text":[{"text":"Connecting paragraphs","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Vary paragraph length.","bold":true},{"text":" Short paragraphs let the reader grasp facts quickly but become "},{"text":"choppy","bold":true},{"text":" if overused; long ones become "},{"text":"boring","bold":true},{"text":". A good essay has "},{"text":"a variation of long and short paragraphs","bold":true},{"text":", which improves continuity and the logic of thought."}]},{"text":[{"text":"Each paragraph communicates a "},{"text":"single idea","bold":true},{"text":" stated in a "},{"text":"topic sentence","bold":true},{"text":", clarified by examples, details and descriptions."}]},{"text":[{"text":"Paragraphs are related by "},{"text":"linking devices (linking expressions)","bold":true},{"text":": first; second; finally; in contrast with; compared to the above; following upon; furthermore; in addition; however. Their function is to specify "},{"text":"continuity","bold":true},{"text":" by establishing a clear relationship with the idea already expressed."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"COEM traps: not \"Entertainment\", \"Comment\" or \"Orientation\". Content is what the essay says; expression is how; organisation is the order; mechanics is the symbols."}]},{"text":[{"text":"Depth trap: to achieve depth you "},{"text":"narrow","bold":true},{"text":" the subject, never expand it. A broad subject is merely skimmed."}]},{"text":[{"text":"The inflated passage on \"organisational behaviour\" says, in fanciful words, only that the field has grown greatly and is now a separate discipline. Inflated vocabulary conceals near emptiness of idea and draws attention to the writer, not the subject."}]}]}]},{"number":"8.4","title":"Punctuation marks and their functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Punctuation marks:","bold":true},{"text":" symbols used to organise and structure expressions so as to convey the right meaning."}]},{"text":[{"text":"The frequently used marks: full stop (.), question mark (?), exclamation mark (!), quotation marks (\" \"), square brackets [ ], comma (,), semi-colon (;), colon (:), capital letters, hyphen (-), dash (–), ellipsis (...), apostrophe ('), parentheses or round brackets ( )."}]},{"text":[{"text":"4 general functions:","bold":true},{"text":" (a) integral to the meaning of the sentence; (b) signify completion or absence of completion of thought; (c) delineate attitudes or idiosyncrasies of speakers or writers; (d) demonstrate variations of pitch or intonation. Punctuation also separates subordinate ideas from major ones, marks stretches of direct speech and shows the possessive case. It does "},{"text":"not","bold":true},{"text":" indicate a writer's background."}]}]}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 34, $study_guide$,{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Full stop (period):","bold":true},{"text":" ends a complete "},{"text":"declarative","bold":true},{"text":" or "},{"text":"imperative","bold":true},{"text":" sentence. Also marks off "},{"text":"abbreviations and initials","bold":true},{"text":" (Mr., Prof., Ph.D., E. A. Adedun). Omitted in "},{"text":"acronyms","bold":true},{"text":" (UNICEF, NEPA, FIFA, ASUU)."}]},{"text":[{"text":"Exclamation mark:","bold":true},{"text":" ends a structure expressing "},{"text":"surprise, horror, disappointment, anger, indeed all forms of excitement","bold":true},{"text":"; strong feeling, a warning or forceful command; punctuates "},{"text":"interjections","bold":true},{"text":" (Move! Look out! Oh, boy!). Hardly used in formal business writing."}]},{"text":[{"text":"Question mark:","bold":true},{"text":" ends a "},{"text":"direct question","bold":true},{"text":" (interrogative sentence). "},{"text":"Never","bold":true},{"text":" after an "},{"text":"indirect (reported) question","bold":true},{"text":": \"The manager demanded to know why production was slow.\""}]},{"text":[{"text":"Colon:","bold":true},{"text":" introduces a "},{"text":"list","bold":true},{"text":", especially after \"these\", \"namely\", \"the following\", \"as follows\". Also introduces "},{"text":"direct speech","bold":true},{"text":" after a speaker's name in dialogue (\"Okon said: 'I am hungry.'\") and the "},{"text":"publisher's name","bold":true},{"text":" in a reference entry (Ibadan: Heinemann)."}]},{"text":[{"text":"Semi-colon:","bold":true},{"text":" (a) "},{"text":"separates independent clauses","bold":true},{"text":", replacing a comma plus coordinating conjunction (\"Supply us with three cars; they must all be black\"); (b) separates "},{"text":"phrases and clauses in a series","bold":true},{"text":" that already contain commas; (c) sets off conjunctive adverbs (however, therefore, moreover) joining independent clauses."}]},{"text":[{"text":"Comma:","bold":true},{"text":" separates words, phrases, clauses, items and non-essentials; sets off a state from a town, a street from a city, the day from the month. The comma before \"and\" in a list is the "},{"text":"serial comma","bold":true},{"text":". Never put a comma between a "},{"text":"subject and its verb","bold":true},{"text":"."}]},{"text":[{"text":"Dash and hyphen:","bold":true},{"text":" the difference is "},{"text":"context, not length","bold":true},{"text":". The "},{"text":"dash","bold":true},{"text":" works in "},{"text":"syntactic","bold":true},{"text":" constructions and introduces "},{"text":"additional information","bold":true},{"text":" (\"All managers – I mean most managers – look forward to vacations\"). The "},{"text":"hyphen","bold":true},{"text":" works in "},{"text":"lexical","bold":true},{"text":" constructions (ex-senator, sister-in-law, bye-laws)."}]},{"text":[{"text":"Parentheses (round brackets):","bold":true},{"text":" mark off "},{"text":"additional or explanatory information","bold":true},{"text":" the sentence could do without (\"management (the decision-making body)\"). Brackets also enclose a "},{"text":"reference","bold":true},{"text":". Commas, dashes and parentheses differ in "},{"text":"degree","bold":true},{"text":": commas for closely related material, dashes to emphasise interruptions, parentheses for the least essential extras."}]},{"text":[{"text":"Square brackets:","bold":true},{"text":" enclose information "},{"text":"inserted into a quotation","bold":true},{"text":" for clarity."}]},{"text":[{"text":"Apostrophe:","bold":true},{"text":" shows "},{"text":"omission (contractions)","bold":true},{"text":": won't; and "},{"text":"possession","bold":true},{"text":": Ade's salary, Moses' allowance. "},{"text":"Never","bold":true},{"text":" with possessive pronouns: theirs, yours, "},{"text":"its","bold":true},{"text":" (\"the dog wagged its tail\"; \"it's\" means \"it is\"). Never used simply to form plurals."}]},{"text":[{"text":"Quotation marks (inverted commas):","bold":true},{"text":" used "},{"text":"in pairs","bold":true},{"text":" to enclose a third party's exact words (direct speech): Okon said: \"I am hungry.\" Not used for indirect speech: Okon said that he was hungry."}]},{"text":[{"text":"Ellipsis:","bold":true},{"text":" three dots showing items omitted from a quotation; "},{"text":"four dots","bold":true},{"text":" if the omission is at the end of a sentence (the fourth is the full stop)."}]},{"text":[{"text":"Capitalisation:","bold":true},{"text":" see Lesson 8.5."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Terminal punctuation marks","bold":true},{"text":" (they end a sentence): "},{"text":"full stop, question mark, exclamation mark","bold":true},{"text":". The comma is "},{"text":"not","bold":true},{"text":" terminal."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unpunctuated: \"william shakespeare 1564-1616 married a woman eight years his senior when he was eighteen.\" Punctuated: \"William Shakespeare (1564-1616) married a woman eight years his senior when he was eighteen.\" Likewise: \"...his collection, "},{"text":"Girls at War","italic":true},{"text":", took place on a cold December day in Lagos.\""}]},{"text":[{"text":"In Oswald Mtshali's poem a dead mother tells her son \"There is no heaven / Above the clouds\"; his reply \"WHAT!\" is neither question nor statement. Capitals plus exclamation mark pack in his surprise, horror and shock: mechanics introducing figurative language."}]},{"text":[{"text":"Serial comma: \"The General Manager, Production Manager and Operations Manager are going\" could mean the GM is being told two people are going; \"...Production Manager, and Operations Manager...\" makes three travellers clear. Insert it for clarity."}]},{"text":[{"text":"Paired-mark trap: only "},{"text":"quotation marks","bold":true},{"text":" come in pairs; question mark, hyphen and apostrophe a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 35, $study_guide$re single."}]},{"text":[{"text":"Comma-splice trap: a comma alone cannot separate two independent clauses; use a semi-colon."}]},{"text":[{"text":"Colon-use trap: the colon's three uses are the list, direct speech and the publisher's name in a reference entry. Breaking a title into two parts is "},{"text":"not","bold":true},{"text":" one of them."}]},{"text":[{"text":"Poor punctuation distorts meaning; attention to these \"minor details\" can determine an employee's career."}]}]}]},{"number":"8.5","title":"Mechanics, spelling and other kinds of writing","mustKnow":[{"type":"paragraph","text":[{"text":"Capitalisation rules.","bold":true},{"text":" Use a capital letter:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"at the "},{"text":"beginning of a sentence","bold":true},{"text":" and after every terminal mark (full stop, question mark, exclamation mark);"}]},{"text":[{"text":"for the pronoun "},{"text":"\"I\"","bold":true},{"text":", wherever it occurs (an isolated \"I\");"}]},{"text":[{"text":"for "},{"text":"proper nouns","bold":true},{"text":" (John, Oshogbo, Africa) and "},{"text":"proper adjectives","bold":true},{"text":" of nationality and language (Chilean, Guatemalan, Gaelic, French);"}]},{"text":[{"text":"for names of "},{"text":"deities and sacred contexts","bold":true},{"text":" (God, Allah, the Bible);"}]},{"text":[{"text":"for "},{"text":"principal words in titles, headings and sub-headings","bold":true},{"text":" ("},{"text":"Elements of English Grammar and Usage","italic":true},{"text":"), and named courses (History);"}]},{"text":[{"text":"for "},{"text":"acronyms","bold":true},{"text":" (NFL, PTA, UNICEF) and letter-based words (U-turn)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Do not","bold":true},{"text":" capitalise "},{"text":"common nouns","bold":true},{"text":" (guesstimates, parsnip) unless they begin a sentence, and do not capitalise after a comma unless the word is a proper noun."}]}]},{"type":"paragraph","text":[{"text":"Spelling.","bold":true},{"text":" Learn these correctly spelled words: "},{"text":"harassment","bold":true},{"text":" (one r, two s), "},{"text":"embarrassment","bold":true},{"text":" (two r, two s), "},{"text":"accommodation","bold":true},{"text":" (two c, two m), "},{"text":"sheriff","bold":true},{"text":" (one r, two f), "},{"text":"souvenir","bold":true},{"text":" (not -ier), "},{"text":"chauffeur","bold":true},{"text":", "},{"text":"parachutist","bold":true},{"text":", "},{"text":"adolescence","bold":true},{"text":" (-esc-, -ence), "},{"text":"shrivel","bold":true},{"text":" (-el), "},{"text":"clammy","bold":true},{"text":" (two m), "},{"text":"sphinx","bold":true},{"text":", "},{"text":"repertoire","bold":true},{"text":", "},{"text":"vagrant","bold":true},{"text":", "},{"text":"resinous","bold":true},{"text":", "},{"text":"communication","bold":true},{"text":", "},{"text":"swinging","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Reports and technical writing","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Report:","bold":true},{"text":" a faithful account of an activity in which the writer participated; it provides "},{"text":"information to influence decisions and actions","bold":true},{"text":". A report must be based on "},{"text":"facts","bold":true},{"text":", not hearsay or arguments."}]},{"text":[{"text":"Objectivity:","bold":true},{"text":" the highest degree is expected in "},{"text":"scientific writing","bold":true},{"text":"."}]},{"text":[{"text":"Technical writing:","bold":true},{"text":" factual, practical, specialised writing: a "},{"text":"car manual, police reports, law reports","bold":true},{"text":". "},{"text":"Not","bold":true},{"text":" love poems. "},{"text":"SME = Subject Matter Expert","bold":true},{"text":", the specialist whose knowledge ensures the content is accurate."}]},{"text":[{"text":"Not reports: a "},{"text":"memorandum","bold":true},{"text":" (brief internal message), an "},{"text":"agenda","bold":true},{"text":" (list of meeting items), "},{"text":"anecdotes","bold":true},{"text":" (short stories), "},{"text":"prolegomena","bold":true},{"text":" (preliminary introduction to a book), an "},{"text":"episode","bold":true},{"text":" (one event in a story)."}]}]},{"type":"paragraph","text":[{"text":"Parts of a formal letter","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Writer's address and "},{"text":"date","bold":true},{"text":"."}]},{"text":[{"text":"Inside address:","bold":true},{"text":" the addressee's name, "},{"text":"designation","bold":true},{"text":" and address."}]},{"text":[{"text":"Salutation:","bold":true},{"text":" Dear Sir / Dear Madam / Dear Mr Okon."}]},{"text":[{"text":"Heading (subject line)","bold":true},{"text":"."}]},{"text":[{"text":"Body","bold":true},{"text":" of the letter."}]},{"text":[{"text":"Subscription","bold":true},{"text":" (complimentary close): "},{"text":"Yours faithfully","bold":true},{"text":" (after Dear Sir/Madam) or "},{"text":"Yours sincerely","bold":true},{"text":" (after a named person)."}]},{"text":[{"text":"Signature","bold":true},{"text":" and the writer's name."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Spotting a wrongly capitalised sentence: check the first letter (\"a parsnip is a root vegetable...\" fails), then proper nouns and acronyms (\"The nfl will repeat...\" fails; it should be NFL)."}]},{"text":[{"text":"Spelling traps: \"harrassment\" copies the double r of \"embarrassment\"; \"souvenier\" adds an unneeded e; \"Adolescense\" ends wrongly in -ense; \"adolescents\" are the people, \"adolescence\" is the stage (the awkward stage); \"parachutis\" has lost its final t; \"clamy\" has lost an m."}]},{"text":[{"text":"Letter trap: the \"subscription\" is the close before the signature, not the salutation, the addressee's designation or the body."}]}]}]}],"recap":[{"type":"list","ordered":fals$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 36, $study_guide$e,"items":[{"text":[{"text":"Writing is the most permanent record of your view; it needs training, tact, imagination, rigour."}]},{"text":[{"text":"Essay = several paragraphs on a central subject; the thesis is the point to prove, stated in the first paragraph; thesis : essay :: topic sentence : paragraph."}]},{"text":[{"text":"Four essay types: narrative (chronological, suspense, character and setting), analytical (rationalisations and critiques), descriptive (dispassionate, visual and sensory), argumentative/persuasive (details and appeal to emotion)."}]},{"text":[{"text":"COEM: Content (meat; narrow the subject), Organisation (introduction, body, conclusion), Expression (precise, concise, concrete), Mechanics (punctuation)."}]},{"text":[{"text":"Vary paragraph length; link paragraphs with linking expressions."}]},{"text":[{"text":"Full stop/period ends statements and marks initials; colon introduces lists and direct speech; semi-colon separates independent clauses; exclamation mark for interjections and excitement; question mark only for direct questions; apostrophe for contractions and possession (never its/theirs/yours); quotation marks in pairs; dash for added information; parentheses for explanatory extras."}]},{"text":[{"text":"Terminal marks: full stop, question mark, exclamation mark."}]},{"text":[{"text":"Capitalise sentence starts, \"I\", proper nouns and adjectives, deities, titles, acronyms; not common nouns."}]},{"text":[{"text":"Reports rest on facts and inform decisions; scientific writing is most objective; SME = subject matter expert; the subscription is \"Yours faithfully\"."}]}]}],"theory":{"itemId":"d9c56737-2394-5e87-a520-cafd3101f6c5","question":[{"type":"paragraph","text":[{"text":"Explain the COEM factor in essay writing."}]}]},"practice":[{"topic":"Writing Skills II: Essay Writing and Punctuation","named":false}]}},{"kind":"note","itemId":"32ce878f-a0db-5952-a8d8-2714a3589b45","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Vocabulary Development","body":"What vocabulary is and where English words came from (Anglo-Saxon, Latin, French, Greek); active versus dormant (recognition) vocabulary and how to grow both; general and specialised dictionaries, including the thesaurus; the types of meaning (denotative, connotative, contextual); the word-formation processes (coining, blending, compounding, clipping, reduplicating, acronym, affixation, neologism); morphemes, roots, prefixes and suffixes; and how to choose the right word from a commonly confused pair.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What vocabulary is and where English words came from (Anglo-Saxon, Latin, French, Greek); active versus dormant (recognition) vocabulary and how to grow both; general and specialised dictionaries, including the thesaurus; the types of meaning (denotative, connotative, contextual); the word-formation processes (coining, blending, compounding, clipping, reduplicating, acronym, affixation, neologism); morphemes, roots, prefixes and suffixes; and how to choose the right word from a commonly confused pair."}],"lessons":[{"number":"9.1","title":"What vocabulary is and where English words came from","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vocabulary:","bold":true},{"text":" the "},{"text":"total stock of words available in a language","bold":true},{"text":"."}]},{"text":[{"text":"Lexicographers","bold":true},{"text":" (word experts) estimate English has about "},{"text":"one million","bold":true},{"text":" words, yet hardly any learner knows "},{"text":"10,000","bold":true},{"text":". "},{"text":"William Shakespeare","bold":true},{"text":" is said to have used "},{"text":"21,000","bold":true},{"text":" words in all his works."}]},{"text":[{"text":"Poor vocabulary","bold":true},{"text":" makes a speaker substitute an "},{"text":"almost-right word","bold":true},{"text":" for the right word, or simply avoid speaking his or her mind."}]},{"text":[{"text":"Meaning in words is largely a matter of agreement:","bold":true},{"text":" a word means what speakers agree it means. That is why a word from another language can become English once English speakers adopt it (e.g. "},{"text":"vuvuzela","bold":true},{"text":", only Zulu before the FIFA 2010 World Cup in South Africa, English afterwards)."}]},{"text":[{"text":"English vocabulary is vast because of "},{"text":"four main influences","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Anglo-Saxon:","bold":true},{"text":" the "},{"text":"basic form","bold":true},{"text":" of English and the bulk of words known as "},{"text":"Native English","bold":true},{"text":". The Anglo-Saxons were "},{"text":"three Germanic tribes","bold":true},{"text":": the "},{"text":"Angles, the Saxons and the Jutes","bold":true},{"text":", who invaded Britain (Britannia) in "},{"text":"450 AD","bold":true},{"text":" and settled. The land where the Angles settled was called "},{"text":"Angle-land","bold":true},{"text":", from which "},{"text":"England","bold":true},{"text":" comes. Later the "},{"text":"Norse and the Vikings","bold":true},{"text":" (Scandinavian tribes) also invaded, adding to the cultural mix."}]},{"text":[{"text":"Latin:","bold":true},{"text":" came in (a) through "},{"text":"Christianity","bold":true},{"text":" (Latin was the language of European Christianity, carried by the Roman church); (b) through the "},{"text":"Renaissance","bold":true},{"text":" in England, the rebirth of learning Greek and Roman classics. The Romans had invaded Britain long before the Anglo-Saxons but did "},{"text":"not interfere","bold":true},{"text":" with the native languages, "},{"text":"Gaelic, Celtic and Welsh","bold":true},{"text":"."}]},{"text":[{"text":"French:","bold":true},{"text":" through the "},{"text":"Norman Conquest of 1066 AD","bold":true},{"text":". French gave words for the "},{"text":"kitchen, cooking, government, administration and persons","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 37, $study_guide$bold":true},{"text":". French also entered English indirectly through Latin, because French is "},{"text":"80% Latin","bold":true},{"text":"."}]},{"text":[{"text":"Greek:","bold":true},{"text":" through the "},{"text":"Renaissance","bold":true},{"text":" and scholarly interest in Greek arts. To this day "},{"text":"scientists","bold":true},{"text":" use Greek to name inventions and discoveries."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example words by origin (exams ask \"which word came from...\"):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Anglo-Saxon:","bold":true},{"text":" everyday words: father, mother, son, wife, king, queen, house, home, sea, sheep, cow, dog, fire, bed, the numbers; tell, bring, drink, say, do, go, come, run, buy, sell, eat; dim, wise, good, little, brave, strong, merry; in, with, by, at, for, of, on, under; often, seldom; and, or, but, nor, until, because, unless."}]},{"text":[{"text":"Latin:","bold":true},{"text":" estate, clergy, pastor, janitor, temple, altar, choir, disciple, candle, priest, century, nun, communion, martyr, cross, rite, shrine, monk, mass, lily, robe, pear, virgin. Many are "},{"text":"church","bold":true},{"text":" words."}]},{"text":[{"text":"French:","bold":true},{"text":" vis-à-vis, souvenir, ambience, façade, milieu, elite, fiancée, mirage, genre, cuisine, vogue, faux pas, protégé, naïve, brochure, cliché, liaison, war, poultry, foyer, jacket, envoy, entrepreneur, debut, silhouette, courtesy, laissez-faire, connoisseur, camouflage, jargon, rapport, précis, résumé, chic, repertoire."}]},{"text":[{"text":"Greek:","bold":true},{"text":" alphabet, grammar, syllable, analysis, mystery, angel, myth, hymn, anecdote, rhetoric, logic, school, economics, apostle, anthology, chronicle, sympathy, pseudonym, epitaph, democracy, acrobat, geometry, "},{"text":"atmosphere","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Trap: the Anglo-Saxons are "},{"text":"three","bold":true},{"text":" tribes (Angles, Saxons, Jutes); the Norse and Vikings came "},{"text":"a few centuries later","bold":true},{"text":" and are not Anglo-Saxons."}]},{"text":[{"text":"Trap: the Norman Conquest is "},{"text":"French","bold":true},{"text":" influence (1066), not Latin. The Renaissance brought both "},{"text":"Latin and Greek","bold":true},{"text":"."}]}]}]},{"number":"9.2","title":"Two kinds of vocabulary, learning strategies and the dictionary","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"2 kinds of vocabulary:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active vocabulary:","bold":true},{"text":" the words a speaker "},{"text":"uses frequently","bold":true},{"text":" in spoken and written English."}]},{"text":[{"text":"Dormant or recognition vocabulary:","bold":true},{"text":" words a user "},{"text":"recognises","bold":true},{"text":" when seen or heard but "},{"text":"cannot clearly recall the meaning","bold":true},{"text":" of."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Strategies for growing vocabulary:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Turn "},{"text":"recognition","bold":true},{"text":" vocabulary into "},{"text":"active","bold":true},{"text":" vocabulary: look up in the "},{"text":"dictionary","bold":true},{"text":" words that keep coming up in your reading, then "},{"text":"use them always","bold":true},{"text":" until you master them."}]},{"text":[{"text":"Keep your spoken and written English "},{"text":"simple","bold":true},{"text":" even as your vocabulary grows."}]},{"text":[{"text":"Build recognition vocabulary by "},{"text":"drawing new words","bold":true},{"text":" from the books you read and speeches you hear. "},{"text":"The wider your reading, the larger your recognition vocabulary.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A good dictionary is the basic tool","bold":true},{"text":" every student needs for effective study. It aids vocabulary development by giving "},{"text":"meanings","bold":true},{"text":", "},{"text":"pronunciation","bold":true},{"text":", "},{"text":"spelling","bold":true},{"text":" and "},{"text":"context of usage","bold":true},{"text":" (all of these)."}]},{"text":[{"text":"A dictionary tells you a word's "},{"text":"definition, spelling, usage, capitalisation, synonyms and antonyms, syllabication, word class and pronunciation","bold":true},{"text":"; unabridged ones add "},{"text":"etymology","bold":true},{"text":" (origin). It does "},{"text":"not","bold":true},{"text":" record the "},{"text":"year a word became obsolete","bold":true},{"text":" (at most it labels a word archaic)."}]},{"text":[{"text":"2 types of dictionary:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"General (non-specialised):","bold":true},{"text":" wider coverage and usage. Two kinds: "},{"text":"unabridged","bold":true},{"text":" (contain most words of English with full details, some with etymology; the best source, so get one: e.g. Oxford Advanced Learner's Dictionary, Longman Dictionary of Contemporary English, BBC English Dictionary, Cambridge Dictionary of English) and "},{"text":"abridged","bold":true},{"text":" (shorter versions; guide spelling, capitalisation, punctuation and vocabulary; easy to carry: e.g. The Oxford Pocket Dictionary, Roget Pocket Dictionary, American Heritage Dictionary of the English Language, The Short Oxford English Dictionary). Always buy the "},{"text":"newest edition","bold":true},{"text":"."}]},{"text":[{"text":"Specialised (technical):","bold":true},{"text":" compiled for a "},{"text":"special purpose","bold":true},{"text":"; more thorough coverage of one subject. Three kinds:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dictionary of synonyms:","bold":true},{"text":" lists of words of "},{"text":"similar meaning","bold":true$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 38, $study_guide$},{"text":". The "},{"text":"thesaurus","bold":true},{"text":" is designed for this. Examples: "},{"text":"Webster's Collegiate Thesaurus, Roget International Thesaurus, Modern Guide to Synonyms and Related Words","bold":true},{"text":"."}]},{"text":[{"text":"Scholarly dictionaries:","bold":true},{"text":" specialised in an area of learning: Oxford Dictionary of Philosophy / Psychology / Sociology, A Dictionary of Medical Terms, Standard Dictionary of Folklore, Mythology and Legend, Modern Science Dictionary, Medical Dictionary."}]},{"text":[{"text":"Usage dictionaries:","bold":true},{"text":" show "},{"text":"how words are used","bold":true},{"text":" in speech and writing; help with "},{"text":"collocation","bold":true},{"text":", "},{"text":"synonyms","bold":true},{"text":" and "},{"text":"common errors","bold":true},{"text":"."}]}]}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Collocation:","bold":true},{"text":" a group of words that habitually go together and behave like a "},{"text":"single word with a single meaning","bold":true},{"text":" (e.g. make a decision, earn a living)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"thesaurus","bold":true},{"text":" is a "},{"text":"specialised dictionary","bold":true},{"text":" (not simplified, pictorial or phonetic). Because it is a dictionary of synonyms, it is at once a "},{"text":"list of words","bold":true},{"text":", a set of "},{"text":"synonymous terms","bold":true},{"text":" and a "},{"text":"collection of selected terminology","bold":true},{"text":"; if an option says \"all of the above\", take it."}]},{"text":[{"text":"Other specialised dictionaries you may meet in questions: a "},{"text":"Dictionary of American Slang","bold":true},{"text":", a dictionary of a particular language (e.g. Yoruba), a dictionary of politics. "},{"text":"Webster's","bold":true},{"text":" and the "},{"text":"Oxford English Dictionary","bold":true},{"text":" are "},{"text":"general","bold":true},{"text":" dictionaries."}]},{"text":[{"text":"Usage example: instead of the vague word "},{"text":"thing","bold":true},{"text":", a usage dictionary suggests precise words: aspect, attribute, characteristic, detail, feature, issue, matter, point, subject, topic, trait. Say \"very useful\", not \"a very useful thing\"; \"something important\", not \"an important thing\"; \"so much\", not \"so many things\"."}]},{"text":[{"text":"Dictionary usage entries draw on classroom research and the "},{"text":"British National Corpus","bold":true},{"text":"."}]},{"text":[{"text":"Trap: dormant vocabulary is "},{"text":"not","bold":true},{"text":" unknown vocabulary; you recognise the word, you just cannot pin down its meaning. Unknown words are a third group."}]}]}]},{"number":"9.3","title":"Types of meaning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A word may have "},{"text":"two types of meaning","bold":true},{"text":", and "},{"text":"context","bold":true},{"text":" can add a third:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Denotative meaning:","bold":true},{"text":" the "},{"text":"literal","bold":true},{"text":" meaning; the meaning "},{"text":"lexicographers give a word and enter into the dictionary","bold":true},{"text":"; the meaning of a word "},{"text":"in isolation","bold":true},{"text":", making "},{"text":"direct reference","bold":true},{"text":" to a thing. Dark = lightlessness, no visibility; night = the hours outside daytime."}]},{"text":[{"text":"Connotative meaning:","bold":true},{"text":" meaning "},{"text":"associated with a word based on feelings, emotions and experiences","bold":true},{"text":"; an "},{"text":"underlying","bold":true},{"text":" meaning beyond the literal; it is "},{"text":"figurative","bold":true},{"text":", and it depends on the word's "},{"text":"environment and usage","bold":true},{"text":". \"He's dark\" = evil or malicious; \"in my dark moments\" = difficult, harsh, sorrowful times."}]},{"text":[{"text":"Contextual meaning (verbal context):","bold":true},{"text":" the meaning you work out for an unfamiliar word from the "},{"text":"other words in the sentence","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Useful clues to contextual meaning come from "},{"text":"paired words","bold":true},{"text":" or "},{"text":"parallelism","bold":true},{"text":". Paired words are either "},{"text":"complementary (parallel)","bold":true},{"text":", so the words are "},{"text":"similar","bold":true},{"text":" in meaning, or "},{"text":"contrasting","bold":true},{"text":", so they are "},{"text":"opposite","bold":true},{"text":" in meaning."}]},{"text":[{"text":"Poetic meaning","bold":true},{"text":" is usually "},{"text":"figurative","bold":true},{"text":" (connotative), not denotative."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Connotations may be "},{"text":"positive or negative","bold":true},{"text":". In the pairs persistent/stubborn, notorious/famous, secret/covert, smart/intelligent, light/fair, mountainous/huge, brilliant/clever, the word with the kinder feeling (persistent, famous, intelligent, fair, brilliant) has the positive connotation. "},{"text":"Persistent/stubborn","bold":true},{"text":" is the pair where one side ("},{"text":"stubborn","bold":true},{"text":") is clearly negative; light/fair, brilliant/clever and smart/intelligent are approving on both sides."}]},{"text":[{"text":"Worked examples of contextual clues:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Since he isn't "},{"text":"wasteful","bold":true},{"text":", he is "},{"text":"frugal","bold":true},{"text":"\": the negation of wasteful tells you frugal = careful with money (contrast)."}]},{"text":[{"text":"\"He was "},{"text":"unscrupulous","bold":true},{"text":" and "},{"text":"dishonest","bold":true},{"text":"\": paired by \"and\", so simil$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 39, $study_guide$ar (complementary)."}]},{"text":[{"text":"\"Her "},{"text":"pulchritude","bold":true},{"text":" and "},{"text":"beauty","bold":true},{"text":" charmed the audience\": pulchritude is a synonym of beauty."}]},{"text":[{"text":"\"He's slow because he's a "},{"text":"tyro","bold":true},{"text":"\" = beginner. \""},{"text":"Vitriolic","bold":true},{"text":" remarks\" = angry. \"The counsel "},{"text":"prayed","bold":true},{"text":" the judge\" = pleaded. \"A "},{"text":"sneaking","bold":true},{"text":" suspicion\" = niggling."}]}]}]},{"text":[{"text":"Trap: options exams swap for \"denotative\": \"words used scientifically\", \"words which refer to the past\", \"listing in alphabetical order\". None is right; denotative words "},{"text":"make direct reference","bold":true},{"text":". \"Expressive\" and \"discursive\" are not types of meaning; the pair is "},{"text":"denotative/connotative","bold":true},{"text":"."}]}]}]},{"number":"9.4","title":"Word-formation strategies","mustKnow":[{"type":"paragraph","text":[{"text":"Words have entered English through various formation processes. The "},{"text":"processes of inventing words","bold":true},{"text":" are "},{"text":"coining, blending, compounding, clipping and reduplicating","bold":true},{"text":"; words are also formed by "},{"text":"affixation, neologism and acronyms","bold":true},{"text":" (8 processes in all)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coining:","bold":true},{"text":" creating a word or phrase for a "},{"text":"specific use","bold":true},{"text":", knowing it does not exist in the lexicon; the situation gives it meaning. Example: "},{"text":"\"wardrobe malfunction\"","bold":true},{"text":" (Janet Jackson). Others: skyjacker, skydiver, credibility gap, Clintonomics, normalcy, Oliver Twist (a person never contented), Casanova (a flirtatious man)."}]},{"text":[{"text":"Blending:","bold":true},{"text":" combining "},{"text":"part of one word with part of another","bold":true},{"text":"; the blend "},{"text":"shares the meaning of both","bold":true},{"text":". sit-com (situation + comedy), smog (smoke + fog), chillax (chill + relax), netiquette (internet + etiquette), camcorder (camera + recorder), chortle (chuckle + snort), telex (teleprinter + exchange), mimsy (miserable + flimsy). Also brunch, malware, webinar."}]},{"text":[{"text":"Compounding:","bold":true},{"text":" the "},{"text":"easiest","bold":true},{"text":" method; combining "},{"text":"two or more existing (independent) words","bold":true},{"text":" to form a new word. Written as "},{"text":"one word","bold":true},{"text":" (boardroom, litterbug, sweatshop, linesman), "},{"text":"two words","bold":true},{"text":" (floppy disk, chat show, rummage sale, surrogate mother) or "},{"text":"hyphenated","bold":true},{"text":" (fail-safe, on-screen, one-upmanship, link-up)."}]},{"text":[{"text":"Clipping:","bold":true},{"text":" "},{"text":"shortening long words that are awkward in everyday speech","bold":true},{"text":"; part is clipped off, leaving the frequently used part. gov (governor), phone (telephone), bike (bicycle), exam (examination), lit (literature), civvy (civilian), lunch (luncheon); also ad, zoo, prep, gents, fax (facsimile)."}]},{"text":[{"text":"Reduplicating:","bold":true},{"text":" "},{"text":"doubling all or part of a word","bold":true},{"text":" with a single vowel or consonant change. hanky-panky, humdrum, boogie-woogie, helter-skelter, walkie-talkie, yum-yum, topsy-turvy, nitty-gritty, dilly-dally, titbit."}]},{"text":[{"text":"Acronym:","bold":true},{"text":" an abbreviation formed from the "},{"text":"initials","bold":true},{"text":" (or first two letters) of each word of a term; it becomes a word when added to the lexicon. Mostly from "},{"text":"names of organisations, inventions and discoveries","bold":true},{"text":". WAN (wide area network), VAT (value added tax), NASA, FIFA, NATO, OPEC, POTUS (President of the United States), scuba (self-contained underwater breathing apparatus), WYSIWYG (what you see is what you get)."}]},{"text":[{"text":"Affixation:","bold":true},{"text":" using "},{"text":"prefixes and suffixes","bold":true},{"text":" to form words (Lesson 9.5)."}]},{"text":[{"text":"Neologism:","bold":true},{"text":" the process in which "},{"text":"old words are given new meanings","bold":true},{"text":". Many dated words have taken on new meanings; some keep the old meaning as well."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Neologism examples (old meaning → new meaning): "},{"text":"nice","bold":true},{"text":" (pretending to be good → beautiful, kind, smart); "},{"text":"lady","bold":true},{"text":" (wife of a noble → spinster, single mother); "},{"text":"dull","bold":true},{"text":" (slow to learn → not flashy, boring); "},{"text":"first lady","bold":true},{"text":" (queen → wife of a president or governor); "},{"text":"promised land","bold":true},{"text":" (Canaan → a place of happiness and safety); "},{"text":"Waterloo","bold":true},{"text":" (a place name → a defeat); "},{"text":"bad","bold":true},{"text":" (unjust, wicked → dangerous, amazing). T. S. Eliot, in "},{"text":"Murder in the Cathedral","italic":true},{"text":", used "},{"text":"malevolence","bold":true},{"text":" so that his audience read it as \"violence by men\"."}]},{"text":[{"text":"Trap: in its widest sense a "},{"text":"neologism","bold":true},{"text":" is any "},{"text":"newly coined word or new meaning","bold":true},{"text":". So in a question like \"all but one are neologisms: atmosphere, brunch, malware, webinar\", the odd one out is "},{"text":"atmosphere","bold":true},{"text":", an old Greek-derived word; brunch, malware and webinar are recent blends. But when asked to "},{"text":"name the process in which old words get new meanings","bold":true},{"text":", the answer is "},{"text":"neologism","bold":true},{"text":", not coining (which makes a brand-new word) or blending."}]},{"text":[{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 40, $study_guide$":"Forms a word can take:","bold":true},{"text":" "},{"text":"simple","bold":true},{"text":" (one unit: table), "},{"text":"compound","bold":true},{"text":" (two or more independent words: suitcase, blackboard) and "},{"text":"complex","bold":true},{"text":" (a base with affixes: unreliable). "},{"text":"Compound-complex","bold":true},{"text":" is a type of "},{"text":"sentence","bold":true},{"text":", never a word form."}]},{"text":[{"text":"Trap: a blend joins "},{"text":"parts","bold":true},{"text":" of two words (smog); a compound joins "},{"text":"whole","bold":true},{"text":" words (boardroom); an acronym uses "},{"text":"initials","bold":true},{"text":" (NATO); clipping "},{"text":"cuts","bold":true},{"text":" one word (exam). \"Chopped\", \"chipped\" and \"crimped\" are not word-formation terms; the term is "},{"text":"clipped","bold":true},{"text":"."}]},{"text":[{"text":"Conversion","bold":true},{"text":" (changing a word's class without changing its form, e.g. \"to google\") is another process you may meet in options; it is not clipping."}]}]}]},{"number":"9.5","title":"Affixation and morphemes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Morpheme:","bold":true},{"text":" the smallest meaningful unit of a word."}]},{"text":[{"text":"Free morpheme:","bold":true},{"text":" can stand alone as a word (happy, boy, the). Free morphemes are sub-categorised into "},{"text":"lexical","bold":true},{"text":" (content words: nouns, verbs, adjectives, adverbs, e.g. boy, run, happy) and "},{"text":"functional","bold":true},{"text":" (grammar words: articles, prepositions, conjunctions, pronouns, e.g. the, of, and, she)."}]},{"text":[{"text":"Bound morpheme:","bold":true},{"text":" cannot stand alone; must attach to a free morpheme or root (un-, -ness, -ed). "},{"text":"Affixes are bound morphemes.","bold":true}]},{"text":[{"text":"Root (stem, base):","bold":true},{"text":" the part of a word "},{"text":"to which other elements can be added","bold":true},{"text":". The base of "},{"text":"educational","bold":true},{"text":" is "},{"text":"educate","bold":true},{"text":" (educate + -ion → education, + -al → educational)."}]},{"text":[{"text":"Affixes:","bold":true},{"text":" the general name for "},{"text":"prefixes and suffixes","bold":true},{"text":". "},{"text":"Affixation","bold":true},{"text":" is the "},{"text":"process","bold":true},{"text":" of adding them. "},{"text":"Every complex word contains an affix.","bold":true}]},{"text":[{"text":"Prefix:","bold":true},{"text":" a bound morpheme added at the "},{"text":"beginning","bold":true},{"text":" of a root (un- in unfaithful, unreliable). "},{"text":"Suffix:","bold":true},{"text":" a bound morpheme added at the "},{"text":"end","bold":true},{"text":" (-ly in happily)."}]},{"text":[{"text":"Unhappily = prefix (un-) + root (happy) + suffix (-ly).","bold":true}]},{"text":[{"text":"Affixes are "},{"text":"derivational","bold":true},{"text":" when they make a new word, changing the meaning and/or the word class (un- in unreliable; -ness in sadness), and "},{"text":"inflectional","bold":true},{"text":" when they only change tense or number without making a new word (-ed, -s)."}]},{"text":[{"text":"Suffix types:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Noun-forming, added to verbs:","bold":true},{"text":" -al, -ance, -ion, -ment, -ure (arrival, severance, governance, domination, development, failure)."}]},{"text":[{"text":"Noun-forming, added to adjectives:","bold":true},{"text":" -dom, -ism, -cy, -ity, -ty, -ness, -th (freedom, socialism, normalcy, normality, loyalty, goodness, warmth)."}]},{"text":[{"text":"Noun-forming, added to nouns:","bold":true},{"text":" -age, -er, -hood, -ful, -dom, -ry, -ule (harbourage, worker, boyhood, handful, dukedom, forestry, globule)."}]},{"text":[{"text":"Adjective-forming, added to nouns:","bold":true},{"text":" -ful, -less, -ish (faithful, faithless, girlish)."}]},{"text":[{"text":"Verb-forming, added to adjectives:","bold":true},{"text":" -ize (socialize, idolize)."}]},{"text":[{"text":"Tense-forming, added to regular verbs:","bold":true},{"text":" -ed, -d (wanted, changed)."}]},{"text":[{"text":"Plural-forming:","bold":true},{"text":" -s, -es, -i, -ies, -ia, -ae (boys, classes, foci, criteria, personae)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Prefix types:","bold":true},{"text":" a "},{"text":"negative prefix","bold":true},{"text":" yields the "},{"text":"opposite","bold":true},{"text":" meaning of the root (a-, de-, dis-, contra-, mis-, im-, in-, retro-, un-). A "},{"text":"positive prefix","bold":true},{"text":" indicates "},{"text":"intensity, degree, emphasis or position","bold":true},{"text":" and does "},{"text":"not","bold":true},{"text":" form an antonym (extra-, post-, re-, sub-, semi-, co-, ultra-, hyper-, trans-, pro-, pre-, inter-, ante-, mega-, self-, circum-, bi-, mono-, pseudo- and others)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Affixation may "},{"text":"change meaning and word class","bold":true},{"text":" (govern → government), "},{"text":"change class but keep meaning","bold":true},{"text":" (arrive → arrival), or keep both while changing tense or number (wanted; boys)."}]},{"text":[{"text":"A "},{"text":"verb-forming prefix","bold":true},{"text":" can turn a noun into a verb: disgrace, imperil. A negative prefix on a negative word repositions it as positive: fetter → unfetter."}]},{"text":[{"text":"-ness","bold":true},{"text":" attaches to "},{"text":"adjectives","bold":true},{"text":" to make nouns: apt → aptness, just → justness, sad → sadness. It does not attach to an adverb (sadly) or to a word that is already a noun (comfort). If asked which of apt, sadly, comfort, just takes -ness \"by way of spelling\", the keyed answer is "},{"text":"apt","bold":true},{"text":" (aptness)."}]},{"text":[{"text":"anti-","bold":true},{"text":" means "},{"text":"ag$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 41, $study_guide$ainst","bold":true},{"text":" (anti-social, antibiotic); do not confuse it with "},{"text":"ante-","bold":true},{"text":", which means "},{"text":"before","bold":true},{"text":" (antenatal). "},{"text":"-un","bold":true},{"text":" in unreliable is a "},{"text":"prefix","bold":true},{"text":", a "},{"text":"bound","bold":true},{"text":" morpheme and, more precisely, a "},{"text":"derivational","bold":true},{"text":" one, because it creates a new word with the opposite meaning."}]},{"text":[{"text":"Trap: a "},{"text":"phrase","bold":true},{"text":" is a group of words, not a word part. Prefix and suffix are the things "},{"text":"added","bold":true},{"text":"; the root is what they are added "},{"text":"to","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"grammatical\" is just another name for functional; the standard sub-categories of free morphemes are "},{"text":"lexical and functional","bold":true},{"text":"."}]}]}]},{"number":"9.6","title":"Choosing the right word: commonly confused pairs","mustKnow":[{"type":"paragraph","text":[{"text":"Good vocabulary means picking the "},{"text":"right","bold":true},{"text":" word, not the almost-right one. Learn these tested pairs:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Discover / invent:","bold":true},{"text":" you "},{"text":"discover","bold":true},{"text":" what already exists (a planet, a mineral); you "},{"text":"invent","bold":true},{"text":" what did not exist until someone made it. "},{"text":"Who ","italic":true},{"text":"invented","bold":true,"italic":true},{"text":" the telephone?","italic":true}]},{"text":[{"text":"Persuaded / convinced:","bold":true},{"text":" "},{"text":"convinced","bold":true},{"text":" = made to "},{"text":"believe","bold":true},{"text":" a fact is true; "},{"text":"persuaded","bold":true},{"text":" = talked into "},{"text":"doing","bold":true},{"text":" something. "},{"text":"The judge was ","italic":true},{"text":"convinced","bold":true,"italic":true},{"text":" that the man was guilty.","italic":true}]},{"text":[{"text":"Took / received:","bold":true},{"text":" a prize is "},{"text":"given","bold":true},{"text":", so the winner "},{"text":"receives","bold":true},{"text":" it; "},{"text":"took","bold":true},{"text":" suggests seizing. "},{"text":"He ","italic":true},{"text":"received","bold":true,"italic":true},{"text":" a prize for his diligence.","italic":true}]},{"text":[{"text":"Interfere in / interfere with:","bold":true},{"text":" you "},{"text":"interfere in","bold":true},{"text":" affairs that are not your business; something "},{"text":"interferes with","bold":true},{"text":" another thing by disturbing or blocking it (noise interferes with reading). "},{"text":"It is not wise to ","italic":true},{"text":"interfere in","bold":true,"italic":true},{"text":" family quarrels.","italic":true}]},{"text":[{"text":"Accept / agree:","bold":true},{"text":" "},{"text":"agree to","bold":true},{"text":" do something (say yes to a request); "},{"text":"accept","bold":true},{"text":" takes a noun object (accept an offer), never \"to go\". "},{"text":"She did not ","italic":true},{"text":"agree","bold":true,"italic":true},{"text":" to go.","italic":true}]},{"text":[{"text":"Deals with / deals in:","bold":true},{"text":" "},{"text":"deal in","bold":true},{"text":" = buy and sell as a trade; "},{"text":"deal with","bold":true},{"text":" = handle or manage a problem or person. "},{"text":"A butcher ","italic":true},{"text":"deals in","bold":true,"italic":true},{"text":" meat.","italic":true}]},{"text":[{"text":"Earn / win:","bold":true},{"text":" you "},{"text":"earn","bold":true},{"text":" a living (by work); you "},{"text":"win","bold":true},{"text":" prizes, games, competitions. "},{"text":"How does that man ","italic":true},{"text":"earn","bold":true,"italic":true},{"text":" his living?","italic":true}]},{"text":[{"text":"Remember / remind:","bold":true},{"text":" to "},{"text":"remind","bold":true},{"text":" someone is to make them remember; you "},{"text":"remember","bold":true},{"text":" for yourself. "},{"text":"Please ","italic":true},{"text":"remind","bold":true,"italic":true},{"text":" me to give the money back.","italic":true}]},{"text":[{"text":"Avenged / revenged:","bold":true},{"text":" to "},{"text":"avenge","bold":true},{"text":" a wrong is to punish the wrongdoer "},{"text":"on behalf of a victim","bold":true},{"text":", in the name of justice; "},{"text":"revenge","bold":true},{"text":" is personal retaliation (revenge yourself on an enemy). "},{"text":"The judge ","italic":true},{"text":"avenged","bold":true,"italic":true},{"text":" the wrong done to the child.","italic":true}]},{"text":[{"text":"Love / like:","bold":true},{"text":" "},{"text":"love","bold":true},{"text":" is deep and intense; "},{"text":"like","bold":true},{"text":" is weak (find pleasant). "},{"text":"Some people ","italic":true},{"text":"love","bold":true,"italic":true},{"text":" freedom so much that they are ready to die for it.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Test each pair by the "},{"text":"object","bold":true},{"text":" it takes: invent a device, discover a fact; convinced "},{"text":"that","bold":true},{"text":", persuaded "},{"text":"to","bold":true},{"text":"; agree "},{"text":"to go","bold":true},{"text":", accept "},{"text":"an invitation","bold":true},{"text":"; deal "},{"text":"in","bold":true},{"text":" goods, deal "},{"text":"with","bold":true},{"text":" people or problems; earn "},{"text":"money","bold":true},{"text":", win "},{"text":"a match","bold":true},{"text":"."}]},{"text":[{"text":"Check the "},{"text":"strength","bold":true},{"text":" of the word: the seriousness of \"ready to die for it\" tells you "},{"text":"love","bold":true},{"text":", not like."}]},{"text":[{"text":"These are the \"almost-right word\" errors a weak vocabulary produces; a usage dictionary lists them under common errors."}]}]}]}],"recap":[{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 42, $study_guide$ype":"list","ordered":false,"items":[{"text":[{"text":"Vocabulary = the total stock of words in a language; English has about one million words, Shakespeare used 21,000, most learners know under 10,000."}]},{"text":[{"text":"Sources of English words: Anglo-Saxon (Angles, Saxons, Jutes, 450 AD; Native English), Latin (Christianity, Renaissance), French (Norman Conquest 1066), Greek (Renaissance, science)."}]},{"text":[{"text":"Active vocabulary = words you use; dormant/recognition = words you recognise but cannot define. Grow both by reading widely and using the dictionary."}]},{"text":[{"text":"Dictionaries: general (unabridged, abridged) and specialised (synonyms/thesaurus, scholarly, usage). A thesaurus is a specialised dictionary of synonyms."}]},{"text":[{"text":"Denotative = literal, dictionary, in isolation; connotative = feelings, figurative, context; contextual meaning comes from paired words (complementary = similar, contrasting = opposite)."}]},{"text":[{"text":"Word formation: coining, blending, compounding, clipping, reduplicating, acronym, affixation, neologism (old words, new meanings)."}]},{"text":[{"text":"Word forms: simple, compound, complex; compound-complex is a sentence type."}]},{"text":[{"text":"Morphemes: free (lexical, functional) and bound (affixes). Prefix + root + suffix (un-happi-ly). Every complex word has an affix."}]},{"text":[{"text":"anti- = against; ante- = before. -ness makes nouns from adjectives."}]},{"text":[{"text":"Right word: invent/discover, convinced/persuaded, received, interfere in, agree to, deal in, earn a living, remind, avenge, love."}]}]}],"theory":{"itemId":"d71fc0df-1a2a-52a9-8b1f-20622cedf9bd","question":[{"type":"paragraph","text":[{"text":"Distinguish between denotative and connotative meaning, and explain how verbal context helps a reader work out the meaning of an unfamiliar word."}]}]},"practice":[{"topic":"Vocabulary Development","named":false}]}},{"kind":"note","itemId":"bd5fff77-dc4a-5971-94fd-9946bf1edb57","sourceKey":"guide-topic:10","position":10,"payload":{"title":"Grammar I: Word Classes and Phrases","body":"Grammar and its two branches (morphology, syntax); the hierarchy morpheme to sentence; free and bound morphemes; 8 traditional parts of speech against 9 modern word classes and the three criteria; forms, sub-classes and functions of nouns; sub-classes and cases of pronouns; determiners; adjectives (sub-classes, position, degree); verbs (5 forms, tenses, transitive/intransitive, primary and modal auxiliaries); adverbs; prepositions, the four groups of conjunctions, interjections; the phrase and its 8 types.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"Grammar and its two branches (morphology, syntax); the hierarchy morpheme to sentence; free and bound morphemes; 8 traditional parts of speech against 9 modern word classes and the three criteria; forms, sub-classes and functions of nouns; sub-classes and cases of pronouns; determiners; adjectives (sub-classes, position, degree); verbs (5 forms, tenses, transitive/intransitive, primary and modal auxiliaries); adverbs; prepositions, the four groups of conjunctions, interjections; the phrase and its 8 types."}],"lessons":[{"number":"10.1","title":"Grammar, its units and word classes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grammar:","bold":true},{"text":" the system of rules that determines how words are formed and combined to make sentences; in short, "},{"text":"the study of sentence structure","bold":true},{"text":"."}]},{"text":[{"text":"2 branches:","bold":true},{"text":" (1) "},{"text":"morphology","bold":true},{"text":", how words are formed; (2) "},{"text":"syntax","bold":true},{"text":", how constituents are arranged within a sentence."}]},{"text":[{"text":"2 steps in studying grammar:","bold":true},{"text":" (1) identify the "},{"text":"units or constituents","bold":true},{"text":" (words, phrases, clauses, sentences); (2) analyse the "},{"text":"patterns","bold":true},{"text":" they fall into and the meaning those patterns communicate."}]},{"text":[{"text":"Grammatical hierarchy, smallest to largest:","bold":true},{"text":" 1. morpheme, 2. word, 3. phrase, 4. clause, 5. sentence. The "},{"text":"morpheme","bold":true},{"text":" is the smallest unit, the "},{"text":"sentence","bold":true},{"text":" the largest. "},{"text":"Words are the building blocks of a sentence.","bold":true}]},{"text":[{"text":"Morpheme:","bold":true},{"text":" the smallest meaningful unit. "},{"text":"Free morphemes","bold":true},{"text":" stand alone as words (boy, go, in); "},{"text":"bound morphemes","bold":true},{"text":" cannot; they are affixes (un-, -s, -ed, -ly). Free morphemes sub-divide into "},{"text":"lexical","bold":true},{"text":" (content words: nouns, verbs, adjectives, adverbs) and "},{"text":"functional","bold":true},{"text":" (grammar words: prepositions, conjunctions, determiners, pronouns)."}]},{"text":[{"text":"Open class words:","bold":true},{"text":" classes to which new words can always be added (nouns, verbs, adjectives, adverbs). "},{"text":"Closed class (grammatical) words","bold":true},{"text":" rarely gain members (prepositions, conjunctions, determiners, pronouns)."}]},{"text":[{"text":"Parts of speech:","bold":true},{"text":" the "},{"text":"traditional","bold":true},{"text":" label, based on "},{"text":"notional (meaning)","bold":true},{"text":" criteria; "},{"text":"8","bold":true},{"text":" classes: nouns, pronouns, adjectives, verbs, prepositions, conjunctions, adverbs, interjections."}]},{"text":[{"text":"Word classes:","bold":true},{"text":" the "},{"text":"contemporary","bold":true},{"text":" label; "},{"text":"9","bold":true},{"text":" classes: nouns, pronouns, adjectives, "},{"text":"determiners","bold":true},{"text":", verbs, adverbs, prepositions, conjunctions, interjections."}]},{"text":[{"text":"3 criteria for a word's class:","bold":true},{"text":" (1) "},{"text":"notional (semantic):","bold":true},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 43, $study_guide$ext":" meaning; (2) "},{"text":"morphological:","bold":true},{"text":" the affixes it takes; (3) "},{"text":"syntactic:","bold":true},{"text":" its position in the sentence and whether a regular word of the same class can replace it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Notional definitions: nouns signify "},{"text":"entities","bold":true},{"text":"; verbs "},{"text":"actions","bold":true},{"text":"; adjectives "},{"text":"states","bold":true},{"text":"; adverbs "},{"text":"manner","bold":true},{"text":"; prepositions "},{"text":"location","bold":true},{"text":"."}]},{"text":[{"text":"Why these are vague: "},{"text":"extermination","italic":true},{"text":" signifies an action but is a "},{"text":"noun","bold":true},{"text":"; "},{"text":"quick","italic":true},{"text":" in "},{"text":"quick fix","italic":true},{"text":" signifies manner but is an "},{"text":"adjective","bold":true},{"text":"; "},{"text":"Ibadan","italic":true},{"text":" denotes a location but is a "},{"text":"noun","bold":true},{"text":"."}]},{"text":[{"text":"Structural clues: a "},{"text":"determiner","bold":true},{"text":" signals a noun; a word that takes the "},{"text":"3rd person -s","bold":true},{"text":", "},{"text":"past tense","bold":true},{"text":" and "},{"text":"-ing","bold":true},{"text":" endings is likely a "},{"text":"verb","bold":true},{"text":"."}]},{"text":[{"text":"Trap: a paragraph is a unit of writing, not of grammar; lexis and syntax are areas of study, not units."}]},{"text":[{"text":"Trap: \"the study of the arrangement of constituents in a sentence\" is "},{"text":"syntax","bold":true},{"text":". Grammar is too broad (it includes morphology); graphology is the writing system."}]}]}]},{"number":"10.2","title":"Nouns","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Noun:","bold":true},{"text":" names a "},{"text":"person","bold":true},{"text":" (David), "},{"text":"animal","bold":true},{"text":" (lion), "},{"text":"place","bold":true},{"text":" (Nigeria), "},{"text":"thing","bold":true},{"text":" (book), "},{"text":"idea","bold":true},{"text":" (love), "},{"text":"incident","bold":true},{"text":" (flood) or "},{"text":"event","bold":true},{"text":" (Christmas)."}]},{"text":[{"text":"Structural definition:","bold":true},{"text":" takes the "},{"text":"plural","bold":true},{"text":" (tables), has a "},{"text":"possessive","bold":true},{"text":" (Bola's bag), can follow a "},{"text":"determiner","bold":true},{"text":" (a/this/my ball), occurs before and after a verb (Dayo is a boy). A noun "},{"text":"has no tense","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 grammatical forms:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Singular:","bold":true},{"text":" one; the dictionary headword (sister, apple)."}]},{"text":[{"text":"Plural:","bold":true},{"text":" more than one; regular nouns add "},{"text":"-s/-es","bold":true},{"text":" (sisters, apples)."}]},{"text":[{"text":"Singular possessive:","bold":true},{"text":" apostrophe + s (wife's, clown's)."}]},{"text":[{"text":"Plural possessive:","bold":true},{"text":" apostrophe after the plural -s (girls', clowns'); irregular plurals keep the -s (men's, children's)."}]}]},{"type":"paragraph","text":[{"text":"Pronunciation of plural -s/-es:","bold":true}]},{"type":"table","header":[[{"text":"Sound"}],[{"text":"After"}],[{"text":"Examples"}]],"rows":[[[{"text":"/s/"}],[{"text":"voiceless consonants"}],[{"text":"gates, taps, desks"}]],[[{"text":"/z/"}],[{"text":"voiced consonants and vowels"}],[{"text":"roads, friends, bananas"}]],[[{"text":"/ɪz/"}],[{"text":"sibilants /s, z, ʃ, ʒ, tʃ, dʒ/"}],[{"text":"nieces, wishes, judges, churches"}]]]},{"type":"paragraph","text":[{"text":"6 kinds of irregular noun:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Vowel change:","bold":true},{"text":" foot/feet, mouse/mice, man/men, tooth/teeth, woman/women, louse/lice, goose/geese."}]},{"text":[{"text":"-en/-ren:","bold":true},{"text":" brother/brethren, child/children, ox/oxen."}]},{"text":[{"text":"-f/-fe to -ves:","bold":true},{"text":" knife/knives, half/halves, leaf/leaves, wife/wives, loaf/loaves, wolf/wolves, hoof/hooves, scarf/scarves (dwarf: dwarfs/dwarves)."}]},{"text":[{"text":"No change:","bold":true},{"text":" sheep, aircraft, furniture, deer, salmon, grouse."}]},{"text":[{"text":"Plural only:","bold":true},{"text":" cattle, spectacles, shorts, glasses, clothes, pyjamas, tongs, scissors, trousers, binoculars."}]},{"text":[{"text":"With or without -s:","bold":true},{"text":" fish/fishes, elk/elks, herring/herrings, antelope/antelopes."}]}]},{"type":"paragraph","text":[{"text":"3 sub-class distinctions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Proper","bold":true},{"text":" (particular person, place, thing or idea; "},{"text":"usually capitalised","bold":true},{"text":": Chief Daniel, National Museum, Peugeot, Darwinism) versus "},{"text":"common","bold":true},{"text":" (general name: man, house, car, temptation). "},{"text":"Collective nouns","bold":true},{"text":" are common nouns naming a group: crew, staff, army, jury, chorus, panel, council, choir."}]},{"text":[{"text":"Count","bold":true},{"text":" (singular and plural: dog/dogs) versus "},{"text":"non-count","bold":true},{"text":" (no plural: furniture, warmth, grass, humour). A division of "},{"text":"common","bold":true},{"text":" nouns."}]},{"text":[{"text":"Concrete","bold":true},{"text":" (occupies space or is perceived by the senses: drug, sweet, music) versus "},{"text":"abstract","bold":true},{"text":" (idea, quality, characteristic: Christianity, Islam, Marxism, youth). Also a division of "},{"text":"common","bold":true},{"text":" nouns."}]}]},{"type":"paragraph","text":[{"text":"8 functions of a noun:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Subject:","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 44, $study_guide$ld":true},{"text":" "},{"text":"Mr Dokunboh","italic":true},{"text":" donated some books."}]},{"text":[{"text":"Direct object","bold":true},{"text":" (answers "},{"text":"what?","italic":true},{"text":"): Mr Dokunboh thanked "},{"text":"the lady","italic":true},{"text":"."}]},{"text":[{"text":"Indirect object","bold":true},{"text":" (answers "},{"text":"to/for whom?","italic":true},{"text":"): he donated some books to "},{"text":"the school","italic":true},{"text":"."}]},{"text":[{"text":"Subject complement:","bold":true},{"text":" Daniel is "},{"text":"an architect","italic":true},{"text":"."}]},{"text":[{"text":"Object complement:","bold":true},{"text":" They made the boy "},{"text":"the class captain","italic":true},{"text":"."}]},{"text":[{"text":"Prepositional complement:","bold":true},{"text":" I left him at "},{"text":"the bus-stop","italic":true},{"text":"."}]},{"text":[{"text":"Qualifier of another noun:","bold":true},{"text":" a concert on "},{"text":"Independence","italic":true},{"text":" Day."}]},{"text":[{"text":"Appositive:","bold":true},{"text":" The senator, "},{"text":"Mr Malaki","italic":true},{"text":", is very smart."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Possessive in speech follows the /ɪz/, /z/, /s/ rules. A base ending in s keeps the written possessive -s if pronounced (Chris's) and drops it if not (Jesus' name, for conscience' sake)."}]},{"text":[{"text":"A collective noun is "},{"text":"singular","bold":true},{"text":" for the group as a whole (The choir "},{"text":"meets","italic":true},{"text":") and "},{"text":"plural","bold":true},{"text":" for its members (The choir "},{"text":"have been","italic":true},{"text":" split)."}]},{"text":[{"text":"Count/non-count has "},{"text":"nothing to do with your ability to count","bold":true},{"text":"; some nouns are both ("},{"text":"two cup cakes","italic":true},{"text":" / "},{"text":"some cake","italic":true},{"text":")."}]},{"text":[{"text":"Trap: common nouns are classified "},{"text":"count/non-count","bold":true},{"text":" and "},{"text":"concrete/abstract","bold":true},{"text":" (every noun also has singular/plural number). "},{"text":"Possessive/non-possessive","bold":true},{"text":" is not a classification; possessive is a form a noun takes."}]},{"text":[{"text":"Trap: among "},{"text":"John, Kaduna, Ocean, mathematics","italic":true},{"text":", the odd one is "},{"text":"mathematics","bold":true},{"text":", a common noun naming a general field, not capitalised; the others carry the capital letter that marks a proper noun."}]},{"text":[{"text":"Gerund (verbal noun):","bold":true},{"text":" the -ing form used as a noun: "},{"text":"Driving","italic":true},{"text":" is my hobby."}]}]}]},{"number":"10.3","title":"Pronouns and determiners","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pronoun:","bold":true},{"text":" replaces a noun or noun phrase, usually to avoid repetition. "},{"text":"Mr James is my uncle. He lives in Ibadan.","italic":true},{"text":" The noun referred to is the "},{"text":"antecedent","bold":true},{"text":" (Mr James)."}]},{"text":[{"text":"A pronoun agrees with its antecedent in "},{"text":"4","bold":true},{"text":" things: "},{"text":"number, gender, person, case","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"8 sub-classes of pronouns:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal:","bold":true},{"text":" 1st person I, me, we, us; 2nd person you; 3rd person he, she, him, her, it, they, them. Third person singular shows "},{"text":"gender","bold":true},{"text":": he/him masculine, she/her feminine, it neuter."}]},{"text":[{"text":"Possessive:","bold":true},{"text":" ownership; some stand alone (mine, yours, hers, his, theirs, ours), others go before nouns."}]},{"text":[{"text":"Interrogative:","bold":true},{"text":" ask questions: who, whom, whose, what, which."}]},{"text":[{"text":"Relative:","bold":true},{"text":" introduce a "},{"text":"relative (adjectival) clause","bold":true},{"text":": "},{"text":"the dress which I wore; the students who were late; the writer whom I would like to meet.","italic":true}]},{"text":[{"text":"Demonstrative:","bold":true},{"text":" this/that (singular), these/those (plural)."}]},{"text":[{"text":"Reciprocal:","bold":true},{"text":" two-way relationship; English has "},{"text":"two","bold":true},{"text":": "},{"text":"each other, one another","italic":true},{"text":"."}]},{"text":[{"text":"Reflexive and intensive:","bold":true},{"text":" -self/-selves forms (myself, yourself, himself, herself, itself; ourselves, yourselves, themselves). "},{"text":"Reflexive","bold":true},{"text":" reflects back to an earlier noun or pronoun ("},{"text":"He taught himself to drive","italic":true},{"text":"); "},{"text":"intensive","bold":true},{"text":" adds emphasis ("},{"text":"David himself cleaned the room","italic":true},{"text":")."}]},{"text":[{"text":"Indefinite:","bold":true},{"text":" no specific person or thing. Singular: anyone, anybody, either, neither, someone, something, little, much; plural: both, several, few, many, any, some ("},{"text":"Several were taken. Few were expected","italic":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"3 cases:","bold":true}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Use"}],[{"text":"Forms"}]],"rows":[[[{"text":"Subjective"}],[{"text":"subject"}],[{"text":"I, we, he, she, they, you, who, it"}]],[[{"text":"Objective"}],[{"text":"object"}],[{"text":"me, us, him, her, them, you, whom, it"}]],[[{"text":"Possessive"}],[{"text":"ownership"}],[{"text":"my/mine, our/ours, his, her/hers, their/theirs, your/yours, whose, its"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Determiner:","bold":true},{"text":" a word used "},{"text":"before a noun","bold":true},{"text":" to give information about it. Like adjectives, determiners qualify nouns, but they "},{"text":"lack $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 45, $study_guide$descriptive content","bold":true},{"text":" and name no qualities, so modern grammar separates them."}]}]},{"type":"paragraph","text":[{"text":"5 classes of determiners:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Articles:","bold":true},{"text":" "},{"text":"the","italic":true},{"text":" (definite); "},{"text":"a, an","italic":true},{"text":" (indefinite)."}]},{"text":[{"text":"Possessives:","bold":true},{"text":" his, her, your, our, my, its, their."}]},{"text":[{"text":"Demonstratives:","bold":true},{"text":" this, that, these, those."}]},{"text":[{"text":"Quantifiers:","bold":true},{"text":" some, many, a few, few, little, a little, several, much."}]},{"text":[{"text":"Numerals:","bold":true},{"text":" one, two, three (cardinal); second, third, fortieth (ordinal)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: there is no \"refractive\" pronoun; it is a distortion of "},{"text":"reflexive","bold":true},{"text":"."}]},{"text":[{"text":"Who","italic":true},{"text":" is subjective, "},{"text":"whom","italic":true},{"text":" objective, "},{"text":"whose","italic":true},{"text":" possessive."}]},{"text":[{"text":"These, those, many, few, several","italic":true},{"text":" go only before "},{"text":"plural count","bold":true},{"text":" nouns; "},{"text":"much, little","italic":true},{"text":" with "},{"text":"non-count","bold":true},{"text":" nouns; "},{"text":"the, some","italic":true},{"text":" with both."}]},{"text":[{"text":"Two determiners cannot precede","bold":true},{"text":" one head noun ("},{"text":"that your book","italic":true},{"text":", "},{"text":"some few things","italic":true},{"text":" are wrong). A "},{"text":"singular count noun always needs a determiner","bold":true},{"text":" ("},{"text":"I gave my brother a pencil","italic":true},{"text":", not "},{"text":"pencil","italic":true},{"text":")."}]},{"text":[{"text":"Trap: the phrase with an "},{"text":"indefinite article","bold":true},{"text":" is "},{"text":"a big fat hen","italic":true},{"text":"; "},{"text":"the Golden Globe awards","italic":true},{"text":" has the definite article, "},{"text":"that house","italic":true},{"text":" a demonstrative, "},{"text":"my friend","italic":true},{"text":" a possessive."}]}]}]},{"number":"10.4","title":"Adjectives and adverbs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjective:","bold":true},{"text":" describes a noun or pronoun by "},{"text":"limiting its meaning","bold":true},{"text":"; answers "},{"text":"what kind?","bold":true},{"text":" (a "},{"text":"beautiful","italic":true},{"text":" day), "},{"text":"which one?","bold":true},{"text":" (a "},{"text":"prestigious","italic":true},{"text":" award), "},{"text":"how many?","bold":true},{"text":" ("},{"text":"several","italic":true},{"text":" people)."}]}]},{"type":"paragraph","text":[{"text":"9 sub-classes of adjectives:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Qualitative:","bold":true},{"text":" a quality (honest, rich)."}]},{"text":[{"text":"Classifying:","bold":true},{"text":" the group it belongs to (democratic, psychological)."}]},{"text":[{"text":"Quantifying:","bold":true},{"text":" amount, usually uncountable (some food, all their money)."}]},{"text":[{"text":"Colour:","bold":true},{"text":" brown, red."}]},{"text":[{"text":"Number:","bold":true},{"text":" exact number or order, countable only (ten people, first birthday)."}]},{"text":[{"text":"Emphatic:","bold":true},{"text":" emphasises feeling or degree (complete idiot, total nightmare)."}]},{"text":[{"text":"Interrogative:","bold":true},{"text":" which way? whose house? what kind?"}]},{"text":[{"text":"Demonstrative:","bold":true},{"text":" that ball, this child."}]},{"text":[{"text":"Possessive:","bold":true},{"text":" my children, your mother."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Position:","bold":true},{"text":" before the noun = "},{"text":"attributive","bold":true},{"text":" ("},{"text":"the beautiful woman","italic":true},{"text":"); linked to the noun by a verb = "},{"text":"predicative","bold":true},{"text":" ("},{"text":"the food is delicious","italic":true},{"text":"). Attributive only: a "},{"text":"main","italic":true},{"text":" road, a "},{"text":"commanding","italic":true},{"text":" lead. Predicative only: the woman is "},{"text":"afraid","italic":true},{"text":"; the girl feels "},{"text":"faint","italic":true},{"text":"."}]},{"text":[{"text":"3 degrees:","bold":true},{"text":" "},{"text":"positive","bold":true},{"text":" (big), "},{"text":"comparative","bold":true},{"text":" (two things: bigger), "},{"text":"superlative","bold":true},{"text":" (three or more: biggest)."}]},{"text":[{"text":"Gradable","bold":true},{"text":" adjectives (big, tall, lazy) can be expressed in degrees and modified by adverbs (fairly big, very big). "},{"text":"Non-gradable","bold":true},{"text":" adjectives name absolute or extreme qualities and have no comparative: perfect, real, right, terrible, fatal, superior, ghastly, unique, utter, inferior, fake, genuine."}]},{"text":[{"text":"Adverb:","bold":true},{"text":" modifies a "},{"text":"verb, an adjective or another adverb","bold":true},{"text":" by making its meaning more specific: "},{"text":"Very beautiful women have always enticed foolish men quite successfully.","italic":true}]},{"text":[{"text":"Forms:","bold":true},{"text":" many add "},{"text":"-ly","bold":true},{"text":" to adjectives (smartly, quickly); others are independent words (very, quite, here, yesterday, often, so, nearby)."}]}]},{"type":"paragraph","text":[{"text":"Types of adverb:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Answers"}],[{"text":"Example"}]],"rows":[[[{"text":"Time"}],[{"text":"when?"}],[{"text":"He arrived "},{"text":"yesterday","italic":true},{"text":"."}]],[[{"text":"Manner"}],[{"text":"how?"}],[{"text":"She walks "},{"text":"briskly"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 46, $study_guide$,"italic":true},{"text":"."}]],[[{"text":"Place"}],[{"text":"where?"}],[{"text":"Tade travelled "},{"text":"to Ibadan","italic":true},{"text":"."}]],[[{"text":"Degree"}],[{"text":"to what extent?"}],[{"text":"My mother cooks "},{"text":"very well","italic":true},{"text":"."}]],[[{"text":"Frequency"}],[{"text":"how often?"}],[{"text":"The man jogs "},{"text":"regularly","italic":true},{"text":"."}]],[[{"text":"How many times"}],[{"text":"how many times?"}],[{"text":"Muslims pray "},{"text":"five times","italic":true},{"text":"."}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Comparative adds "},{"text":"-er","bold":true},{"text":" (-r after -e); superlative "},{"text":"-est","bold":true},{"text":" (-st after -e). Longer adjectives take "},{"text":"more/most","bold":true},{"text":" (more difficult, most difficult); some allow either (politer/more polite, likelier/more likely)."}]},{"text":[{"text":"Irregular adjectives:","bold":true},{"text":" good/better/best; bad/worse/worst; much/more/most; many/more/most; far/farther/farthest."}]},{"text":[{"text":"Trap: "},{"text":"tall, taller, tallest","italic":true},{"text":" illustrates a "},{"text":"gradable","bold":true},{"text":" adjective (expressed in degrees); \"comparative\" names only the middle form."}]},{"text":[{"text":"Trap: attributive/predicative = "},{"text":"position","bold":true},{"text":"; positive/comparative/superlative = "},{"text":"form (degree)","bold":true},{"text":"."}]},{"text":[{"text":"Order of adjectives:","bold":true},{"text":" quality, length, weight, size, shape, age, colour, origin, then the noun: "},{"text":"a beautiful big white house; an elegant short pink dress","italic":true},{"text":"."}]},{"text":[{"text":"Adverb degrees:","bold":true},{"text":" cheerfully/more cheerfully/most cheerfully; badly/worse/worst; well/better/best; soon/sooner/soonest; quickly/more quickly/most quickly. Adverbs also show order (first, last)."}]},{"text":[{"text":"Trap: "},{"text":"very well","italic":true},{"text":" is an adverb of "},{"text":"degree","bold":true},{"text":" ("},{"text":"very","italic":true},{"text":" tells the extent of "},{"text":"well","italic":true},{"text":"); "},{"text":"to Ibadan","italic":true},{"text":" works as an adverb of "},{"text":"place","bold":true},{"text":"."}]},{"text":[{"text":"Position:","bold":true},{"text":" an adverb modifying a "},{"text":"verb","bold":true},{"text":" can move ("},{"text":"Quickly he ate / He quickly ate / He ate quickly","italic":true},{"text":"); one modifying an "},{"text":"adjective or adverb","bold":true},{"text":" must come "},{"text":"immediately before","bold":true},{"text":" it ("},{"text":"very kind, so quickly","italic":true},{"text":"). Position changes meaning, since modifiers relate to the "},{"text":"closest modifiable word","bold":true},{"text":": "},{"text":"Smartly, he walked past","italic":true},{"text":" (the walking was smart) versus "},{"text":"He smartly walked past","italic":true},{"text":" (he was smart)."}]}]}]},{"number":"10.5","title":"Verbs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Verb:","bold":true},{"text":" expresses an "},{"text":"action","bold":true},{"text":" or a "},{"text":"state of being","bold":true},{"text":" and is "},{"text":"required to make a sentence","bold":true},{"text":". Action: dance, clap, jump. State of being: "},{"text":"be","bold":true},{"text":" (be, am, is, are, was, were, been, being), become, seem, appear, look, remain, feel, sound, smell."}]},{"text":[{"text":"Forms:","bold":true},{"text":" "},{"text":"be","italic":true},{"text":" has "},{"text":"8","bold":true},{"text":". Other verbs (action and state-of-being) usually have "},{"text":"5","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Base (infinitive):","bold":true},{"text":" dictionary form (look, take)."}]},{"text":[{"text":"Third person singular present:","bold":true},{"text":" -s/-es (looks, takes)."}]},{"text":[{"text":"Past tense","bold":true},{"text":" (looked, took)."}]},{"text":[{"text":"Perfect (past participle)","bold":true},{"text":" (looked, taken)."}]},{"text":[{"text":"Progressive (-ing)","bold":true},{"text":" (looking, taking)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Regular","bold":true},{"text":" verbs add "},{"text":"-ed","bold":true},{"text":" for past and perfect (look, kick, wait); "},{"text":"irregular","bold":true},{"text":" verbs form them otherwise (take, make, go)."}]},{"text":[{"text":"The -s/-es ending is pronounced like the noun plural: /ɪz/ passes, catches, pushes; /z/ robs, goes; /s/ cuts, looks, drinks."}]},{"text":[{"text":"Tense","bold":true},{"text":" relates the action to a "},{"text":"time","bold":true},{"text":". There are "},{"text":"about nine","bold":true},{"text":"; five are treated here:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Simple present:","bold":true},{"text":" something done "},{"text":"regularly","bold":true},{"text":" or going on all the time ("},{"text":"I jog every morning; The cock crows at dawn","italic":true},{"text":"). It signals "},{"text":"regularity","bold":true},{"text":"."}]},{"text":[{"text":"Present continuous:","bold":true},{"text":" happening "},{"text":"at the time of speaking or writing","bold":true},{"text":"; "},{"text":"be + -ing","bold":true},{"text":" ("},{"text":"I am dancing","italic":true},{"text":")."}]},{"text":[{"text":"Present perfect:","bold":true},{"text":" past action "},{"text":"linked to the present","bold":true},{"text":"; "},{"text":"has/have + past participle","bold":true},{"text":" ("},{"text":"I have lived in Lagos for ten years","italic":true},{"text":": started then, still there)."}]},{"text":[{"text":"Simple past:","bold":true},{"text":" happened and "},{"text":"completed","bold":true},{"text":" in the past ("},{"text":"I went to school yesterday","italic":true},{"text":")."}]},{"text":[{"text":"Simple fu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 47, $study_guide$ture:","bold":true},{"text":" not yet happened; "},{"text":"will/shall + base","bold":true},{"text":" ("},{"text":"I shall leave for Kano tomorrow","italic":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Transitive verb:","bold":true},{"text":" action passes from subject to an "},{"text":"object","bold":true},{"text":"; it always occurs with an object ("},{"text":"The man shut the door","italic":true},{"text":"). "},{"text":"Intransitive verb:","bold":true},{"text":" subject but "},{"text":"no object","bold":true},{"text":" ("},{"text":"The baby slept; The baby cried","italic":true},{"text":")."}]},{"text":[{"text":"Auxiliary (helping) verbs","bold":true},{"text":" come in "},{"text":"2 types","bold":true},{"text":": "},{"text":"primary","bold":true},{"text":" ("},{"text":"have, be, do","bold":true},{"text":"), which can also be main verbs; "},{"text":"modal","bold":true},{"text":" (can, could, will, would, shall, should, may, might, must, ought to), which "},{"text":"cannot stand alone as main verbs","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary auxiliaries in both roles: "},{"text":"The dress is long","italic":true},{"text":" (main) / "},{"text":"The man is playing","italic":true},{"text":" (auxiliary); "},{"text":"I have a car","italic":true},{"text":" / "},{"text":"I have bought a car","italic":true},{"text":"; "},{"text":"I do a lot of knitting","italic":true},{"text":" / "},{"text":"I don't drink","italic":true},{"text":"."}]},{"text":[{"text":"Modals express possibility, probability, "},{"text":"ability","bold":true},{"text":" ("},{"text":"can","italic":true},{"text":"), "},{"text":"permission","bold":true},{"text":" ("},{"text":"may","italic":true},{"text":"), prediction, "},{"text":"obligation","bold":true},{"text":" ("},{"text":"must","italic":true},{"text":"), offers, promises."}]},{"text":[{"text":"Trap: "},{"text":"will, shall, could, should, can, may","italic":true},{"text":" are "},{"text":"modal auxiliaries","bold":true},{"text":". Auxiliaries are classified "},{"text":"primary and modal","bold":true},{"text":", never \"primary and secondary\" or \"modal and main\"; regular/irregular classifies verbs by past-tense formation."}]},{"text":[{"text":"Trap: simple present = "},{"text":"regularity","bold":true},{"text":", not \"now\"; \"now\" is the present continuous."}]},{"text":[{"text":"Trap: "},{"text":"The woman ate the food","italic":true},{"text":" has an object (transitive); "},{"text":"Your house is too far","italic":true},{"text":" has linking "},{"text":"is","italic":true},{"text":"; "},{"text":"The baby cried","italic":true},{"text":" follows the standard intransitive pattern."}]}]}]},{"number":"10.6","title":"Prepositions, conjunctions, interjections and phrases","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Preposition:","bold":true},{"text":" shows the "},{"text":"relationship","bold":true},{"text":" (time, place) between a noun or pronoun and another word: about, above, at, behind, by, for, from, into, of, to, under, with. "},{"text":"Compound (phrasal) prepositions:","bold":true},{"text":" because of, along with, next to, on account of, according to, owing to, instead of, in addition to, in spite of."}]},{"text":[{"text":"Prepositions "},{"text":"begin phrases that end with either a noun or a pronoun","bold":true},{"text":", the "},{"text":"object of the preposition (prepositional complement)","bold":true},{"text":": "},{"text":"behind the campus; under the table","italic":true},{"text":"."}]},{"text":[{"text":"Conjunction:","bold":true},{"text":" links words or groups of words. "},{"text":"4 groups:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coordinating:","bold":true},{"text":" join items of "},{"text":"equal grammatical status","bold":true},{"text":": "},{"text":"and, yet, but, or, nor, for, so","bold":true},{"text":" ("},{"text":"The man and his wife; firm yet fair","italic":true},{"text":"). They build "},{"text":"compound sentences","bold":true},{"text":"."}]},{"text":[{"text":"Correlative:","bold":true},{"text":" "},{"text":"pairs","bold":true},{"text":" joining items of equal status: "},{"text":"both...and; either...or; just as...so; neither...nor; not only...but (also); whether...or","bold":true},{"text":"."}]},{"text":[{"text":"Subordinating:","bold":true},{"text":" join two clauses, making one "},{"text":"dependent","bold":true},{"text":": because, when, if, as, although, though, since, before, after, as soon as, whenever, until, so that. They introduce "},{"text":"adverb clauses","bold":true},{"text":" and build "},{"text":"complex sentences","bold":true},{"text":"."}]},{"text":[{"text":"Conjunctive adverbs:","bold":true},{"text":" clarify the relationship between clauses of "},{"text":"equal status","bold":true},{"text":", more strongly than coordinators: also, however, moreover, nevertheless, besides, furthermore, still, consequently, therefore, thus, likewise, similarly ("},{"text":"He got to the bank after four; nevertheless, the cashier attended to him","italic":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interjection:","bold":true},{"text":" expresses "},{"text":"strong feeling, emotion or exclamation","bold":true},{"text":"; "},{"text":"no grammatical connection","bold":true},{"text":" to the other words; hardly used in formal writing: ouch, ha, oh, hey, eek, wow, oh no, watch it."}]},{"text":[{"text":"Phrase:","bold":true},{"text":" a group of words working in a sentence as a "},{"text":"single grammatical unit","bold":true},{"text":"; may be "},{"text":"just one word","bold":true},{"text":". Each type is "},{"text":"named after the word class of its key word (head)","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"8 types of phrase:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Noun p$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 48, $study_guide$hrase (NP):","bold":true},{"text":" head is a noun; does every job a noun does ("},{"text":"A heavy rain","italic":true},{"text":" fell: subject; Dami is "},{"text":"a very charming young man","italic":true},{"text":": subject complement)."}]},{"text":[{"text":"Verb phrase (VP):","bold":true},{"text":" main (lexical) verb + auxiliaries ("},{"text":"will go, is going, may have been going","italic":true},{"text":"); shows time, mood, voice, number, person; acts as "},{"text":"predicator","bold":true},{"text":"."}]},{"text":[{"text":"Prepositional phrase (PP):","bold":true},{"text":" preposition + its object ("},{"text":"in the fridge, under the bed, across the road","italic":true},{"text":")."}]},{"text":[{"text":"Adjective phrase (AdjP):","bold":true},{"text":" head is an adjective; modifies a noun ("},{"text":"very happy","italic":true},{"text":" man, "},{"text":"extremely valuable","italic":true},{"text":" documents, "},{"text":"happily married","italic":true},{"text":" couple)."}]},{"text":[{"text":"Adverb phrase (AdvP):","bold":true},{"text":" head is an adverb ("},{"text":"fairly regularly, very recently, extremely warmly","italic":true},{"text":")."}]},{"text":[{"text":"Appositive phrase:","bold":true},{"text":" a noun phrase next to another noun, identifying it ("},{"text":"The senator, Mr Malaki","italic":true},{"text":")."}]},{"text":[{"text":"Gerund phrase:","bold":true},{"text":" gerund + its modifiers or complement ("},{"text":"I love chatting with my friends","italic":true},{"text":")."}]},{"text":[{"text":"Participial phrase:","bold":true},{"text":" present or past participle + complement ("},{"text":"Sobbing uncontrollably, she tore up the pictures; Encouraged by her friends, she drove home","italic":true},{"text":")."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: "},{"text":"nevertheless","italic":true},{"text":" is a "},{"text":"conjunctive adverb","bold":true},{"text":", so it cannot introduce an adverb clause; "},{"text":"although, when, if","italic":true},{"text":" can."}]},{"text":[{"text":"Trap: "},{"text":"so","italic":true},{"text":" is coordinating but "},{"text":"so that","bold":true},{"text":" is "},{"text":"subordinating","bold":true},{"text":" (complex, not compound, sentence). "},{"text":"Even...then","italic":true},{"text":" is "},{"text":"not","bold":true},{"text":" a correlative pair."}]},{"text":[{"text":"A PP can act as an "},{"text":"adjective","bold":true},{"text":" ("},{"text":"The red book on the table is mine","italic":true},{"text":") or an "},{"text":"adverb","bold":true},{"text":" ("},{"text":"The bus arrived during the day","italic":true},{"text":"), which is why "},{"text":"to Ibadan","italic":true},{"text":" is an adverb of place."}]},{"text":[{"text":"Name a phrase by its "},{"text":"head","bold":true},{"text":": "},{"text":"across the road","italic":true},{"text":" is a "},{"text":"PP","bold":true},{"text":" (head "},{"text":"across","italic":true},{"text":") though "},{"text":"the road","italic":true},{"text":" inside it is an NP; in "},{"text":"because of the heavy rain","italic":true},{"text":", "},{"text":"the heavy rain","italic":true},{"text":" alone is a "},{"text":"noun phrase","bold":true},{"text":" (head "},{"text":"rain","italic":true},{"text":"); "},{"text":"extremely valuable","italic":true},{"text":" is an "},{"text":"adjective phrase","bold":true},{"text":" (head "},{"text":"valuable","italic":true},{"text":"), not an adverb phrase."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grammar = study of sentence structure; morphology (word formation) + syntax (arrangement)."}]},{"text":[{"text":"Hierarchy: morpheme < word < phrase < clause < sentence. Free morphemes = lexical + functional; bound = affixes."}]},{"text":[{"text":"Traditional: 8 parts of speech by meaning. Modern: 9 word classes (adds determiners) by notional, morphological and syntactic criteria."}]},{"text":[{"text":"Nouns: 4 forms; plural /s/ /z/ /ɪz/; proper/common, count/non-count, concrete/abstract; 8 functions; no tense."}]},{"text":[{"text":"Pronouns: 8 sub-classes, 3 cases; agree in number, gender, person, case. Determiners: articles, possessives, demonstratives, quantifiers, numerals."}]},{"text":[{"text":"Adjectives: 9 sub-classes; attributive vs predicative; positive, comparative (two), superlative (three+); gradable vs non-gradable."}]},{"text":[{"text":"Verbs: 5 forms (be has 8); transitive takes an object; auxiliaries = primary (have, be, do) + modal."}]},{"text":[{"text":"Simple present = regularity; present continuous = now; present perfect = past linked to present."}]},{"text":[{"text":"Adverbs: time, manner, place, degree, frequency; conjunctions: coordinating, correlative, subordinating, conjunctive adverbs."}]},{"text":[{"text":"Phrase = single unit named after its head; 8 types."}]}]}],"theory":{"itemId":"581e7879-0c09-57ec-994f-64e9d493d020","question":[{"type":"paragraph","text":[{"text":"Define a phrase and explain any four types of phrase in English with one example each."}]}]},"practice":[{"topic":"Grammar I: Word Classes and Phrases","named":false}]}},{"kind":"note","itemId":"a652032e-ce99-5b72-a681-36ab66baa78c","sourceKey":"guide-topic:11","position":11,"payload":{"title":"Grammar II: Clauses and Sentences","body":"What a clause is; main versus subordinate clauses; the three clause types by form (finite, non-finite, verbless) and three by function (adjective/relative, adverb, noun); defining versus non-defining relative clauses and their commas; the sentence, major and minor sentences and fragments; simple, compound, multiple, complex and compound-complex sentences; the four sentence types by function; subject and predicate, S, V, O, C, A and the seven clause patterns; subject-verb agreement; the seven common sentence faults.","noteType":"guide_topic","number":11,"mustKnow":[{"text":"What a clause is; main versus subordinate clauses; the three clause types by form (finite,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 49, $study_guide$ non-finite, verbless) and three by function (adjective/relative, adverb, noun); defining versus non-defining relative clauses and their commas; the sentence, major and minor sentences and fragments; simple, compound, multiple, complex and compound-complex sentences; the four sentence types by function; subject and predicate, S, V, O, C, A and the seven clause patterns; subject-verb agreement; the seven common sentence faults."}],"lessons":[{"number":"11.1","title":"The clause and its forms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hierarchy of grammatical units:","bold":true},{"text":" morpheme, word, phrase, clause, sentence. The clause is next in rank after the phrase; the "},{"text":"sentence is the highest unit of grammatical analysis","bold":true},{"text":"."}]},{"text":[{"text":"Clause:","bold":true},{"text":" a group of words that contains a "},{"text":"subject and a predicate","bold":true},{"text":"."}]},{"text":[{"text":"Main (independent) clause:","bold":true},{"text":" can stand by itself and make sense. It identifies what the sentence is about (the subject) and gives the essential information about it (the predicate)."}]},{"text":[{"text":"Subordinate (dependent) clause:","bold":true},{"text":" cannot stand by itself or make complete sense; it needs the main clause. It works inside the main clause like a "},{"text":"noun","bold":true},{"text":" or a "},{"text":"modifier","bold":true},{"text":"."}]},{"text":[{"text":"A simple sentence occurring by itself can also be called a clause.","bold":true},{"text":" When simple sentences combine into a larger sentence, each becomes a clause: "},{"text":"Olu kicked the ball and Ade caught it","italic":true},{"text":" has two clauses linked by "},{"text":"and","italic":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"3 types of subordinate clause by form","bold":true},{"text":" (structure):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Finite clause:","bold":true},{"text":" contains a "},{"text":"finite verb","bold":true},{"text":", a verb form that "},{"text":"changes","bold":true},{"text":" with "},{"text":"number, person and tense","bold":true},{"text":" ("},{"text":"visit, visits, visited, am visiting, is visiting","italic":true},{"text":")."}]},{"text":[{"text":"Non-finite clause:","bold":true},{"text":" contains a "},{"text":"non-finite verb","bold":true},{"text":", a form that "},{"text":"remains unchanging","bold":true},{"text":" whatever the number, person or tense. Often has "},{"text":"no subject","bold":true},{"text":": "},{"text":"It will be safer [for us to leave the scene]","italic":true},{"text":"; "},{"text":"The car [being repaired] is mine","italic":true},{"text":"; "},{"text":"[The applause having died down,] she began to sing","italic":true},{"text":"."}]},{"text":[{"text":"Verbless clause:","bold":true},{"text":" has "},{"text":"no verb","bold":true},{"text":", and usually no subject; both are understood from context: "},{"text":"He became a drug addict [while in prison]","italic":true},{"text":"; "},{"text":"[When in his famous sad mood,] he will not talk to anyone for days","italic":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Main + subordinate: "},{"text":"We had to abandon our home","italic":true},{"text":" | "},{"text":"as the flood waters rose higher","italic":true},{"text":"; "},{"text":"They found out","italic":true},{"text":" | "},{"text":"that he had lied to them","italic":true},{"text":"."}]},{"text":[{"text":"The subordinate clause may come "},{"text":"first","bold":true},{"text":" ("},{"text":"As the flood waters rose higher, we had to abandon our home","italic":true},{"text":") or be "},{"text":"embedded","bold":true},{"text":" in the main clause ("},{"text":"The boy [who came here today] is my cousin","italic":true},{"text":"; "},{"text":"My sister, [who lives in Warri,] is visiting us today","italic":true},{"text":")."}]},{"text":[{"text":"Finite verb changes: "},{"text":"They visit","italic":true},{"text":" (plural, present); "},{"text":"Mary visits","italic":true},{"text":" (singular); "},{"text":"Mary visited","italic":true},{"text":" (past); "},{"text":"I am visiting","italic":true},{"text":"."}]},{"text":[{"text":"Verbless clause rule:","bold":true},{"text":" only clauses whose main verb is "},{"text":"to be","bold":true},{"text":" ("},{"text":"is, am, are, was, were, be, been, being","italic":true},{"text":") can be verbless. The missing subject is usually the subject of the main clause: "},{"text":"while (he was) in prison","italic":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a finite clause contains "},{"text":"a verb that changes","bold":true},{"text":"; \"a verb that remains unchanging\" is non-finite and \"no verb at all\" is verbless. There is no "},{"text":"\"infinite clause\"","bold":true},{"text":"."}]}]}]},{"number":"11.2","title":"Clauses by function: adjective, adverb and noun clauses","mustKnow":[{"type":"paragraph","text":[{"text":"Subordinate clauses do the work of adjectives, adverbs and nouns, so there are "},{"text":"3 types by function","bold":true},{"text":":"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjective (or relative) clause:","bold":true},{"text":" modifies a "},{"text":"noun","bold":true},{"text":" (or pronoun) like an adjective. The other name for the adjective clause is "},{"text":"relative clause","bold":true},{"text":". Introduced by the "},{"text":"relative pronouns","bold":true},{"text":" "},{"text":"who, whom, whose, which, that","italic":true},{"text":" (occasionally "},{"text":"when, why, where","italic":true},{"text":"). The relative pronoun is the "},{"text":"subject","bold":true},{"text":" or "},{"text":"object","bold":true},{"text":" of its clause: "},{"text":"The man [who called you up this morning] is my uncle","italic":true},{"text":" ("},{"text":"who","italic":true},{"text":" = subject); "}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 50, $study_guide$,{"text":"This is the man [whom the police questioned yesterday]","italic":true},{"text":" ("},{"text":"whom","italic":true},{"text":" = object)."}]},{"text":[{"text":"Adverb clause:","bold":true},{"text":" usually modifies the "},{"text":"verb","bold":true},{"text":" (time, place, manner, cause, condition, degree, comparison, concession), or an adjective, another adverb or the rest of the sentence. Introduced by "},{"text":"subordinating conjunctions","bold":true},{"text":": "},{"text":"when, if, since, before, as, because, although, while, wherever, after, unless, whether","italic":true},{"text":"."}]},{"text":[{"text":"Noun clause:","bold":true},{"text":" sits in noun positions and does noun jobs: "},{"text":"subject, direct object, indirect object, subject complement, object complement, prepositional complement, appositive","bold":true},{"text":". Usually introduced by "},{"text":"that","bold":true},{"text":"; also "},{"text":"what, where, who, whoever, whether, why, when, whatever","italic":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Relative clauses: 2 major functions","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"identify","bold":true},{"text":" the particular noun meant; they answer "},{"text":"\"which one?\"","bold":true},{"text":" This is the "},{"text":"defining (restrictive)","bold":true},{"text":" clause."}]},{"text":[{"text":"To give "},{"text":"additional information","bold":true},{"text":" about a noun already known. This is the "},{"text":"non-defining (non-restrictive)","bold":true},{"text":" clause."}]}]},{"type":"table","header":[[],[{"text":"Defining (restrictive)"}],[{"text":"Non-defining (non-restrictive)"}]],"rows":[[[{"text":"Job"}],[{"text":"Identifies: \"which one?\""}],[{"text":"Adds new, extra information"}]],[[{"text":"Essential to meaning?"}],[{"text":"Yes; fused into the sentence"}],[{"text":"No; can be left out"}]],[[{"text":"Commas"}],[{"text":"None","bold":true}],[{"text":"Paired commas","bold":true},{"text":", one before and one after"}]],[[{"text":"that","italic":true}],[{"text":"Accepted","bold":true}],[{"text":"Never","bold":true},{"text":" used"}]],[[{"text":"Pronoun omitted?"}],[{"text":"Yes, if not the subject ("},{"text":"the man we have been looking for","italic":true},{"text":")"}],[{"text":"No"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Defining:","bold":true},{"text":" "},{"text":"The man who lent you a book this morning is our Use of English instructor","italic":true},{"text":" (without the clause: \"which man?\"); "},{"text":"The banks which had failed to comply were sanctioned","italic":true},{"text":"."}]},{"text":[{"text":"Non-defining:","bold":true},{"text":" "},{"text":"My cousin Miriam, who was runner-up last year, won the first prize this year","italic":true},{"text":"; "},{"text":"Chike, who had never been to Lagos before, was excited about the trip.","italic":true},{"text":" Miriam and Chike are already known."}]},{"text":[{"text":"Commas change meaning:","bold":true},{"text":" "},{"text":"The students who arrived late for the lecture were locked out","italic":true},{"text":" = "},{"text":"some","bold":true},{"text":" students arrived late. "},{"text":"The students, who arrived late for the lecture, were locked out","italic":true},{"text":" = "},{"text":"all","bold":true},{"text":" students arrived late."}]},{"text":[{"text":"That","bold":true,"italic":true},{"text":":","bold":true},{"text":" "},{"text":"The students that arrived late were locked out","italic":true},{"text":" is correct (restrictive). "},{"text":"*Chike, that had never been to Lagos before, ...","italic":true},{"text":" is unacceptable. American English permits only "},{"text":"that","italic":true},{"text":" in defining clauses; use this as a guide to punctuating."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"restrictive clause\" is only a "},{"text":"sub-type","bold":true},{"text":" of relative clause, not another name for the adjective clause."}]},{"text":[{"text":"Adverb clauses:","bold":true},{"text":" "},{"text":"She hung onto his feet [as if her life depended on it]","italic":true},{"text":" is an "},{"text":"adverbial clause of manner","bold":true},{"text":" modifying "},{"text":"hung","italic":true},{"text":" (not adjectival; \"relative clause of manner\" and \"verbal clause\" are not clause types). "},{"text":"[Whenever he is upset,] he goes out and gets drunk","italic":true},{"text":" is an adverbial clause of "},{"text":"time","bold":true},{"text":". "},{"text":"If you study very hard","italic":true},{"text":" = condition; "},{"text":"Wherever they went","italic":true},{"text":" = place; "},{"text":"Although the two countries had signed a peace treaty","italic":true},{"text":" = concession; "},{"text":"because he was afraid","italic":true},{"text":" = cause."}]},{"text":[{"text":"Noun clauses:","bold":true},{"text":" "},{"text":"[That she was the best suited for the job] was pretty obvious","italic":true},{"text":" (subject); "},{"text":"We found out [that he was not telling the truth]","italic":true},{"text":" (direct object); "},{"text":"He told his pathetic story to [whoever he met on the way]","italic":true},{"text":" (indirect object); "},{"text":"The question now is [how we can solve this problem]","italic":true},{"text":" (subject complement); "},{"text":"Our reaction will depend on [what he does next]","italic":true},{"text":" (complement of the preposition "},{"text":"on","italic":true},{"text":"); "},{"text":"The fact [that she is not here now] speaks for itself","italic":true},{"text":" (appositive). A "},{"text":"nominal clause","bold":true},{"text":" = noun clause; "},{"text":"adjectival clause","bold":true},{"text":" = adjective clause."}]}]}]},{"number":"11.3","title":"The sentence and its types by form","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sentence, 2 definitions:","bold":true},{"text":" (1) a gr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 51, $study_guide$oup of words that "},{"text":"begins with a capital letter and ends with a full stop","bold":true},{"text":"; (2) a group of words that "},{"text":"expresses a complete thought","bold":true},{"text":"."}]},{"text":[{"text":"Sentence fragment:","bold":true},{"text":" does "},{"text":"not","bold":true},{"text":" express a complete thought; essential parts are missing: "},{"text":"*Because I was hungry","italic":true},{"text":"; "},{"text":"*While Dad was driving across town.","italic":true},{"text":" "},{"text":"Unacceptable.","bold":true}]}]},{"type":"paragraph","text":[{"text":"By form, first distinguish:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Major sentences:","bold":true},{"text":" complete; contain the "},{"text":"subject and the predicate","bold":true},{"text":": "},{"text":"The carpenter completed the job this afternoon.","italic":true},{"text":" The vast majority of sentences are major."}]},{"text":[{"text":"Minor sentences:","bold":true},{"text":" "},{"text":"meaningful but grammatically incomplete","bold":true},{"text":"; they lack an essential component, but the omitted parts are "},{"text":"recoverable from context","bold":true},{"text":": "},{"text":"No fuel. Gatekeeper wanted. For sale. No vacancy. No smoking. Look out! Taxi, Surulere! Better luck next time!","italic":true},{"text":" "},{"text":"Acceptable.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Major sentences are further divided into 5 kinds:","bold":true}]},{"type":"table","header":[[{"text":"Kind"}],[{"text":"Clauses"}],[{"text":"Example"}]],"rows":[[[{"text":"Simple","bold":true}],[{"text":"one clause","bold":true},{"text":", "},{"text":"only one finite verb","bold":true},{"text":" (a single statement)"}],[{"text":"The boy killed the snake.","italic":true}]],[[{"text":"Compound","bold":true}],[{"text":"two","bold":true},{"text":" clauses, each independent and equal; two finite verbs"}],[{"text":"Ngozi was at the scene, but she didn't witness the accident.","italic":true}]],[[{"text":"Multiple","bold":true}],[{"text":"like compound, but "},{"text":"three or more","bold":true},{"text":" clauses"}],[{"text":"The fire was raging, the police kept the anxious crowd at bay, and the firefighters were dashing around.","italic":true}]],[[{"text":"Complex","bold":true}],[{"text":"one","bold":true},{"text":" independent (main) + "},{"text":"one or more","bold":true},{"text":" dependent (subordinate)"}],[{"text":"She met her husband while she was studying abroad.","italic":true}]],[[{"text":"Compound-complex","bold":true}],[{"text":"two or more","bold":true},{"text":" main + "},{"text":"at least one","bold":true},{"text":" subordinate"}],[{"text":"Olu kicked the ball as it rolled towards him and Ade caught it.","italic":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fragment vs minor sentence:","bold":true},{"text":" a fragment leaves the reader wondering; a minor sentence is clear: "},{"text":"(There is) no fuel. (A) gatekeeper (is) wanted. (You should) look out! (I wish you) better luck next time!","italic":true}]},{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"God bless you","italic":true},{"text":" is "},{"text":"not","bold":true},{"text":" a minor sentence: it has its own subject ("},{"text":"God","italic":true},{"text":") and verb ("},{"text":"bless","italic":true},{"text":"). "},{"text":"No smoking","italic":true},{"text":" is a minor sentence, not a simple one (no subject, no finite verb)."}]},{"text":[{"text":"Simple sentence trap:","bold":true},{"text":" one clause "},{"text":"and","bold":true},{"text":" one finite verb. Two clauses or two finite verbs means it is not simple. "},{"text":"The teacher asked a difficult question and no student could answer it","italic":true},{"text":" is compound."}]},{"text":[{"text":"Compound sentences","bold":true},{"text":" use "},{"text":"coordinating conjunctions","bold":true},{"text":" ("},{"text":"and, but, or, nor, for, yet","italic":true},{"text":") and "},{"text":"conjunctive adverbs","bold":true},{"text":" ("},{"text":"however, moreover, nevertheless, therefore, still, so","italic":true},{"text":")."}]},{"text":[{"text":"Complex:","bold":true},{"text":" the subordinate clause is joined by a "},{"text":"subordinating conjunction","bold":true},{"text":" ("},{"text":"They returned home after the war ended","italic":true},{"text":") or by "},{"text":"embedding","bold":true},{"text":" ("},{"text":"The escaping robber, who was shot in the head last night, died this morning","italic":true},{"text":"). "},{"text":"Trap:","bold":true},{"text":" one independent clause and "},{"text":"one or more","bold":true},{"text":" dependent clauses, not exactly one. Two independent clauses plus a subordinate one = compound-complex ("},{"text":"He washed the clothes when it stopped raining and ironed them later","italic":true},{"text":")."}]}]}]},{"number":"11.4","title":"Sentence types by function and the elements of a sentence","mustKnow":[{"type":"paragraph","text":[{"text":"4 sentence types by function:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Declarative:","bold":true},{"text":" makes a "},{"text":"statement","bold":true},{"text":"; ends with a "},{"text":"full stop (period)","bold":true},{"text":". "},{"text":"Tomorrow is my birthday.","italic":true}]},{"text":[{"text":"Interrogative:","bold":true},{"text":" "},{"text":"asks a question","bold":true},{"text":". "},{"text":"What were you doing this morning?","italic":true}]},{"text":[{"text":"Imperative:","bold":true},{"text":" "},{"text":"gives directives","bold":true},{"text":". "},{"text":"Get out! Have a drink. Look out!","italic":true}]},{"text":[{"text":"Exclamatory:","bold":true},{"text":" expresses "},{"text":"strong emotion","bold":true},{"text":"; usually ends with an "},{"text":"exclamation mark","bold":true},{"text":". "},{"text":"Oh, my goodness! I'll be damned!","italic":true}]}]},{"type$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 52, $study_guide$":"paragraph","text":[{"text":"12 kinds of imperative directive:","bold":true},{"text":" commanding ("},{"text":"Get out!","italic":true},{"text":"), inviting ("},{"text":"Have a drink.","italic":true},{"text":"), warning ("},{"text":"Look out!","italic":true},{"text":"), pleading ("},{"text":"Have mercy.","italic":true},{"text":"), permitting ("},{"text":"Suit yourself.","italic":true},{"text":"), suggesting ("},{"text":"Let's go by bus.","italic":true},{"text":"), advising ("},{"text":"Take the first flight.","italic":true},{"text":"), requesting ("},{"text":"Open the windows, please.","italic":true},{"text":"), meditating ("},{"text":"Let me see.","italic":true},{"text":"), expressing an imprecation ("},{"text":"Damn you!","italic":true},{"text":"), expressing good wishes ("},{"text":"Have a lovely day.","italic":true},{"text":"), instructing ("},{"text":"Stir for five minutes.","italic":true},{"text":")."}]},{"type":"paragraph","text":[{"text":"Elements of a sentence:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"2 major components:","bold":true},{"text":" the "},{"text":"subject","bold":true},{"text":" (names the person or thing about which something is said) and the "},{"text":"predicate","bold":true},{"text":" (what is said about the subject). "},{"text":"Birds","italic":true},{"text":" | "},{"text":"fly","italic":true},{"text":". "},{"text":"The happy children","italic":true},{"text":" | "},{"text":"poured out of the classroom","italic":true},{"text":"."}]},{"text":[{"text":"5 components:","bold":true},{"text":" "},{"text":"subject (S), verb (V), object (O), complement (C), adverbial or adjunct (A)","bold":true},{"text":"."}]},{"text":[{"text":"7 basic clause patterns","bold":true},{"text":" of the English simple sentence:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"SV:","bold":true},{"text":" "},{"text":"Jesus wept.","italic":true}]},{"text":[{"text":"SVO:","bold":true},{"text":" "},{"text":"The guards caught the thief.","italic":true}]},{"text":[{"text":"SVC:","bold":true},{"text":" "},{"text":"Kofi became the president.","italic":true}]},{"text":[{"text":"SVA:","bold":true},{"text":" "},{"text":"The plane took off at eight o'clock.","italic":true}]},{"text":[{"text":"SVOO:","bold":true},{"text":" "},{"text":"The man bought his wife a present.","italic":true}]},{"text":[{"text":"SVOC:","bold":true},{"text":" "},{"text":"The priest pronounced the couple man and wife.","italic":true}]},{"text":[{"text":"SVOA:","bold":true},{"text":" "},{"text":"The tribunal conducted the hearing behind closed doors.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" \"interlocutory\" is not a sentence type. "},{"text":"Oh, my goodness!","italic":true},{"text":" and "},{"text":"I don't believe that!","italic":true},{"text":" are exclamatory, "},{"text":"not","bold":true},{"text":" imperative. The plainest imperative is a bare verb with "},{"text":"you","italic":true},{"text":" understood: "},{"text":"Take the bus home.","italic":true}]},{"text":[{"text":"Trap:","bold":true},{"text":" the "},{"text":"major components of a sentence are the subject and the predicate","bold":true},{"text":", not main and subordinate clause, not independent and dependent clause, not nouns and adjectives."}]},{"text":[{"text":"Subject:","bold":true},{"text":" in "},{"text":"That boy is my cousin","italic":true},{"text":", "},{"text":"boy","italic":true},{"text":" is the "},{"text":"subject of the verb","bold":true},{"text":" "},{"text":"is","italic":true},{"text":"."}]},{"text":[{"text":"Direct object:","bold":true},{"text":" receives the action; answers \"what/whom?\" "},{"text":"Mr Dokunboh thanked the lady","italic":true},{"text":" ("},{"text":"the lady","italic":true},{"text":" = direct object); "},{"text":"The young lady thanked Mr Dokubo","italic":true},{"text":" ("},{"text":"Mr Dokubo","italic":true},{"text":" = direct object); "},{"text":"Mr Dokunboh donated some books","italic":true},{"text":" ("},{"text":"some books","italic":true},{"text":" = direct object)."}]},{"text":[{"text":"Indirect object:","bold":true},{"text":" the receiver, \"to or for whom?\", normally present only when the verb has two objects (SVOO). "},{"text":"We bought John a guitar","italic":true},{"text":": "},{"text":"John","italic":true},{"text":" = indirect object, "},{"text":"a guitar","italic":true},{"text":" = "},{"text":"direct object","bold":true},{"text":". "},{"text":"The man bought his wife a present","italic":true},{"text":": "},{"text":"his wife","italic":true},{"text":" = indirect, "},{"text":"a present","italic":true},{"text":" = direct."}]},{"text":[{"text":"Complement:","bold":true},{"text":" (i) a noun or noun phrase that is "},{"text":"the same as","bold":true},{"text":" the subject or object ("},{"text":"Nosa is my cousin","italic":true},{"text":"; "},{"text":"Kofi became the president","italic":true},{"text":", so SVC; "},{"text":"man and wife","italic":true},{"text":" = "},{"text":"the couple","italic":true},{"text":", so SVOC); or (ii) an "},{"text":"adjective describing","bold":true},{"text":" the subject or object ("},{"text":"The panel considered his remarks misleading","italic":true},{"text":")."}]},{"text":[{"text":"Adverbial (adjunct):","bold":true},{"text":" like an adverb, tells "},{"text":"time, place, manner","bold":true},{"text":": "},{"text":"at eight o'clock","italic":true},{"text":" (SVA), "},{"text":"behind closed doors","italic":true},{"text":" (SVOA)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"seven","bold":true},{"text":" patterns, not 4, 6 or 8; "},{"text":"SVCC is not one","bold":true},{"text":". "},{"text":"Jesus wept","italic":true},{"text":" = SV."}]}]}]},{"number":"11.5","title":"Subject-verb agreement (concord)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Concord","bold":true},{"text":" = grammatical agreement. "},{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 53, $study_guide$t":"4 types:","bold":true},{"text":" subject-verb, pronoun-antecedent, determiner-noun head, tense concord. Focus: "},{"text":"subject-verb agreement in number","bold":true},{"text":" (singular/plural)."}]},{"text":[{"text":"Rule:","bold":true},{"text":" "},{"text":"singular subject, singular verb; plural subject, plural verb.","bold":true},{"text":" "},{"text":"The girl lives in Surulere. The girls live in Surulere.","italic":true}]},{"text":[{"text":"The -s inconsistency:","bold":true},{"text":" plural "},{"text":"nouns","bold":true},{"text":" take -s; "},{"text":"singular verbs","bold":true},{"text":" take -s. "},{"text":"The car drives. The cars drive.","italic":true}]}]},{"type":"paragraph","text":[{"text":"7 rules for doubtful subjects:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Joined by ","bold":true},{"text":"and","bold":true,"italic":true},{"text":":","bold":true},{"text":" "},{"text":"plural","bold":true},{"text":" ("},{"text":"The man and his wife were present. The manager and all his staff are here.","italic":true},{"text":"), "},{"text":"unless","bold":true},{"text":" the members form a "},{"text":"single unit","bold":true},{"text":" ("},{"text":"Hot lemonade and honey is good for a cold. Waiter, is the rice and beans ready? The MD and Chief Executive Officer of the company was introduced.","italic":true},{"text":")."}]},{"text":[{"text":"Singular members joined by ","bold":true},{"text":"(either...) or","bold":true,"italic":true},{"text":" / ","bold":true},{"text":"(neither...) nor","bold":true,"italic":true},{"text":":","bold":true},{"text":" singular ("},{"text":"Either the security man or the suspect is lying","italic":true},{"text":"). Plural members: plural ("},{"text":"Neither the apprentices nor their supervisors were available","italic":true},{"text":")."}]},{"text":[{"text":"Concord of proximity","bold":true},{"text":" (nearness): mixed "},{"text":"or","italic":true},{"text":"-compounds agree with the "},{"text":"nearest","bold":true},{"text":" member: "},{"text":"Either Janet or her parents visit...","italic":true},{"text":"; "},{"text":"Either you or Ibrahim is...","italic":true},{"text":"; "},{"text":"Either you or I am...","italic":true}]},{"text":[{"text":"Plural in form, singular in meaning:","bold":true},{"text":" always singular: "},{"text":"There is no news yet. Two hundred pounds is all he managed to save. Statistics is not as difficult as many think.","italic":true}]},{"text":[{"text":"Linking expressions","bold":true},{"text":" ("},{"text":"with, together with, accompanied by, as well as, along with, in collaboration with, in conjunction with, flanked by, escorted by, in addition to","italic":true},{"text":"): the verb "},{"text":"stays singular","bold":true},{"text":" with a singular subject: "},{"text":"The Manager, together with all his staff, was outside. The governor, accompanied by his aides, is walking down the street.","italic":true}]},{"text":[{"text":"The number of","bold":true,"italic":true},{"text":" (a specific figure) = "},{"text":"singular","bold":true},{"text":"; "},{"text":"a number of","bold":true,"italic":true},{"text":" (\"several\") = "},{"text":"plural","bold":true},{"text":": "},{"text":"The number of reported cases has dropped. A number of women and children have been treated.","italic":true}]},{"text":[{"text":"Collective nouns","bold":true},{"text":" ("},{"text":"class, committee, crew, team, congregation, audience, herd, jury","italic":true},{"text":"): singular if viewed as a "},{"text":"unit","bold":true},{"text":", plural if viewed as "},{"text":"individuals","bold":true},{"text":". This is "},{"text":"notional concord","bold":true},{"text":": "},{"text":"The jury has reached a verdict. The jury are still arguing over that point.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" only "},{"text":"The man and his wife were present","italic":true},{"text":" has a "},{"text":"plural compound subject","bold":true},{"text":"; lemonade and honey (one drink), rice and beans (one dish) and the MD and CEO (one person) are singular units."}]},{"text":[{"text":"And","bold":true,"italic":true},{"text":" vs a linking expression:","bold":true},{"text":" "},{"text":"The captain and several crew members were injured","italic":true},{"text":" gives both equal attention; "},{"text":"The captain, along with several crew members, was injured","italic":true},{"text":" focuses on the captain. "},{"text":"Organisation A in collaboration with Organisation B","italic":true},{"text":" = B played a subsidiary role."}]},{"text":[{"text":"Any "},{"text":"pronoun","bold":true},{"text":" referring to a collective noun must agree with it too. Faulty: "},{"text":"*The committee has concluded its deliberations and their report is expected","italic":true},{"text":" ("},{"text":"its","italic":true},{"text":" then "},{"text":"their","italic":true},{"text":"); "},{"text":"*The cabinet is divided, but it is hoped that they will soon agree","italic":true},{"text":" ("},{"text":"is","italic":true},{"text":" then "},{"text":"they","italic":true},{"text":")."}]}]}]},{"number":"11.6","title":"Common errors in sentence construction","mustKnow":[{"type":"paragraph","text":[{"text":"7 sentence faults:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Empty sentences:","bold":true},{"text":" grammatically correct but "},{"text":"say nothing","bold":true},{"text":": "},{"text":"*I want to acquire university education because acquiring university education will satisfy my long-felt desires.","italic":true},{"text":" Cancel or revise."}]},{"text":[{"text":"Padded sentences:","bold":true},{"text":" full of "},{"text":"unnecessary words","bold":true},{"text":". Two kinds: "},{"text":"unnecessary repetition","bold":true},{"text":" and "},{"text":"wordiness","bold":true},{"text":". Sentences should be "},{"text":"accurate, brief and $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 54, $study_guide$clear","bold":true},{"text":"."}]},{"text":[{"text":"Overloaded sentences:","bold":true},{"text":" "},{"text":"too many facts and ideas","bold":true},{"text":" crowded in. Split them. Rules: (i) "},{"text":"say one thing at a time","bold":true},{"text":"; (ii) "},{"text":"say it simply and directly","bold":true},{"text":"."}]},{"text":[{"text":"Dangling modifiers:","bold":true},{"text":" modifiers whose word is "},{"text":"missing","bold":true},{"text":", so they have "},{"text":"nothing to modify","bold":true},{"text":": "},{"text":"*Returning home late one night, the gate was locked.","italic":true}]},{"text":[{"text":"Run-on sentences:","bold":true},{"text":" two or more sentences "},{"text":"collapsed into one with no punctuation","bold":true},{"text":" between them: "},{"text":"*Anne looked everywhere for her missing phone unfortunately she did not find it.","italic":true}]},{"text":[{"text":"The comma splice:","bold":true},{"text":" related to the run-on; a "},{"text":"comma weakly separates","bold":true},{"text":" sentences run together: "},{"text":"*Anne looked everywhere for her phone, unfortunately she did not find it, she reported the loss to the hostel warden.","italic":true}]},{"text":[{"text":"The sentence fragment:","bold":true},{"text":" a "},{"text":"phrase or subordinate clause","bold":true},{"text":" punctuated as a sentence: "},{"text":"A nominal clause functions like a noun. *While an adjectival clause modifies a noun.","italic":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Padding:","bold":true},{"text":" "},{"text":"*The modern businessman of today must completely master all of the principles of computerization","italic":true},{"text":": \"of today\" repeats \"modern\"; \"completely\" and \"all of\" repeat \"master\". "},{"text":"*...as a result of the fact that our computers broke down","italic":true},{"text":": seven words replaced by "},{"text":"because","bold":true},{"text":"."}]},{"text":[{"text":"Overloading:","bold":true},{"text":" one long sentence about a large university was split into three; one about Chike's parents into four."}]},{"text":[{"text":"Dangling modifiers:","bold":true},{"text":" correct use: "},{"text":"While climbing a palm tree, Amodu lost his grip","italic":true},{"text":" (the modifier attaches to "},{"text":"Amodu","italic":true},{"text":"). Faulty: "},{"text":"*Driving around Greensville a year later, it's clear the town will never be the same","italic":true},{"text":"; "},{"text":"*Having said that, there are other points to consider","italic":true},{"text":"; "},{"text":"*Returning home late one night, a snake bit Olu","italic":true},{"text":" (the modified word must be "},{"text":"right next to","bold":true},{"text":" the modifier, since modifiers attach to the "},{"text":"closest","bold":true},{"text":" noun or pronoun). "},{"text":"Two corrections:","bold":true},{"text":" put the doer next to the modifier ("},{"text":"Returning home late one night, Olu was bitten by a snake","italic":true},{"text":") or make the modifier a full clause ("},{"text":"As Olu returned home late one night, he was bitten by a snake","italic":true},{"text":")."}]},{"text":[{"text":"Run-ons:","bold":true},{"text":" break into sentences or link with suitable conjunctions."}]},{"text":[{"text":"While","bold":true,"italic":true},{"text":" and other "},{"text":"subordinating conjunctions","bold":true},{"text":" ("},{"text":"when, although, as, because, since, whenever, wherever","italic":true},{"text":") make a clause subordinate, so it cannot stand alone. Correct: "},{"text":"A nominal clause functions as a noun, while an adjectival clause modifies a noun.","italic":true}]},{"text":[{"text":"Trap:","bold":true},{"text":" run-on = "},{"text":"no","bold":true},{"text":" punctuation; comma splice = a "},{"text":"comma","bold":true},{"text":" where a full stop or conjunction is needed. Minor sentence = acceptable; fragment = not."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clause = subject + predicate; main stands alone, subordinate does not. A simple sentence alone is also a clause."}]},{"text":[{"text":"Form: finite (verb changes), non-finite (unchanging), verbless (no verb; "},{"text":"to be","italic":true},{"text":" only)."}]},{"text":[{"text":"Function: adjective/relative (noun; "},{"text":"who, whom, whose, which, that","italic":true},{"text":"), adverb (verb; subordinating conjunctions), noun (S, DO, IO, complement, appositive; "},{"text":"that","italic":true},{"text":")."}]},{"text":[{"text":"Defining: \"which one?\", no commas, accepts "},{"text":"that","italic":true},{"text":". Non-defining: extra information, paired commas, never "},{"text":"that","italic":true},{"text":"."}]},{"text":[{"text":"Major (subject + predicate) vs minor (incomplete but recoverable); fragments unacceptable."}]},{"text":[{"text":"Simple (1 clause, 1 finite verb), compound (2), multiple (3+), complex (1 main + 1 or more subordinate), compound-complex (2+ main + 1 or more subordinate)."}]},{"text":[{"text":"Declarative (statement), interrogative (question), imperative (directive), exclamatory (emotion)."}]},{"text":[{"text":"Subject + predicate; S, V, O, C, A; 7 patterns: SV, SVO, SVC, SVA, SVOO, SVOC, SVOA."}]},{"text":[{"text":"Concord: "},{"text":"and","italic":true},{"text":" plural unless one unit; "},{"text":"or/nor","italic":true},{"text":" nearest member; "},{"text":"together with","italic":true},{"text":" keeps singular; "},{"text":"the number of","italic":true},{"text":" singular, "},{"text":"a number of","italic":true},{"text":" plural; collective nouns notional."}]},{"text":[{"text":"7 faults: empty, padded, overloaded, dangling modifier, run-on, comma splice, fragment."}]}]}],"theory":{"itemId":"f080dbdc-2921-5808-9f7e-555c36543412","question":[{"type":"paragraph","text":[{"text":"Distinguish between defining and non-defining relative clauses, with one example of each, and show how punctuation af$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 55, $study_guide$fects meaning."}]}]},"practice":[{"topic":"Grammar II: Clauses and Sentences","named":false}]}},{"kind":"note","itemId":"d709d882-4a78-5857-8521-e2dc52415c0e","sourceKey":"guide-topic:12","position":12,"payload":{"title":"The Library, Information Resources and Use","body":"The library, its types and five functions; data, information and information literacy; the five characteristics of good information; the six forms and two sources (primary, secondary) of information; the University of Lagos Library's three resource categories, five print collections, eleven types of reference collection, and where each is housed.","noteType":"guide_topic","number":12,"mustKnow":[{"text":"The library, its types and five functions; data, information and information literacy; the five characteristics of good information; the six forms and two sources (primary, secondary) of information; the University of Lagos Library's three resource categories, five print collections, eleven types of reference collection, and where each is housed."}],"lessons":[{"number":"12.1","title":"The library, its functions, data and information","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Library:","bold":true},{"text":" any "},{"text":"organised collection","bold":true},{"text":" for use by an individual or group of people; a collection of books gathered for purposes of "},{"text":"reading, study or reference","bold":true},{"text":". Today it means a body of "},{"text":"recorded information","bold":true},{"text":" brought together for specific purposes, "},{"text":"organised for use","bold":true},{"text":" and "},{"text":"made available to users","bold":true},{"text":"."}]},{"text":[{"text":"Types of library (the 5 named):","bold":true},{"text":" public, academic, special, school, private, and so on. A "},{"text":"court library","bold":true},{"text":" is not one of the named types."}]},{"text":[{"text":"5 basic functions","bold":true},{"text":" of every library, whatever its type, for resources in "},{"text":"print and electronic","bold":true},{"text":" format:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Selection","bold":true}]},{"text":[{"text":"Acquisition","bold":true},{"text":" (acquiring print and non-print materials for users)"}]},{"text":[{"text":"Organisation","bold":true},{"text":" (organising resources for effective use)"}]},{"text":[{"text":"Preservation","bold":true},{"text":" (preserving the resources acquired)"}]},{"text":[{"text":"Dissemination","bold":true},{"text":" (making information available to users)"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Book selling","bold":true},{"text":" is not a library function."}]},{"text":[{"text":"Data:","bold":true},{"text":" plural of "},{"text":"datum","italic":true},{"text":"; "},{"text":"facts","bold":true},{"text":" used in describing or discussing an item or set of items; also facts, figures or instructions in a form that can be comprehended and communicated by a human being or processed by a computer. Another word for data is "},{"text":"fact","bold":true},{"text":"."}]},{"text":[{"text":"Information:","bold":true},{"text":" facts, news, opinions, messages, symbols, signals and "},{"text":"processed data","bold":true},{"text":" capable of "},{"text":"improving the knowledge state","bold":true},{"text":" of a user. It is the "},{"text":"building block","bold":true},{"text":" in the creation of "},{"text":"knowledge and wisdom","bold":true},{"text":"."}]},{"text":[{"text":"Information literacy:","bold":true},{"text":" the ability to "},{"text":"locate, retrieve, evaluate and apply","bold":true},{"text":" information as you convert it into knowledge; it also includes the ability to "},{"text":"recognise when information is needed","bold":true},{"text":". It stresses the skill of finding needed information and understanding how the library and its resources are organised."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Data and information are "},{"text":"not","bold":true},{"text":" the same. Data is raw facts; information is processed data that improves what you know. \"Another word for data\" is "},{"text":"fact","bold":true},{"text":", not information."}]},{"text":[{"text":"Information literacy distractors: \"information knowledge\", \"information discovery\" (only finding, not evaluating and applying), \"information explosion\" (the rapid growth in the amount of information), \"information support\", \"information asset\". None is the term."}]},{"text":[{"text":"Library sections and terms","bold":true},{"text":" you must recognise:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Circulation section (circulation desk):","bold":true},{"text":" deals with the "},{"text":"borrowing and returning","bold":true},{"text":" of books; also where you ask for help locating a book (with the library catalogue and any library staff). Distributing books among affiliated libraries is inter-library lending, a separate service."}]},{"text":[{"text":"Acquisitions section:","bold":true},{"text":" acquires new materials. "},{"text":"Cataloguing section:","bold":true},{"text":" catalogues and classifies acquired materials. Both are back-office units."}]},{"text":[{"text":"Reference librarian:","bold":true},{"text":" the person who provides "},{"text":"reference services","bold":true},{"text":". Not the Chief Librarian or University Librarian (head of the library) and not a general \"library officer\"."}]},{"text":[{"text":"Weeding:","bold":true},{"text":" "},{"text":"removing outdated","bold":true},{"text":" (damaged or no-longer-useful) books from the collection. Not dusting shelves, clearing tables or screening users."}]},{"text":[{"text":"Catalogue:","bold":true},{"text":" gives the "},{"text":"bibliographic details","bold":true},{"text":" (author, title and "},{"text":"call number","bold":true},{"text":", also called the "},{"text":"call mark","bold":true},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 56, $study_guide$text":") needed to retrieve a book. Two forms: the "},{"text":"card catalogue","bold":true},{"text":" (author/title and subject) and the "},{"text":"Online Public Access Catalogue (OPAC)","bold":true},{"text":"."}]}]}]}]}]},{"number":"12.2","title":"Characteristics of good information","mustKnow":[{"type":"paragraph","text":[{"text":"Information is good if it has these "},{"text":"5 characteristics","bold":true},{"text":" (attributes, qualities):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Availability/Accessibility:","bold":true},{"text":" information is of no use if it is not within reach of its intended users; it should be "},{"text":"easy to obtain and access","bold":true},{"text":". Accessibility is the "},{"text":"ease with which information can be obtained","bold":true},{"text":"."}]},{"text":[{"text":"Accuracy:","bold":true},{"text":" information must be accurate for the purpose for which it is used."}]},{"text":[{"text":"Reliability:","bold":true},{"text":" the "},{"text":"truthfulness","bold":true},{"text":" with which information is presented; ensured by its "},{"text":"authoritativeness and dependability","bold":true},{"text":"."}]},{"text":[{"text":"Timeliness:","bold":true},{"text":" information must be provided "},{"text":"on time","bold":true},{"text":" for the purpose it is required; late information becomes "},{"text":"irrelevant","bold":true},{"text":". Timeliness is a "},{"text":"sub-set of accessibility","bold":true},{"text":"."}]},{"text":[{"text":"Relevance:","bold":true},{"text":" information must be relevant to the purpose and "},{"text":"suitable for the user","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" characteristics: "},{"text":"news","bold":true},{"text":" (a form information takes), "},{"text":"citation","bold":true},{"text":", "},{"text":"printing","bold":true},{"text":" (things done with information), "},{"text":"non-reliability","bold":true},{"text":" (the opposite of a required quality)."}]},{"text":[{"text":"Example of accessibility: the University of Lagos Library is the "},{"text":"major organ of information provision","bold":true},{"text":" in the university community and beyond; it gives access to many types and formats of information through the traditional "},{"text":"catalogue","bold":true},{"text":" and the "},{"text":"OPAC","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"Where information is not provided on time it becomes ...\" The answer is "},{"text":"irrelevant","bold":true},{"text":", never \"useful\" or \"relevant\"."}]}]}]},{"number":"12.3","title":"Types and sources of information","mustKnow":[{"type":"paragraph","text":[{"text":"6 types (forms) of information:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Oral:","bold":true},{"text":" spoken words."}]},{"text":[{"text":"Textual:","bold":true},{"text":" text and words."}]},{"text":[{"text":"Numeric:","bold":true},{"text":" numbers."}]},{"text":[{"text":"Bibliographic:","bold":true},{"text":" the use of multi-diversified means of dissemination."}]},{"text":[{"text":"Graphical:","bold":true},{"text":" graphs and charts."}]},{"text":[{"text":"Multimedia:","bold":true},{"text":" a "},{"text":"diversified medium","bold":true},{"text":" of communication such as "},{"text":"audio, visual, audio-visual","bold":true},{"text":" and so on."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Information can therefore be in the form of numbers, texts, graphs and charts ("},{"text":"all","bold":true},{"text":" of them)."}]}]},{"type":"paragraph","text":[{"text":"2 sources of information: primary and secondary.","bold":true}]},{"type":"table","header":[[],[{"text":"Primary source"}],[{"text":"Secondary source"}]],"rows":[[[{"text":"What it is"}],[{"text":"Stands on its own; gives a "},{"text":"first-hand","bold":true},{"text":" account of an event; provides the information the user needs "},{"text":"directly","bold":true}],[{"text":"Analyses, critiques, reviews or explains","bold":true},{"text":" a primary source"}]],[[{"text":"Who writes it"}],[{"text":"The original observer or creator"}],[{"text":"Scholars who studied the primary source and drew their own conclusions; often people "},{"text":"not present","bold":true},{"text":" when the event occurred"}]],[[{"text":"Literature"}],[{"text":"Novel, short story, poem"}],[{"text":"Criticism, reviews"}]],[[{"text":"History"}],[{"text":"Laws, letters, oral histories, diaries, newspaper articles on events"}],[{"text":"Books explaining the events"}]],[[{"text":"Science"}],[{"text":"Reports of original research","bold":true},{"text":" (journal articles, theses)"}],[{"text":"Textbooks, encyclopaedias, digests"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Neither type is by nature more or less reliable","bold":true},{"text":" than the other. Depending on your topic, primary documents may be essential; some disciplines require the information to be "},{"text":"current","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"The two sources of information\" are "},{"text":"primary and secondary","bold":true},{"text":". \"Print and electronic\" is a division by "},{"text":"format","bold":true},{"text":", not by kind of source; \"books and online\" and \"library and internet\" are informal. "},{"text":"Tertiary","bold":true},{"text":" is not one of the two categories."}]},{"text":[{"text":"Fill-in: \"A secondary source is one that "},{"text":"analyses and explains","bold":true},{"text":" a primary source.\" \"Disqualify\" and \"manipulates\" are not part of the definition."}]},{"text":[{"text":"A "},{"text":"thesis","bold":true},{"text":" is a "},{"text":"primary","bold":true},{"text":" source (original research). "},{"text":"Textbooks, encyclopaedias and digests","bold":true},{"text":" compile or explain other people's work, so $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 57, $study_guide$they are "},{"text":"secondary","bold":true},{"text":"."}]},{"text":[{"text":"Journals","bold":true},{"text":" convey "},{"text":"recent original research and observation","bold":true},{"text":"; textbooks summarise established knowledge."}]},{"text":[{"text":"\"Multimedia ... diversified medium of communication such as ...\" The answer is "},{"text":"audio-visual","bold":true},{"text":", not text, graphs or numbers, which are single types."}]}]}]},{"number":"12.4","title":"Resources of the University of Lagos Library: print collections","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 categories of resources","bold":true},{"text":" in the University of Lagos Library: "},{"text":"Print, Non-print, Audio-visual","bold":true},{"text":" (all three)."}]},{"text":[{"text":"A. Print resources (books):","bold":true},{"text":" general and special collections, made up of "},{"text":"5 collections","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Africana collection","bold":true}]},{"text":[{"text":"Reference collection","bold":true}]},{"text":[{"text":"Reserved collection","bold":true}]},{"text":[{"text":"Serials collection","bold":true}]},{"text":[{"text":"Recent accessions","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"There is "},{"text":"no \"American collection\"","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Africana collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Print materials "},{"text":"published on Africa","bold":true},{"text":" by "},{"text":"African and non-African authors","bold":true},{"text":"; primarily "},{"text":"research","bold":true},{"text":" collections."}]},{"text":[{"text":"Housed at the "},{"text":"Research and Bibliographic Department","bold":true},{"text":", otherwise known as the "},{"text":"Gandhi Library","bold":true},{"text":", at the "},{"text":"basement","bold":true},{"text":" of the main library."}]},{"text":[{"text":"To use it, consult the "},{"text":"OPAC","bold":true},{"text":" or the "},{"text":"Card Catalogue","bold":true},{"text":" (author/title and subject) on the "},{"text":"ground floor","bold":true},{"text":" for the "},{"text":"author, title and call number (call mark)","bold":true},{"text":"."}]},{"text":[{"text":"Run on a "},{"text":"closed access system","bold":true},{"text":": users may "},{"text":"not","bold":true},{"text":" retrieve materials from the shelves; the "},{"text":"desk officer","bold":true},{"text":" retrieves them from the details supplied. Closed access means "},{"text":"restricted access","bold":true},{"text":"."}]},{"text":[{"text":"Access is "},{"text":"strictly for researchers and postgraduate students","bold":true},{"text":". Undergraduates enter only with a "},{"text":"letter from the head of department, supervisor or course lecturer","bold":true},{"text":"."}]},{"text":[{"text":"Africana materials are "},{"text":"not loanable","bold":true},{"text":" and may not be taken out of the department. They are consulted within the department; "},{"text":"photocopying is allowed","bold":true},{"text":". (True.)"}]},{"text":[{"text":"Other holdings: "},{"text":"special collections of notable individuals","bold":true},{"text":"; "},{"text":"newspapers, old and current, dating back to 1930","bold":true},{"text":" (the "},{"text":"West African Pilot","italic":true},{"text":", founded and owned by Nnamdi Azikiwe); magazines; "},{"text":"PhD theses","bold":true},{"text":" from the university; government papers; NGO papers; "},{"text":"cartographic materials","bold":true},{"text":" (maps); the "},{"text":"University of Lagos archives","bold":true},{"text":". A separate catalogue in the Gandhi Library lists these."}]}]},{"type":"paragraph","text":[{"text":"Reference collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Materials consulted to provide "},{"text":"specific information","bold":true},{"text":" whenever the need arises; also called "},{"text":"reference sources","bold":true},{"text":"; in "},{"text":"print and electronic","bold":true},{"text":" formats."}]},{"text":[{"text":"Contain "},{"text":"facts and rarely opinions","bold":true},{"text":" (True). "},{"text":"Not read from cover to cover","bold":true},{"text":" like books. Entries (tables, diagrams, statistics, maps) are arranged in "},{"text":"alphabetical order","bold":true},{"text":"."}]},{"text":[{"text":"Reference books "},{"text":"cannot be borrowed","bold":true},{"text":"; they are consulted in the "},{"text":"reference section","bold":true},{"text":", on the "},{"text":"left-hand side of the ground floor","bold":true},{"text":"."}]},{"text":[{"text":"Notable reference collections:","bold":true},{"text":" dictionaries, encyclopaedias, biographies, indexes, abstracts, fact sources, geographical sources, bibliographical sources, books of quotation, handbooks and manuals. "},{"text":"Books","bold":true},{"text":" in general and "},{"text":"journals","bold":true},{"text":" (serials) are "},{"text":"not","bold":true},{"text":" reference materials."}]}]},{"type":"paragraph","text":[{"text":"Reserved collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Valuable","bold":true},{"text":", often "},{"text":"rare","bold":true},{"text":" materials cutting across all disciplines."}]},{"text":[{"text":"Run on a "},{"text":"closed access system","bold":true},{"text":": you place a request with the "},{"text":"bibliographic details","bold":true},{"text":"; the material is retrieved for you."}]},{"text":[{"text":"Housed at the "},{"text":"Reserved Section","bold":true},{"text":", at the "},{"text":"immediate right on the ground floor","bold":true},{"text":"."}]},{"text":[{"text":"Must be "},{"text":"consulted within the reading room","bold":true},{"text":"; "},{"text":"not placed on long loan","bold":true},{"text":"; so reserved books "},{"text":"cannot be borrowed","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 58, $study_guide$d":true},{"text":", but you can use them and "},{"text":"photocopy","bold":true},{"text":"."}]},{"text":[{"text":"Books are placed on reserve to "},{"text":"facilitate a rapid and wider circulation of scarce materials among users","bold":true},{"text":", not to protect them from wear, keep them from unregistered users or save them for serious students only. They are for students, not staff only."}]}]},{"type":"paragraph","text":[{"text":"Serials collection","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"serial","bold":true},{"text":" is any publication issued in "},{"text":"successive parts","bold":true},{"text":", appearing at "},{"text":"regular intervals","bold":true},{"text":", and as a rule "},{"text":"intended to be continued indefinitely","bold":true},{"text":"."}]},{"text":[{"text":"Examples: newspapers, magazines, newsletters, "},{"text":"journals","bold":true},{"text":", indexes, abstracts, reports, proceedings and transactions of societies."}]},{"text":[{"text":"Very important because of the "},{"text":"currency","bold":true},{"text":" of their content. Holdings are recorded in a "},{"text":"kardex","bold":true},{"text":" (a card information system holding bibliographic details), updated as new volumes arrive. Serials also have an "},{"text":"index to magazines","bold":true},{"text":" used for term papers."}]},{"text":[{"text":"Article/journal searches","bold":true},{"text":" are done in the "},{"text":"Serials section","bold":true},{"text":" and the "},{"text":"E-library","bold":true},{"text":", not in the Cataloguing or Acquisition sections."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Special collections in the Gandhi Library belong to: "},{"text":"Mahatma Gandhi","bold":true},{"text":" (Indian nationalist and elder statesman), "},{"text":"D.O. Fagunwa","bold":true},{"text":" (the \"Shakespeare of Africa\"), "},{"text":"Pa S.O. Solanke","bold":true},{"text":" (WASU Secretary), "},{"text":"Revd Awojobi","bold":true},{"text":", "},{"text":"Professor Babalola","bold":true},{"text":", "},{"text":"Yesufu Eke","bold":true},{"text":" (one-time bursar), "},{"text":"Bishop Kale","bold":true},{"text":" and "},{"text":"Professor Adetokunbo Sofoluwe","bold":true},{"text":" (former Vice-Chancellor)."}]},{"text":[{"text":"\"The Research and Bibliographic section houses ...\" The defining answer is "},{"text":"PhD theses","bold":true},{"text":"; old and current newspapers are also kept there. Law books belong to the general collection."}]},{"text":[{"text":"Location map: "},{"text":"basement","bold":true},{"text":" = Gandhi Library (Africana); "},{"text":"ground floor","bold":true},{"text":" = card catalogue, reference section (left), reserved section (immediate right); "},{"text":"third floor","bold":true},{"text":" = Automation Section and E-Library classrooms."}]},{"text":[{"text":"Open access (the opposite of closed access) lets users retrieve materials from the shelves themselves. The reserved and Africana systems are called "},{"text":"closed","bold":true},{"text":" access (not \"restricted access system\" or \"reserve access system\"), and what closed access "},{"text":"refers to","bold":true},{"text":" is "},{"text":"restricted access","bold":true},{"text":"."}]},{"text":[{"text":"Newspapers go back to "},{"text":"1930","bold":true},{"text":", not 1860, 1920 or 1960."}]}]}]},{"number":"12.5","title":"The eleven types of reference collection","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Dictionaries:","bold":true},{"text":" give information about "},{"text":"words","bold":true},{"text":": spelling, meaning, pronunciation, usage, synonyms, etymology and grammatical function. "},{"text":"3 types:","bold":true},{"text":" "},{"text":"general","bold":true},{"text":" (Oxford English Dictionary, Chambers English Dictionary), "},{"text":"specialised","bold":true},{"text":" and "},{"text":"subject","bold":true},{"text":" dictionaries (Roget's International Thesaurus, Dictionary of American Slang, Dictionary of the Yoruba Language, Dictionary of Modern Politics). Arranged "},{"text":"alphabetically","bold":true},{"text":"; housed at the "},{"text":"reference section","bold":true},{"text":". Dictionaries are used as quick "},{"text":"reference","bold":true},{"text":" sources. There is no \"anthem dictionary\"."}]},{"text":[{"text":"Encyclopaedias:","bold":true},{"text":" give "},{"text":"background and current information on any topic","bold":true},{"text":"; a book or set of books on "},{"text":"one or all branches of knowledge","bold":true},{"text":". "},{"text":"General","bold":true},{"text":" (Encyclopaedia Britannica, Encyclopaedia Americana) or "},{"text":"subject-based","bold":true},{"text":" (Encyclopedia of Library and Information Science, of Linguistics and Languages, of Philosophy). Alphabetical; at the "},{"text":"reference section","bold":true},{"text":"."}]},{"text":[{"text":"Fact sources:","bold":true},{"text":" provide "},{"text":"facts on a wide range of current issues","bold":true},{"text":": "},{"text":"directories","bold":true},{"text":" (Nigeria Yellow Pages, Directory of African Universities), "},{"text":"handbooks","bold":true},{"text":" (Guinness World Records, Handbook of Statistical Tables), "},{"text":"yearbooks","bold":true},{"text":" (Europa World Yearbook, Africa South of the Sahara) and "},{"text":"almanacs","bold":true},{"text":". Housed at the "},{"text":"reference section","bold":true},{"text":". Yearbooks are also called "},{"text":"annuals","bold":true},{"text":"."}]},{"text":[{"text":"Biographical sources:","bold":true},{"text":" information on "},{"text":"individuals","bold":true},{"text":": date of birth, place of birth, education, career achievements ("},{"text":"all of these","bold":true},{"text":"). "},{"text":"2 categories:","bold":true},{"text":" "},{"text":"universal and current","bold":true},{"text":" (International Who's Who, Webster's Bio$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 59, $study_guide$graphical Dictionary, Who's Who) and "},{"text":"national and local","bold":true},{"text":" (Africa Who's Who, Newswatch Who's Who). Reference section, some in the Gandhi Library."}]},{"text":[{"text":"Bibliographical sources:","bold":true},{"text":" "},{"text":"lists","bold":true},{"text":" of articles in periodicals, books, conference proceedings, technical reports, theses and dissertations on a "},{"text":"subject","bold":true},{"text":" or by a "},{"text":"given author","bold":true},{"text":"; give quick access to knowledge in the shortest time. "},{"text":"National bibliography","bold":true},{"text":" (National Bibliography of Nigeria, British National Bibliography); "},{"text":"trade","bold":true},{"text":" (The Bookseller, Publishers' Trade List Annual); "},{"text":"subject","bold":true},{"text":" (Economic Development in Nigeria, Bibliographic Guide to Technology). Reference section; old ones in Gandhi."}]},{"text":[{"text":"Index:","bold":true},{"text":" a "},{"text":"directional aid","bold":true},{"text":" (indicator or pointer) to already published materials in "},{"text":"serial form","bold":true},{"text":" within a period; a systematic guide to the contents of a book or text; arranged alphabetically by author, title and subject; published as part of a book or separately. "},{"text":"4 types:","bold":true},{"text":" "},{"text":"book indexes","bold":true},{"text":", "},{"text":"index to collections","bold":true},{"text":" (Anthology of Shakespeare Plays), "},{"text":"periodical index","bold":true},{"text":" (Agricultural Index, British Education Index), "},{"text":"newspaper index","bold":true},{"text":"."}]},{"text":[{"text":"Abstracts:","bold":true},{"text":" a "},{"text":"summary","bold":true},{"text":" of a publication or article with enough bibliographical detail to trace the original; brings quick information to users who may not have access to the original. "},{"text":"3 types:","bold":true},{"text":" "},{"text":"indicative, informative, evaluative","bold":true},{"text":". Examples: Abstracts of English Studies, Nigerian Universities Dissertation Abstracts, Science Abstracts, Chemical Abstracts. Old ones (CAB) in Gandhi; recent ones at the reference section."}]},{"text":[{"text":"Geographical sources:","bold":true},{"text":" information on "},{"text":"places","bold":true},{"text":" (towns, cities, states, countries) and "},{"text":"physical features","bold":true},{"text":" (mountains, valleys, rivers): "},{"text":"maps","bold":true},{"text":" (Map of Nigeria), "},{"text":"atlases","bold":true},{"text":" (The Times Atlas of the World), "},{"text":"gazetteers","bold":true},{"text":" (Federal Republic of Nigeria Gazette) and "},{"text":"travel guides","bold":true},{"text":". Old ones in Gandhi; recent at the reference section."}]},{"text":[{"text":"Manuals:","bold":true},{"text":" "},{"text":"instructions on how to do things","bold":true},{"text":" (\"how to do\", \"how to perform\", \"make\"). Example: product manuals."}]},{"text":[{"text":"Books of quotation:","bold":true},{"text":" quotations on sets of subjects by certain authors, found through their indexes; consulted mostly by "},{"text":"speech makers and writers","bold":true},{"text":". Example: Home Book of Quotations."}]},{"text":[{"text":"Handbooks:","bold":true},{"text":" a "},{"text":"small ready reference source","bold":true},{"text":" that provides facts and information on places, techniques, institutions, subjects; used much like a manual. Examples: "},{"text":"Faculty and Departmental Handbooks","bold":true},{"text":" (True: a faculty handbook is a small ready reference source)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pairs the exam swaps:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fact sources","bold":true},{"text":" give facts on current issues; "},{"text":"biographical sources","bold":true},{"text":" give facts about "},{"text":"individuals","bold":true},{"text":"."}]},{"text":[{"text":"Bibliographical sources","bold":true},{"text":" list publications on a subject or by an author; an "},{"text":"index","bold":true},{"text":" points you to where items appear in serials or a book."}]},{"text":[{"text":"Bibliographical","bold":true},{"text":" (about publications) is not "},{"text":"biographical","bold":true},{"text":" (about people)."}]},{"text":[{"text":"Geographical sources","bold":true},{"text":" are the answer for \"places and physical features\" and for \"Map of Nigeria and travel guide\"; \"reference source\" is too general there."}]}]}]},{"text":[{"text":"\"The encyclopaedia is ...\" Choose "},{"text":"a book or set of books on one or all branches of knowledge","bold":true},{"text":", not \"on Britain\", \"on America\" or \"compiled by Chambers\"; those are only titles or publishers."}]},{"text":[{"text":"\"Reference materials include all EXCEPT\": "},{"text":"journals","bold":true},{"text":" (serials). \"Notable reference collection includes all EXCEPT\": "},{"text":"books","bold":true},{"text":"."}]},{"text":[{"text":"Handbooks appear twice: as a type of "},{"text":"fact source","bold":true},{"text":" and as a reference collection on their own. Both are correct. \"Encyclopedia\" and \"encyclopaedia\" are the same word."}]}]}]},{"number":"12.6","title":"Non-print and audio-visual resources","mustKnow":[{"type":"paragraph","text":[{"text":"B. Non-print resources","bold":true},{"text":" (soft copies, accessed electronically on computers, laptops and phones):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic books, electronic journals, electronic images, electronic texts/records","bold":true},{"text":" (full text from the internet), "},{"text":"servers","bold":true},{"text":" (library software), "},{"text":"CD-ROMs","bold":true},{"text":", floppy and flash disks, hard disks. The main electronic materials in most libraries are "},{"text":"e-books and e-periodicals","bold":true},{"text":"."}]},{"text":[{"text":"No$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 60, $study_guide$n-print resources allow "},{"text":"multiple usage","bold":true},{"text":" of a material "},{"text":"at the same time","bold":true},{"text":" (a print book serves one person at a time)."}]},{"text":[{"text":"Managed by the "},{"text":"Automation Section","bold":true},{"text":", on the "},{"text":"third floor","bold":true},{"text":". Enquiries on how to access any resource go to the "},{"text":"Readers' Services","bold":true},{"text":" point."}]},{"text":[{"text":"Access area: the "},{"text":"E-Library","bold":true},{"text":": "},{"text":"two classrooms on the third floor","bold":true},{"text":" (undergraduate and postgraduate) plus the "},{"text":"MTN Connect Library","bold":true},{"text":" at the "},{"text":"Akintunde Ojo building","bold":true},{"text":". The library provides "},{"text":"wireless access","bold":true},{"text":", so you may use your own devices in other approved areas. E-resources cover all programmes of the university and beyond."}]},{"text":[{"text":"Remote access","bold":true},{"text":" to the library's online resources is through the "},{"text":"UNILAG Library website","bold":true},{"text":" (not a matric number, telephone directory or hall of residence)."}]}]},{"type":"paragraph","text":[{"text":"C. Audio-visual resources:","bold":true},{"text":" aids that make learning as real as possible, giving first-hand knowledge through "},{"text":"hearing and seeing","bold":true},{"text":". "},{"text":"3 groups:","bold":true}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Materials"}],[{"text":"Where"}]],"rows":[[[{"text":"Audio aids","bold":true}],[{"text":"Radio, tape-recorder, gramophone, audio cassette player"}],[{"text":"Music Library","bold":true}]],[[{"text":"Visual aids","bold":true}],[{"text":"Maps, pictures, textbooks, slide projector, transparencies, print materials"}],[{"text":"Research and Bibliographic Department and Automation Section"}]],[[{"text":"Audio-visual aids","bold":true}],[{"text":"LCD projector, "},{"text":"television","bold":true},{"text":", computers, VCD player, multimedia, artefacts"}],[{"text":"Various sections and the "},{"text":"Museum","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Print versus non-print:","bold":true},{"text":" print is hard copy on the shelves; non-print is soft copy (e-books, e-journals) accessed only on electronic devices and usable by many at once."}]},{"text":[{"text":"Trap: radio, tape-recorder, gramophone and cassette player are "},{"text":"audio","bold":true},{"text":" materials (sound only), not audio-visual and not simply \"electronic\". "},{"text":"Television","bold":true},{"text":" is the standard example of an "},{"text":"audio-visual","bold":true},{"text":" material. Electronic journals, electronic images, library software and CD-ROMs are "},{"text":"non-print","bold":true},{"text":", not audio-visual."}]},{"text":[{"text":"The "},{"text":"MTN Connect Library","bold":true},{"text":" is an e-library area; fact sources are at the "},{"text":"reference section","bold":true},{"text":"."}]},{"text":[{"text":"If a friend cannot find a book: use the "},{"text":"library catalogue","bold":true},{"text":" (card catalogue or OPAC) or ask the officer at the "},{"text":"circulation desk","bold":true},{"text":" or any library staff."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Library: 5 types (public, academic, special, school, private); 5 functions (selection, acquisition, organisation, preservation, dissemination)."}]},{"text":[{"text":"Data = facts; information = processed data; information literacy = locate, retrieve, evaluate, apply, and recognise when information is needed."}]},{"text":[{"text":"5 characteristics: availability/accessibility, accuracy, reliability, timeliness, relevance. Late information is irrelevant."}]},{"text":[{"text":"6 forms: oral, textual, numeric, bibliographic, graphical, multimedia. 2 sources: primary (first-hand; thesis) and secondary (analyses/explains; textbook, encyclopaedia)."}]},{"text":[{"text":"UNILAG Library: print, non-print, audio-visual. Print collections: Africana, Reference, Reserved, Serials, Recent accessions."}]},{"text":[{"text":"Africana = Gandhi Library, basement, closed access, researchers and postgraduates, not loanable, newspapers from 1930, PhD theses."}]},{"text":[{"text":"Reference = facts not opinions, not read cover to cover, not borrowable. Reserved = closed access, no long loan, rapid wider circulation of scarce materials."}]},{"text":[{"text":"Serials = successive parts, regular intervals, indefinitely; journals carry recent original research."}]},{"text":[{"text":"11 reference types: dictionaries (general, specialised, subject), encyclopaedias, fact sources (yearbooks = annuals), biographical, bibliographical, index, abstracts, geographical, manuals, books of quotation, handbooks."}]},{"text":[{"text":"Non-print = Automation Section, E-Library, multiple usage, remote access via library website; audio (Music Library), audio-visual (television)."}]}]}],"theory":{"itemId":"0b59eb48-441b-5264-be58-705b94b87e1e","question":[{"type":"paragraph","text":[{"text":"Highlight five characteristics of good information."}]}]},"practice":[{"topic":"Understanding the Library and Information Resources","named":false}]}},{"kind":"note","itemId":"e874aa7f-8187-5387-924a-f9b3eff80a0a","sourceKey":"guide-topic:13","position":13,"payload":{"title":"Information Retrieval Tools","body":"The tools that locate information (library catalogue and OPAC, indexes, abstracts, bibliographies); how to search the OPAC by title, author, subject and keyword; the Library of Congress classes A to Z and the NLM scheme; the internet and its domain types; library databases; the five criteria for evaluating an information resource.","noteType":"guide_topic","number":13,"mustKnow":[{"text":"The tools that locate information (library catalogue and OPAC, indexes, abstracts, bibliographies); how to search the OPAC by title,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 61, $study_guide$ author, subject and keyword; the Library of Congress classes A to Z and the NLM scheme; the internet and its domain types; library databases; the five criteria for evaluating an information resource."}],"lessons":[{"number":"13.1","title":"The library catalogue","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Information retrieval tools:","bold":true},{"text":" the tools or aids used to access information. They act as a guide to library resources. The three main ones are the "},{"text":"library catalogue","bold":true},{"text":", "},{"text":"indexes and abstracts","bold":true},{"text":", and the "},{"text":"bibliography","bold":true},{"text":"."}]},{"text":[{"text":"Library catalogue:","bold":true},{"text":" the "},{"text":"index","bold":true},{"text":" and essential tool for retrieving library resources. It gives access to "},{"text":"all","bold":true},{"text":" items the library holds, physical and digital: books, e-books, audiovisual materials, reference materials, reserve materials and databases. A library's entire holding is recorded in it."}]},{"text":[{"text":"2 formats of the catalogue:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Manual catalogue","bold":true},{"text":" (catalogue cards): arranged by "},{"text":"author, title and subject","bold":true},{"text":". Entries are filed in "},{"text":"alphabetical","bold":true},{"text":" order."}]},{"text":[{"text":"Online Public Access Catalogue (OPAC):","bold":true},{"text":" the electronic catalogue on the library website. Searched by "},{"text":"title, author, series and keywords","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"UNILAG's two public catalogue cabinets:","bold":true},{"text":" the "},{"text":"Author/Title","bold":true},{"text":" cabinet and the "},{"text":"Subject","bold":true},{"text":" cabinet."}]},{"text":[{"text":"Catalogues for official use only:","bold":true},{"text":" the "},{"text":"Shelf-list","bold":true},{"text":" and the "},{"text":"Authority","bold":true},{"text":" catalogue."}]},{"text":[{"text":"Call number","bold":true},{"text":" (call mark): the number generated when a material is catalogued. It tells you where the item sits on the shelf."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The internet is not always the best or first place to look; the catalogue shows what your own library has and where it is."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the manual card catalogue has author cards, title cards and subject cards. An \"index card\" is "},{"text":"not","bold":true},{"text":" a type of catalogue card."}]},{"text":[{"text":"Trap:","bold":true},{"text":" you can search the catalogue by author, title, subject (and in the OPAC, series and keyword). "},{"text":"Language","bold":true},{"text":" is not a search option."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the catalogue is a "},{"text":"locating tool","bold":true},{"text":"; it does not arrange books on the shelves. Shelf arrangement is the job of the "},{"text":"classification scheme","bold":true},{"text":" (Lesson 13.3)."}]},{"text":[{"text":"OPAC means Online "},{"text":"Public","bold":true},{"text":" Access Catalogue, not \"primary\" or \"private\". It is open to all library users."}]}]}]},{"number":"13.2","title":"Searching the OPAC","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The OPAC has a "},{"text":"Basic Search","bold":true},{"text":" and an "},{"text":"Advanced Search","bold":true},{"text":" platform."}]},{"text":[{"text":"Search by title:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"In the drop-down menu, select "},{"text":"\"Title Keyword\"","bold":true},{"text":"."}]},{"text":[{"text":"Type the title of the book in the next box."}]},{"text":[{"text":"A results page lists the items matching your terms; select your desired title."}]},{"text":[{"text":"Click the title to see its "},{"text":"full record","bold":true},{"text":" (bibliographic details), which also shows where the book is."}]},{"text":[{"text":"Check the "},{"text":"call number","bold":true},{"text":" to know the location."}]},{"text":[{"text":"Go to the shelf to retrieve the material."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Search by author:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Select "},{"text":"\"Author Keyword\"","bold":true},{"text":" or "},{"text":"\"Author (last name first)\"","bold":true},{"text":"."}]},{"text":[{"text":"Type the name as "},{"text":"LAST NAME, FIRST NAME","bold":true},{"text":" if you chose \"Author (last name first)\". If you do not know the first name, leave it out or type the first initial."}]},{"text":[{"text":"Choose your author from the list of authors displayed."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Search by subject:","bold":true},{"text":" type the subject area in the space provided; a list of subjects is displayed. Subject searching lets you "},{"text":"browse for items by subject","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Choosing the access point: if you do not know the author, use the "},{"text":"title keyword","bold":true},{"text":" when you know the title; if you know neither, use the "},{"text":"subject keyword","bold":true},{"text":". Repeat the process with any other search term you have."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Clause heading\" and \"phrase heading\" are not search types. The real access points are title, author, subject, series and keyword."}]}]}]},{"number":"13.3","title":"Classification: Library of Congress and NLM","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classification scheme:","bold":true},{"text":" the system used to classify and arrange library books on the shelves. Shelf arrangement is done wi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 62, $study_guide$th a classification scheme, not with the catalogue."}]},{"text":[{"text":"UNILAG Main Library","bold":true},{"text":" uses the "},{"text":"Library of Congress (LC) Classification Scheme","bold":true},{"text":". The "},{"text":"College of Medicine Library, Idi-Araba","bold":true},{"text":", uses the "},{"text":"National Library of Medicine (NLM) Classification Scheme","bold":true},{"text":"."}]},{"text":[{"text":"Mixed notation:","bold":true},{"text":" the use of "},{"text":"letters of the alphabet as well as Arabic numerals","bold":true},{"text":". Also called "},{"text":"alpha-numeric","bold":true},{"text":". The LC scheme has a mixed notation."}]},{"text":[{"text":"LC main classes use the letters "},{"text":"A to Z","bold":true},{"text":". The letters "},{"text":"O, X and Y","bold":true},{"text":" are reserved for future expansion, so there is no Class O."}]}]},{"type":"table","header":[[{"text":"Letter"}],[{"text":"Subject"}]],"rows":[[[{"text":"A"}],[{"text":"General works"}]],[[{"text":"B"}],[{"text":"Philosophy"}]],[[{"text":"C"}],[{"text":"History"}]],[[{"text":"D"}],[{"text":"History and topography"}]],[[{"text":"E"}],[{"text":"United States (history)"}]],[[{"text":"F"}],[{"text":"United States (local)"}]],[[{"text":"G"}],[{"text":"Geography, Anthropology"}]],[[{"text":"H"}],[{"text":"Social science"}]],[[{"text":"J"}],[{"text":"Political science"}]],[[{"text":"K"}],[{"text":"Law"}]],[[{"text":"L"}],[{"text":"Education"}]],[[{"text":"M"}],[{"text":"Music"}]],[[{"text":"N"}],[{"text":"Fine art"}]],[[{"text":"P"}],[{"text":"Language and linguistics"}]],[[{"text":"Q"}],[{"text":"Science"}]],[[{"text":"R"}],[{"text":"Medicine"}]],[[{"text":"S"}],[{"text":"Agriculture"}]],[[{"text":"T"}],[{"text":"Technology"}]],[[{"text":"U"}],[{"text":"Military science"}]],[[{"text":"V"}],[{"text":"Natural science"}]],[[{"text":"Z"}],[{"text":"Bibliography"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Main classes are "},{"text":"sub-divided with two capital letters","bold":true},{"text":". Examples:"}]}]},{"type":"table","header":[[{"text":"Class Q: Science"}],[{"text":"Class H: Social science"}]],"rows":[[[{"text":"QA Mathematics"}],[{"text":"HA Statistics"}]],[[{"text":"QB Astronomy"}],[{"text":"HB Economic theory, Demography"}]],[[{"text":"QC Physics"}],[{"text":"HC Economic history and conditions"}]],[[{"text":"QD Chemistry"}],[{"text":"HD Economic history and conditions / Production"}]],[[{"text":"QE Geology"}],[{"text":"HE Transportation and communication"}]],[[{"text":"QH Natural history"}],[{"text":"HF Commerce"}]],[[{"text":"QK Botany"}],[{"text":"HG Finance"}]],[[{"text":"QL Zoology"}],[{"text":"HJ Public finance"}]],[[{"text":"QM Human anatomy"}],[{"text":"HM Sociology (General)"}]],[[{"text":"QP Physiology"}],[{"text":"HN Social history, conditions, problems and reform"}]],[[{"text":"QR Microbiology"}],[{"text":"HQ The family, Marriage"}]],[[],[{"text":"HS Societies / Secret societies"}]],[[],[{"text":"HT Communities, Classes, Races"}]],[[],[{"text":"HV Social pathology, Welfare and Criminology"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Dewey Decimal Classification (DDC):","bold":true},{"text":" a different scheme that divides knowledge into ten main classes numbered "},{"text":"000 to 999","bold":true},{"text":". UNILAG does "},{"text":"not","bold":true},{"text":" use it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exam favourites: Law = "},{"text":"K","bold":true},{"text":"; Language = "},{"text":"P","bold":true},{"text":"; Technology = "},{"text":"T","bold":true},{"text":"; Science = "},{"text":"Q","bold":true},{"text":"; Medicine = "},{"text":"R","bold":true},{"text":"; Fine art = "},{"text":"N","bold":true},{"text":"; Music = "},{"text":"M","bold":true},{"text":"; Social science = "},{"text":"H","bold":true},{"text":"; Agriculture = "},{"text":"S","bold":true},{"text":"; Geography = "},{"text":"G","bold":true},{"text":"; Education = "},{"text":"L","bold":true},{"text":"; General works = "},{"text":"A","bold":true},{"text":". \"Law and languages\" in that order = "},{"text":"K and P","bold":true},{"text":"."}]},{"text":[{"text":"Sociology books sit at shelf "},{"text":"HM","bold":true},{"text":" (Sociology, General). HC is Economic history, TA is under Technology, NA is under Fine art."}]},{"text":[{"text":"A call number mixes letters and Arabic numerals (e.g. HM followed by numbers); that is the mixed, alpha-numeric notation. Roman numerals are "},{"text":"not","bold":true},{"text":" used."}]},{"text":[{"text":"NLM scheme:","bold":true},{"text":" covers Medicine and related sciences. It uses the LC schedules as a supplement for subjects bordering on medicine and for general reference material. Because they overlap with NLM, the LC schedules "},{"text":"QM (Human anatomy), QR (Microbiology) and R (Medicine)","bold":true},{"text":" are "},{"text":"not used at all","bold":true},{"text":" by the NLM."}]},{"text":[{"text":"NLM structure (QS to QZ are preclinical sciences; W classes are the health professions and clinical medicine):"}]}]},{"type":"table","header":[[{"text":"Preclinical sciences"}],[{"text":"Medicine and related subjects"}]],"rows":[[[{"text":"QS Human anatomy"}],[{"text":"W Health professions"}]],[[{"text":"QT Physiology"}],[{"text":"WA Public health"}]],[[{"text":"QU Biochemistry"}],[{"text":"WB Practice of medicine"}]],[[{"text":"QV Pharmacology"}],[{"text":"WC Communicable diseases"}]],[[{"text":"QW Microbiology and Immunology"}],[{"text":"WD 100 Nutrition disorders; WD 200 Metabolic diseases; WD 300 Immunologic diseases; WD 400 Animal poisons; WD 500 Plant poisons; WD 600 Injuries caused by physical agents; WD 700 Aviation and space medicine"}]],[[{"text":"QX Parasitology"}],[{"text":"WE Musculoskeletal system"}]],[[{"text":"QY Clinical pathology"}],[{"text":"WF Respiratory system"}]],[[{"text":"QZ Pathology"}],[{"text":"WG Cardiovascular system"}]],[[],[{"text":"WH Hemic and lymphatic system"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 63, $study_guide$}]],[[],[{"text":"WI Digestive system"}]],[[],[{"text":"WJ Urogenital system"}]],[[],[{"text":"WK Endocrine system"}]],[[],[{"text":"WL Nervous system"}]],[[],[{"text":"WM Psychiatry"}]],[[],[{"text":"WN Radiology"}]],[[],[{"text":"WO Surgery"}]],[[],[{"text":"WP Gynaecology"}]],[[],[{"text":"WQ Obstetrics"}]],[[],[{"text":"WR Dermatology"}]],[[],[{"text":"WS Paediatrics"}]],[[],[{"text":"WT Geriatrics"}]],[[],[{"text":"WU Dentistry, Oral surgery"}]],[[],[{"text":"WV Otolaryngology"}]],[[],[{"text":"WW Ophthalmology"}]],[[],[{"text":"WX Hospitals and health facilities"}]],[[],[{"text":"WY Nursing"}]],[[],[{"text":"WZ History of medicine"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Questions to ask while searching the catalogue:","bold":true},{"text":" how many titles does the library have on your topic? What do the titles, dates and authors tell you? Are there subheadings? Are there cross-references or alternative headings? Will the library support your topic, or will you need "},{"text":"interlibrary loan","bold":true},{"text":"?"}]},{"text":[{"text":"Cross-references:","bold":true},{"text":" terms, names or subjects that lead you from the known to the unknown (and the reverse) in the catalogue."}]},{"text":[{"text":"Interlibrary loan:","bold":true},{"text":" students have no reciprocal borrowing privileges at all Nigerian universities, but UNILAG library can borrow materials from any university library in Nigeria for you. It can take a week or longer, so start early."}]}]}]},{"number":"13.4","title":"Indexes, abstracts and bibliographies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Indexes and abstracts:","bold":true},{"text":" bibliographic information sources that help users find information quickly and efficiently. They are also called "},{"text":"bridges to published information","bold":true},{"text":"."}]},{"text":[{"text":"Index:","bold":true},{"text":" an "},{"text":"indicator or pointer","bold":true},{"text":" to required information. It gives a systematic guide to the contents of a text or series of texts: names, places, titles, keywords and titles of publications. An index may be published at the "},{"text":"back of a book","bold":true},{"text":" or as a "},{"text":"separate publication","bold":true},{"text":". It does "},{"text":"not","bold":true},{"text":" give the full text."}]},{"text":[{"text":"4 uses of an index:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Serves as a gateway to the information material."}]},{"text":[{"text":"Gives the basic information."}]},{"text":[{"text":"Provides only the entry points to users during their search for information."}]},{"text":[{"text":"Can list all the sources cited within a text or article."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Examples of indexes:","bold":true},{"text":" Newspaper Index, Engineering Index, Index Medicus. "},{"text":"Types of index:","bold":true},{"text":" book index, index to collections, periodical index, newspaper index."}]},{"text":[{"text":"Abstract:","bold":true},{"text":" a "},{"text":"brief summary","bold":true},{"text":" of the contents of a book, research article, thesis, speech or conference proceedings. "},{"text":"3 uses:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provides a description or summary of the content of the article."}]},{"text":[{"text":"Serves as a real "},{"text":"surrogate","bold":true},{"text":" (stand-in) of the document."}]},{"text":[{"text":"Lets a user know the content of the document without reading it from beginning to end."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Examples of abstracts:","bold":true},{"text":" Chemical Abstracts, Dissertation Abstracts, Library and Information Science Abstracts, Social Science Abstracts. "},{"text":"3 types of abstract:","bold":true},{"text":" "},{"text":"indicative","bold":true},{"text":", "},{"text":"informative","bold":true},{"text":" and "},{"text":"evaluative","bold":true},{"text":"."}]},{"text":[{"text":"Bibliography:","bold":true},{"text":" a "},{"text":"list of books or written sources of information on a subject","bold":true},{"text":", usually consulted in preparing a piece of work and referred to in the text. Examples in the University Library: "},{"text":"National Bibliography of Nigeria (NBN)","bold":true},{"text":" and "},{"text":"British National Bibliography (BNB)","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Index versus abstract: an index only "},{"text":"points","bold":true},{"text":" to where information is; an abstract "},{"text":"summarises","bold":true},{"text":" what the document says. Both are now mainly online; abstracts are usually collected, organised systematically and indexed."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"An index serves as a ______ to required information\": the full answer is "},{"text":"pointer and indicator","bold":true},{"text":", not one alone."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Review abstract\" is not a type of abstract. The three types are indicative, informative and evaluative."}]},{"text":[{"text":"Bibliography definitions you may see, all correct: a list of written sources on a subject; a list of books and articles someone used when writing on a subject; a list of books, magazines and articles about a particular subject. If all three appear together, the answer is \"all of the above\"."}]}]}]},{"number":"13.5","title":"The internet and library databases","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internet:","bold":true},{"text":" has a wealth of knowledge for anyone with access, but "},{"text":"anyone with access can place false information","bold":true},{"text":" on it. There are "},{"text":"no guidelines","bold":true},{"text":" on the general web for accuracy. So information from the internet "},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 64, $study_guide$:"cannot","bold":true},{"text":" be assumed accurate; it must be evaluated."}]},{"text":[{"text":"4 domain types:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":".com:","bold":true},{"text":" originally commercial, but can be used for anything as long as it is paid for."}]},{"text":[{"text":".edu:","bold":true},{"text":" used "},{"text":"only by accredited post-secondary institutions","bold":true},{"text":" (institutions of higher learning)."}]},{"text":[{"text":".gov and .us:","bold":true},{"text":" owned by the United States Government."}]},{"text":[{"text":".org:","bold":true},{"text":" owned by an organisation, but it does not matter "},{"text":"what type","bold":true},{"text":" of organisation."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Library databases:","bold":true},{"text":" collections of e-books, journals, newspapers and magazines, available anywhere with an internet connection and a login. They make searching for "},{"text":"peer-reviewed","bold":true},{"text":" articles easy. Examples of interfaces: "},{"text":"EBSCO, Science Direct, LexisNexis, JSTOR","bold":true},{"text":"."}]},{"text":[{"text":"Major benefit:","bold":true},{"text":" they are designed by proprietary publishers or aggregators and "},{"text":"subscribed to by the library to support student assignments and topics","bold":true},{"text":". They are more organised than Google results and easier to document and cite."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The Martin Luther King example: Google returns Wikipedia (anyone can edit it, so not reliable), the Nobel Peace Prize site (generally reliable) and www.martinlutherking.org, which is hosted by Stormfront, a white-supremacist organisation. A .org address proves nothing about reliability."}]},{"text":[{"text":"Access at UNILAG:","bold":true},{"text":" databases are reached through the library website when you are within the university "},{"text":"IP range","bold":true},{"text":"; some fee-based databases need a "},{"text":"password","bold":true},{"text":" for remote access."}]},{"text":[{"text":"Match subject coverage:","bold":true},{"text":" most disciplines have their own databases; others are "},{"text":"interdisciplinary","bold":true},{"text":". "},{"text":"EBSCO Host and JSTOR","bold":true},{"text":" are interdisciplinary; "},{"text":"Westlaw, HeinOnline and LexisNexis","bold":true},{"text":" are for Law; "},{"text":"JaypeeDigital","bold":true},{"text":" is for Clinical and Biomedical Sciences."}]},{"text":[{"text":"Match time coverage:","bold":true},{"text":" some databases give full text for the most recent 15 to 20 years, some only the current year, some over 100 years back."}]},{"text":[{"text":"7 types of information in databases:","bold":true},{"text":" full-text periodical articles; full-text encyclopaedic or reference sources; full-text books or chapters (e-books); government or primary documents; images, audio or video clips; statistical information; citations and/or abstracts."}]},{"text":[{"text":"Update frequency:","bold":true},{"text":" newspaper databases update "},{"text":"daily","bold":true},{"text":"; an encyclopaedia database irregularly or yearly. The more current your need, the more frequent the update you want."}]},{"text":[{"text":"2 most frequent ways results are ranked:","bold":true},{"text":" "},{"text":"chronologically by date","bold":true},{"text":" (most recent first; "},{"text":"LIFO","bold":true},{"text":", Last In First Out) and by "},{"text":"relevancy","bold":true},{"text":". Relevancy ranking counts how often search terms appear, how close they are to each other and how prominent they are; a term in the "},{"text":"title","bold":true},{"text":" counts as more relevant than one in the body."}]},{"text":[{"text":"Read the "},{"text":"abstract","bold":true},{"text":" before the full article; it may show the article is not needed. Databases have "},{"text":"PRINT, EMAIL and SAVE","bold":true},{"text":" buttons; still keep a back-up on a storage device."}]}]}]},{"number":"13.6","title":"Evaluating information resources","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Resources are evaluated to determine their "},{"text":"credibility and relevance","bold":true},{"text":" to your topic before you select them for research or an assignment."}]},{"text":[{"text":"5 criteria:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Currency:","bold":true},{"text":" publication date; how up to date the citations are; how current the information needs to be for your topic."}]},{"text":[{"text":"Relevancy:","bold":true},{"text":" does it relate directly to your topic or answer your question? Who is the audience (scholarly or general)? Is it primary or secondary? General background or in-depth?"}]},{"text":[{"text":"Authority:","bold":true},{"text":" who created it? Qualifications of the author, publisher or organisation; the author's education and experience; look for the author's biography or publisher information."}]},{"text":[{"text":"Accuracy:","bold":true},{"text":" is it supported by evidence? Can you verify it in another source? How extensive is the bibliography? Are there spelling, grammar or typographical errors?"}]},{"text":[{"text":"Purpose:","bold":true},{"text":" is it meant to inform, sell or persuade? Is it fair and balanced? Are there political, ideological, cultural, religious or personal biases? Is opinion or propaganda easy to recognise? Are there advertisements?"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"Size","bold":true},{"text":" is not a criterion. A long book is not more credible because it is big. Nor are \"intelligence\" or \"strategy\" criteria."}]},{"text":[{"text":"\"Currency, authority, ______ and ______\": the missing pair is "},{"text":"relevancy and accuracy","bold":true},{"text":".$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 65, $study_guide$"}]},{"text":[{"text":"Quick reliability test: is it accurate, well written and current? Does it cover the topic thoroughly, state its purpose and give supporting documentation? Apply the five criteria to print and non-print sources alike."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Information retrieval tools: library catalogue, indexes and abstracts, bibliography."}]},{"text":[{"text":"Catalogue formats: manual (cards; author, title, subject; alphabetical) and OPAC (title, author, series, keyword). Shelf-list and Authority catalogues are for official use."}]},{"text":[{"text":"OPAC search: Title Keyword or Author Keyword, then full record, then call number, then shelf."}]},{"text":[{"text":"UNILAG Main Library: Library of Congress scheme (mixed, alpha-numeric notation; A to Z; O, X, Y reserved). College of Medicine: NLM scheme."}]},{"text":[{"text":"K Law, P Language, T Technology, Q Science, R Medicine, H Social science, HM Sociology."}]},{"text":[{"text":"Dewey Decimal: 000 to 999; not used at UNILAG."}]},{"text":[{"text":"Index = pointer and indicator; abstract = brief summary (indicative, informative, evaluative); bibliography = list of written sources on a subject (NBN, BNB)."}]},{"text":[{"text":"Internet: anyone can post false information; .com, .edu (accredited post-secondary only), .gov/.us, .org."}]},{"text":[{"text":"Library databases are subscribed to by the library for student assignments; EBSCO and JSTOR are interdisciplinary."}]},{"text":[{"text":"Evaluate with currency, relevancy, authority, accuracy, purpose. Not size."}]}]}],"theory":{"itemId":"1554bfcd-b06b-56b2-9054-2ead2b884028","question":[{"type":"paragraph","text":[{"text":"List the three information retrieval tools in the library and explain how the University of Lagos Main Library classifies its materials."}]}]},"practice":[{"topic":"Information Retrieval Tools","named":false}]}},{"kind":"note","itemId":"83084064-8894-5e3b-9ebd-8691e527c2f5","sourceKey":"guide-topic:14","position":14,"payload":{"title":"Search Strategies","body":"What a search strategy is and its 3 basic steps; the 5 stages of an electronic search; simple, advanced and meta searches; the 6 search techniques (Boolean AND/OR/NOT, parenthesis, phrase, truncation, wildcards, field searching); keyword vs subject searching; search engines and Google Scholar; how to narrow or broaden a search, save sources and choose quotations.","noteType":"guide_topic","number":14,"mustKnow":[{"text":"What a search strategy is and its 3 basic steps; the 5 stages of an electronic search; simple, advanced and meta searches; the 6 search techniques (Boolean AND/OR/NOT, parenthesis, phrase, truncation, wildcards, field searching); keyword vs subject searching; search engines and Google Scholar; how to narrow or broaden a search, save sources and choose quotations."}],"lessons":[{"number":"14.1","title":"What a search strategy is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search strategy:","bold":true},{"text":" the art of planning and conducting searches for the most efficient result. Its whole essence is to conceptualise a research topic and access the right information resources needed for a project, so you can navigate your way to the end of the project."}]},{"text":[{"text":"Effective use of library resources requires a search strategy.","bold":true},{"text":" It is the process employed to achieve effective search results."}]},{"text":[{"text":"A research exercise must be driven by a subject matter or topic.","bold":true}]}]},{"type":"paragraph","text":[{"text":"3 basic steps","bold":true},{"text":" in a search strategy, in order:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identification of the subject matter/topic.","bold":true}]},{"text":[{"text":"General knowledge/overview of the subject matter/topic:","bold":true},{"text":" attempt a definition of the topic to get the right conceptualisation or scope. Use a "},{"text":"general encyclopedia","bold":true},{"text":" (Encyclopedia Britannica, Encyclopedia Americana), or sometimes a specialised reference source. Overviews give insight into the historical development or antecedents of the area."}]},{"text":[{"text":"Narrower overview:","bold":true},{"text":" move from the general concept to a narrower scope focused on specific areas of research and variables. Resources: "},{"text":"abstracts, indexes, bibliographies","bold":true},{"text":" (pointers or bridges to specific resources through their full bibliographic details), plus the "},{"text":"card catalogue","bold":true},{"text":" or "},{"text":"online catalogue","bold":true},{"text":" for specific titles or subjects."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic search strategy:","bold":true},{"text":" a structured organisation of terms used to search a database; it shows how search terms combine to retrieve the best results. "},{"text":"Relevant","bold":true},{"text":" results are on target or very close to the information sought."}]},{"text":[{"text":"A complex search statement is refined by adding "},{"text":"Boolean operators, quotation marks","bold":true},{"text":" (exact phrases), "},{"text":"truncation symbols","bold":true},{"text":" or "},{"text":"field search limiters","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The 5 stages of effective electronic searching","bold":true},{"text":" (do not rush to the first search box):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Define your information need."}]},{"text":[{"text":"Decide which resource/s to use (both e-resources and search engines)."}]},{"text":[{"text":"Find out what search options your chosen resource offers."}]},{"text":[{"text":"Run your search."}]},{"text":[{"text":"Review and refine your search."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The 3 steps apply to both print and electronic resources. The $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 66, $study_guide$physical library can be explored with the library guide and professional guidance; electronic resources demand "},{"text":"extra skills","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the 3 steps go from "},{"text":"general to narrow","bold":true},{"text":". Encyclopedias belong to step 2; abstracts, indexes and bibliographies to step 3."}]},{"text":[{"text":"Trap: \"effective use of library resources requires...\" "},{"text":"search strategies","bold":true},{"text":", not punctuality, smartness or maturity."}]},{"text":[{"text":"Keep the counts apart: "},{"text":"3 basic steps","bold":true},{"text":" of a search strategy; "},{"text":"5 stages","bold":true},{"text":" of an electronic search."}]}]}]},{"number":"14.2","title":"Types of searches","mustKnow":[{"type":"paragraph","text":[{"text":"To search is to carefully look for something; effective searching requires planning. There are "},{"text":"3 types of searches","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Simple search:","bold":true},{"text":" the user uses some "},{"text":"keywords","bold":true},{"text":" to perform a "},{"text":"quick information search","bold":true},{"text":" from a database or a search engine. It may retrieve a "},{"text":"huge amount of output","bold":true},{"text":" that takes time to sieve through. It is browsing rather than focused searching; one or two concepts may be used. Use it when you are "},{"text":"not sure of the type of information required","bold":true},{"text":" and when the topic is "},{"text":"not focused on any area","bold":true},{"text":"."}]},{"text":[{"text":"Advanced search:","bold":true},{"text":" the use of techniques that help to "},{"text":"define","bold":true},{"text":" the information being searched. "},{"text":"Filtering","bold":true},{"text":" is done to reduce the amount of items retrieved; filtering refines the search for relevancy. The user can apply "},{"text":"multiple search fields","bold":true},{"text":" to broaden or narrow the search. Available in most search tools such as "},{"text":"ScienceDirect, Ebrary, EbscoHost","bold":true},{"text":"."}]},{"text":[{"text":"Meta search:","bold":true},{"text":" the user uses a "},{"text":"variety of search tools simultaneously","bold":true},{"text":", through "},{"text":"meta search engines","bold":true},{"text":" such as "},{"text":"Dogpile, Search.com, Metacrawler and Vivisimo","bold":true},{"text":". These search many search tools (Google, Yahoo, MSN) at once."}]}]},{"type":"paragraph","text":[{"text":"3 things advanced searching helps you do:","bold":true},{"text":" apply filtering; reduce the number of items retrieved; apply multiple search fields."}]},{"type":"table","header":[[],[{"text":"Simple search"}],[{"text":"Advanced search"}],[{"text":"Meta search"}]],"rows":[[[{"text":"Advantage 1"}],[{"text":"Quick information search from a database or search engine"}],[{"text":"Allows filtering, so more relevant materials are retrieved"}],[{"text":"Uses a variety of search tools simultaneously"}]],[[{"text":"Advantage 2"}],[{"text":"Helpful when not sure of the type of information required"}],[{"text":"Reduces the number of items retrieved"}],[]],[[{"text":"Advantage 3"}],[{"text":"Useful when the topic is not focused on any area"}],[{"text":"Applies multiple search fields"}],[]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example of a simple search: "},{"text":"Malaria and Africa","bold":true},{"text":". It can cover any period, adults or children, male or female, any part of Africa, and may even retrieve information on Africa unrelated to malaria. The results are overwhelming, so the user must apply search techniques to focus them."}]},{"text":[{"text":"A meta search is conducted the same way as a search in a single engine; the "},{"text":"only difference","bold":true},{"text":" is that results come from several engines simultaneously."}]},{"text":[{"text":"Trap: \"retrieves a huge amount of information\" belongs to "},{"text":"simple","bold":true},{"text":" search, so it is the "},{"text":"exception","bold":true},{"text":" in any list of advanced-search advantages."}]},{"text":[{"text":"Trap: \"complex search\" and \"quick search\" are not recognised types. Multiple search fields = "},{"text":"advanced search","bold":true},{"text":"; many search tools at once = "},{"text":"meta search","bold":true},{"text":"; quick keyword search = "},{"text":"simple search","bold":true},{"text":"."}]},{"text":[{"text":"Advanced search lets you limit by fields such as "},{"text":"year of publication","bold":true},{"text":", language or author, not by size of book, number of pages or volume."}]}]}]},{"number":"14.3","title":"Search techniques","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search techniques:","bold":true},{"text":" ways of using search terms to find required information from search tools such as "},{"text":"OPAC (Online Public Access Catalogues), general search engines, search directories, portals and online databases (the deep web)","bold":true},{"text":"."}]},{"text":[{"text":"Choosing keywords:","bold":true},{"text":" identify the main concepts of your topic and build a list of keywords; this increases your search capacity (acid rain: \"wet deposition\", \"acid deposition\"). Do "},{"text":"not","bold":true},{"text":" type a complete sentence. Leave out minor words: articles (a, an, the) and prepositional or verb phrases. Stick to "},{"text":"nouns and noun phrases","bold":true},{"text":" that express the major concepts, and search for "},{"text":"synonyms","bold":true},{"text":" as alternative terms."}]},{"text":[{"text":"To find alternative keywords use a "},{"text":"thesaurus","bold":true},{"text":", the "},{"text":"Library of Congress Subject Headings","bold":true},{"text":", a "},{"text":"reference book","bold":true},{"text":" or "},{"text":"Internet subject directories","bold":true},{"text":". Write down all your $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 67, $study_guide$search terms so you know which worked."}]}]},{"type":"paragraph","text":[{"text":"The 6 search techniques:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Boolean searching","bold":true}]},{"text":[{"text":"Parenthesis","bold":true}]},{"text":[{"text":"Phrase searching","bold":true}]},{"text":[{"text":"Truncation","bold":true}]},{"text":[{"text":"Wildcards","bold":true}]},{"text":[{"text":"Field searching","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Boolean searching:","bold":true},{"text":" based on the symbolic logic of "},{"text":"George Boole","bold":true},{"text":", a 19th-century English mathematician. Keywords are combined with connecting terms called "},{"text":"Boolean operators","bold":true},{"text":"; the "},{"text":"3 basic operators are AND, OR, NOT","bold":true},{"text":". Boolean techniques "},{"text":"reduce irrelevant documents","bold":true},{"text":". "},{"text":"2 reasons for using them:","bold":true},{"text":" to focus a search when the topic has multiple search terms; to connect pieces of information exactly as you want them (Second creation (title) AND Wilmot and Campbell (author) AND 2000 (year))."}]}]},{"type":"table","header":[[{"text":"Operator"}],[{"text":"Effect"}],[{"text":"Tells the database"}],[{"text":"Example"}]],"rows":[[[{"text":"AND","bold":true}],[{"text":"Narrows","bold":true},{"text":" results"}],[{"text":"ALL","bold":true},{"text":" terms must be present"}],[{"text":"cloning AND humans AND ethics"}]],[[{"text":"OR","bold":true}],[{"text":"Broadens","bold":true},{"text":" results; connects similar concepts ("},{"text":"synonyms","bold":true},{"text":")"}],[{"text":"ANY","bold":true},{"text":" term may be present"}],[{"text":"cloning OR genetics OR reproduction"}]],[[{"text":"NOT","bold":true}],[{"text":"Excludes","bold":true},{"text":" words; narrows"}],[{"text":"Ignore concepts implied by your terms"}],[{"text":"cloning NOT sheep"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Parenthesis:","bold":true},{"text":" brackets specify the "},{"text":"order","bold":true},{"text":" of interpretation. Information inside brackets is read "},{"text":"first","bold":true},{"text":", then information outside. (vomit OR diarrhoea) AND blood; Malaria AND (prevention OR control). Without brackets, keywords are searched left to right."}]},{"text":[{"text":"Phrase searching:","bold":true},{"text":" surround keywords in "},{"text":"quotation marks","bold":true},{"text":" so the engine finds only words that appear "},{"text":"side by side","bold":true},{"text":" in that order. It narrows results significantly. \"capital gains tax\", \"physician assisted suicide\", \"human genome project\"."}]},{"text":[{"text":"Truncation:","bold":true},{"text":" using an "},{"text":"asterisk (*)","bold":true},{"text":" at the "},{"text":"root","bold":true},{"text":" of a word so the tool retrieves all word variations after it. Purpose: to "},{"text":"broaden","bold":true},{"text":" results. teen* retrieves teen, teens, teenager, teenagers, teenaged, teensy, teeny."}]},{"text":[{"text":"Wildcards:","bold":true},{"text":" characters that represent "},{"text":"one character or letter","bold":true},{"text":" in a word; useful when you are "},{"text":"not sure of the spelling","bold":true},{"text":" (American vs English spelling). Most common symbol: "},{"text":"?","bold":true},{"text":". An?mia retrieves anaemia and anemia; colo?r retrieves colour and color."}]},{"text":[{"text":"Field searching:","bold":true},{"text":" searching a "},{"text":"particular part of a computer record","bold":true},{"text":" (title, author's last name, date range, language; on the web, domain name, URL or file type). Use it to narrow very specifically: year of publication, language, affiliation, review articles, age, gender or abstract only."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discipline matters.","bold":true},{"text":" Information is organised into disciplines, and your topic's discipline shapes the research: one or more organisations may disseminate its information; there may be a standard terminology and a standard index; scholarly resources may be preferred over popular, primary over secondary, current over historical; and certain investigative methods may be preferred (laboratory experiments, simulations, field work, interviews, surveys, statistical analysis, tests and measurements, original thought and analysis)."}]},{"text":[{"text":"Keyword example: for a topic on university students who are heavy drinkers of alcohol and risk-taking behaviour, choose alcohol, alcoholic beverages, drinking, risk-taking behaviour, university students."}]},{"text":[{"text":"AND is implied","bold":true},{"text":" in many databases: Google turns \"college students test anxiety\" into college AND students AND test AND anxiety, so the words may appear separately. Fix this with phrases: \"college students\" AND \"test anxiety\"."}]},{"text":[{"text":"Search order:","bold":true},{"text":" databases usually treat "},{"text":"AND as the primary operator","bold":true},{"text":" and connect AND terms first. When mixing AND and OR, put the alternatives in brackets: (ethic* OR moral*) AND (bioengineering OR cloning)."}]},{"text":[{"text":"Truncation cautions: do not truncate a very short root (too many words, poor relevance). Some engines truncate automatically for plural, -ing or -ed endings; symbols vary; some tools do not support it."}]},{"text":[{"text":"Trap: "},{"text":"* = truncation","bold":true},{"text":" (any letters after a root, broadens); "},{"text":"? = wildcard","bold":true},{"text":" (one letter inside a word, spelling variants). \"The asterisk sign (*) is known as...\" "},{"text":"truncation","bold":true},{"text":", not wild card."}]},{"text":[{"text":"Trap: "},{"text":"filtering is not a search technique","bold":true},{"text":"; it is what advanced searching does."}]},{"text":[{"text":"Trap:$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 68, $study_guide$ OR "},{"text":"broadens","bold":true},{"text":"; AND and NOT "},{"text":"narrow","bold":true},{"text":" or limit. \"Develop\" and \"differentiate\" are not Boolean functions."}]}]}]},{"number":"14.4","title":"Keyword vs subject searching, search engines and Google Scholar","mustKnow":[{"type":"paragraph","text":[{"text":"Most databases offer two ways to search:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Subject searching:","bold":true},{"text":" browsing for items by "},{"text":"subject heading","bold":true},{"text":"; returns only results where the term appears in the "},{"text":"subject field","bold":true},{"text":"."}]},{"text":[{"text":"Keyword searching:","bold":true},{"text":" looks for documents containing "},{"text":"one or more words specified by the user","bold":true},{"text":", anywhere in the record."}]}]},{"type":"table","header":[[{"text":"Keyword searching"}],[{"text":"Subject searching"}]],"rows":[[[{"text":"Natural language words describing your topic; good to start with"}],[{"text":"Pre-defined "},{"text":"controlled vocabulary","bold":true},{"text":" used to describe each item's content"}]],[[{"text":"More flexible; terms combine in many ways"}],[{"text":"Less flexible; you must know the exact controlled vocabulary term"}]],[[{"text":"Database looks for keywords "},{"text":"anywhere","bold":true},{"text":" in the record, not necessarily connected"}],[{"text":"Database looks only in the "},{"text":"subject heading or descriptor field","bold":true},{"text":", where the most relevant words appear"}]],[[{"text":"May yield too many or too few results"}],[{"text":"If too many results, "},{"text":"subheadings","bold":true},{"text":" focus on one aspect of the broader subject"}]],[[{"text":"May yield many irrelevant results"}],[{"text":"Results usually very relevant to the topic"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Search engines:","bold":true},{"text":" huge databases of Internet files collected by a computer program called a "},{"text":"crawler, robot or spider","bold":true},{"text":". They have "},{"text":"no policies for selection of content","bold":true},{"text":" or evaluation, so results may not be what you expect. They use web browsers (e.g. Internet Explorer) to query the databases, index files into terms such as title, author and URL, and search mostly by "},{"text":"keywords","bold":true},{"text":". Example: "},{"text":"Google","bold":true},{"text":"."}]},{"text":[{"text":"3 times to use a search engine:","bold":true},{"text":" for general information; when a topic has many facets; for current information."}]},{"text":[{"text":"Google Scholar:","bold":true},{"text":" a useful search tool for "},{"text":"academic information","bold":true},{"text":". It holds scholarly material: "},{"text":"books, patents, journal articles and conference papers","bold":true},{"text":", and links to the full text of articles and to related or similar articles. A search on Malaria +Africa gave results from a book and from journal articles."}]},{"text":[{"text":"Ranking of results:","bold":true},{"text":" databases rank retrieved articles by "},{"text":"date","bold":true},{"text":" (most recent first) and "},{"text":"relevance","bold":true},{"text":" (how often and how prominently the search terms appear in the record)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the tool for academic information is "},{"text":"Google Scholar","bold":true},{"text":", not Google (whole web, no scholarly selection), not a web crawler (a program that collects pages) and not Opera Mini (a browser)."}]},{"text":[{"text":"Keyword searching is where you "},{"text":"start","bold":true},{"text":"; subject searching gives "},{"text":"precision","bold":true},{"text":" once you know the controlled term."}]},{"text":[{"text":"Ranking is never by \"number of times the search was conducted\" or \"number of records\"."}]}]}]},{"number":"14.5","title":"Assessing results, saving sources and quoting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Research is seldom neat. A first search may give "},{"text":"too much","bold":true},{"text":", "},{"text":"too little","bold":true},{"text":", or "},{"text":"unhelpful","bold":true},{"text":" information; you may need to redesign your topic question. The most common problem is results that are "},{"text":"too broad or unrelated","bold":true},{"text":"; the way out is to "},{"text":"rethink (change) your search strategy","bold":true},{"text":", not your topic, author or location."}]}]},{"type":"paragraph","text":[{"text":"6 ways to narrow a search (too many results):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Use "},{"text":"AND","bold":true},{"text":" to add relevant terms."}]},{"text":[{"text":"Use "},{"text":"NOT","bold":true},{"text":" to eliminate terms."}]},{"text":[{"text":"Search for words in the "},{"text":"title field","bold":true},{"text":" instead of the full text."}]},{"text":[{"text":"Use "},{"text":"phrase searching","bold":true},{"text":"."}]},{"text":[{"text":"Use "},{"text":"more specific vocabulary","bold":true},{"text":"."}]},{"text":[{"text":"Choose a "},{"text":"narrower category","bold":true},{"text":" of the major topic."}]}]},{"type":"paragraph","text":[{"text":"5 ways to broaden a search (too few results):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Combine "},{"text":"synonymous terms with OR","bold":true},{"text":"."}]},{"text":[{"text":"Think of the topic in "},{"text":"broader terms","bold":true},{"text":" and use more general vocabulary."}]},{"text":[{"text":"Use the "},{"text":"appropriate vocabulary for the discipline","bold":true},{"text":"."}]},{"text":[{"text":"Eliminate the least important concept.","bold":true}]},{"text":[{"text":"Use the "},{"text":"\"related documents\"","bold":true},{"text":" option offered by some engines and databases."}]}]},{"type":"p$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 69, $study_guide$aragraph","text":[{"text":"Saving sources:","bold":true},{"text":" save as much information about each source as possible, so you can find it again and build citations. Catalogues and databases let you "},{"text":"email, print or save","bold":true},{"text":" the citation information and sometimes the "},{"text":"full text","bold":true},{"text":". For a website, save the "},{"text":"URL","bold":true},{"text":" (cut and paste it into your email). "},{"text":"Memorising","bold":true},{"text":" a source is not a way of saving it."}]},{"type":"paragraph","text":[{"text":"Identifying sources to quote:","bold":true},{"text":" pick ideas and statements relevant to your topic. "},{"text":"4 reasons to use a quotation:","bold":true},{"text":" to add the power of the author's words to your argument; to disagree with the author's argument; to compare and contrast specific points of view; to note important research already available on your topic."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The narrowing and broadening lists are the Boolean table in action: AND and NOT narrow; OR broadens. Too "},{"text":"few","bold":true},{"text":" sources: "},{"text":"OR with synonyms","bold":true},{"text":", never AND or NOT."}]},{"text":[{"text":"Example of saving: in Academic Search Complete, open the record or full text and look for the email, print or save options. Some online newspapers and magazines let you email articles to yourself."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search strategy = the art of planning and conducting searches for the most efficient result; effective library use requires it."}]},{"text":[{"text":"3 basic steps: identify the topic; general overview (encyclopedia); narrower overview (abstracts, indexes, bibliographies, catalogue)."}]},{"text":[{"text":"5 stages of electronic search: define need; choose resources; learn search options; run; review and refine."}]},{"text":[{"text":"3 types: simple (quick keywords, huge output), advanced (filtering, multiple fields), meta (many search tools at once: Dogpile, Metacrawler, Search.com, Vivisimo)."}]},{"text":[{"text":"6 techniques: Boolean, parenthesis, phrase, truncation, wildcards, field searching. Filtering is not one."}]},{"text":[{"text":"AND narrows (all terms); OR broadens (synonyms, any term); NOT excludes."}]},{"text":[{"text":"Brackets read first; quotation marks = phrase; * = truncation (broadens); ? = wildcard (one letter)."}]},{"text":[{"text":"Keyword search = natural language, anywhere in the record; subject search = controlled vocabulary, subject field only."}]},{"text":[{"text":"Google Scholar is the tool for academic information; results are ranked by date and relevance."}]},{"text":[{"text":"Too many results: AND, NOT, title field, phrases. Too few: OR synonyms, broader terms. Save sources by email, print or save."}]}]}],"theory":{"itemId":"ff6ca6bc-9dce-5840-9ac7-584fe28ccd74","question":[{"type":"paragraph","text":[{"text":"Explain the three Boolean operators and give two reasons for using them in an online search."}]}]},"practice":[{"topic":"Search Strategies","named":false}]}},{"kind":"note","itemId":"ac7a570b-da0d-57d9-9911-e1a795ba4e49","sourceKey":"guide-topic:15","position":15,"payload":{"title":"Style Manual, Citation and Referencing","body":"Copyright, fair use and unfair use; what plagiarism is (including self-plagiarism and cyber plagiarism), how to avoid it and its consequences; why we cite and what can be cited; the two parts of referencing and the five elements to record; which disciplines use APA, MLA, Harvard and Chicago; the in-text and reference-list rules of APA, Harvard and MLA with worked examples.","noteType":"guide_topic","number":15,"mustKnow":[{"text":"Copyright, fair use and unfair use; what plagiarism is (including self-plagiarism and cyber plagiarism), how to avoid it and its consequences; why we cite and what can be cited; the two parts of referencing and the five elements to record; which disciplines use APA, MLA, Harvard and Chicago; the in-text and reference-list rules of APA, Harvard and MLA with worked examples."}],"lessons":[{"number":"15.1","title":"Copyright, fair use and unfair use","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Copyright (author's right):","bold":true},{"text":" the law that says you "},{"text":"cannot use any creative work without the permission of the owner","bold":true},{"text":". Copyrighted works are protected by "},{"text":"law","bold":true},{"text":". Anyone found guilty of breaking it is "},{"text":"liable to prosecution under the law","bold":true},{"text":"."}]},{"text":[{"text":"Fair use:","bold":true},{"text":" \"a judicial doctrine that refers to a use of copyrighted material that does not infringe or violate the exclusive rights of the copyright holder\". In plain terms: fair use allows copyrighted works to be used "},{"text":"without permission, under certain conditions","bold":true},{"text":", for "},{"text":"academic purposes, to a certain limit","bold":true},{"text":"."}]},{"text":[{"text":"Purposes allowed under fair use:","bold":true},{"text":" criticism, comment, news reporting, teaching and similar "},{"text":"non-commercial","bold":true},{"text":" purposes."}]},{"text":[{"text":"Works eligible for copyright","bold":true},{"text":" (World Intellectual Property Organization): books, music, paintings, sculpture, films, computer programs, databases, advertisements, maps, technical drawings."}]},{"text":[{"text":"Unfair use:","bold":true},{"text":" when a student or researcher "},{"text":"copies any copyrighted work indiscriminately, with or without acknowledgement","bold":true},{"text":". Fair use has a limit; crossing it is unfair use."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"As a student you rely on the documented knowledge of other people. Fair use makes that legal; acknowledgement keeps it honest."}]},{"text":[{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 70, $study_guide$t":"Trap: fair use is for "},{"text":"academic","bold":true},{"text":" purposes, not business, publishing or commercial purposes."}]},{"text":[{"text":"Trap: the punishment for violating copyright law is "},{"text":"prosecution under the law","bold":true},{"text":", not \"jail the offender\"."}]},{"text":[{"text":"Trap: "},{"text":"complimentary cards","bold":true},{"text":" are not on the WIPO list; books, music and paintings are."}]},{"text":[{"text":"Paraphrasing correctly","bold":true},{"text":", with acknowledgement, is fair use. Copying indiscriminately is unfair use; using without acknowledgement is plagiarism."}]}]}]},{"number":"15.2","title":"Plagiarism and how to avoid it","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Plagiarism:","bold":true},{"text":" from the Latin "},{"text":"plagiarius","italic":true},{"text":", meaning "},{"text":"\"kidnapper\"","bold":true},{"text":". It is the "},{"text":"act of using copyrighted work without permission or acknowledging the source","bold":true},{"text":". In the academic environment it is called "},{"text":"\"academic theft\"","bold":true},{"text":" and "},{"text":"academic fraud","bold":true},{"text":". A scholar who does not acknowledge all quoted and borrowed ideas as he reads and writes is guilty of plagiarism."}]},{"text":[{"text":"It covers:","bold":true},{"text":" other people's copyrighted work, an organisation's copyrighted work, and even your "},{"text":"own","bold":true},{"text":" work."}]},{"text":[{"text":"Self-plagiarism:","bold":true},{"text":" copying from your "},{"text":"previous assignment for a new assignment without acknowledgement","bold":true},{"text":"."}]},{"text":[{"text":"Cyber plagiarism:","bold":true},{"text":" using the "},{"text":"Internet","bold":true},{"text":" to appropriate the ideas or expression of another."}]},{"text":[{"text":"Rules for avoiding plagiarism","bold":true},{"text":" (any copyrighted work used must be duly acknowledged):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Internal citation or footnotes must be done "},{"text":"properly according to the prescribed reference style","bold":true},{"text":"."}]},{"text":[{"text":"Internal citation or footnotes must be "},{"text":"listed in the reference list or bibliography","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Three things a student must learn","bold":true},{"text":" to avoid plagiarism:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"How to "},{"text":"manage time","bold":true},{"text":" to leave enough time for academic work."}]},{"text":[{"text":"How to "},{"text":"paraphrase correctly","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"skill of citation","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Paraphrase:","bold":true},{"text":" restating another writer's idea "},{"text":"in your own words","bold":true},{"text":". A "},{"text":"direct quotation","bold":true},{"text":" uses the author's "},{"text":"exact words","bold":true},{"text":" and is shown with "},{"text":"quotation marks","bold":true},{"text":". Both must be cited."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In one line: to avoid plagiarism, other people's ideas must be "},{"text":"paraphrased and cited","bold":true},{"text":", and "},{"text":"all used works must be cited","bold":true},{"text":". Consulting a lecturer, using the library or reading a manuscript are good habits but do not by themselves stop plagiarism."}]},{"text":[{"text":"Trap: copying from a lecturer's handout or from the internet without acknowledgement is ordinary plagiarism, not self-plagiarism. Self-plagiarism is only about "},{"text":"your own","bold":true},{"text":" earlier work."}]},{"text":[{"text":"Trap: paraphrasing is "},{"text":"not","bold":true},{"text":" quoting verbatim and "},{"text":"not","bold":true},{"text":" translating into another language."}]},{"text":[{"text":"When taking notes, mark a direct quotation with "},{"text":"quotation marks","bold":true},{"text":" so you can tell it from your paraphrase later. Underlining or capitals are not the recognised way."}]},{"text":[{"text":"Citation is a skill learnt for "},{"text":"academic purposes","bold":true},{"text":"."}]}]}]},{"number":"15.3","title":"Consequences of plagiarism and reasons for citing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5 consequences of plagiarism","bold":true},{"text":" (personal, professional and legal):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"academic reputation","bold":true},{"text":" of the offender could be destroyed."}]},{"text":[{"text":"Suspension or rustication","bold":true},{"text":" of the affected student."}]},{"text":[{"text":"Summary dismissal","bold":true},{"text":" of an affected member of staff."}]},{"text":[{"text":"It can affect the "},{"text":"reputation of the institution","bold":true},{"text":"."}]},{"text":[{"text":"It can lead to "},{"text":"prosecution","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"6 reasons for citing","bold":true},{"text":" published works:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Acknowledging people's works and ideas is essential for "},{"text":"moral and legal","bold":true},{"text":" reasons."}]},{"text":[{"text":"To "},{"text":"give credit","bold":true},{"text":" to work done by others."}]},{"text":[{"text":"To "},{"text":"give direction","bold":true},{"text":" to prospective researchers on resources to consult."}]},{"text":[{"text":"Verification","bold":true},{"text":" of citations in support of the author's arguments."}]},{"text":[{"text":"It "},{"text":"reveals the scope and quality","bold":true},{"text":" of the researcher's work."}]},{"text":[{"text":"Positions in a research work are "},{"text":"strengthened$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 71, $study_guide$","bold":true},{"text":" when previous good sources are cited."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sources that can be cited:","bold":true},{"text":" secondary sources (books, encyclopaedias, dictionaries, scholarly journals, newspapers, magazines), electronic resources, institutional sources, websites, and "},{"text":"grey literature","bold":true},{"text":" (theses and dissertations, technical reports, conference proceedings)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: a student who plagiarises can be "},{"text":"dismissed from school","bold":true},{"text":" (suspension or rustication). \"Jailed\" is tempting because prosecution is possible, but the direct student penalty is removal from school."}]},{"text":[{"text":"A "},{"text":"quotation","bold":true},{"text":" is used in a research write-up to "},{"text":"support an argument","bold":true},{"text":" with the author's own words (also to disagree with an author, compare views or note existing research), not to show off writing skills or vocabulary."}]},{"text":[{"text":"Trap: "},{"text":"every","bold":true},{"text":" type of source listed can go in a reference list: books, chapters or articles in edited books, web pages, journal articles, newspapers, theses. None is excluded."}]}]}]},{"number":"15.4","title":"Referencing styles and what to record","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Referencing style:","bold":true},{"text":" the "},{"text":"various ways of acknowledging literature sources consulted","bold":true},{"text":" in a piece of writing; a "},{"text":"set of rules","bold":true},{"text":" telling a researcher how to acknowledge the thoughts, ideas and works of others in a particular way. A crucial part of successful academic writing."}]},{"text":[{"text":"Style manual:","bold":true},{"text":" each style has a manual that guides its acceptable manner of citation and referencing."}]},{"text":[{"text":"Referencing has 2 parts:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"In-text referencing (internal citation):","bold":true},{"text":" the brief citation in the "},{"text":"body of the manuscript","bold":true},{"text":", right where the idea or words are used."}]},{"text":[{"text":"Reference list (bibliography):","bold":true},{"text":" the full details, placed "},{"text":"at the end","bold":true},{"text":" of the assignment."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Rule:","bold":true},{"text":" any citation given in-text must appear in the reference list, "},{"text":"and vice versa","bold":true},{"text":". "},{"text":"Only exception:","bold":true},{"text":" "},{"text":"personal communications","bold":true},{"text":" (conversations, lectures, email). They are non-print and are cited "},{"text":"in the body of the text only","bold":true},{"text":"."}]},{"text":[{"text":"5 key elements to record","bold":true},{"text":" for every source:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Author","bold":true},{"text":" (how authors are cited varies by style)."}]},{"text":[{"text":"Title","bold":true},{"text":" (book: the title on the title page; anthology: the work's name and the book's title; periodical: the "},{"text":"article","bold":true},{"text":" name, not the periodical name)."}]},{"text":[{"text":"Publication information","bold":true},{"text":" (book: publisher and place; periodical: journal or magazine name, volume and issue numbers; website: the organisation that created the content)."}]},{"text":[{"text":"Dates","bold":true},{"text":" (record all date information)."}]},{"text":[{"text":"Access","bold":true},{"text":" (Web or print; URL or "},{"text":"Digital Object Identifier, DOI","bold":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Styles and disciplines:","bold":true}]}]},{"type":"table","header":[[{"text":"Style"}],[{"text":"Full name"}],[{"text":"Used mostly by"}]],"rows":[[[{"text":"APA","bold":true}],[{"text":"American Psychological Association"}],[{"text":"Social sciences","bold":true},{"text":" (and sciences)"}]],[[{"text":"MLA","bold":true}],[{"text":"Modern Language Association"}],[{"text":"Composition","bold":true},{"text":" and language courses"}]],[[{"text":"Chicago","bold":true}],[{"text":"Chicago style"}],[{"text":"Humanities","bold":true}]],[[{"text":"Harvard","bold":true}],[{"text":"Harvard (author-date)"}],[{"text":"University students generally"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A full bibliography entry shows "},{"text":"all","bold":true},{"text":" of: author's name and year, title and place of publication, and publisher. A bibliography is arranged "},{"text":"alphabetically","bold":true},{"text":" and sits at the "},{"text":"end","bold":true},{"text":" of the work. A "},{"text":"keyword","bold":true},{"text":" never appears in a reference entry; author, title and page numbers do."}]},{"text":[{"text":"Trap: \"NLA\", \"ALA\" and \"MPA\" are "},{"text":"not","bold":true},{"text":" referencing styles. The four to know are "},{"text":"APA, MLA, Harvard, Chicago","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"In-text citation appears in the body of the manuscript\" is "},{"text":"true","bold":true},{"text":", fully, not partially."}]},{"text":[{"text":"You will likely use different styles during your degree; the style depends on your "},{"text":"discipline","bold":true},{"text":", so always follow the citation guide your lecturer assigns."}]}]}]},{"number":"15.5","title":"APA style","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"APA","bold":true},{"text":" is most commonly used in the "},{"text":"social sciences","bold":true},{"text":", popular worldwide, has changed often and (as taught here) is in its "},{"text":"6th edition","bold":true},{"text":"."}]},{"text":[{"text":"In-text:","bold":true},{"text":" author's "}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 72, $study_guide$,{"text":"surname, year of publication","bold":true},{"text":", and "},{"text":"page number only for a direct quotation","bold":true},{"text":"."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Quotations of "},{"text":"less than 40 words","bold":true},{"text":": inside the text, in "},{"text":"double quotation marks \" \"","bold":true},{"text":"."}]},{"text":[{"text":"Quotations of "},{"text":"more than 40 words","bold":true},{"text":": a "},{"text":"block","bold":true},{"text":" on a new line, "},{"text":"indented 5 spaces","bold":true},{"text":" from the left margin, "},{"text":"no quotation marks","bold":true},{"text":"."}]},{"text":[{"text":"No page numbers","bold":true},{"text":" when you summarise or paraphrase."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reference list","bold":true},{"text":" rules:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Alphabetical order","bold":true},{"text":" by the author's "},{"text":"surname","bold":true},{"text":"."}]},{"text":[{"text":"No author:","bold":true},{"text":" use the "},{"text":"title","bold":true},{"text":" in the author's place."}]},{"text":[{"text":"Italics","bold":true},{"text":" for book and journal titles, websites and the "},{"text":"volume number","bold":true},{"text":" of a journal. The "},{"text":"issue number","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" in italics."}]},{"text":[{"text":"Lines after the first line of an entry are "},{"text":"indented 5 spaces","bold":true},{"text":" (hanging indent)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Authors:","bold":true},{"text":" 2 authors: use "},{"text":"&","bold":true},{"text":" inside parentheses and "},{"text":"and","bold":true},{"text":" in the sentence. 3 to 5 authors: all surnames the first time, then "},{"text":"et al.","bold":true},{"text":" 6 or more: "},{"text":"et al.","bold":true},{"text":" from the "},{"text":"first","bold":true},{"text":" in-text citation. In the reference list, with "},{"text":"more than 6 authors","bold":true},{"text":", list the first six and then write "},{"text":"et al.","bold":true},{"text":" in place of the rest. The exam's wording for this rule is: after the sixth author, do "},{"text":"not","bold":true},{"text":" list any more names; write "},{"text":"et al.","bold":true},{"text":" in their place."}]}]},{"type":"table","header":[[{"text":"Source"}],[{"text":"In-text citation"}],[{"text":"Reference list entry"}]],"rows":[[[{"text":"Book"}],[{"text":"John states \"all of us need reassurance occasionally\" (2002, p. 77). "},{"text":"or","italic":true},{"text":" (John, 2002, p. 77)"}],[{"text":"John, P. (2002). "},{"text":"Mental health and mental illness","italic":true},{"text":" (7th ed.). Philadelphia: Lippincott."}]],[[{"text":"Journal article"}],[{"text":"Gregory and Verdouw (2005) explain… "},{"text":"or","italic":true},{"text":" (Gregory & Verdouw, 2005)"}],[{"text":"Gregory, S., & Verdouw, J. (2005). Therapeutic touch: Its application for residents in aged care. "},{"text":"Australian Nursing Journal, 12","italic":true},{"text":"(7), 23-25."}]],[[{"text":"Web document"}],[{"text":"(Diabetes WA, 2006)"}],[{"text":"Diabetes WA. (2006). "},{"text":"Gestational","italic":true},{"text":". Retrieved October 17, 2008, from http://diabeteswa.com.au/Default.aspx?f=pv&ctr=Default&mid=133&pid=433&page_id=436"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order: "},{"text":"Author. (Year). Title. Place: Publisher.","bold":true},{"text":" For a journal: "},{"text":"Author. (Year). Article title. ","bold":true},{"text":"Journal, volume","bold":true,"italic":true},{"text":"(issue), pages.","bold":true},{"text":" For a web document: "},{"text":"Author. (Year). ","bold":true},{"text":"Title","bold":true,"italic":true},{"text":". Retrieved [date], from [URL].","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Web document with no date:","bold":true},{"text":" write "},{"text":"(n.d.)","bold":true},{"text":" for the year and still give "},{"text":"both the retrieval date and the URL","bold":true},{"text":": WA Deaf Society. (n.d.). "},{"text":"You have rights!","italic":true},{"text":" Retrieved October 17, 2008, from http://www.wadeaf.org.au/index.php?id=45. In text: (WA Deaf Society, n.d.)."}]},{"text":[{"text":"Book without an author:","bold":true},{"text":" the "},{"text":"title","bold":true},{"text":" (its first few words, in italics, with capitals) takes the author's place in text: ("},{"text":"Nursing Procedures","italic":true},{"text":", 2002, p. 17). Reference list: "},{"text":"Nursing procedures made incredibly easy","italic":true},{"text":". (2002). Springhouse: Springhouse. Exam answer: a book without an author is cited in text using "},{"text":"the title","bold":true},{"text":"."}]},{"text":[{"text":"Journal article with no author:","bold":true},{"text":" the first few words of the article title in "},{"text":"double quotation marks","bold":true},{"text":", with the comma inside the closing mark: (\"Mobile Phones,\" 2007)."}]},{"text":[{"text":"Editor:","bold":true},{"text":" Macpherson, G. (Ed.). (1995). "},{"text":"Black's medical dictionary","italic":true},{"text":" (38th ed.). London: A & C Black."}]},{"text":[{"text":"Secondary source:","bold":true},{"text":" Palfrey (2000, as cited in Talbot & Verrinder, 2005, p. 79). Only the book you actually "},{"text":"read","bold":true},{"text":" (Talbot & Verrinder) goes in the reference list."}]},{"text":[{"text":"Several authors at once:","bold":true},{"text":" (Hamilton, 2005; Stevens, 2003), in "},{"text":"alphabetical order","bold":true},{"text":", separated by a "},{"text":"semicolon","bold":true},{"text":"."}]},{"text":[{"text":"Database article or eBook:","bold":true},{"text":" end the entry with \"Retrieved from\" and the database or eBook library name."}]},{"text":[{"text":"Newspaper:","bold":true},{"text":" O'Leary, C$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 73, $study_guide$. (2005, June 11). Painkillers raise heart attack risk. "},{"text":"The West Australian","italic":true},{"text":", p. 1."}]},{"text":[{"text":"Trap: in the reference list the "},{"text":"volume","bold":true},{"text":" is italic and the "},{"text":"issue","bold":true},{"text":" is not: "},{"text":"12","italic":true},{"text":"(7)."}]}]}]},{"number":"15.6","title":"Harvard and MLA styles","mustKnow":[{"type":"paragraph","text":[{"text":"Harvard","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Primarily used by "},{"text":"university students","bold":true},{"text":". An "},{"text":"author-date","bold":true},{"text":" style with two types of citation: "},{"text":"in-text citations","bold":true},{"text":" (when quoting or paraphrasing; a fragment of the full citation in the body) and the "},{"text":"reference list","bold":true},{"text":"."}]},{"text":[{"text":"In-text format: "},{"text":"(Author's Last Name Year, Page Number)","bold":true},{"text":" with "},{"text":"no comma","bold":true},{"text":" between name and year: "},{"text":"(Austen 1813, p. 64)","bold":true},{"text":". Initials have "},{"text":"no full stops","bold":true},{"text":" and the year has "},{"text":"no brackets","bold":true},{"text":" in the reference list. Article titles go in "},{"text":"single quotation marks","bold":true},{"text":"; use "},{"text":"vol.","bold":true},{"text":", "},{"text":"no.","bold":true},{"text":", "},{"text":"pp.","bold":true},{"text":"; publisher comes "},{"text":"before","bold":true},{"text":" place."}]}]},{"type":"table","header":[[{"text":"Source"}],[{"text":"In-text citation"}],[{"text":"Reference list entry"}]],"rows":[[[{"text":"Book"}],[{"text":"(Holt 1997) "},{"text":"or","italic":true},{"text":" Holt (1997) wrote that…"}],[{"text":"Holt, DH 1997, "},{"text":"Management principles and practices","italic":true},{"text":", Prentice-Hall, Sydney."}]],[[{"text":"Journal article"}],[{"text":"(Conley & Galeson 1998)"}],[{"text":"Conley, TG & Galeson, DW 1998, 'Nativity and wealth in mid-nineteenth century cities', "},{"text":"Journal of Economic History","italic":true},{"text":", vol. 58, no. 2, pp. 468-493."}]],[[{"text":"Web page"}],[{"text":"(Weida & Stolley 2013)"}],[{"text":"Weida, S & Stolley, K 2013, "},{"text":"Developing strong thesis statements","italic":true},{"text":". Available from: https://owl.english.purdue.edu/owl/resource/588/1/. [13 October 2015]."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order: "},{"text":"Author, Initials Year, ","bold":true},{"text":"Title","bold":true,"italic":true},{"text":", Publisher, Place.","bold":true},{"text":" Electronic: add "},{"text":"Available from: [source]. [date accessed]","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"MLA","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A widely used system that helps an author acknowledge others' ideas, lets a reader "},{"text":"quickly locate","bold":true},{"text":" the source, and shows the "},{"text":"scope and depth","bold":true},{"text":" of the research."}]},{"text":[{"text":"In-text:","bold":true},{"text":" author's "},{"text":"last name and page number","bold":true},{"text":", "},{"text":"no year","bold":true},{"text":" and "},{"text":"no comma","bold":true},{"text":": "},{"text":"(McDonagh 80)","bold":true},{"text":". MLA is the style that "},{"text":"excludes the year","bold":true},{"text":" from the in-text citation."}]},{"text":[{"text":"Reference list order:","bold":true},{"text":" "},{"text":"Author's last name, first name. Title. Place of publication: publisher, year.","bold":true},{"text":" Full first names, not initials; the year comes "},{"text":"last","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Source"}],[{"text":"In-text citation"}],[{"text":"Reference list entry"}]],"rows":[[[{"text":"Book"}],[{"text":"In another study (McDonagh 80)… "},{"text":"or","italic":true},{"text":" McDonagh has discussed (80)…"}],[{"text":"McDonagh, Sean. "},{"text":"Why Are We Deaf to the Cry of the Earth","italic":true},{"text":". Dublin: Veritas, 2001."}]],[[{"text":"Journal article"}],[{"text":"Mann (850) argues…"}],[{"text":"Mann, Susan. \"Myths of Asian Womanhood.\" "},{"text":"Journal of Asian Studies","italic":true},{"text":" 59.1 (2000): 835-62."}]],[[{"text":"Web page"}],[{"text":"Harris argues… "},{"text":"or","italic":true},{"text":" (Harris)"}],[{"text":"Harris, Robert. \"Evaluating Internet Research Sources.\" "},{"text":"VirtualSalt","italic":true},{"text":". 15 June 2008. Web. 27 April 2011."}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Harvard variants:","bold":true},{"text":" 2 or 3 authors: (McCarthy, William & Pascale 1997). More than 3: (Bond et al. 1996) in text, but "},{"text":"all names","bold":true},{"text":" in the reference list. No author: ("},{"text":"A history of Greece","italic":true},{"text":" 1994). Editor: Jones, MD (ed) 1998; two editors: (eds). Chapter in an edited book: Milkman, R 1998, 'The new American workplace: High road or low road?' in P Thompson & C Warhurst (eds), "},{"text":"Workplaces of the future","italic":true},{"text":", pp. 22-34, Macmillan Press, London. Edition: 10th edn. Newspaper: Devlin, M 2011, 'Keys found to success by the less privileged', "},{"text":"The Australian","italic":true},{"text":", 16 November, p. 32."}]},{"text":[{"text":"MLA variants:","bold":true},{"text":" two or three authors: McLean, Bethany and Peter Elkind. "},{"text":"The Smartest Guys in the Room","italic":true},{"text":". New York: Portfolio, 2004; in text, McLean and Elkind (122). More than three: McGeady, Thomas et al.; in text, McGeady et al. (155). Editor: Booth, David. Ed. "},{"text":"Rethinking Social Development","italic":true},{"text":". Essex: Longman, 1994. E-journal: add the database, \"Web.\" and the access date. Print newspaper: Gleeson, Jim. \"Towards Holistic Approach to School Discipline.\" "},{"text":"Irish Times","ita$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 74, $study_guide$lic":true},{"text":" 10 February 2006, p. 16."}]},{"text":[{"text":"Quick comparison of the three in-text forms","bold":true},{"text":" for the same quotation on page 77 of a 2002 book by John: APA "},{"text":"(John, 2002, p. 77)","bold":true},{"text":"; Harvard "},{"text":"(John 2002, p. 77)","bold":true},{"text":"; MLA "},{"text":"(John 77)","bold":true},{"text":"."}]},{"text":[{"text":"Trap: APA and Harvard are both "},{"text":"author-date","bold":true},{"text":" styles; only MLA leaves the year out of the in-text citation. In APA the year is in brackets in the reference list, (2002); in Harvard it is bare, 1997; in MLA it comes at the very end."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Copyright law protects creative works; violation means prosecution. Fair use = academic, non-commercial use within a limit; unfair use = indiscriminate copying."}]},{"text":[{"text":"Plagiarism (Latin "},{"text":"plagiarius","italic":true},{"text":", \"kidnapper\") = using copyrighted work without permission or acknowledgement; \"academic theft\". Self-plagiarism = reusing your own old assignment unacknowledged; cyber plagiarism = via the Internet."}]},{"text":[{"text":"Avoid it: cite properly in the prescribed style, list every citation in the reference list; learn time management, correct paraphrasing and the skill of citation."}]},{"text":[{"text":"5 consequences: reputation, suspension/rustication, dismissal of staff, institutional reputation, prosecution. 6 reasons to cite."}]},{"text":[{"text":"Referencing = in-text citation (body) + reference list (end); every in-text entry appears in the list and vice versa, except personal communications."}]},{"text":[{"text":"Record 5 elements: author, title, publication information, dates, access (URL/DOI)."}]},{"text":[{"text":"APA: social sciences; MLA: composition; Chicago: humanities; Harvard: author-date, university students."}]},{"text":[{"text":"APA: (Surname, Year, p. x); quotes under 40 words in double quotation marks, over 40 as an indented block; list alphabetical, title replaces a missing author, italics for titles and volume but not issue; more than 6 authors: six then et al.; no-date web: (n.d.) plus retrieval date and URL."}]},{"text":[{"text":"Harvard: (Holt 1997, p. 64), no comma; MLA: (McDonagh 80), no year."}]}]}],"theory":{"itemId":"6857b502-3b17-5f52-85ec-0c9586bcd0f6","question":[{"type":"paragraph","text":[{"text":"You have consulted a book written by O. P. Maxwell and I. Daniel, published in 2017 by Oxford in England, titled "},{"text":"Introduction to Geodesy","italic":true},{"text":". Show how you would enter it in the reference list in (a) APA and (b) Harvard style, and explain what plagiarism is and two ways to avoid it."}]}]},"practice":[{"topic":"Style Manual: Citation and Referencing","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"ec7fe978-c8e8-53e4-be5f-cc7dd10fcb82","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Define listening and discuss four strategies for enhancing listening skills."},"answer":{"kind":"model_answer","itemId":"999936c6-81ea-5806-8e41-7ecad6a74cb5","sourceKey":"guide-answer:1","payload":{"body":"Define listening (the ability to receive, perceive and decode the meaning of spoken words; a receptive skill without which communication is impossible). Then 1-2 lines each on four strategies, e.g. eye contact (links your mind with the speaker's, shows readiness), concentrating on content (identify the topic, focus on the message), repressing emotional attachment (avoid prejudice from bias or personal emotions), avoiding hasty generalisations (let the speaker finish the point before reacting)."}}},{"kind":"theory_question","itemId":"012bd206-3418-51b1-b543-d68a623244a6","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"What is the basic difference between consonant and vowel articulation, and how is each type of sound described?"},"answer":{"kind":"model_answer","itemId":"ee5079f7-f445-5731-bcd8-ff63ef8bb625","sourceKey":"guide-answer:2","payload":{"body":"Consonants: at least two articulators make contact and obstruct the airflow; described by place of articulation, manner of articulation and state of the glottis (voicing), e.g. /p/ voiceless bilabial stop. Vowels: no obstruction, no contact, all voiced; described by tongue height, tongue horizontality, lip rounding and duration (tense/lax), e.g. /i:/ high front tense. Mention the counts: 24 consonants, 20 vowels."}}},{"kind":"theory_question","itemId":"ef210d0b-f9ba-5347-8a99-74e606af4cb3","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Stress is perceptually marked by four main features. List them and explain how each indicates stress."},"answer":{"kind":"model_answer","itemId":"3f87732b-324b-58aa-b0c3-c8828461ab7c","sourceKey":"guide-answer:3","payload":{"body":"Define stress (relative prominence of one syllable over others in a polysyllabic word). Then one or two lines each: loudness (stressed syllable is louder), length (longer syllable heard as stressed), pitch (higher pitch from faster vocal cord vibration; strongest effect), quality (strong vowel or diphthong versus weak /ə, ɪ, ʊ/). Close: the factors usually combine."}}},{"kind":"theory_question","itemId":"89869c2e-9fb3-5179-b521-a6966386ef84","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Differentiate between skimming and scanning, and list four bad reading habits, stating why each is not recommended."},"answer":{"kind":"model_answer","itemId":"9904caa0-e35c-571c-9d78-e77aa7c3e210","sourceKey":"guide-answer:4","payload":{"body":"Skimming: quick reading for the overall idea via title, blurb, contents, headings, topic sentences; no specific information sought. Scanning: quick search for one specific piece of information using the index or contents; ignores irrelevant details. Then any four habits, one line each, e.g. word-by-word reading (slow, laborious), vocalisation (moving vocal organs cuts $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 75, $study_guide$rate and comprehension), finger-pointing (forces the eyes word by word), regression (excessive backward glances hinder comprehension)."}}},{"kind":"theory_question","itemId":"4e3c6792-c883-5505-b754-5200e0943a0e","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Explain the four categories of comprehension questions, giving one example of each."},"answer":{"kind":"model_answer","itemId":"368a6527-0c25-5c69-bf99-ef7db127e13d","sourceKey":"guide-answer:5","payload":{"body":"State that the categories come from the tools examiners use to test understanding. Then one or two lines each: direct reference (refer directly to the text; \"with reference to the passage...\"); inference (establish the relationship between parts of the passage; \"the difference between sentence 1 and sentence 3...\"); supposition (think beyond the passage to the outside world; \"what do you suppose is responsible for...\"); evaluation (judge the information and the effectiveness of the writer's language; \"in your opinion, what is the writer's motivation?\")."}}},{"kind":"theory_question","itemId":"d8a9e146-234e-515d-9111-7148c5c6a8b8","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Explain the SQ3R technique of study reading."},"answer":{"kind":"model_answer","itemId":"457b4fe5-0559-5b25-a241-ee60cc354fc6","sourceKey":"guide-answer:6","payload":{"body":"Define study reading. Expand SQ3R: Survey (preliminary matters: title, preface, foreword, contents, blurb, date), Question (ask guiding questions about correctness, aim, objectivity), Read (careful, critical reading, two or three times, taking notes), Recall/Recite (remember from memory by paraphrasing or exact words), Review (assess and revise everything; a repetition of all the steps). One line each."}}},{"kind":"theory_question","itemId":"4bd81e1d-548e-510e-949b-183e435120aa","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Outline and explain the five-step process for paragraph development."},"answer":{"kind":"model_answer","itemId":"ec3a518b-003c-572d-b89f-ad38c8232af8","sourceKey":"guide-answer:7","payload":{"body":"Name the five steps in order, one or two lines each: (1) decide on a controlling idea and write a topic sentence; (2) explain the controlling idea; (3) give one or more examples as evidence; (4) explain each example's relevance to the topic sentence; (5) complete the idea or transition to the next paragraph. Add that steps 3 and 4 may be repeated, and illustrate with the African oral narratives model (the tortoise and the feast in the sky)."}}},{"kind":"theory_question","itemId":"d9c56737-2394-5e87-a520-cafd3101f6c5","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"Explain the COEM factor in essay writing."},"answer":{"kind":"model_answer","itemId":"2b2688f4-ffe5-567d-95cc-49c61c43dc9f","sourceKey":"guide-answer:8","payload":{"body":"Define COEM as the four quality-control components of an essay. Then 2-3 lines each: Content (depth of treatment, the \"meat\"; narrow the subject; keep a central idea or thesis), Organisation (logical ordering; suitable introduction, body from familiar to unfamiliar, striking conclusion), Expression (precise, concise, concrete words; avoid jargon and highfalutin language), Mechanics (punctuation and related symbols that convey the right meaning). Close by saying that together they distinguish a well-executed essay from a poorly rendered one."}}},{"kind":"theory_question","itemId":"d71fc0df-1a2a-52a9-8b1f-20622cedf9bd","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"Distinguish between denotative and connotative meaning, and explain how verbal context helps a reader work out the meaning of an unfamiliar word."},"answer":{"kind":"model_answer","itemId":"29222e23-31c2-5672-aecd-e5c2a2b315bf","sourceKey":"guide-answer:9","payload":{"body":"Define denotative meaning (literal, dictionary meaning; dark = lightlessness). Define connotative meaning (associated, figurative meaning from feelings and experience; \"he's dark\" = evil). Then explain verbal context: clues from paired words that are complementary (similar meaning: unscrupulous and dishonest) or contrasting (opposite meaning: not wasteful, so frugal), with one example of each."}}},{"kind":"theory_question","itemId":"581e7879-0c09-57ec-994f-64e9d493d020","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"Define a phrase and explain any four types of phrase in English with one example each."},"answer":{"kind":"model_answer","itemId":"13f5c8fb-1fde-5aa2-989c-105de38c40cc","sourceKey":"guide-answer:10","payload":{"body":"Define a phrase as a group of words (possibly one word) working as a single grammatical unit and named after its head word. Then one or two lines each on four types, e.g. noun phrase (a heavy rain, works as a noun), verb phrase (may have gone, main verb plus auxiliaries), prepositional phrase (under the bed, preposition plus object, works as adjective or adverb), adjective phrase (extremely valuable, modifies a noun)."}}},{"kind":"theory_question","itemId":"f080dbdc-2921-5808-9f7e-555c36543412","sourceKey":"guide-theory:11","position":11,"payload":{"prompt":"Distinguish between defining and non-defining relative clauses, with one example of each, and show how punctuation affects meaning."},"answer":{"kind":"model_answer","itemId":"64dce646-70cb-578f-be61-a7ad893af70b","sourceKey":"guide-answer:11","payload":{"body":"Define the relative (adjective) clause. Defining: identifies the noun (\"which one?\"), essential, no commas, accepts that (The students who arrived late were locked out: some students). Non-defining: adds information about a known noun, non-essential, paired commas, never that (The students, who arrived late, were locked out: all students). Conclude that the commas change \"some\" to \"all\"."}}},{"kind":"theory_question","itemId":"0b59eb48-441b-5264-be58-705b94b87e1e","sourceKey":"guide-theory:12","position":12,"payload":{"prompt":"Highlight five characteristi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_gst111', 76, $study_guide$cs of good information."},"answer":{"kind":"model_answer","itemId":"73ff98d9-640f-52bb-bcf6-b4415a5dedc9","sourceKey":"guide-answer:12","payload":{"body":"Define information briefly (processed data that improves the user's knowledge). Then one or two lines each: availability/accessibility (easy to obtain and within reach); accuracy (correct for its purpose); reliability (truthful, authoritative, dependable); timeliness (on time, or it becomes irrelevant); relevance (suited to the purpose and the user)."}}},{"kind":"theory_question","itemId":"1554bfcd-b06b-56b2-9054-2ead2b884028","sourceKey":"guide-theory:13","position":13,"payload":{"prompt":"List the three information retrieval tools in the library and explain how the University of Lagos Main Library classifies its materials."},"answer":{"kind":"model_answer","itemId":"028b7b14-2b90-597a-944b-6bef48558e99","sourceKey":"guide-answer:13","payload":{"body":"Name the library catalogue (manual and OPAC), indexes and abstracts, and bibliography, with one line on each. Then state that the Main Library uses the Library of Congress scheme: mixed (alpha-numeric) notation, main classes A to Z with O, X and Y reserved, sub-divided by two letters (e.g. HM Sociology). Add that the College of Medicine uses the NLM scheme."}}},{"kind":"theory_question","itemId":"ff6ca6bc-9dce-5840-9ac7-584fe28ccd74","sourceKey":"guide-theory:14","position":14,"payload":{"prompt":"Explain the three Boolean operators and give two reasons for using them in an online search."},"answer":{"kind":"model_answer","itemId":"f7d5cf3e-e2fc-5a93-8533-71330bbbc6e7","sourceKey":"guide-answer:14","payload":{"body":"Name George Boole. AND narrows: all terms must be present (cloning AND humans AND ethics). OR broadens: connects synonyms, any term may be present (cloning OR genetics OR reproduction). NOT excludes a word (cloning NOT sheep). Reasons: to focus a search with multiple terms; to connect pieces of information exactly as wanted (title AND author AND year). Mention that AND is often implied and that brackets fix the order."}}},{"kind":"theory_question","itemId":"6857b502-3b17-5f52-85ec-0c9586bcd0f6","sourceKey":"guide-theory:15","position":15,"payload":{"prompt":"You have consulted a book written by O. P. Maxwell and I. Daniel, published in 2017 by Oxford in England, titled Introduction to Geodesy. Show how you would enter it in the reference list in (a) APA and (b) Harvard style, and explain what plagiarism is and two ways to avoid it."},"answer":{"kind":"model_answer","itemId":"0515e25a-8a3b-5b8d-8f30-88be56131b12","sourceKey":"guide-answer:15","payload":{"body":"(a) APA: Maxwell, O. P., & Daniel, I. (2017). Introduction to geodesy. England: Oxford. (b) Harvard: Maxwell, OP & Daniel, I 2017, Introduction to geodesy, Oxford, England. Then define plagiarism (using copyrighted work without permission or acknowledging the source; \"academic theft\") and give the two rules: cite properly in the prescribed style, and list every citation in the reference list or bibliography."}}}]}$study_guide$);
